BEGIN TRANSACTION;

CREATE SCHEMA pem;
COMMENT ON SCHEMA pem IS 'Postgres Enterprise Manager Internal Tables';

CREATE SCHEMA pemdata;
COMMENT ON SCHEMA pemdata IS 'Postgres Enterprise Manager Monitoring Data';

CREATE SCHEMA pemhistory;
COMMENT ON SCHEMA pemhistory IS 'Postgres Enterprise Manager Historical Data';

--
-- WARNING!!
--
-- If updating the schema version:
-- -> You *must* also update it in the common version.h file, to avoid
--    having the client (and agent) throw warnings upon connection.
--
CREATE OR REPLACE FUNCTION pem.schema_version()
  RETURNS integer AS
'SELECT 202511251::integer;'
  LANGUAGE 'sql' IMMUTABLE;
COMMENT ON FUNCTION pem.schema_version() IS 'Returns the version number of the PEM schema';

CREATE OR REPLACE FUNCTION pem.remove_string_from_array(varchar[], varchar)
 RETURNS varchar[] AS $$
	SELECT COALESCE(array_agg(u), '{}'::varchar[])
		FROM (SELECT unnest($1) AS u) x WHERE u != $2
$$ LANGUAGE sql IMMUTABLE;

-- Reference - https://wiki.postgresql.org/wiki/Unnest_multidimensional_array
CREATE OR REPLACE FUNCTION pem.reduce_dim(anyarray)
RETURNS SETOF anyarray AS
$function$
DECLARE
    s $1%TYPE;
BEGIN
    FOREACH s SLICE 1  IN ARRAY $1 LOOP
        RETURN NEXT s;
    END LOOP;
    RETURN;
END;
$function$
LANGUAGE plpgsql IMMUTABLE;

CREATE OR REPLACE FUNCTION pem.backend_minimum(majorversion integer, minorversion integer DEFAULT NULL)
  RETURNS boolean AS
$$
DECLARE
    version varchar;
    version_arr varchar[3];
    major integer;
    minor integer;
BEGIN
    SELECT version() INTO version;
    version_arr := regexp_matches(version, '[PostgreSQL|EnterpriseDB] ([0-9]+)[.]{0,1}([0-9]+)*');
    major := version_arr[1]::integer;
    minor := version_arr[2]::integer;

    IF (major > majorversion OR (major = majorversion AND minor >= minorversion)) THEN
      return true;
    ELSIF (major = majorversion AND minorversion IS NULL) THEN
      return true;
    ELSE
      return false;
    END IF;
END;
$$
 LANGUAGE plpgsql VOLATILE;

CREATE OR REPLACE FUNCTION pem.create_generic_role(varchar)
RETURNS BOOL AS $$
DECLARE
    role_exist boolean;
    role_name text;
BEGIN
    role_exist := false;
    role_name  := quote_ident($1);

    SELECT true INTO role_exist FROM pg_catalog.pg_roles WHERE rolname = role_name;
    IF role_exist THEN
        RAISE NOTICE 'ROLE % already exist', role_name;
    ELSE
        EXECUTE 'CREATE ROLE ' || role_name  || ' WITH NOLOGIN';
    END IF;
    RETURN role_exist;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION pem.create_proxy_agent_user(varchar, varchar DEFAULT NULL)
RETURNS VOID AS $$
DECLARE
    username text;
    passwd text;
    user_exists boolean;
BEGIN
    user_exists := pem.create_generic_role($1);
    username := pg_catalog.quote_ident($1);

    IF user_exists THEN
        RAISE NOTICE 'ROLE/USER % EXIST.', $1;
    ELSE
        passwd := pg_catalog.quote_literal(COALESCE($2, md5(random()::text)));
        EXECUTE $SQL$ALTER USER $SQL$ || username || $SQL$ LOGIN PASSWORD $SQL$ || passwd;
    END IF;
    EXECUTE $SQL$GRANT pem_agent_pool, pem_agent TO $SQL$ || username;
END;
$$ LANGUAGE plpgsql;

-- Create a generic user pem_agent.
SELECT pem.create_generic_role('pem_user');

-- Create a generic user pem_admin.
SELECT pem.create_generic_role('pem_admin');

-- Create a generic user pem_agent.
SELECT pem.create_generic_role('pem_agent');

-- Create a generic user pem_agent.
SELECT pem.create_generic_role('pem_agent_pool');

-- Create a generic role for Kerberos/GSSAPI support
SELECT pem.create_generic_role('pem_gssapi');

--
-- Probes can gather data about multiple objects.  For example, a single probe
-- configured and run at the database level might gather information about
-- every table in every schema within that database.  Given the target_type_id,
-- that is, the level at which data is being gathered, and the list of keys
-- from the collected data, this function works out a new target_type_id
-- reflecting the object to which the collected data pertains.
--
-- This is not an exact process, because the probe might have extra keys.
-- But the result of this function might still be useful to give some idea of
-- where the probe data could most logically be displayed in the tree view.
--
CREATE OR REPLACE FUNCTION pem.probe_applies_to(target_type_id integer,
	key_list varchar[]) RETURNS integer AS $$
BEGIN
	IF target_type_id IN (100, 500, 600, 700, 800, 900)
		OR key_list = '{}'::varchar[] THEN
		RETURN target_type_id;
	END IF;
	IF target_type_id = 200 AND 'database_name' = ANY(key_list) THEN
		target_type_id := 300;
		key_list = pem.remove_string_from_array(key_list, 'database_name');
	END IF;
	IF target_type_id = 300 AND 'schema_name' = ANY(key_list) THEN
		target_type_id := 400;
		key_list = pem.remove_string_from_array(key_list, 'schema_name');
	END IF;
	IF target_type_id = 400 AND 'table_name' = ANY(key_list) THEN
		RETURN 500;
	END IF;
	IF target_type_id = 400 AND 'index_name' = ANY(key_list) THEN
		RETURN 600;
	END IF;
	IF target_type_id = 400 AND 'sequence_name' = ANY(key_list) THEN
		RETURN 700;
	END IF;
	IF target_type_id = 400 AND 'function_name' = ANY(key_list) THEN
		RETURN 800;
	END IF;
	IF target_type_id = 400 AND 'view_name' = ANY(key_list) THEN
		RETURN 900;
	END IF;
	RETURN target_type_id;
END
$$ LANGUAGE plpgsql IMMUTABLE;

CREATE TABLE pem.config (
	param      character varying(64) NOT NULL,
	value      text,
	unit       text,
	datatype   text NOT NULL DEFAULT '',
	options    json DEFAULT NULL,
	role       text DEFAULT NULL,
	CONSTRAINT config_pkey PRIMARY KEY (param)
);
COMMENT ON TABLE pem.config IS 'Global configuration data';
COMMENT ON COLUMN pem.config.param IS 'Configuration parameter name';
COMMENT ON COLUMN pem.config.value IS 'Configuration parameter value';
COMMENT ON COLUMN pem.config.unit IS 'Configuration parameter unit';
COMMENT ON COLUMN pem.config.datatype IS 'Configuration parameter data type';
COMMENT ON COLUMN pem.config.options IS 'Possible values for an enum type (selection/combo box)';
COMMENT ON COLUMN pem.config.role IS 'Can only be modifitied by this role';

-- RLS (Row Level Security) for the pem.config table
DO $$
DECLARE
  rls_supported boolean;
BEGIN
    SELECT (count(*) = 1) INTO rls_supported FROM pg_catalog.pg_class WHERE relname = 'pg_policy' AND relnamespace = (SELECT oid FROM pg_catalog.pg_namespace WHERE nspname = 'pg_catalog');

    IF rls_supported THEN
        RAISE INFO 'RLS policies for pem.config...';
        EXECUTE $SQL$ ALTER TABLE pem.config ENABLE ROW LEVEL SECURITY $SQL$;

        EXECUTE $SQL$
            CREATE POLICY pem_config_role_select
                ON pem.config
                FOR SELECT
                USING (true)
        $SQL$;

        EXECUTE $SQL$
            CREATE POLICY pem_config_role_insert
                ON pem.config
                FOR INSERT
                WITH CHECK (true)
        $SQL$;

        EXECUTE $SQL$
            CREATE POLICY pem_config_role_update
                ON pem.config
                FOR UPDATE
                USING (
                    role is NULL or pg_catalog.pg_has_role(role, 'member'::text)
                )
                WITH CHECK (true)
        $SQL$;

        -- DELETE operation on pem.config
        EXECUTE $SQL$
            CREATE POLICY pem_config_role_delete
                ON pem.config
                FOR DELETE
                USING (role is NULL or pg_catalog.pg_has_role(role, 'member'::text))
        $SQL$;

    END IF;
END
$$ language 'plpgsql';

-- PEM-5755 Create Manage Profile and Configuration Tables
-- Main table to define the profiles
CREATE TABLE IF NOT EXISTS pem.profile (
	id SERIAL PRIMARY KEY,
	name TEXT NOT NULL,
	description TEXT,
	target_kind CHAR(1) NOT NULL CHECK (target_kind IN ('a', 's')), -- 'a' -> Agent/Host, 's' -> Server
	status TEXT NOT NULL DEFAULT 'published' CHECK (status IN ('published', 'draft')),
	parent_id INTEGER REFERENCES pem.profile(id) ON DELETE CASCADE
);

-- This ensures a published profile can have at most ONE draft.
CREATE UNIQUE INDEX one_draft_per_profile_idx
ON pem.profile (parent_id)
WHERE status = 'draft';

-- The user-facing name should be unique for published profiles.
CREATE UNIQUE INDEX unique_published_profile_name_idx
ON pem.profile (name)
WHERE status = 'published';

CREATE TABLE pem.server (
	id					serial NOT NULL, -- Server unique ID
	description			text, -- Server description
	server				text NOT NULL, -- Server hostname or address
	port				integer NOT NULL DEFAULT 5432, -- Server port number
	database			text NOT NULL DEFAULT 'postgres'::text, -- Maint. DB
	serviceid			text,		-- The server's service ID
	active				boolean NOT NULL DEFAULT true,
	hostaddr			text,
	service				text,
	alert_blackout		boolean DEFAULT false,
	owner				oid,
	team				text,
	is_remote_monitoring  boolean NOT NULL DEFAULT false,
	replication_solution text DEFAULT ''::text,
	efm_cluster_name	text DEFAULT NULL,
	efm_service_name	text DEFAULT NULL,
	efm_installation_path	text DEFAULT NULL,
	patroni_installation_path 	text DEFAULT NULL,
	patroni_cluster_name 	text DEFAULT NULL,
	patroni_config_path 	text DEFAULT NULL,
	comment			text DEFAULT NULL,
	tags            jsonb DEFAULT '[]'::jsonb,
	post_connection_sql text DEFAULT ''::text,
	auto_alert_blackout boolean DEFAULT false,
	profile_id      integer REFERENCES pem.profile (id) ON DELETE SET NULL,
	CONSTRAINT server_pkey PRIMARY KEY (id)
);

COMMENT ON TABLE pem.server IS 'Enterprise server directory';
COMMENT ON COLUMN pem.server.id IS 'Server unique ID';
COMMENT ON COLUMN pem.server.description IS 'Server description';
COMMENT ON COLUMN pem.server.server IS 'Server hostname or address';
COMMENT ON COLUMN pem.server.port IS 'Server port number';
COMMENT ON COLUMN pem.server.database IS 'Maintenance database';
COMMENT ON COLUMN pem.server.serviceid IS 'The server''s service ID';
COMMENT ON COLUMN pem.server.hostaddr IS 'The server''s host address';
COMMENT ON COLUMN pem.server.service IS 'The server''s libpq service name';
COMMENT ON COLUMN pem.server.alert_blackout IS 'Blackout server alert processing';
COMMENT ON COLUMN pem.server.owner IS 'The owner of the registered server';
COMMENT ON COLUMN pem.server.team IS 'Defines the visibility of the server in particular role/team';
COMMENT ON COLUMN pem.server.is_remote_monitoring IS 'Indicate whether this server is remotely monitored or not';
COMMENT ON COLUMN pem.server.replication_solution IS 'Replication solution used by the server';
COMMENT ON COLUMN pem.server.efm_cluster_name IS 'Cluster name of EFM';
COMMENT ON COLUMN pem.server.efm_service_name IS 'Service name of EFM';
COMMENT ON COLUMN pem.server.efm_installation_path IS 'Installation Path of EFM';
COMMENT ON COLUMN pem.server.patroni_installation_path IS 'Optional path to the patronictl executable if not in standard PATH.';
COMMENT ON COLUMN pem.server.patroni_cluster_name IS 'The name of the Patroni cluster to monitor (used by patronictl).';
COMMENT ON COLUMN pem.server.patroni_config_path IS 'Optional path to the patroni.yml configuration file used by the patronictl command run by the agent.';
COMMENT ON COLUMN pem.server.profile_id IS 'The profile associated with the server.';
CREATE OR REPLACE FUNCTION pem.server_insertion() RETURNS trigger AS $$
DECLARE
	curr_user_oid oid;
BEGIN
	IF NEW.owner IS NULL THEN
		SELECT oid INTO curr_user_oid FROM pg_catalog.pg_roles WHERE rolname = current_user;
		NEW.owner := curr_user_oid;
	END IF;
	RETURN NEW;
END
$$ LANGUAGE 'plpgsql';

CREATE TRIGGER server_insertion
	BEFORE INSERT ON pem.server
	FOR EACH ROW EXECUTE PROCEDURE pem.server_insertion();

CREATE OR REPLACE FUNCTION pem.server_postupdate() RETURNS trigger AS $$
BEGIN
	IF (OLD.active AND NOT NEW.active) THEN
		DELETE FROM pem.agent_server_binding WHERE server_id = NEW.id;
		DELETE FROM pem.alert WHERE server_id = NEW.id;
		DELETE FROM pem.job WHERE jobid IN (SELECT j.jobid FROM pem.job j INNER JOIN pem.jobstep js ON j.jobid = js.jstjobid WHERE js.server_id = NEW.id);
	END IF;
	RETURN NULL;
END
$$ LANGUAGE plpgsql;

CREATE TRIGGER server_postupdate
	AFTER UPDATE ON pem.server
	FOR EACH ROW EXECUTE PROCEDURE pem.server_postupdate();

CREATE OR REPLACE FUNCTION pem.server_postdelete() RETURNS trigger AS $$
BEGIN
	DELETE FROM pem.alert WHERE server_id = OLD.id;
	RETURN NULL;
END
$$ LANGUAGE plpgsql;

CREATE TRIGGER server_postdelete
	AFTER DELETE ON pem.server
	FOR EACH ROW EXECUTE PROCEDURE pem.server_postdelete();

CREATE OR REPLACE FUNCTION pem.server_efm_probe_update() RETURNS trigger AS $$
DECLARE
	efm_cluster_probe_id integer;
	efm_node_probe_id integer;
	is_windows_server boolean;
BEGIN
	SELECT agent_capability_list @> ARRAY['windows'] INTO is_windows_server FROM pem.agent WHERE id = (SELECT agent_id FROM pem.agent_server_binding WHERE server_id = NEW.id);
	SELECT id INTO efm_node_probe_id FROM pem.probe WHERE internal_name = 'efm_cluster_node_status';
	SELECT id INTO efm_cluster_probe_id FROM pem.probe WHERE internal_name = 'efm_cluster_info';
	-- If cluster name is not null then either we need to insert or update
	-- the pem.probe_config_server table and if the value is NULL then we
	-- need to delete the entry fron the table.
	IF (NEW.efm_cluster_name IS NOT NULL AND NEW.efm_cluster_name != '' AND NOT NEW.is_remote_monitoring AND NOT is_windows_server)THEN
		INSERT INTO pem.probe_config_server(probe_id, server_id, enabled) SELECT efm_cluster_probe_id, NEW.id, true
		WHERE NOT EXISTS (SELECT 1 FROM pem.probe_config_server WHERE probe_id = efm_cluster_probe_id AND server_id = NEW.id);
		INSERT INTO pem.probe_config_server(probe_id, server_id, enabled) SELECT efm_node_probe_id, NEW.id, true
		WHERE NOT EXISTS (SELECT 1 FROM pem.probe_config_server WHERE probe_id = efm_node_probe_id AND server_id = NEW.id);
	ELSE
		DELETE FROM pem.probe_config_server WHERE probe_id = efm_cluster_probe_id AND server_id = NEW.id;
		DELETE FROM pem.probe_config_server WHERE probe_id = efm_node_probe_id AND server_id = NEW.id;
	END IF;
	RETURN NULL;
END
$$ LANGUAGE plpgsql;

CREATE TRIGGER server_efm_cluster_name
	AFTER INSERT OR UPDATE ON pem.server
	FOR EACH ROW EXECUTE PROCEDURE pem.server_efm_probe_update();

CREATE OR REPLACE FUNCTION pem.is_server_owner(_user text, _server_id int)
RETURNS boolean AS
$$
SELECT CASE WHEN
_user = COALESCE((
        SELECT usename FROM pg_catalog.pg_user u
        WHERE u.usesysid = (
            SELECT s.owner FROM pem.server s WHERE s.id = _server_id
        )
    ), current_user
) THEN TRUE ELSE FALSE END;
$$ language 'sql';

CREATE TABLE pem.server_group
(
  id serial NOT NULL,
  name text NOT NULL,
  parent_id integer,
  CONSTRAINT server_group_pkey PRIMARY KEY (id),
  CONSTRAINT uniqueconstraint UNIQUE (id, name)
);

ALTER TABLE pem.server_group ADD CONSTRAINT parent_id_fkey FOREIGN KEY (parent_id)
	REFERENCES pem.server_group (id) ON UPDATE NO ACTION
	ON DELETE NO ACTION;

CREATE OR REPLACE FUNCTION pem.can_access_server(_server_id int)
RETURNS boolean AS
$$
    SELECT EXISTS (SELECT 1 FROM pem.server WHERE id = _server_id);
$$ language 'sql';

INSERT INTO pem.config (param, value, unit, datatype, role) VALUES (
	'show_objects_with_no_team', 't', 't/f', 'bool', 'pem_admin'
);

CREATE OR REPLACE FUNCTION pem.can_access_team(_owner OID, _team text)
RETURNS boolean AS
$$
    SELECT
        (
            -- team is not defined
            (SELECT (value = 't') AS value FROM pem.config WHERE param = 'show_objects_with_no_team') AND
            (_team IS NULL OR _team = '')
        ) OR
        -- current user is the owner
 		_owner =  pg_catalog.quote_ident(current_user)::regrole::oid OR
        -- current user is pem_super_admin
        pg_catalog.pg_has_role('pem_super_admin', 'member') OR
        -- current user is a member of the team (or team does not exist)
        CASE WHEN EXISTS (
            SELECT 1 FROM pg_catalog.pg_roles AS t WHERE t.rolname = _team
        ) THEN pg_catalog.pg_has_role(_team, 'member')
        ELSE false
        END;
$$ LANGUAGE 'sql';

CREATE OR REPLACE FUNCTION pem.object_owner(_owner OID)
RETURNS boolean AS
$$
    SELECT
        u.usesysid = _owner OR
        pg_has_role('pem_admin', 'member'::text)
    FROM pg_user u WHERE usename = current_user;
$$ LANGUAGE 'sql';

-- Do not allow to change team other than owner/pem_super_admin
CREATE OR REPLACE FUNCTION pem.on_team_onwer_update()
RETURNS trigger AS
$$
DECLARE
    is_owner boolean := false;
BEGIN
    SELECT
        (usesysid = OLD.owner OR
        pg_has_role('pem_super_admin', 'member'::text)) INTO is_owner
    FROM pg_user u WHERE u.usename = current_user;

    IF NOT is_owner THEN
        RAISE EXCEPTION
            '% does not have permission to change the team/owner.',
            current_user;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE 'plpgsql';

CREATE TRIGGER pem_team_update BEFORE UPDATE OF team, owner
    ON pem.server
    FOR EACH ROW
    EXECUTE PROCEDURE pem.on_team_onwer_update();

CREATE OR REPLACE FUNCTION pem.current_user_id()
  RETURNS oid AS $$
SELECT oid FROM pg_catalog.pg_roles WHERE rolname=current_user$$ LANGUAGE SQL;

-- Table: pem.user_server_group
CREATE TABLE pem.user_server_group
(
  id     int  NOT NULL,
  uid    oid  NOT NULL DEFAULT pem.current_user_id(),
  name   text NOT NULL,
  hidden boolean NOT NULL DEFAULT false,
  deleted boolean NOT NULL DEFAULT false,
  CONSTRAINT user_server_group_pk PRIMARY KEY (id, uid),
  CONSTRAINT user_server_group_id_fk FOREIGN KEY (id) REFERENCES pem.server_group(id)
    MATCH SIMPLE ON UPDATE CASCADE ON DELETE CASCADE INITIALLY DEFERRED
);

CREATE OR REPLACE FUNCTION pem.create_server_group(
    _name text, _uid oid DEFAULT pem.current_user_id()
) RETURNS integer AS
$$
DECLARE
    gid integer;
    hidden bool;
BEGIN
    SELECT s.id, s.hidden INTO gid, hidden FROM pem.user_server_group s WHERE s.name = _name AND uid = _uid;

    IF gid IS NOT NULL THEN
        IF hidden THEN
            UPDATE pem.user_server_group SET hidden = FALSE WHERE id = gid;
        END IF;
        RETURN gid;
    ELSE
        SELECT s.id INTO gid FROM pem.server_group s WHERE s.name = _name;

        IF gid IS NULL THEN
            INSERT INTO pem.server_group(name) VALUES (_name) RETURNING id INTO gid;
        END IF;
        RETURN gid;
    END IF;
END$$ LANGUAGE 'plpgsql';

CREATE OR REPLACE FUNCTION pem.rename_server_group(
    _id integer, _name text,
    _uid oid DEFAULT pem.current_user_id()
)
RETURNS integer AS
$$
DECLARE
    v_gid integer;
    v_deleted bool;
BEGIN
    -- Server group name already exists for the user!
    SELECT s.id INTO v_gid FROM pem.user_server_group s
    WHERE s.name = _name AND s.uid = _uid;

    IF FOUND THEN
        RETURN -2;
    END IF;

    SELECT s.id INTO v_gid FROM pem.server_group s WHERE s.name = _name AND
    NOT EXISTS(
        SELECT g.id FROM pem.user_server_group g
        WHERE g.id = s.id AND g.uid = _uid
    );

    -- Already present!
    IF FOUND THEN
        RETURN -3;
    END IF;

    SELECT s.deleted INTO v_deleted FROM pem.user_server_group s
    WHERE s.id = _id AND s.uid = _uid;

    IF FOUND THEN
        IF v_deleted THEN
            -- Can't change deleted!
            RETURN -1;
        END IF;
        SELECT id INTO v_gid FROM pem.server_group
        WHERE id = _id AND name = _name;

        IF FOUND THEN
            DELETE FROM pem.user_server_group WHERE id = _id AND uid = _uid;
        ELSE
            UPDATE pem.user_server_group SET name = _name WHERE id = _id;
        END IF;
        RETURN 0;
    END IF;

    INSERT INTO pem.user_server_group (id, name, uid) VALUES (_id, _name, _uid);
    RETURN 0;

END$$ LANGUAGE 'plpgsql';

CREATE OR REPLACE FUNCTION pem.change_server_group(
    _old integer, _aid integer, _sid integer, _uid integer
) RETURNS integer AS $$
DECLARE
    v_cnt integer;
    v_user text;
BEGIN

    SELECT rolname into v_user FROM pg_roles WHERE oid = _uid;

    EXECUTE $SQL$
WITH update_agent_options AS (
    UPDATE pem.agent_options SET group_id = $2
    WHERE group_id = $1 AND pem_user = $4
    RETURNING 1
),
insert_agent_options AS (
    INSERT INTO pem.agent_options(agent_id, description, group_id, pem_user)
    SELECT id, description, $2, $4 FROM pem.agent a
    WHERE a.group_id = $1 AND NOT a.id = ANY(
        SELECT ao.agent_id FROM pem.agent_options ao WHERE ao.pem_user = $4
    ) RETURNING 1
),
update_server_options AS (
    UPDATE pem.server_options SET server_group_id = $3
    WHERE server_group_id = $1 AND pem_user = $4
    RETURNING 1
),
insert_server_options AS (
    INSERT INTO pem.server_options(
        server_id, server_group_id, pem_user, server_colour, fgcolor,
        database_restriction, store_pwd, restore_env,
        sslcompression, username
    ) SELECT
        so.server_id, $3, $4, so.server_colour, so.fgcolor,
        so.database_restriction, false, so.restore_env,
        sslcompression, username
    FROM pem.server_options so
    LEFT JOIN pem.server s ON (so.server_id = s.id)
    LEFT JOIN pg_roles r ON (s.owner = r.oid)
    WHERE s.group_id = $1 AND r.rolname = so.pem_user AND
        NOT s.id = ANY(
            SELECT c.server_id FROM pem.server_options c
            WHERE c.pem_user = $4
        )
    RETURNING 1
)
SELECT sum(g.cnt) FROM (
    SELECT count(*) AS cnt FROM update_agent_options
    UNION ALL
    SELECT count(*) AS cnt FROM insert_agent_options
    UNION ALL
    SELECT count(*) AS cnt FROM update_server_options
    UNION ALL
    SELECT count(*) AS cnt FROM insert_server_options
) g$SQL$ USING _old, _aid, _sid, v_user INTO v_cnt;
    RETURN v_cnt;
END;
$$ LANGUAGE 'plpgsql';

CREATE OR REPLACE FUNCTION pem.hide_server_group(
    _id integer,
    _uid integer default pem.current_user_id()
)
RETURNS integer AS
$$
DECLARE
    v_name text;
    v_hidden bool;
    v_cnt integer;
BEGIN
    -- Move the servers, and agents to the default respective groups
    -- i.e. Move servers in group #1 (PEM Server Directory), and agents in the
    -- group #0 (PEM Agents)
    SELECT pem.change_server_group(_id, 0, 1, _uid) INTO v_cnt;

    SELECT hidden INTO v_hidden FROM pem.user_server_group
    WHERE id = _id AND uid = _uid;

    IF FOUND THEN
        IF NOT v_hidden THEN
            UPDATE pem.user_server_group SET hidden = TRUE
            WHERE id = _id AND uid = _uid;
        ELSE
            RETURN -1;
        END IF;
    ELSE
        INSERT INTO pem.user_server_group(id, name, hidden, uid)
        SELECT s.id, s.name, TRUE, _uid FROM pem.server_group s WHERE s.id = _id;
    END IF;
    RETURN 0;
END$$ LANGUAGE 'plpgsql';

CREATE OR REPLACE FUNCTION pem.delete_server_group(
    _id integer, new_implementation boolean default false,
    _uid integer default pem.current_user_id()
)
RETURNS boolean AS
$$
DECLARE
    v_name text;
    v_cnt integer;
BEGIN
    PERFORM pem.hide_server_group(_id, _uid);
    IF NOT new_implementation THEN
        RETURN false;
    END IF;

    -- 'pem.hide_server_group' will already inserted the required row (if not
    -- present already)
    UPDATE pem.user_server_group SET deleted = true
    WHERE id = _id AND uid = _uid;

    -- Check - how many servers, and agents are present under the agents for
    -- other users, if none then remove it permenantly.
    SELECT SUM(g.cnt) INTO v_cnt FROM (
        SELECT count(*) AS cnt FROM pem.server_options
        WHERE server_group_id = _id
        UNION ALL
        SELECT count(*) AS cnt FROM pem.agent_options WHERE group_id = _id
    ) g;

    IF v_cnt = 0 THEN
        UPDATE pem.server SET group_id = 1 WHERE group_id = _id;
        UPDATE pem.agent SET group_id = 0 WHERE group_id = _id;
        DELETE FROM pem.server_group WHERE id = _id;
        RETURN true;
    END IF;

    RETURN false;
END$$ LANGUAGE 'plpgsql' SECURITY DEFINER;

CREATE TABLE pem.server_options (
	id				serial NOT NULL, -- Server option unique identifier
	server_id			integer NOT NULL, -- Server identifier
	pem_user			text NOT NULL DEFAULT CURRENT_USER, -- ID of PEM user
	server_colour			text,
	fgcolor				text,
	server_group_id			integer,
	database_restriction 		text, -- Database restriction SQL clause
	store_pwd			boolean NOT NULL DEFAULT false,
	restore_env			boolean NOT NULL DEFAULT false,
	last_database			text, -- The last database viewed
	last_schema			text, -- The last schema viewed
	rolename			text, -- The role the connection will use
	sslcompression                  boolean NOT NULL DEFAULT false, -- SSL compression flag
	username text NOT NULL DEFAULT ''::text, -- Username to login to the server
	connection_params jsonb, -- Connection parameters
	CONSTRAINT server_option_pkey PRIMARY KEY (id),
	CONSTRAINT server_option_server_id_fkey FOREIGN KEY (server_id)
		REFERENCES pem.server (id) MATCH SIMPLE
		ON UPDATE CASCADE ON DELETE CASCADE INITIALLY DEFERRED,
	CONSTRAINT server_option_pem_user_key UNIQUE (pem_user, server_id),
	CONSTRAINT server_group_id_fkey FOREIGN KEY (server_group_id)
		REFERENCES pem.server_group (id) ON UPDATE NO ACTION
		ON DELETE NO ACTION
);
COMMENT ON TABLE pem.server_options IS 'Per-user server options';
COMMENT ON COLUMN pem.server_options.id IS 'Server option unique identifier';
COMMENT ON COLUMN pem.server_options.server_id IS 'Server identifier';
COMMENT ON COLUMN pem.server_options.pem_user IS 'ID of the PEM user account';
COMMENT ON COLUMN pem.server_options.server_colour IS 'Server colour in the treeview';
COMMENT ON COLUMN pem.server_options.server_group_id IS 'Id of the server group in the treeview';
COMMENT ON COLUMN pem.server_options.database_restriction IS 'Database restriction SQL clause';
COMMENT ON COLUMN pem.server_options.store_pwd IS 'Store the password in the pgpass file?';
COMMENT ON COLUMN pem.server_options.restore_env IS 'Restore the treeview status upon connection?';
COMMENT ON COLUMN pem.server_options.last_database IS 'The last database viewed';
COMMENT ON COLUMN pem.server_options.last_schema IS 'The last schema viewed';
COMMENT ON COLUMN pem.server_options.rolename IS 'The role the connection will use';
COMMENT ON COLUMN pem.server_options.sslcompression IS 'The SSL compression flag';
COMMENT ON COLUMN pem.server_options.username IS 'Username to login to the server';

CREATE TABLE pem.server_auth
(
  id serial NOT NULL, -- Server option unique identifier
  server_id integer NOT NULL, -- Server identifier
  pem_user text NOT NULL DEFAULT CURRENT_USER, -- ID of the PEM user account
  ssl_root_cert text, -- The SSL root certificate file
  ssl_rev_list text, -- The SSL certificate revocation list
  ssl_client_cert text, -- The SSL client certificate file
  ssl_client_key text, -- The SSL client certificate key file
  save_password boolean NOT NULL DEFAULT false, -- The Server password Saved flag
  password text, -- The Server password
  passfile text, -- The Server password file
  use_ssh_tunnel boolean NOT NULL DEFAULT false, -- Using SSH Tunnel or not
  tunnel_host text, -- Host/IP Address of SSH Tunnel
  tunnel_port integer DEFAULT 22, -- Port of SSH Tunnel
  tunnel_username text, -- SSH Tunnel user name
  tunnel_authentication boolean DEFAULT false, -- Authentication using identity file or password
  tunnel_identity_file text, -- Path of the identity file
  tunnel_password text, -- SSH Tunnel password
  use_gssapi      boolean NOT NULL DEFAULT false, -- Kerberos Authentication?
  CONSTRAINT server_auth_pkey PRIMARY KEY (id),
  CONSTRAINT server_auth_server_id_fkey FOREIGN KEY (server_id)
      REFERENCES pem.server (id) MATCH SIMPLE
      ON UPDATE CASCADE ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT server_auth_pem_user_key UNIQUE (pem_user, server_id)
)
WITH (
  OIDS=FALSE
);

COMMENT ON TABLE pem.server_auth
  IS 'Per-user server authentication options';
COMMENT ON COLUMN pem.server_auth.id IS 'Server option unique identifier';
COMMENT ON COLUMN pem.server_auth.server_id IS 'Server identifier';
COMMENT ON COLUMN pem.server_auth.pem_user IS 'ID of the PEM user account';
COMMENT ON COLUMN pem.server_auth.ssl_root_cert IS 'The SSL root certificate file';
COMMENT ON COLUMN pem.server_auth.ssl_rev_list IS 'The SSL certificate revocation list';
COMMENT ON COLUMN pem.server_auth.ssl_client_cert IS 'The SSL client certificate file';
COMMENT ON COLUMN pem.server_auth.ssl_client_key IS 'The SSL client certificate key file';
COMMENT ON COLUMN pem.server_auth.save_password IS 'The Server password saved flag';
COMMENT ON COLUMN pem.server_auth.password IS 'The Server password';
COMMENT ON COLUMN pem.server_auth.passfile IS 'The Server password file';
COMMENT ON COLUMN pem.server_auth.use_ssh_tunnel IS 'Using SSH Tunnel or not';
