CREATE OR REPLACE FUNCTION pem.default_email_group() RETURNS integer AS
$$
DECLARE
	email_group_id integer;
BEGIN
	SELECT min(id) INTO email_group_id FROM pem.email_group;
	IF email_group_id IS NULL THEN
		INSERT INTO pem.email_group(name) VALUES ('<Default>')
			RETURNING id INTO email_group_id;
	END IF;
	RETURN email_group_id;
END;
$$ LANGUAGE 'plpgsql';

CREATE TABLE pem.agent (
	id				serial NOT NULL,
	agent_capability_list		text[] NOT NULL DEFAULT '{}',
	description			text NOT NULL DEFAULT '',
	active				boolean NOT NULL DEFAULT true,
	heartbeat_tolerance		integer NOT NULL DEFAULT 15,
	alert_blackout			boolean DEFAULT false,
	version				text NOT NULL DEFAULT 'Unknown',
	platform			text NOT NULL DEFAULT 'Unknown',
	owner				oid, -- The owner of the registered agent
	team text, -- Defines the visibility of the agent in particular role/team
	ignore_mnt_points   text[] DEFAULT NULL, -- Used to ignore the mount point for disk usage calculation.
	job_notification_override_default boolean NOT NULL DEFAULT false,
	job_failure_notification boolean NOT NULL DEFAULT false,
	job_status_change_notification boolean NOT NULL DEFAULT false,
	job_notification_email_group_id integer NOT NULL
			DEFAULT pem.default_email_group(),
	tags            jsonb DEFAULT '[]'::jsonb,
	auto_alert_blackout boolean DEFAULT false,
	profile_id      integer REFERENCES pem.profile (id) ON DELETE SET NULL,
	CONSTRAINT agent_pkey PRIMARY KEY (id)
);
COMMENT ON TABLE pem.agent IS 'Agent registrations';
COMMENT ON COLUMN pem.agent.id IS 'Agent unique identifier';
COMMENT ON COLUMN pem.agent.agent_capability_list IS 'Array of capabilities the agent has';
COMMENT ON COLUMN pem.agent.description IS 'Description of the agent';
COMMENT ON COLUMN pem.agent.active IS 'Is the agent active (or deleted)?';
COMMENT ON COLUMN pem.agent.heartbeat_tolerance IS 'The interval before heartbeat is considered missed, in seconds';
COMMENT ON COLUMN pem.agent.alert_blackout IS 'Blackout agent alert processing';
COMMENT ON COLUMN pem.agent.version IS 'Agent version number';
COMMENT ON COLUMN pem.agent.platform IS 'Operating system on which agent is running';
COMMENT ON COLUMN pem.agent.owner IS 'The owner of the registered agent';
COMMENT ON COLUMN pem.agent.team IS 'Defines the visibility of the agent in particular role/team';
COMMENT ON COLUMN pem.agent.job_notification_override_default IS
	'Suggests whether to override the default job notification settings';
COMMENT ON COLUMN pem.agent.job_status_change_notification IS
	'Determines whether to send the notification on scheduled job '
	'successful completion';
COMMENT ON COLUMN pem.agent.job_failure_notification IS
	'Determines whether to send the notification on scheduled job '
	'failed to complete';
COMMENT ON COLUMN pem.agent.job_notification_email_group_id IS
	'Send the notification of the scheduled task to which email group';
COMMENT ON COLUMN pem.agent.profile_id IS
	'The profile associated with the agent';

CREATE OR REPLACE FUNCTION pem.agent_postupdate() RETURNS trigger AS $$
BEGIN
	IF (OLD.active AND NOT NEW.active) THEN
		DELETE FROM pem.agent_server_binding WHERE agent_id = NEW.id;
		DELETE FROM pem.agent_tool_binding WHERE agent_id = NEW.id;
		DELETE FROM pem.alert WHERE agent_id = NEW.id;
	END IF;
	RETURN NULL;
END
$$ LANGUAGE plpgsql;

CREATE TRIGGER agent_postupdate
	AFTER UPDATE ON pem.agent
	FOR EACH ROW EXECUTE PROCEDURE pem.agent_postupdate();

CREATE OR REPLACE FUNCTION pem.agent_postdelete() RETURNS trigger AS $$
BEGIN
	DELETE FROM pem.alert WHERE agent_id = OLD.id;
	RETURN NULL;
END
$$ LANGUAGE plpgsql;

CREATE TRIGGER agent_postdelete
	AFTER DELETE ON pem.agent
	FOR EACH ROW EXECUTE PROCEDURE pem.agent_postdelete();


CREATE TRIGGER pem_team_update BEFORE UPDATE OF team, owner
    ON pem.agent
    FOR EACH ROW
    EXECUTE PROCEDURE pem.on_team_onwer_update();


-- The connection parameters below are those to be used by the agent when
-- connecting to the server, as opposed to those to be used by the client
-- when connecting to the server.  These could be the same, but not
-- necessarily: since the agent is running on the same host as the server,
-- it might connect via UNIX sockets rather than over TCP, or via the loopback
-- interface rather than some other IP.
CREATE TABLE pem.agent_server_binding (
	agent_id			integer NOT NULL
		REFERENCES pem.agent (id) ON DELETE CASCADE ON UPDATE RESTRICT,
	server_id			integer NOT NULL
		REFERENCES pem.server (id) ON DELETE CASCADE ON UPDATE RESTRICT,
	server				text NOT NULL,
	port				integer NOT NULL DEFAULT 5432,
	username			text NOT NULL,
	password			text,
	database			text NOT NULL DEFAULT 'postgres'::text,
	sslmode				text NOT NULL DEFAULT 'disable'::text,
	allow_takeover			boolean NOT NULL DEFAULT false,
	exclude_databases   text[] DEFAULT '{}',
	CONSTRAINT agent_server_binding_pkey PRIMARY KEY (agent_id, server_id),
	CHECK (sslmode IN ('', 'require', 'prefer', 'allow', 'disable', 'verify-ca', 'verify-full'))
);

CREATE OR REPLACE FUNCTION pem.agent_insertion() RETURNS trigger AS $$
DECLARE
	curr_user_oid oid;
BEGIN
	IF NEW.owner IS NULL THEN
		SELECT oid INTO curr_user_oid FROM pg_catalog.pg_roles WHERE rolname = current_user;
		NEW.owner := curr_user_oid;
	END IF;
	RETURN NEW;
END
$$ LANGUAGE 'plpgsql';

CREATE TRIGGER agent_insertion
	BEFORE INSERT ON pem.agent
	FOR EACH ROW EXECUTE PROCEDURE pem.agent_insertion();

-- ==========================================================
-- Table: pem.pem_host_and_server
-- Description: Maps PEM agents to backend database servers.
-- ==========================================================
CREATE TABLE pem.pem_host_and_server (
  agent_id  INTEGER NOT NULL,  -- Represents the host (PEM agent)
  server_id INTEGER NOT NULL,  -- Represents the backend server
  database  TEXT NOT NULL,     -- Name of the database on the server
  is_leader BOOLEAN DEFAULT FALSE, -- Leader flag for job execution

  FOREIGN KEY (agent_id, server_id)
    REFERENCES pem.agent_server_binding(agent_id, server_id)
    ON DELETE CASCADE ON UPDATE CASCADE
);

