-- Added new table to save per user agent grouping information.
CREATE TABLE pem.agent_options (
    agent_id            integer NOT NULL, -- Agent identifier
    pem_user            text NOT NULL DEFAULT CURRENT_USER, -- ID of PEM user
    group_id            integer,
    description         text,
    CONSTRAINT agent_option_pkey PRIMARY KEY (agent_id, pem_user),
    CONSTRAINT agent_option_agent_id_fkey FOREIGN KEY (agent_id)
        REFERENCES pem.agent (id) MATCH SIMPLE
        ON UPDATE CASCADE ON DELETE CASCADE INITIALLY DEFERRED,
    CONSTRAINT agent_option_pem_user_key UNIQUE (pem_user, agent_id),
    CONSTRAINT group_id_fkey FOREIGN KEY (group_id)
        REFERENCES pem.server_group (id) ON UPDATE NO ACTION
        ON DELETE NO ACTION
);

ALTER TABLE pem.agent ADD COLUMN group_id integer DEFAULT 0;
ALTER TABLE pem.agent ADD CONSTRAINT agent_group_id_fkey FOREIGN KEY (group_id)
        REFERENCES pem.server_group (id) ON UPDATE NO ACTION
        ON DELETE NO ACTION;

ALTER TABLE pem.server ADD COLUMN group_id integer DEFAULT 1;
ALTER TABLE pem.server ADD CONSTRAINT server_groups_id_fkey FOREIGN KEY (group_id)
        REFERENCES pem.server_group (id) ON UPDATE NO ACTION
        ON DELETE NO ACTION;

-- Only these server(s) are available, which meets following conditions:
-- 1.  Active
-- 2.  current user is member of the 'team'
CREATE OR REPLACE VIEW pem.avail_servers AS
	SELECT
		s.id AS id,
		s.description AS description,
		s.server AS server,
		s.port AS port,
		s.database AS database,
		s.serviceid AS serviceid,
		s.active AS active,
		s.hostaddr AS hostaddr,
		s.service AS service,
		s.alert_blackout AS alert_blackout,
		s.owner AS owner,
		s.team AS team,
		s.profile_id as profile_id,
		s.owner::regrole::name AS server_owner,
		s.is_remote_monitoring AS is_remote_monitoring,
    	s.replication_solution AS replication_solution,
		s.efm_cluster_name AS efm_cluster_name,
		s.efm_service_name AS efm_service_name,
		s.efm_installation_path AS efm_installation_path,
		s.patroni_installation_path AS patroni_installation_path,
		s.patroni_cluster_name AS patroni_cluster_name,
		s.patroni_config_path AS patroni_config_path,
		COALESCE(so.server_group_id, s.group_id, 1) AS group_id
	FROM pem.server s
		LEFT JOIN pem.server_options so ON (s.id = so.server_id AND pem_user = current_user)
	WHERE
		-- Only active servers
		s.active AND
		pem.can_access_team(s.owner, s.team);

-- Only these agent(s) are available, which meets following conditions:
-- 1. Active
CREATE OR REPLACE VIEW pem.avail_agents AS
	SELECT
		a.id AS id,
		a.agent_capability_list AS agent_capability_list,
		COALESCE(ao.description, a.description) AS description,
		a.active AS active,
		a.heartbeat_tolerance AS heartbeat_tolerance,
		a.alert_blackout AS alert_blackout,
		a.version AS version,
		a.platform AS platform,
		a.owner AS owner,
		a.team AS team,
		a.owner::regrole::name AS agent_owner,
		COALESCE(ao.group_id, a.group_id, 0) AS group_id,
		a.profile_id AS profile_id
	FROM pem.agent a
		LEFT JOIN pem.agent_options ao ON (a.id = ao.agent_id AND pem_user = current_user)
	WHERE
		-- Only active agents
		a.active AND (
			pem.can_access_team(a.owner, a.team) OR
			pg_catalog.pg_has_role('pem_agent', 'member'::text) OR
			id in (
				SELECT DISTINCT(agent_id)
				FROM pem.agent_server_binding
				WHERE server_id in (SELECT s.id FROM pem.server s WHERE pem.can_access_team(s.owner, s.team))
			)
		);

CREATE TABLE pem.server_version (
	id					integer NOT NULL,
	display_name		text NOT NULL,
	CONSTRAINT server_version_pkey PRIMARY KEY (id)
);

-- BARMAN schema
-- Update this function for listing all the supported tools.
CREATE FUNCTION pem.supported_tool(text) RETURNS boolean AS $$
    SELECT $1 IN ('barman');
$$ LANGUAGE SQL IMMUTABLE;

CREATE TABLE pem.tool (
    id serial NOT NULL,
    gid int NOT NULL DEFAULT 1 /* PEM Directory Server */,
    name text NOT NULL,
    active boolean NOT NULL DEFAULT true,
    options jsonb,
    description text NOT NULL,
    team text NOT NULL DEFAULT '', -- Defines the visibility of the tool in particular role/team
    owner oid, -- The owner of the registered tool
    CONSTRAINT pem_tool_pkey PRIMARY KEY (id),
    CONSTRAINT pem_tool_is_supported CHECK (pem.supported_tool(name))
);

CREATE OR REPLACE FUNCTION pem.tool_insertion() RETURNS trigger AS $$
DECLARE
	curr_user_oid oid;
BEGIN
	IF NEW.owner IS NULL THEN
		SELECT oid INTO curr_user_oid FROM pg_catalog.pg_roles WHERE rolname = current_user;
		NEW.owner := curr_user_oid;
	END IF;
	RETURN NEW;
END
$$ LANGUAGE 'plpgsql';

CREATE TRIGGER tool_insertion
	BEFORE INSERT ON pem.tool
	FOR EACH ROW EXECUTE PROCEDURE pem.tool_insertion();

CREATE FUNCTION pem.validate_agent_tool_options(p_agent_id int, p_tool_id int, p_options jsonb)
RETURNS boolean AS
$FUNC$
DECLARE
    v_name text;
BEGIN
    SELECT name INTO v_name FROM pem.tool WHERE id = p_tool_id;
    IF v_name = 'barman' THEN
        RETURN (SELECT pem.validate_barman_agent_options(p_agent_id, p_tool_id, p_options));
    END IF;
RETURN false;
END;
$FUNC$
LANGUAGE 'plpgsql';

CREATE FUNCTION pem.validate_barman_agent_options(p_agent_id int, p_tool_id int, p_options jsonb)
RETURNS boolean AS
$FUNC$
DECLARE
	url text;
	result boolean;
BEGIN
	SELECT p_options -> 'url' INTO url;
	SELECT url like '"http://%' OR url like '"https://%' into result;
	IF result = 'f' THEN
		RAISE INFO 'URL must start with http:// or https://';
	END IF;
	RETURN result;
RETURN true;
END;
$FUNC$
LANGUAGE 'plpgsql';

CREATE TABLE pem.agent_tool_binding (
    agent_id int NOT NULL,
    tool_id int NOT NULL,
    options jsonb,
    CONSTRAINT agent_tool_binding_pkey PRIMARY KEY (tool_id),
    CONSTRAINT agent_tool_uniq UNIQUE(agent_id, tool_id),
    CONSTRAINT pem_tool_id_fkey FOREIGN KEY (tool_id)
    REFERENCES pem.tool (id) MATCH SIMPLE
        ON UPDATE CASCADE ON DELETE CASCADE INITIALLY DEFERRED,
    CONSTRAINT pem_agent_id_fkey FOREIGN KEY (agent_id)
    REFERENCES pem.agent (id) MATCH SIMPLE
        ON UPDATE CASCADE ON DELETE CASCADE INITIALLY DEFERRED,
        CONSTRAINT pem_agent_tool_options_validation CHECK (pem.validate_agent_tool_options(agent_id, tool_id, options))
);

CREATE OR REPLACE FUNCTION pem.tool_postupdate() RETURNS trigger AS $$
BEGIN
	IF (OLD.active AND NOT NEW.active) THEN
		DELETE FROM pem.agent_tool_binding WHERE tool_id = NEW.id;
	END IF;
	NEW.name := OLD.name;
	RETURN NEW;
END
$$ LANGUAGE plpgsql;

CREATE TRIGGER tool_postupdate
	AFTER UPDATE ON pem.tool
	FOR EACH ROW EXECUTE PROCEDURE pem.tool_postupdate();

-- table to save per user pem tool information.
CREATE TABLE pem.tool_options (
    tool_id             integer NOT NULL, -- Agent identifier
    pem_user            text NOT NULL DEFAULT CURRENT_USER, -- ID of PEM user
    description         text,
    options             jsonb,
    gid                 int NOT NULL DEFAULT 1,
    CONSTRAINT tool_option_pkey PRIMARY KEY (tool_id, pem_user),
    CONSTRAINT tool_option_tool_id_fkey FOREIGN KEY (tool_id)
        REFERENCES pem.tool (id) MATCH SIMPLE
        ON UPDATE CASCADE ON DELETE CASCADE INITIALLY DEFERRED,
    CONSTRAINT tool_option_pem_user_key UNIQUE (pem_user, tool_id)
);

CREATE TABLE pem.tool_heartbeat(
	agent_id	           integer NOT NULL,
	tool_id	             integer NOT NULL,
	missing_heartbeat_at timestamptz NOT NULL,
	CONSTRAINT tool_heartbeat_uniq UNIQUE(agent_id, tool_id),
	CONSTRAINT tool_heartbeat_fkey FOREIGN KEY (tool_id)
		REFERENCES pem.agent_tool_binding ON UPDATE CASCADE ON DELETE CASCADE
);

CREATE TABLE pemhistory.tool_heartbeat(
       agent_id   integer NOT NULL,
       tool_id    integer NOT NULL,
       start_time timestamptz NOT NULL,
       end_time   timestamptz NOT NULL
);

CREATE OR REPLACE FUNCTION pem.update_tool_history() RETURNS trigger AS $$
BEGIN
       IF (OLD.missing_heartbeat_at IS NOT NULL AND NEW.missing_heartbeat_at IS NULL) THEN
               INSERT INTO pemhistory.tool_heartbeat(
                       agent_id, tool_id, start_time, end_time
               ) VALUES (
                       OLD.agent_id, OLD.tool_id, OLD.missing_heartbeat_at, now()
               );
       END IF;
       IF TG_OP = 'UPDATE' THEN
               -- Do not allow to change the tool type
               NEW.name := OLD.name;
       END IF;
       RETURN NEW;
END
$$ LANGUAGE plpgsql;

CREATE TRIGGER tool_heartbeat_postupdate
       AFTER UPDATE ON pem.tool_heartbeat
       FOR EACH ROW EXECUTE PROCEDURE pem.update_tool_history();

CREATE TRIGGER tool_heartbeat_postdelete
       AFTER DELETE ON pem.tool_heartbeat
       FOR EACH ROW EXECUTE PROCEDURE pem.update_tool_history();

-- Only these tool(s) are available, which meets following conditions:
-- 1.  Active
-- 2. team is accessible (Refer: pem.can_access_team)
CREATE OR REPLACE VIEW pem.avail_tools AS
	SELECT
		a.id AS id,
		a.name,
		COALESCE(tos.description, a.description) AS description,
		a.options,
		a.active AS active,
		a.owner AS owner,
		a.team AS team,
		a.owner::regrole::name AS tool_owner,
		a.gid
		--COALESCE(tos.group_id, a.group_id, 0) AS group_id
	FROM pem.tool a
		LEFT JOIN pem.tool_options tos ON (a.id = tos.tool_id AND pem_user = current_user)
	WHERE
		-- Only active tools
		a.active AND pem.can_access_team(a.owner, a.team);

