CREATE TABLE pem.agent_heartbeat(
	agent_id	integer NOT NULL UNIQUE
				REFERENCES pem.agent (id) ON UPDATE RESTRICT ON DELETE CASCADE,

	last_heartbeat	timestamptz NOT NULL
);

CREATE TABLE pem.server_heartbeat(
	agent_id	integer NOT NULL,
	server_id	integer NOT NULL,

	last_heartbeat	timestamptz NOT NULL,

	CONSTRAINT server_heartbeat_uniq UNIQUE(agent_id, server_id),

	CONSTRAINT server_heartbeat_fkey FOREIGN KEY (agent_id, server_id)
		REFERENCES pem.agent_server_binding ON UPDATE CASCADE ON DELETE CASCADE
);

CREATE OR REPLACE FUNCTION pem.do_heartbeat(
    p_agentId                  integer,
    p_serverIDs                integer[],
    p_missedHeartbeatsForTools integer[] = '{}'::integer[]
)
RETURNS void AS $$
DECLARE
    idx integer;
BEGIN
    -- perform heartbeat only when agent is active.
    IF ((SELECT active FROM pem.agent WHERE id = p_agentId) IS NOT TRUE) THEN
        RETURN;
    END IF;

    UPDATE pem.agent_heartbeat
        SET last_heartbeat = now()
        WHERE agent_id = p_agentId;

    IF (NOT FOUND) THEN
        INSERT INTO pem.agent_heartbeat VALUES(p_agentId, now());
    END IF;

    FOR idx in 1..COALESCE(array_upper(p_serverIDs, 1), 0) LOOP
        UPDATE pem.server_heartbeat
            SET last_heartbeat = now()
            WHERE agent_id = p_agentId AND server_id = p_serverIDs[idx];

        IF (NOT FOUND) THEN
		    -- it is possible that agent-server binding is broken by now.
		    IF EXISTS(SELECT * FROM pem.agent_server_binding WHERE agent_id = p_agentId) THEN
                INSERT INTO pem.server_heartbeat
                    SELECT asb.agent_id, asb.server_id, now()
                    FROM pem.agent_server_binding asb
                    WHERE asb.agent_id = p_agentId AND
                        asb.server_id = p_serverIDs[idx];
            END IF;
        END IF;
    END LOOP;

    FOR idx in 1..COALESCE(array_upper(p_missedHeartbeatsForTools, 1), 0) LOOP
        IF EXISTS(
            SELECT agent_id FROM pem.agent_tool_binding
            WHERE agent_id = p_agentId
                AND tool_id = p_missedHeartbeatsForTools[idx]
        ) THEN
            INSERT INTO pem.tool_heartbeat (
                agent_id, tool_id, missing_heartbeat_at
            ) VALUES (
                p_agentId, p_missedHeartbeatsForTools[idx], now()
            ) ON CONFLICT DO NOTHING;
        END IF;
    END LOOP;

    -- Mark all the tools available, for which missing-heartbeat is not
    -- reported.
    DELETE FROM pem.tool_heartbeat
    WHERE agent_id = p_agentId
        AND NOT (tool_id = ANY(p_missedHeartbeatsForTools));
END;
$$ LANGUAGE plpgsql;

CREATE TABLE pem.probe (
	id					serial NOT NULL,
	display_name		text NOT NULL,
	internal_name		text NOT NULL,
	reference_id		text NOT NULL,
	collection_method	char NOT NULL,
	target_type_id		integer NOT NULL REFERENCES pem.probe_target_type (id),
	applies_to_id		integer NOT NULL REFERENCES pem.probe_target_type (id),
	agent_capability	text,
	probe_code			text NOT NULL,
	enabled_by_default	boolean NOT NULL,
	default_execution_frequency	integer NOT NULL,
	-- Default lifetime value in 'days'
	default_lifetime	integer NOT NULL,
	-- When false, server version must be listed in pem.probe_server_version,
	-- or probe will not apply.  When true, applies anyway.
	any_server_version	boolean NOT NULL,
	-- When false, extension version must be listed in pem.probe_extension_version,
	-- or probe will not apply.  When true, applies anyway.
	any_extension_version boolean NOT NULL default true,
	-- Name for the extension
	extension_name text,
	-- If force_enabled is set, UI should not permit user disable.
	force_enabled		boolean NOT NULL DEFAULT false,
	-- Computed column, updated by triggers on pem.probe_column.
	probe_key_list		varchar[] NOT NULL DEFAULT '{}'::varchar[],
	-- If is_discard_history is set, the history table for that probe will not be created
	discard_history		boolean NOT NULL DEFAULT false,
	-- Defines whether the given probe is system or custom
	is_system_probe		boolean NOT NULL DEFAULT true,
	-- Marks the probe as deleted for purge job to delete a probe and it's data
	deleted				boolean NOT NULL DEFAULT false,
	-- Stores the timestamp when the probe was marked for deletion
	deleted_time            timestamptz DEFAULT NULL,
	-- Defines the platform for a custom batch probe
	platform		text,
	-- Defines the probe is listed in the Manage Chart option
	is_chartable		boolean NOT NULL DEFAULT true,
	jstid				integer,
	-- Defines whether rerun the given probe when restart Agent
	rerun_on_restart	boolean NOT NULL DEFAULT false,
	CONSTRAINT probe_pkey PRIMARY KEY (id),
	-- 'b' = batch, collect via shell script
	-- 's' = SQL, collect via SQL query
	-- 'i' = Internal
	-- 'w' = WMI
	CONSTRAINT probe_collection_method
		CHECK (collection_method IN ('b', 's', 'i', 'w')),
	CONSTRAINT probe_target_type_coherence
		CHECK (collection_method != 's' OR target_type_id != 100)
);

COMMENT ON COLUMN pem.probe.default_lifetime IS 'Default lifetime value in days';

CREATE OR REPLACE FUNCTION pem.probe_preupdate() RETURNS trigger AS $$
BEGIN
	NEW.applies_to_id := pem.probe_applies_to(
		NEW.target_type_id,	NEW.probe_key_list
	);
	-- Override the reference_name.
	-- It will same as internal_name for system proebs, but - user defined probes
	-- will use a UUID generated based on creation time.
	--
	-- It can be used to refer the importing & exporting probes.
	IF TG_OP = 'INSERT' THEN
		IF NEW.is_system_probe THEN
			NEW.reference_id := NEW.internal_name;
		ELSE
			NEW.reference_id := md5(
				NEW.internal_name || random()::text || clock_timestamp()::text
			)::uuid::text;
		END IF;
	END IF;
	RETURN NEW;
END
$$ LANGUAGE plpgsql;

CREATE TRIGGER probe_preupdate
	BEFORE INSERT OR UPDATE ON pem.probe
	FOR EACH ROW EXECUTE PROCEDURE pem.probe_preupdate();

CREATE OR REPLACE FUNCTION pem.custom_probe_deleted() RETURNS TRIGGER AS $$
BEGIN
	IF OLD.is_system_probe THEN
		RAISE EXCEPTION 'Can not delete a pre-defined probe (%) in Postgres Enterprise Manager', OLD.id;
	END IF;
	IF NEW.deleted = true THEN
		IF OLD.deleted_time IS NOT NULL THEN
			NEW.deleted_time := OLD.deleted_time;
		ELSE
			NEW.deleted_time := now();
		END IF;
	ELSE
		NEW.deleted_time := NULL;
	END IF;

	RETURN NEW;
END
$$ LANGUAGE plpgsql;

CREATE TRIGGER pem_custom_probe_deleted
    BEFORE UPDATE OF deleted ON pem.probe
    FOR EACH ROW EXECUTE PROCEDURE pem.custom_probe_deleted();

CREATE or REPLACE FUNCTION pem.alert_templates_probe_dependency_deletion() RETURNS TRIGGER AS $$
BEGIN
	UPDATE pem.alert_template SET probe_dependency_list = (select ARRAY_REMOVE(probe_dependency_list, OLD.internal_name));
	RETURN NEW;
END
$$ LANGUAGE plpgsql;

CREATE TRIGGER alert_templates_probe_dependency_deletion
    AFTER UPDATE OF deleted
    OR DELETE ON pem.probe
	FOR EACH ROW EXECUTE PROCEDURE pem.alert_templates_probe_dependency_deletion();

CREATE TABLE pem.probe_server_version (
	id					serial NOT NULL,
	probe_id			integer NOT NULL
		REFERENCES pem.probe (id) ON UPDATE RESTRICT ON DELETE CASCADE,
	server_version_id	integer NOT NULL
		REFERENCES pem.server_version (id)
		ON UPDATE RESTRICT ON DELETE CASCADE,
	probe_code			text,
	CONSTRAINT probe_server_version_pkey PRIMARY KEY (id),
	CONSTRAINT probe_server_version_unique UNIQUE (probe_id, server_version_id)
);

-- Add new table to store extension version specific probe details
CREATE TABLE pem.probe_extension_version (
	id					serial NOT NULL,
	probe_id			integer NOT NULL
		REFERENCES pem.probe (id) ON UPDATE RESTRICT ON DELETE CASCADE,
	server_version_id	integer
		REFERENCES pem.server_version (id)
		ON UPDATE RESTRICT ON DELETE CASCADE,
	extension_version	text NOT NULL,
	probe_code			text,
	CONSTRAINT probe_extension_version_pkey PRIMARY KEY (id),
	CONSTRAINT probe_extension_version_unique UNIQUE (probe_id, server_version_id, extension_version)
);

CREATE TABLE pem.probe_column (
	id					serial NOT NULL,
	probe_id			integer NOT NULL
		REFERENCES pem.probe (id) ON UPDATE RESTRICT ON DELETE CASCADE,
	internal_name		text NOT NULL,
	display_name		text NOT NULL,
	display_position	integer NOT NULL,
	classification		char NOT NULL,
	sql_data_type		text NOT NULL,
	unit_of_value		text,
	calculate_pit		boolean	NOT NULL DEFAULT false,
	discard_history		boolean NOT NULL DEFAULT false,
	pit_by_default		boolean NOT NULL DEFAULT false,
	is_graphable		boolean NOT NULL DEFAULT false,
	CONSTRAINT probe_parameter_pkey PRIMARY KEY (id),
	CONSTRAINT probe_parameter_unique UNIQUE (probe_id, internal_name),
	-- 'k' = key, 'm' = metric
	CONSTRAINT probe_column_classification CHECK (classification IN ('k', 'm')),
	CONSTRAINT pit_column_type_check CHECK (calculate_pit OR NOT discard_history),
	CONSTRAINT column_type_for_pit   CHECK (NOT calculate_pit OR sql_data_type IN ('bigint', 'integer', 'numeric', 'decimal', 'real', 'double precision'))
);

CREATE OR REPLACE FUNCTION pem.probe_column_trigger() RETURNS trigger AS $$
DECLARE
	pid integer;
	inl varchar[];
BEGIN
	pid := CASE WHEN TG_OP = 'DELETE' THEN OLD.probe_id ELSE NEW.probe_id END;
	SELECT array_agg(internal_name) INTO inl FROM (
		SELECT internal_name FROM pem.probe_column WHERE probe_id = pid
		AND classification = 'k' ORDER BY 1
	) x;
	UPDATE pem.probe SET probe_key_list = inl
		WHERE id = pid AND probe_key_list != inl;
	RETURN NULL;
END
$$ LANGUAGE plpgsql;

CREATE TRIGGER probe_column_trigger
	AFTER INSERT OR UPDATE OR DELETE ON pem.probe_column
	FOR EACH ROW EXECUTE PROCEDURE pem.probe_column_trigger();

CREATE OR REPLACE VIEW pem.probe_column_definition AS
SELECT
	id AS probe_id,
	'recorded_time'::text AS quoted_name,
	'timestamp with time zone not null DEFAULT now()'::text AS column_definition,
	'r'::text AS classification,
	-6::integer AS display_position,
	false::boolean AS calculate_pit,
	false::boolean AS discard_history
FROM
	pem.probe
UNION ALL
SELECT
	id AS probe_id,
	'agent_id'::text AS quoted_name,
	'integer not null REFERENCES pem.agent (id) ON UPDATE RESTRICT ON DELETE CASCADE'::text AS column_definition,
	'k'::text AS classification,
	-5::integer AS display_position,
	false::boolean AS calculate_pit,
	false::boolean AS discard_history
FROM
	pem.probe
WHERE
	target_type_id = 100
UNION ALL
SELECT
	id AS probe_id,
	'tool_id'::text AS quoted_name,
	'integer not null REFERENCES pem.tool (id) ON UPDATE RESTRICT ON DELETE CASCADE'::text AS column_definition,
	'k'::text AS classification,
	-4::integer AS display_position,
	false::boolean AS calculate_pit,
	false::boolean AS discard_history
FROM
	pem.probe
WHERE
	target_type_id = 150
UNION ALL
SELECT
	id AS probe_id,
	'server_id'::text AS quoted_name,
	'integer not null REFERENCES pem.server (id) ON UPDATE RESTRICT ON DELETE CASCADE'::text AS column_definition,
	'k'::text AS classification,
	-4::integer AS display_position,
	false::boolean AS calculate_pit,
	false::boolean AS discard_history
FROM
	pem.probe
WHERE
	target_type_id != 100 AND target_type_id != 150
UNION ALL
SELECT
	id AS probe_id,
	'database_name'::text AS quoted_name,
	'text not null'::text AS column_definition,
	'k'::text AS classification,
	-3::integer AS display_position,
	false::boolean AS calculate_pit,
	false::boolean AS discard_history
FROM
	pem.probe
WHERE
	target_type_id >= 300
UNION ALL
SELECT
	id AS probe_id,
	'schema_name'::text AS quoted_name,
	'text not null'::text AS column_definition,
	'k'::text AS classification,
	-2::integer AS display_position,
	false::boolean AS calculate_pit,
	false::boolean AS discard_history
FROM
	pem.probe
WHERE
	target_type_id >= 400 AND target_type_id != 1000
UNION ALL
SELECT
	probe.id AS probe_id,
	lower(probe_target_type.display_name) || '_name' AS quoted_name,
	'text not null'::text AS column_definition,
	'k'::text AS classification,
	-1::integer AS display_position,
	false::boolean AS calculate_pit,
	false::boolean AS discard_history
FROM
	pem.probe, pem.probe_target_type
WHERE
	probe.target_type_id = probe_target_type.id
	AND target_type_id IN (500,600,700,800,900)
UNION ALL
SELECT
	probe_id,
	quote_ident(internal_name) AS quoted_name,
	sql_data_type || CASE WHEN classification = 'k' THEN ' NOT NULL'
		ELSE '' END AS column_definition,
	classification,
	display_position,
	calculate_pit,
	discard_history
FROM
	pem.probe_column;

