CREATE SEQUENCE pem.agent_runtime_seq MINVALUE 0 MAXVALUE 999999999 CYCLE;

CREATE TABLE pem.agent_runtime (
	process_id		int4 NOT NULL,
	login_time		timestamptz NOT NULL DEFAULT current_timestamp,
	agent_id		integer NOT NULL
		REFERENCES pem.agent (id) ON UPDATE RESTRICT ON DELETE CASCADE,
	runtime_id bigint NOT NULL DEFAULT nextval('pem.agent_runtime_seq'),
	supported_schema        int NOT NULL DEFAULT 0,
	CONSTRAINT agent_runtime_pkey PRIMARY KEY (agent_id)
);
COMMENT ON TABLE pem.agent_runtime IS 'Active agents info';

-- Create the pem.jobagent view to make it work with the older version of
-- agents (i.e. < 201810021) for the backword compability
CREATE VIEW pem.jobagent AS
	SELECT
		ar.process_id AS jagpid, ar.login_time AS jaglogintime,
		ar.agent_id
	FROM pem.agent_runtime ar
	WHERE ar.supported_schema < 201810021;

CREATE RULE jobagent_insert AS ON INSERT TO pem.jobagent DO INSTEAD (
	INSERT INTO pem.agent_runtime (process_id, login_time, agent_id) VALUES (
		CASE WHEN NEW.jagpid IS NULL THEN pg_catalog.pg_backend_pid()
		ELSE NEW.jagpid END,
		CASE WHEN NEW.jaglogintime IS NULL THEN now() ELSE NEW.jaglogintime END,
		NEW.agent_id
	) RETURNING process_id AS jagpid, login_time AS jaglogintime, agent_id
);

CREATE RULE jobagent_delete AS ON DELETE TO pem.jobagent DO INSTEAD (
	DELETE FROM pem.agent_runtime ar WHERE OLD.jagpid = ar.process_id AND OLD.agent_id = ar.agent_id;
);

CREATE TYPE pem.notify_job_status AS ENUM(
	'DEFAULT',
	'NEVER',
	'ALWAYS',
	'ON_FAILURE'
);

COMMENT ON TYPE pem.notify_job_status IS 'Defines when to send an email';

CREATE TABLE pem.job (
	jobid				serial NOT NULL PRIMARY KEY,
	jobname				text NOT NULL,
	jobdesc				text NOT NULL DEFAULT '',
	agent_id			integer NOT NULL
		REFERENCES pem.agent (id) ON DELETE CASCADE ON UPDATE RESTRICT,
	jobenabled			bool NOT NULL DEFAULT true,
	jobcreated			timestamptz NOT NULL DEFAULT current_timestamp,
	jobchanged			timestamptz NOT NULL DEFAULT current_timestamp,
	jobprocessid			int4, -- Agent process-id
	jobnextrun			timestamptz,
	joblastrun			timestamptz,
	issystemjob			bool NOT NULL DEFAULT false,
	dependent_on_job	integer[] DEFAULT NULL,
	execute_on_dep_job_status	char NOT NULL
		CHECK (execute_on_dep_job_status IN ('s', 'f', 'i', 'd')) DEFAULT 's', -- s=successfully finished, f=failed, i=no steps to execute, d=aborted
	jobarid				integer, -- Agent Runtime-id
	notify				pem.notify_job_status NOT NULL DEFAULT 'DEFAULT',
	email_group_id      integer,
	is_global_job boolean DEFAULT false,
	is_alert_job boolean DEFAULT false
);
COMMENT ON TABLE pem.job IS 'Job main entry';
COMMENT ON COLUMN pem.job.jobprocessid IS 'PID of agent that currently executes this job.';
COMMENT ON COLUMN pem.job.jobarid IS 'Runtime-ID of agent that currently executes this job.';
COMMENT ON COLUMN pem.job.execute_on_dep_job_status IS 'Execute the job only when status of the dependent job is one of this: s=successfully finished, f=failed, i=no steps to execute, d=aborted';
COMMENT ON COLUMN pem.job.notify IS 'Notify on job status change';
COMMENT ON COLUMN pem.job.is_global_job IS 'Set if job is global job';
COMMENT ON COLUMN pem.job.email_group_id IS 'ID of the email_group to whom SMTP email to be send';

CREATE INDEX job_joblastrun_idx ON pem.job (joblastrun);

CREATE TABLE pem.jobstep (
	jstid				serial NOT NULL PRIMARY KEY,
	jstjobid			int4 NOT NULL
		REFERENCES pem.job (jobid) ON DELETE CASCADE ON UPDATE RESTRICT,
	jstname				text NOT NULL,
	jstdesc				text NOT NULL DEFAULT '',
	jstenabled			bool NOT NULL DEFAULT true,
	jstkind				char NOT NULL
		CHECK (jstkind IN ('b', 'i', 's')), -- batch, internal, sql
	jstcode				text NOT NULL,
	server_id			integer REFERENCES pem.server (id),
	database_name			text,
	jstonerror			char NOT NULL
		CHECK (jstonerror IN ('f', 's', 'i')) DEFAULT 'f', -- fail, success, ignore
	jstsetenvironment	bool NOT NULL DEFAULT false
);
CREATE INDEX jobstep_jobid ON pem.jobstep(jstjobid);
COMMENT ON TABLE pem.jobstep IS 'Job step to be executed';
COMMENT ON COLUMN pem.jobstep.jstkind IS 'Kind of jobstep: b=batch, i=internal, s=sql';
COMMENT ON COLUMN pem.jobstep.jstonerror IS 'What to do if step returns an error: f=fail the job, s=mark step as succeeded and continue, i=mark as fail but ignore it and proceed';

-- Function to fetch timezone of PEM database server
CREATE OR REPLACE FUNCTION pem.get_timezone() RETURNS text
LANGUAGE SQL AS
$$ SELECT current_setting('TIMEZONE')::text; $$;

CREATE TABLE pem.schedule (
	jscid				serial NOT NULL PRIMARY KEY,
	jscjobid			int4 NOT NULL
		REFERENCES pem.job (jobid) ON DELETE CASCADE ON UPDATE RESTRICT,
	jscname				text NOT NULL,
	jscdesc				text NOT NULL DEFAULT '',
	jscenabled			bool NOT NULL DEFAULT true,
	jscstart			timestamptz NOT NULL DEFAULT current_timestamp,
	jscend				timestamptz,
	jscminutes			bool[60] NOT NULL DEFAULT '{f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f}',
	jschours			bool[24] NOT NULL DEFAULT '{f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f}',
	jscweekdays			bool[7]  NOT NULL DEFAULT '{f,f,f,f,f,f,f}',
	jscmonthdays		bool[32] NOT NULL DEFAULT '{f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f}',
	jscmonths			bool[12] NOT NULL DEFAULT '{f,f,f,f,f,f,f,f,f,f,f,f}',
	jsctimezone         text NOT NULL DEFAULT pem.get_timezone(),
	CONSTRAINT schedule_jscminutes_size CHECK (array_upper(jscminutes, 1) = 60),
	CONSTRAINT schedule_jschours_size CHECK (array_upper(jschours, 1) = 24),
	CONSTRAINT schedule_jscweekdays_size CHECK (array_upper(jscweekdays, 1) = 7),
	CONSTRAINT schedule_jscmonthdays_size CHECK (array_upper(jscmonthdays, 1) = 32),
	CONSTRAINT schedule_jscmonths_size CHECK (array_upper(jscmonths, 1) = 12)
);
CREATE INDEX jobschedule_jobid ON pem.schedule(jscjobid);
COMMENT ON TABLE pem.schedule IS 'Schedule for a job';

CREATE TABLE pem.exception (
	jexid				serial NOT NULL PRIMARY KEY,
	jexscid				int4 NOT NULL
		REFERENCES pem.schedule (jscid) ON DELETE CASCADE ON UPDATE RESTRICT,
	jexdate				date,
	jextime				time
);
CREATE INDEX exception_jexscid ON pem.exception (jexscid);
CREATE UNIQUE INDEX exception_datetime ON pem.exception (jexdate, jextime);
COMMENT ON TABLE pem.schedule IS 'Job schedule exceptions';

CREATE SEQUENCE pem.joblog_jlgid_seq;
CREATE TABLE pem.joblog (
	jlgid				integer NOT NULL default nextval('pem.joblog_jlgid_seq'::regclass) PRIMARY KEY,
	jlgjobid			int4 NOT NULL
		REFERENCES pem.job (jobid) ON DELETE CASCADE ON UPDATE RESTRICT,
	jlgstatus			char NOT NULL DEFAULT 'r'
		CHECK (jlgstatus IN ('r', 's', 'f', 'i', 'd')),
	jlgstart			timestamptz NOT NULL DEFAULT current_timestamp,
	jlgduration			interval,
	jlgemailsent		boolean,
	jlgwebhookid integer[]
);
CREATE INDEX joblog_jobid ON pem.joblog(jlgjobid);
CREATE INDEX joblog_jlgstart_idx ON pem.joblog (jlgstart);

COMMENT ON TABLE pem.joblog IS 'Job run logs.';
COMMENT ON COLUMN pem.joblog.jlgstatus IS 'Status of job: r=running, s=successfully finished, f=failed, i=no steps to execute, d=aborted';

CREATE SEQUENCE pem.jobsteplog_jslid_seq;
CREATE TABLE pem.jobsteplog (
	jslid				integer NOT NULL default nextval('pem.jobsteplog_jslid_seq'::regclass) PRIMARY KEY,
	jsljlgid			int4 NOT NULL
		REFERENCES pem.joblog (jlgid) ON DELETE CASCADE ON UPDATE RESTRICT,
	jsljstid			int4 NOT NULL
		REFERENCES pem.jobstep (jstid) ON DELETE CASCADE ON UPDATE RESTRICT,
	jslstatus			char NOT NULL DEFAULT 'r'
		CHECK (jslstatus IN ('r', 's', 'i', 'f', 'd')),
	jslresult			int4,
	jslstart			timestamptz NOT NULL DEFAULT current_timestamp,
	jslduration			interval,
	jsloutput			text
);
CREATE INDEX jobsteplog_jslid ON pem.jobsteplog(jsljlgid);
COMMENT ON TABLE pem.jobsteplog IS 'Job step run logs.';
COMMENT ON COLUMN pem.jobsteplog.jslstatus IS 'Status of job step: r=running, s=successfully finished,  f=failed stopping job, i=ignored failure, d=aborted';
COMMENT ON COLUMN pem.jobsteplog.jslresult IS 'Return code of job step';

CREATE OR REPLACE FUNCTION pem.job_is_complete(dependent_on_job_ids integer[], execute_on_dep_job_status char, jobid integer default null) RETURNS BOOL AS $$
DECLARE
	res boolean := false;
	max_jlgid integer := null;
BEGIN
	-- Get the latest job log id for a job, which is about get execute
	-- Compare max_jlgid with dependent job jlgid, so that we don't execute job before dependent job is executed
	SELECT MAX(jlgid) into max_jlgid FROM pem.joblog WHERE jlgjobid = jobid;
	FOR i in 1..COALESCE(array_upper(dependent_on_job_ids, 1), 0) LOOP
		SELECT CASE WHEN (execute_on_dep_job_status = 'i' AND a.jlgstatus != 'r') OR execute_on_dep_job_status = a.jlgstatus THEN true ELSE false END INTO res
		FROM
		(
			SELECT l.jlgstatus jlgstatus
			FROM pem.job j
			LEFT JOIN pem.joblog l ON j.jobid = l.jlgjobid
			WHERE j.jobid = dependent_on_job_ids[i] and (l.jlgid > max_jlgid or max_jlgid is null)
			ORDER BY l.jlgstart DESC LIMIT 1
		) a;

		IF res = false or res is null THEN
			RETURN false;
		END IF;
	END LOOP;

	RETURN true;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION pem.next_schedule(int4, timestamptz, timestamptz, _bool, _bool, _bool, _bool, _bool) RETURNS timestamptz AS '
DECLARE
    jscid           ALIAS FOR $1;
    jscstart        ALIAS FOR $2;
    jscend          ALIAS FOR $3;
    jscminutes      ALIAS FOR $4;
    jschours        ALIAS FOR $5;
    jscweekdays     ALIAS FOR $6;
    jscmonthdays    ALIAS FOR $7;
    jscmonths       ALIAS FOR $8;

    nextrun         timestamptz := ''1970-01-01 00:00:00-00'';
    runafter        timestamp := ''1970-01-01 00:00:00-00'';

    bingo            bool := FALSE;
    gotit            bool := FALSE;
    foundval        bool := FALSE;
    daytweak        bool := FALSE;
    minutetweak        bool := FALSE;

    i                int2 := 0;
    d                int2 := 0;

    nextminute        int2 := 0;
    nexthour        int2 := 0;
    nextday            int2 := 0;
    nextmonth       int2 := 0;
    nextyear        int2 := 0;

BEGIN
    -- No valid start date has been specified
    IF jscstart IS NULL THEN RETURN NULL; END IF;

    -- The schedule is past its end date
    IF jscend IS NOT NULL AND jscend < now() THEN RETURN NULL; END IF;

    -- Get the time to find the next run after. It will just be the later of
    -- now() + 1m and the start date for the time being, however, we might want to
    -- do more complex things using this value in the future.
    IF date_trunc(''MINUTE'', jscstart) > date_trunc(''MINUTE'', (now() + ''1 Minute''::interval)) THEN
        runafter := date_trunc(''MINUTE'', jscstart);
    ELSE
        runafter := date_trunc(''MINUTE'', (now() + ''1 Minute''::interval));
    END IF;

    --
    -- Enter a loop, generating next run timestamps until we find one
    -- that falls on the required weekday, and is not matched by an exception
    --
    WHILE bingo = FALSE LOOP

        --
        -- Get the next run year
        --
        nextyear := date_part(''YEAR'', runafter);

        --
        -- Get the next run month
        --
        nextmonth := date_part(''MONTH'', runafter);
        gotit := FALSE;
        FOR i IN (nextmonth) .. 12 LOOP
            IF jscmonths[i] = TRUE THEN
                nextmonth := i;
                gotit := TRUE;
                foundval := TRUE;
                EXIT;
            END IF;
        END LOOP;
        IF gotit = FALSE THEN
            FOR i IN 1 .. (nextmonth - 1) LOOP
                IF jscmonths[i] = TRUE THEN
                    nextmonth := i;

                    -- Wrap into next year
                    nextyear := nextyear + 1;
                    gotit := TRUE;
                    foundval := TRUE;
                    EXIT;
                END IF;
           END LOOP;
        END IF;

        --
        -- Get the next run day
        --
        -- If the year, or month have incremented, get the lowest day,
        -- otherwise look for the next day matching or after today.
        IF (nextyear > date_part(''YEAR'', runafter) OR nextmonth > date_part(''MONTH'', runafter)) THEN
            nextday := 1;
            FOR i IN 1 .. 32 LOOP
                IF jscmonthdays[i] = TRUE THEN
                    nextday := i;
                    foundval := TRUE;
                    EXIT;
                END IF;
            END LOOP;
        ELSE
            nextday := date_part(''DAY'', runafter);
            gotit := FALSE;
            FOR i IN nextday .. 32 LOOP
                IF jscmonthdays[i] = TRUE THEN
                    nextday := i;
                    gotit := TRUE;
                    foundval := TRUE;
                    EXIT;
                END IF;
            END LOOP;
            IF gotit = FALSE THEN
                FOR i IN 1 .. (nextday - 1) LOOP
                    IF jscmonthdays[i] = TRUE THEN
                        nextday := i;

                        -- Wrap into next month
                        IF nextmonth = 12 THEN
                            nextyear := nextyear + 1;
                            nextmonth := 1;
                        ELSE
                            nextmonth := nextmonth + 1;
                        END IF;
                        gotit := TRUE;
                        foundval := TRUE;
                        EXIT;
                    END IF;
                END LOOP;
            END IF;
        END IF;

        -- Was the last day flag selected?
        IF nextday = 32 THEN
            IF nextmonth = 1 THEN
                nextday := 31;
            ELSIF nextmonth = 2 THEN
                IF pem.is_leap_year(nextyear) = TRUE THEN
                    nextday := 29;
                ELSE
                    nextday := 28;
                END IF;
            ELSIF nextmonth = 3 THEN
                nextday := 31;
            ELSIF nextmonth = 4 THEN
                nextday := 30;
            ELSIF nextmonth = 5 THEN
                nextday := 31;
            ELSIF nextmonth = 6 THEN
                nextday := 30;
            ELSIF nextmonth = 7 THEN
                nextday := 31;
            ELSIF nextmonth = 8 THEN
                nextday := 31;
            ELSIF nextmonth = 9 THEN
                nextday := 30;
            ELSIF nextmonth = 10 THEN
                nextday := 31;
            ELSIF nextmonth = 11 THEN
                nextday := 30;
            ELSIF nextmonth = 12 THEN
                nextday := 31;
            END IF;
        END IF;

        --
        -- Get the next run hour
        --
        -- If the year, month or day have incremented, get the lowest hour,
        -- otherwise look for the next hour matching or after the current one.
        IF (nextyear > date_part(''YEAR'', runafter) OR nextmonth > date_part(''MONTH'', runafter) OR nextday > date_part(''DAY'', runafter) OR daytweak = TRUE) THEN
            nexthour := 0;
            FOR i IN 1 .. 24 LOOP
                IF jschours[i] = TRUE THEN
                    nexthour := i - 1;
                    foundval := TRUE;
                    EXIT;
                END IF;
            END LOOP;
        ELSE
            nexthour := date_part(''HOUR'', runafter);
            gotit := FALSE;
            FOR i IN (nexthour + 1) .. 24 LOOP
                IF jschours[i] = TRUE THEN
                    nexthour := i - 1;
                    gotit := TRUE;
                    foundval := TRUE;
                    EXIT;
                END IF;
            END LOOP;
            IF gotit = FALSE THEN
                FOR i IN 1 .. nexthour LOOP
                    IF jschours[i] = TRUE THEN
                        nexthour := i - 1;

                        -- Wrap into next month
                        IF (nextmonth = 1 OR nextmonth = 3 OR nextmonth = 5 OR nextmonth = 7 OR nextmonth = 8 OR nextmonth = 10 OR nextmonth = 12) THEN
                            d = 31;
                        ELSIF (nextmonth = 4 OR nextmonth = 6 OR nextmonth = 9 OR nextmonth = 11) THEN
                            d = 30;
                        ELSE
                            IF pem.is_leap_year(nextyear) = TRUE THEN
                                d := 29;
                            ELSE
                                d := 28;
                            END IF;
                        END IF;

                        IF nextday = d THEN
                            nextday := 1;
                            IF nextmonth = 12 THEN
                                nextyear := nextyear + 1;
                                nextmonth := 1;
                            ELSE
                                nextmonth := nextmonth + 1;
                            END IF;
                        ELSE
                            nextday := nextday + 1;
                        END IF;

                        gotit := TRUE;
                        foundval := TRUE;
                        EXIT;
                    END IF;
                END LOOP;
            END IF;
        END IF;

        --
        -- Get the next run minute
        --
        -- If the year, month day or hour have incremented, get the lowest minute,
        -- otherwise look for the next minute matching or after the current one.
        IF (nextyear > date_part(''YEAR'', runafter) OR nextmonth > date_part(''MONTH'', runafter) OR nextday > date_part(''DAY'', runafter) OR nexthour > date_part(''HOUR'', runafter) OR daytweak = TRUE) THEN
            nextminute := 0;
            IF minutetweak = TRUE THEN
        d := 1;
            ELSE
        d := date_part(''MINUTE'', runafter)::int2;
            END IF;
            FOR i IN d .. 60 LOOP
                IF jscminutes[i] = TRUE THEN
                    nextminute := i - 1;
                    foundval := TRUE;
                    EXIT;
                END IF;
            END LOOP;
        ELSE
            nextminute := date_part(''MINUTE'', runafter);
            gotit := FALSE;
            FOR i IN (nextminute + 1) .. 60 LOOP
                IF jscminutes[i] = TRUE THEN
                    nextminute := i - 1;
                    gotit := TRUE;
                    foundval := TRUE;
                    EXIT;
                END IF;
            END LOOP;
            IF gotit = FALSE THEN
                FOR i IN 1 .. nextminute LOOP
                    IF jscminutes[i] = TRUE THEN
                        nextminute := i - 1;

                        -- Wrap into next hour
                        IF (nextmonth = 1 OR nextmonth = 3 OR nextmonth = 5 OR nextmonth = 7 OR nextmonth = 8 OR nextmonth = 10 OR nextmonth = 12) THEN
                            d = 31;
                        ELSIF (nextmonth = 4 OR nextmonth = 6 OR nextmonth = 9 OR nextmonth = 11) THEN
                            d = 30;
                        ELSE
                            IF pem.is_leap_year(nextyear) = TRUE THEN
                                d := 29;
                            ELSE
                                d := 28;
                            END IF;
                        END IF;

                        IF nexthour = 23 THEN
                            nexthour = 0;
                            IF nextday = d THEN
                                nextday := 1;
                                IF nextmonth = 12 THEN
                                    nextyear := nextyear + 1;
                                    nextmonth := 1;
                                ELSE
                                    nextmonth := nextmonth + 1;
                                END IF;
                            ELSE
                                nextday := nextday + 1;
                            END IF;
                        ELSE
                            nexthour := nexthour + 1;
                        END IF;

                        gotit := TRUE;
                        foundval := TRUE;
                        EXIT;
                    END IF;
                END LOOP;
            END IF;
        END IF;

        -- Build the result, and check it is not the same as runafter - this may
        -- happen if all array entries are set to false. In this case, add a minute.

        nextrun := (nextyear::varchar || ''-''::varchar || nextmonth::varchar || ''-'' || nextday::varchar || '' '' || nexthour::varchar || '':'' || nextminute::varchar)::timestamptz;

        IF nextrun = runafter AND foundval = FALSE THEN
                nextrun := nextrun + INTERVAL ''1 Minute'';
        END IF;

        -- If the result is past the end date, exit.
        IF nextrun > jscend THEN
            RETURN NULL;
        END IF;

        -- Check to ensure that the nextrun time is actually still valid. Its
        -- possible that wrapped values may have carried the nextrun onto an
        -- invalid time or date.
        IF ((jscminutes = ''{f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f}'' OR jscminutes[date_part(''MINUTE'', nextrun) + 1] = TRUE) AND
            (jschours = ''{f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f}'' OR jschours[date_part(''HOUR'', nextrun) + 1] = TRUE) AND
            (jscmonthdays = ''{f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f}'' OR jscmonthdays[date_part(''DAY'', nextrun)] = TRUE OR
            (jscmonthdays = ''{f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,t}'' AND
             ((date_part(''MONTH'', nextrun) IN (1,3,5,7,8,10,12) AND date_part(''DAY'', nextrun) = 31) OR
              (date_part(''MONTH'', nextrun) IN (4,6,9,11) AND date_part(''DAY'', nextrun) = 30) OR
              (date_part(''MONTH'', nextrun) = 2 AND ((pem.is_leap_year(date_part(''YEAR'', nextrun)::int2) AND date_part(''DAY'', nextrun) = 29) OR date_part(''DAY'', nextrun) = 28))))) AND
            (jscmonths = ''{f,f,f,f,f,f,f,f,f,f,f,f}'' OR jscmonths[date_part(''MONTH'', nextrun)] = TRUE)) THEN

            -- Now, check to see if the nextrun time found is a) on an acceptable
            -- weekday, and b) not matched by an exception. If not, set
            -- runafter = nextrun and try again.

            -- Check for a wildcard weekday
            gotit := FALSE;
            FOR i IN 1 .. 7 LOOP
                IF jscweekdays[i] = TRUE THEN
                    gotit := TRUE;
                    EXIT;
                END IF;
            END LOOP;

            -- OK, is the correct weekday selected, or a wildcard?
            IF (jscweekdays[date_part(''DOW'', nextrun) + 1] = TRUE OR gotit = FALSE) THEN

                -- Check for exceptions
                SELECT INTO d jexid FROM pem.exception WHERE jexscid = jscid AND ((jexdate = pg_catalog.date(nextrun) AND jextime = nextrun::time) OR (jexdate = pg_catalog.date(nextrun) AND jextime IS NULL) OR (jexdate IS NULL AND jextime = nextrun::time));
                IF FOUND THEN
                    -- Nuts - found an exception. Increment the time and try again
                    runafter := nextrun + INTERVAL ''1 Minute'';
                    bingo := FALSE;
                    minutetweak := TRUE;
            daytweak := FALSE;
                ELSE
                    bingo := TRUE;
                END IF;
            ELSE
                -- We''re on the wrong week day - increment a day and try again.
                runafter := nextrun + INTERVAL ''1 Day'';
                bingo := FALSE;
                minutetweak := FALSE;
                daytweak := TRUE;
            END IF;

        ELSE
            runafter := nextrun + INTERVAL ''1 Minute'';
            bingo := FALSE;
            minutetweak := TRUE;
        daytweak := FALSE;
        END IF;

    END LOOP;

    RETURN nextrun;
END;
' LANGUAGE 'plpgsql' VOLATILE;
COMMENT ON FUNCTION pem.next_schedule(int4, timestamptz, timestamptz, _bool, _bool, _bool, _bool, _bool) IS 'Calculates the next runtime for a given schedule';

--
-- Test code
--
-- SELECT pem.next_schedule(
--     2, -- Schedule ID
--     '2005-01-01 00:00:00', -- Start date
--     '2006-10-01 00:00:00', -- End date
--     '{f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f}', -- Minutes
--     '{f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f}', -- Hours
--     '{f,f,f,f,f,f,f}', -- Weekdays
--     '{f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f}', -- Monthdays
--     '{f,f,f,f,f,f,f,f,f,f,f,f}' -- Months
-- );

CREATE OR REPLACE FUNCTION pem.is_leap_year(int2) RETURNS bool AS '
BEGIN
    IF $1 % 4 != 0 THEN
        RETURN FALSE;
    END IF;
    IF $1 % 100 != 0 THEN
        RETURN TRUE;
    END IF;
    RETURN $1 % 400 = 0;
END;
' LANGUAGE 'plpgsql' IMMUTABLE;
COMMENT ON FUNCTION pem.is_leap_year(int2) IS 'Returns TRUE if $1 is a leap year';

CREATE OR REPLACE FUNCTION pem.job_trigger()
  RETURNS "trigger" AS
$$
DECLARE
    db_timezone text := NULL;
    server_config_timezone text := NULL;
    job_timezone text := NULL;
    job_tz text := NULL;
BEGIN
    IF NEW.jobenabled THEN
        IF NEW.jobnextrun IS NULL THEN
            -- Fetch required timezone values for the job
            SELECT jsctimezone INTO job_timezone
                FROM pem.schedule ps
                WHERE jscenabled AND jscjobid=OLD.jobid;

            -- If job is pem system/in-built job
            IF OLD.issystemjob THEN
                SELECT pem.get_timezone() INTO db_timezone;
                SELECT TRIM(value) INTO server_config_timezone
                    FROM pem.config WHERE param = 'timezone_for_system_jobs';

                job_tz := db_timezone;
                -- We will override the db_time if user has set the different value in System config dialog
                IF db_timezone != server_config_timezone THEN
                    job_tz := server_config_timezone;
                END IF;
            ELSE
                job_tz := job_timezone;
            END IF;

            -- Set the appropriate timezone for current transaction, it won't affect database server timezone
            IF job_tz IS NOT NULL AND job_tz != '' THEN
                EXECUTE 'SET LOCAL TIME ZONE ''' || job_tz || ''';' ;
            END IF;

            SELECT INTO NEW.jobnextrun
                MIN(pem.next_schedule(jscid, jscstart, jscend, jscminutes, jschours, jscweekdays, jscmonthdays, jscmonths))
            FROM pem.schedule
            WHERE jscenabled AND jscjobid=OLD.jobid;
        END IF;
    ELSE
        NEW.jobnextrun := NULL;
    END IF;
    RETURN NEW;
END;
$$
  LANGUAGE 'plpgsql' VOLATILE;
COMMENT ON FUNCTION pem.job_trigger() IS 'Update the job''s next run time.';

CREATE TRIGGER job_trigger BEFORE UPDATE
	ON pem.job FOR EACH ROW
	EXECUTE PROCEDURE pem.job_trigger();
COMMENT ON TRIGGER job_trigger ON pem.job IS 'Update the job''s next run time.';

CREATE OR REPLACE FUNCTION pem.schedule_trigger() RETURNS trigger AS '
BEGIN
    IF TG_OP = ''DELETE'' THEN
        -- update job from remaining schedules
        -- the actual calculation of jobnextrun will be performed in the trigger
        UPDATE pem.job
           SET jobnextrun = NULL
         WHERE jobenabled AND jobid=OLD.jscjobid;
        RETURN OLD;
    ELSE
        UPDATE pem.job
           SET jobnextrun = NULL
         WHERE jobenabled AND jobid=NEW.jscjobid;
        RETURN NEW;
    END IF;
END;
' LANGUAGE 'plpgsql';
COMMENT ON FUNCTION pem.schedule_trigger() IS 'Update the job''s next run time whenever a schedule changes';

CREATE TRIGGER schedule_trigger AFTER INSERT OR UPDATE OR DELETE
	ON pem.schedule FOR EACH ROW
	EXECUTE PROCEDURE pem.schedule_trigger();
COMMENT ON TRIGGER schedule_trigger ON pem.schedule IS 'Update the job''s next run time whenever a schedule changes';

CREATE OR REPLACE FUNCTION pem.exception_trigger() RETURNS "trigger" AS '
DECLARE
    jid int4 := 0;
BEGIN
     IF TG_OP = ''DELETE'' THEN
        SELECT INTO jid jscjobid FROM pem.schedule WHERE jscid = OLD.jexscid;
        -- update job from remaining schedules
        -- the actual calculation of jobnextrun will be performed in the trigger
        UPDATE pem.job
           SET jobnextrun = NULL
         WHERE jobenabled AND jobid=jid;
        RETURN OLD;
    ELSE
        SELECT INTO jid jscjobid FROM pem.schedule WHERE jscid = NEW.jexscid;
        UPDATE pem.job
           SET jobnextrun = NULL
         WHERE jobenabled AND jobid=jid;
        RETURN NEW;
    END IF;
END;
' LANGUAGE 'plpgsql' VOLATILE;
COMMENT ON FUNCTION pem.exception_trigger() IS 'Update the job''s next run time whenever an exception changes';

CREATE TRIGGER exception_trigger AFTER INSERT OR UPDATE OR DELETE
	ON pem.exception FOR EACH ROW
	EXECUTE PROCEDURE pem.exception_trigger();
COMMENT ON TRIGGER exception_trigger ON pem.exception IS
	'Update the job''s next run time whenever an exception changes';

