-- ----------------
-- FUNCTION: pem.create_pem_server_system_tasks()
--
-- It will create the system jobs for these agent & server combination.
-- They will be disabled by default.
-- When leader is found automatically as a 'standalone' or 'primary', it will
-- enable these system jobs.
--
CREATE OR REPLACE FUNCTION pem.create_pem_server_system_tasks()
    RETURNS void AS
    $FUNC$
    DECLARE
        rec RECORD;
    BEGIN
        FOR rec IN SELECT * FROM pem.pem_host_and_server
        LOOP
            -- Call all the sub-functions with explicit parameters for each record
            PERFORM pem.create_pem_server_system_tasks_data_cleanup(rec.agent_id, rec.server_id, rec.database, rec.is_leader);
            PERFORM pem.create_pem_server_system_tasks_update_probes(rec.agent_id, rec.server_id, rec.database, rec.is_leader);
            PERFORM pem.create_pem_server_system_tasks_log_cleanup(rec.agent_id, rec.server_id, rec.database, rec.is_leader);
            PERFORM pem.create_pem_server_system_tasks_purge_deleted(rec.agent_id, rec.server_id, rec.database, rec.is_leader);
            PERFORM pem.create_pem_server_system_tasks_check_ca_certificate_expiry(rec.agent_id, rec.server_id, rec.database, rec.is_leader);
            PERFORM pem.create_pem_server_system_tasks_blackout_unreachable_servers(rec.agent_id, rec.server_id, rec.database, rec.is_leader);
			PERFORM pem.create_pem_server_system_tasks_refresh_probe_view(rec.agent_id, rec.server_id, rec.database, rec.is_leader);
        END LOOP;
    END
    $FUNC$ LANGUAGE 'plpgsql';

-- ----------------
-- TRIGGER FUNCTION: pem.pem_host_and_server_updated()
--
--   It calls the 'pem.create_pem_server_system_tasks()' function.
--
CREATE OR REPLACE FUNCTION pem.pem_host_and_server_updated()
  RETURNS TRIGGER AS
$FUNC$
BEGIN
    PERFORM pem.create_pem_server_system_tasks();
    RETURN NULL;
END
$FUNC$ LANGUAGE 'plpgsql';


---------
-- Trigger: pem_host_and_server_change
-- Table: pem.pem_host_and_server
-- Event: insert or update or delete (statement level)
--
--   Execute 'pem.pem_host_and_server_updated(...)' trigger function to
--   create the system jobs for this server and agent.
--
CREATE TRIGGER pem_host_and_server_change
	AFTER INSERT OR UPDATE OR DELETE ON pem.pem_host_and_server
	FOR EACH STATEMENT
	EXECUTE FUNCTION pem.pem_host_and_server_updated();

-- Unreachable server timeout value will be used for blacking out the servers/agents
INSERT INTO pem.config (param, value, unit, datatype) VALUES (
	'server_contact_timeout', 48, 'hours', 'integer'
	);

-- ==========================================================
-- Function: pem.auto_blackout
-- Description:
-- Function which will automatically blackouts servers or agents
-- that are no longer reachable.
-- ==========================================================
CREATE OR REPLACE FUNCTION pem.auto_blackout()
RETURNS void AS
$FUNC$
DECLARE
    v_timeout_value   INTEGER;
BEGIN
    --
    -- Fetch the server contact timeout value from the configuration table.
    -- The value is assumed to be in hours.
    --
    SELECT value
    INTO v_timeout_value
    FROM pem.config
    WHERE param = 'server_contact_timeout';

    --
    -- 1. Blackout servers when the last heartbeat is older than the configured timeout in hours.
    --
    UPDATE pem.server s
    SET
        alert_blackout = true,
        auto_alert_blackout = true
    FROM pem.server_heartbeat sh
    WHERE
        s.id = sh.server_id
        AND sh.last_heartbeat < NOW() - (v_timeout_value || ' hours')::interval;

    --
    -- 2. Un-blackout servers only if the blackout was system-initiated.
    --
    UPDATE pem.server s
    SET
        alert_blackout = false,
        auto_alert_blackout = false
    FROM pem.server_heartbeat sh
    WHERE
        s.id = sh.server_id
        AND sh.last_heartbeat >= NOW() - (v_timeout_value || ' hours')::interval
        AND s.auto_alert_blackout = true;

    --
    -- 3. Blackout agents when the last heartbeat is older than the configured timeout in hours.
    --
    UPDATE pem.agent a
    SET
        alert_blackout = true,
        auto_alert_blackout = true
    FROM pem.agent_heartbeat ah
    WHERE
        a.id = ah.agent_id
        AND ah.last_heartbeat < NOW() - (v_timeout_value || ' hours')::interval;

    --
    -- 4. Un-blackout agents only if the blackout was system-initiated.
    --
    UPDATE pem.agent a
    SET
        alert_blackout = false,
        auto_alert_blackout = false
    FROM pem.agent_heartbeat ah
    WHERE
        a.id = ah.agent_id
        AND ah.last_heartbeat >= NOW() - (v_timeout_value || ' hours')::interval
        AND a.auto_alert_blackout = true;
END
$FUNC$ LANGUAGE 'plpgsql';

CREATE TABLE pem.probe_schedule (
	probe_id			integer NOT NULL,
	parameter_value_list text[] NOT NULL,
	random_seed			integer NOT NULL DEFAULT random()*2000000000,
	last_execution_time timestamptz NOT NULL DEFAULT current_timestamp,
	current_backend_pid	integer,
	agent_id		integer,
	CONSTRAINT probe_schedule_pkey
		PRIMARY KEY (probe_id, parameter_value_list)
);

CREATE INDEX probe_schedule_pid ON pem.probe_schedule (current_backend_pid)
	WHERE current_backend_pid IS NOT NULL;
CREATE INDEX probe_schedule_agent_id_idx ON pem.probe_schedule (agent_id);

CREATE OR REPLACE FUNCTION pem.clear_probe_zombies(agent_id integer = NULL)
RETURNS void AS $FUNC$
BEGIN
	-- New agents will clear from its own zombie probes
	IF agent_id IS NOT NULL THEN
		UPDATE pem.probe_schedule s
		SET current_backend_pid = NULL, agent_id = NULL WHERE s.agent_id = $1;
		-- Clear all probes with no agent attached.
		UPDATE pem.probe_schedule s
		SET current_backend_pid = NULL
		WHERE current_backend_pid is not NULL AND s.agent_id IS NULL;
	ELSE
		WITH pids (pid) AS (
			SELECT ps.current_backend_pid FROM pem.probe_schedule AS ps
			WHERE NOT EXISTS (
				SELECT 1 FROM pg_catalog.pg_stat_activity AS a
				WHERE a.pid = ps.current_backend_pid
			)
			ORDER BY ps.current_backend_pid
			FOR UPDATE SKIP LOCKED
		)
		UPDATE pem.probe_schedule AS ps SET current_backend_pid = NULL, agent_id = NULL
		WHERE ps.current_backend_pid IN (SELECT pid FROM pids);
	END IF;
END;
$FUNC$ LANGUAGE 'plpgsql';

CREATE OR REPLACE FUNCTION pem.clear_job_zombies(integer) RETURNS void AS
$FUNC$
DECLARE
	agent_runtime_id integer := NULL;
BEGIN
	SELECT runtime_id INTO agent_runtime_id FROM pem.agent_runtime ar
	WHERE ar.agent_id = $1;

	WITH running_agent_job AS (
		SELECT j.jobid, j.agent_id
		FROM pem.job j LEFT JOIN pem.joblog jl ON (j.jobid = jl.jlgjobid)
		WHERE jl.jlgstatus = 'r' AND agent_id = $1 AND j.jobarid != agent_runtime_id
		ORDER BY j.jobid, jl.jlgjobid
		FOR UPDATE SKIP LOCKED
	), joblog_status_update AS (
		UPDATE pem.joblog jl SET jlgstatus='d'
		FROM running_agent_job r
		WHERE r.jobid = jl.jlgjobid AND jl.jlgstatus='r'
		RETURNING r.agent_id, jl.jlgjobid, jl.jlgid
	), jobsteplog_status_update AS (
		UPDATE pem.jobsteplog js SET jslstatus='d'
		FROM joblog_status_update jl
		WHERE js.jsljlgid = jl.jlgid AND js.jslstatus='r'
		RETURNING jl.agent_id, jl.jlgjobid AS job_id
	)
	UPDATE pem.job j SET jobprocessid=NULL, jobnextrun=NULL, jobarid=NULL
	FROM (SELECT DISTINCT agent_id, job_id FROM jobsteplog_status_update) js
	WHERE js.job_id = j.jobid;
END;
$FUNC$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION pem.lock_schedule_table(_probe_id integer, _parameter_value_list text[])
RETURNS boolean AS $BODY$
DECLARE
    _current_backend_pid integer;
BEGIN
    -- Find out if this record already exists
    SELECT current_backend_pid INTO _current_backend_pid FROM pem.probe_schedule WHERE probe_id=$1 AND parameter_value_list = $2;

    -- If not exists insert it
    IF NOT FOUND THEN
        INSERT INTO pem.probe_schedule(probe_id, parameter_value_list, current_backend_pid) VALUES ($1, $2, pg_backend_pid()::integer);
    ELSE
        IF _current_backend_pid IS NULL THEN
            -- Update the probe_schedule table and lock by the current process
            UPDATE pem.probe_schedule SET current_backend_pid=pg_backend_pid()::integer WHERE probe_id=$1 AND parameter_value_list=$2;
        ELSE
            -- We can not lock a probe for which current_backend_pid is not NULL (It means - it is already been locked.)
            RETURN false;
        END IF;
    END IF;
    RETURN true;
END
$BODY$ LANGUAGE plpgsql;


CREATE OR REPLACE FUNCTION pem.lock_agent_probe_schedule_table(
	_agent_id integer, _probe_id integer, _parameter_value_list text[]
) RETURNS boolean AS $BODY$
DECLARE
    _current_agent_id integer;
BEGIN
    -- Find out if this record already exists
    SELECT agent_id INTO _current_agent_id FROM pem.probe_schedule WHERE probe_id=$2 AND parameter_value_list = $3;

    -- If not exists insert it
    IF NOT FOUND THEN
        INSERT INTO pem.probe_schedule(probe_id, parameter_value_list, agent_id) VALUES ($2, $3, _agent_id);
    ELSE
        IF _current_agent_id IS NULL OR _current_agent_id != _agent_id THEN
            -- Update the probe_schedule table and lock by the current process
            UPDATE pem.probe_schedule SET current_backend_pid=NULL, agent_id=_agent_id WHERE probe_id=$2 AND parameter_value_list=$3;
        ELSE
            -- We can not lock a probe for which current_backend_pid is not NULL (It means - it is already been locked.)
            RETURN false;
        END IF;
    END IF;
    RETURN true;
END
$BODY$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION pem.create_data_and_history_tables()
  RETURNS void AS $BODY$
DECLARE
    curs_table CURSOR FOR
		SELECT id, internal_name, target_type_id, discard_history FROM pem.probe as pr
			WHERE NOT EXISTS
			(SELECT 1 FROM pg_class, pg_namespace WHERE pg_namespace.oid =
			 pg_class.relnamespace AND pg_namespace.nspname = 'pemdata' AND
			 pg_class.relname = pr.internal_name);
	r RECORD;
    quoted_table_name varchar;
    trigger_function_command varchar;
    trigger_command varchar;
BEGIN
    -- Loop through tables that are not present in pemdata schema, but defined
	-- in pem.probe table.
    FOR probe_table_name IN curs_table LOOP
	    quoted_table_name := quote_ident(probe_table_name.internal_name);

		SELECT INTO r
			-- PIT value trigger definition
			string_agg(
				CASE WHEN calculate_pit THEN
					'        NEW.' || quoted_name || E'_pit := 0;\n        IF NEW.' || quoted_name || ' - OLD.' || quoted_name || E' >= 0 THEN\n'
					|| '            NEW.' || quoted_name || '_pit :=  NEW.' || quoted_name || ' - OLD.' || quoted_name || E';\n        END IF;'
				END, E'\n')
			    AS data_trigger_clause,
			-- Data table create definition
			string_agg(
				CASE WHEN NOT calculate_pit THEN
					quoted_name || ' ' || column_definition
				ELSE
					quoted_name || ' ' || column_definition || ', ' || quoted_name || '_pit ' || column_definition
				END, ', ')
			    AS create_table_clause,
			-- History table create definition
			string_agg(
				CASE WHEN NOT discard_history THEN
					CASE WHEN NOT calculate_pit THEN
						quoted_name || ' ' || column_definition
					ELSE
						quoted_name || ' ' || column_definition || ', ' || quoted_name || '_pit ' || column_definition
					END
				ELSE
					CASE WHEN calculate_pit THEN
						quoted_name || '_pit ' || column_definition
					END
				END, ', ')
			    AS create_history_table_clause,
			-- Insert/Update history table definition
			string_agg(
			        CASE WHEN NOT discard_history THEN
					CASE WHEN NOT calculate_pit THEN
						quoted_name
					ELSE
						quoted_name || ', ' || quoted_name || '_pit'
					END
				ELSE
					CASE WHEN calculate_pit THEN
						quoted_name || '_pit'
					END
				END, ', ')
			    AS column_string,
			-- Insert/Update history table definition
			string_agg(
				CASE WHEN NOT discard_history THEN
					CASE WHEN NOT calculate_pit THEN
						'NEW.' || quoted_name
					ELSE
						'NEW.' || quoted_name || ', NEW.' || quoted_name || '_pit'
					END
				ELSE
					CASE WHEN calculate_pit THEN
						'NEW.' || quoted_name || '_pit'
					END
				END, ', ')
			    AS new_column_string,
			string_agg(CASE WHEN classification = 'k' THEN quoted_name END,
				', ') AS key_string,
			string_agg(CASE WHEN classification = 'k' THEN 'OLD.'
				|| quoted_name END, ', ') AS old_key_string
			FROM
			    (SELECT * FROM pem.probe_column_definition
					ORDER BY display_position) x
			WHERE
				probe_id = probe_table_name.id;

		IF COALESCE(r.create_table_clause, '') = ''
			OR COALESCE(r.key_string, '') = '' THEN
			RAISE EXCEPTION 'data table has no defined columns: %',
				probe_table_name.id;
		END IF;

		IF COALESCE(r.create_history_table_clause, '') = ''
			OR COALESCE(r.key_string, '') = '' THEN
			RAISE EXCEPTION 'history table has no defined columns: %',
				probe_table_name.id;
		END IF;

		EXECUTE 'CREATE TABLE pemdata.' || quoted_table_name || ' ('
			|| r.create_table_clause || ', PRIMARY KEY ('
			|| r.key_string || '))';

                -- Give permission to pem_user, pem_agent and pem_admin
		EXECUTE 'GRANT SELECT ON TABLE pemdata.' || quoted_table_name || ' TO pem_user;';
		EXECUTE 'GRANT ALL ON TABLE pemdata.' || quoted_table_name || ' TO pem_admin;';
		EXECUTE 'GRANT SELECT, UPDATE, INSERT, DELETE ON TABLE pemdata.' || quoted_table_name || ' TO pem_agent;';

		IF NOT probe_table_name.discard_history THEN
			EXECUTE 'CREATE TABLE pemhistory.' || quoted_table_name || ' ('
				|| r.create_history_table_clause || ', PRIMARY KEY ('
				|| r.key_string || ', recorded_time))';

	                -- Give permission to pem_user, pem_agent and pem_admin
			EXECUTE 'GRANT SELECT ON TABLE pemhistory.' || quoted_table_name || ' TO pem_user;';
			EXECUTE 'GRANT ALL ON TABLE pemhistory.' || quoted_table_name || ' TO pem_admin;';
			EXECUTE 'GRANT SELECT, UPDATE, INSERT, DELETE ON TABLE pemhistory.' || quoted_table_name || ' TO pem_agent;';

			EXECUTE 'CREATE INDEX '
				|| quote_ident(probe_table_name.internal_name || '_timeidx')
				|| ' ON ' || 'pemhistory.' || quoted_table_name
				|| ' (recorded_time)';

			-- Trigger Function Command String
			trigger_function_command := 'CREATE OR REPLACE FUNCTION pemdata.' ||  quote_ident('copy_' || probe_table_name.internal_name || '_to_history') || '() RETURNS TRIGGER AS $$
			BEGIN
				IF (TG_OP = ''INSERT'' OR TG_OP = ''UPDATE'') THEN
					INSERT INTO pemhistory.' || quoted_table_name || ' (' || r.column_string || ') VALUES (' || r.new_column_string || ');
					ELSIF EXISTS(SELECT 1 FROM ' || CASE WHEN probe_table_name.target_type_id = 100 THEN 'pem.agent WHERE id = OLD.agent_id' WHEN probe_table_name.target_type_id = 150 THEN 'pem.tool WHERE id = OLD.tool_id' ELSE 'pem.server WHERE id = OLD.server_id' END || ') THEN
					INSERT INTO pemhistory.' || quoted_table_name || ' (' || r.key_string || ') VALUES (' || r.old_key_string || ');
				END IF;
				RETURN NEW;
			END;
			$$ LANGUAGE plpgsql;';

			-- Trigger Command String
			trigger_command := 'CREATE TRIGGER ' || quote_ident('copy_' || probe_table_name.internal_name || '_to_history') || ' AFTER INSERT OR UPDATE OR DELETE ON pemdata.' || quoted_table_name || ' FOR EACH ROW EXECUTE PROCEDURE pemdata.' || quote_ident('copy_' || probe_table_name.internal_name || '_to_history') || '()' ;

			-- Execute the commands.
			EXECUTE trigger_function_command;
			EXECUTE trigger_command;
		END IF;

	    -- Trigger Function for calculating PIT values definition
	    IF COALESCE(r.data_trigger_clause, '') != ''
	    THEN
		-- Trigger Function Command String
		trigger_function_command := 'CREATE OR REPLACE FUNCTION pemdata.' ||  quote_ident('calculate_' || probe_table_name.internal_name || '_pit_value') || E'() RETURNS TRIGGER AS $$
BEGIN
    IF (TG_OP = ''UPDATE'') THEN \n'
	 ||  r.data_trigger_clause ||
    E'\n    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;';

		-- Trigger Command String
		trigger_command := 'CREATE TRIGGER ' || quote_ident('calculate_' || probe_table_name.internal_name || '_pit_value') || ' BEFORE UPDATE ON pemdata.' || quoted_table_name || ' FOR EACH ROW EXECUTE PROCEDURE pemdata.' || quote_ident('calculate_' || probe_table_name.internal_name || '_pit_value') || '()' ;

		-- Execute the commands.
		EXECUTE trigger_function_command;
	        EXECUTE trigger_command;
	    END IF;

    END LOOP;
END;
$BODY$ LANGUAGE plpgsql;

-- Adding the foreign key constraint for pem.probe (jstid) refering to
-- pem.jobstep (jstid) now, as pem.jobstep was not present during the
-- creation of that table.
ALTER TABLE pem.probe ADD CONSTRAINT
	probe_purge_jobstep_id_fkey FOREIGN KEY (jstid)
	REFERENCES pem.jobstep(jstid) ON UPDATE NO ACTION;

--
-- TABLE: pem.probe_objects_combo
--
-- Keeps track of the combination of the probe-id, parameter_value_list.
-- It will release the
-- parameters combination to avoid the unnecessary locks during the
-- whole purging process to make things smoother.
CREATE TABLE pem.probe_objects_combo (
	pid       integer NOT NULL,
	objects   text[] NOT NULL,
	lifetime  integer NOT NULL,
	purged_on timestamptz,
	delete_on date,
	PRIMARY KEY (pid, objects),
	CONSTRAINT purge_probe_tasks_pid_fkey FOREIGN KEY (pid)
		REFERENCES pem.probe(id) MATCH SIMPLE
		ON UPDATE CASCADE ON DELETE CASCADE INITIALLY DEFERRED
);

CREATE OR REPLACE FUNCTION pem.purge_probe_history(_pid integer)
RETURNS void
LANGUAGE plpgsql
AS $function$
    DECLARE
        r	record;
    BEGIN
        FOR r IN

            WITH
                target_types (id, parameter_list) AS (
                    VALUES  ( 100, ARRAY['agent_id']),
                        ( 150, ARRAY['tool_id']),
                        ( 200, ARRAY['server_id']),
                        ( 300, ARRAY['server_id', 'database_name']),
                        (1000, ARRAY['server_id', 'database_name']),
                        ( 400, ARRAY['server_id', 'database_name', 'schema_name'])
                )
            SELECT
                format($sql$DELETE FROM %I.%I AS d WHERE ROW(%s) IN (%s) AND d.recorded_time <= now() - %s * interval '1d'$sql$,
                    nsp.nspname,
                    rel.relname,
                    array_to_string(tt.parameter_list, ', '),
                    string_agg(objs.objects, ', '),
                    combo.lifetime) AS sql
            FROM pem.probe AS p
                JOIN pg_class AS rel ON rel.relname = p.internal_name
                JOIN pg_namespace AS nsp ON nsp.oid = rel.relnamespace
                JOIN pem.probe_objects_combo AS combo ON combo.pid = p.id
                JOIN target_types AS tt ON tt.id = p.target_type_id
                CROSS JOIN LATERAL (
                    /* Map quote_literal over each value of the `objects` array */
                    SELECT 'ROW(' || string_agg(quote_literal(objs.obj), ', ' ORDER BY objs.ord) || ')'
                    FROM UNNEST(combo.objects) WITH ORDINALITY AS objs (obj, ord)
                ) AS objs (objects)
            WHERE p.id = _pid
              AND nsp.nspname = 'pemhistory'
            GROUP BY p.id, nsp.nspname, rel.relname, tt.parameter_list, combo.lifetime

        LOOP
            EXECUTE r.sql;
        END LOOP;

        UPDATE pem.probe_objects_combo SET purged_on = now() WHERE pid = _pid;
    END;
$function$;

--
-- TRIGGER FUNCTION: pem.run_job_to_update_probe_objects_combo()
--
-- This trigger function will update the job to update the purge jobsteps in
-- 24 hours.
CREATE OR REPLACE FUNCTION pem.run_job_to_update_probe_objects_combo()
	RETURNS trigger AS
$function$
DECLARE
	needs_update boolean;
BEGIN
	-- We will not update the purge job tasks immediately, there is
	-- no requirement to do it immediately.
	EXECUTE $SQL$
		UPDATE pem.job
			SET jobnextrun = now() + INTERVAL '10 minutes'
			WHERE jobname = 'Update the probe-objects combination' AND issystemjob AND (
				jobnextrun IS NULL OR jobnextrun < now()
			)
			$SQL$;
	RETURN NEW;
END;
$function$ LANGUAGE 'plpgsql' SECURITY DEFINER;

-- Trigger to add the tags primary/replica based on the node_type in server_info
CREATE OR REPLACE FUNCTION pem.update_server_node_type_info()
RETURNS TRIGGER AS $$
DECLARE
	primary_color text := '#008000';   -- Green
	replica_color text := '#737373';   -- Dark Grey
BEGIN

	-- Update is_leader field for non-replica nodes
	IF (
			TG_OP = 'INSERT' OR (TG_OP = 'UPDATE' AND NEW.node_type <> OLD.node_type)
		)
		AND NEW.node_type = ANY('{standalone, primary}'::text[])
		AND EXISTS (
			SELECT 1 FROM pem.pem_host_and_server WHERE server_id = NEW.server_id
		)
	THEN
		UPDATE pem.pem_host_and_server
			SET is_leader = (server_id = NEW.server_id)::boolean;
	END IF;

	-- Add or remove tags based on node_type changes
	IF TG_OP = 'INSERT' OR TG_OP = 'UPDATE' THEN
		-- Skip processing if server has 'bdr' extension
		IF EXISTS (
			SELECT 1
				FROM pemdata.oc_extension
				WHERE server_id = NEW.server_id AND extension_name = 'bdr'
			) THEN
			RETURN NEW;
		END IF;

		-- PRIMARY tag handling
		IF NEW.node_type = 'primary' AND (TG_OP = 'INSERT' OR OLD.node_type != 'primary') THEN
			PERFORM pem.add_server_tag(NEW.server_id, 'primary', primary_color);
		ELSIF TG_OP = 'UPDATE' AND OLD.node_type = 'primary' AND NEW.node_type != 'primary' THEN
			PERFORM pem.remove_server_tag(NEW.server_id, 'primary');
		END IF;

		-- REPLICA tag handling
		IF NEW.node_type = 'replica' AND (TG_OP = 'INSERT' OR OLD.node_type != 'replica') THEN
			PERFORM pem.add_server_tag(NEW.server_id, 'replica', replica_color);
		ELSIF TG_OP = 'UPDATE' AND OLD.node_type = 'replica' AND NEW.node_type != 'replica' THEN
			PERFORM pem.remove_server_tag(NEW.server_id, 'replica');
		END IF;
	END IF;

	RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION pem.remove_primary_tag_on_bdr()
RETURNS TRIGGER AS $$
BEGIN
    -- Only proceed if extension_name contains 'bdr' (case-insensitive match)
    IF NEW.extension_name ILIKE '%bdr%' THEN
        UPDATE pem.server s
        SET tags = COALESCE((
            SELECT jsonb_agg(tag_elem)
            FROM jsonb_array_elements(s.tags) AS tag_elem
            WHERE tag_elem->>'text' IS DISTINCT FROM 'primary'
        ), '[]'::jsonb)
        WHERE s.id = NEW.server_id;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

--
-- TRIGGER FUNCTION: pem.create_delete_probe_purge_jobstep()
--
-- This trigger function will create/remove the jobsteps for purging history
-- data for a particular probe.
CREATE OR REPLACE FUNCTION pem.create_delete_probe_purge_jobstep()
	RETURNS trigger AS
$function$
DECLARE
	purge_job_id integer;
	purge_jstid  integer;
	pem_server   integer;
	pem_database text;
	phs RECORD;
BEGIN
	IF TG_OP = 'INSERT' THEN
		IF NOT NEW.discard_history THEN
			FOR phs IN
				SELECT * FROM pem.pem_host_and_server
				LOOP
					PERFORM pem.create_or_update_system_job_with_a_step_and_schedule(
						phs.agent_id, phs.server_id, phs.database,
						-- Job name
						'Database cleanup',
						-- Job description
						'This job runs periodically to purge old data from the database.',
						-- Step name
						'Purge data (' || NEW.display_name || ')',
						-- Step description
						'Purging the history data for the probe (' || NEW.display_name || ')...',
						's',
						'SELECT pem.purge_probe_history(' || NEW.id || '::integer)',
						phs.is_leader, TRUE,
						-- Schedule name
						'Database cleanup',
						-- Schedule description
						'This job schedule runs periodically to purge old data from the database.',
						'{t,f,f,f,f,f,f,f,f,f,f,f,f,f,f,t,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f,f}',
						'{f,t,f,f,f,f,f,f,f,t,f,f,f,t,f,f,f,t,f,f,f,f,f,f}'
					);
				END LOOP;
		END IF;
		RETURN NEW;
	ELSE
		IF NOT OLD.discard_history THEN
			DELETE FROM pem.jobstep
			WHERE jstjobid = ANY (
				SELECT jobid FROM pem.job
				WHERE jobdesc = 'Database cleanup' AND issystemjob
			)
			AND jstdesc = 'Purge data (' || OLD.display_name || ')';
		END IF;
		RETURN OLD;
	END IF;
END;
$function$ LANGUAGE plpgsql SECURITY DEFINER;

-- This function will be called by server installer at the time of installation. This function add the PEM Server to the directory,
-- bind it to the default agent, and create the job for data purging.
--

CREATE OR REPLACE FUNCTION pem.startup(server_desc text, server_name text, server_host text, server_port int, server_database text,
					user_name text, passwd text, ser_group text, agentid int, agent_database text)
	RETURNS void AS
$BODY$
DECLARE
	sg_id     integer;
	serverid  integer := 1;
	is_active boolean;
	name      text;
	probe_curs CURSOR FOR SELECT id, display_name FROM pem.probe
		WHERE NOT discard_history AND jstid IS NULL;
BEGIN

	-- Check if the server group already exists.
	SELECT id INTO sg_id FROM pem.server_group sg WHERE sg.name = ser_group;

	IF (NOT FOUND) THEN
		-- Create new server group
		INSERT INTO pem.server_group(name) VALUES(ser_group) RETURNING id INTO sg_id;
	END IF;

	-- Check the server entry is already exist.
	SELECT active INTO is_active FROM pem.server WHERE id = serverid;

	-- if entry not found or server with id serverid is already exist and server is active then add new server.
	IF (NOT FOUND) OR is_active THEN
		-- Create entry of PEM server in pem.server table.
		INSERT INTO pem.server (
			description, server, port, database
		) VALUES (
			server_desc, server_name, server_port, server_database
		) RETURNING id INTO serverid;

		-- Set the options of the PEM server
		INSERT INTO pem.server_options (
			server_id, pem_user, server_group_id, username, connection_params
		) VALUES (
			serverid, user_name, sg_id, user_name,
			jsonb_build_object(
		        'sslmode', 'prefer',
		        'connect_timeout', 10
	        )
		);

		-- Set the options of the PEM server auth table
		INSERT INTO pem.server_auth (server_id, pem_user) VALUES (serverid, user_name);

	ELSE
		UPDATE pem.server SET
			description = server_desc,
			server = server_name,
			port = server_port,
			database = server_database,
			active = 't'
		WHERE id = serverid;

		UPDATE pem.server_options SET
			pem_user = user_name,
			server_group_id = sg_id,
			username = user_name,
			connection_params = jsonb_build_object(
		        'sslmode', 'prefer',
		        'connect_timeout', 10
	)
		WHERE server_id = serverid;

		UPDATE pem.server_auth SET pem_user = user_name WHERE server_id = serverid;

	END IF;

	-- Create Agent Server Binding
	INSERT INTO pem.agent_server_binding (
		agent_id, server_id, server, port, username, database, password
	) VALUES (
		agentid, serverid, server_host, server_port, user_name, agent_database, passwd
	);

	PERFORM pem.register_pem_server(serverid);

END;
$BODY$ LANGUAGE plpgsql;

