--
-- FUNCTION: pem.create_update_probe_objects_combo()
--
-- This function will helps us to maintain the purging job steps for each individual probe,
-- and parameters combination. It will update only the job steps, whose
-- lifetime has been modified. Also, creates new job steps for the object-probe
-- combination.
CREATE OR REPLACE FUNCTION pem.create_update_probe_objects_combo()
	RETURNS void AS
$function$
DECLARE
	info_curs    REFCURSOR;
	info         RECORD;
BEGIN
	-- Fetch the new/updated probe-object parameters combination.
	OPEN info_curs FOR EXECUTE $SQL$
SELECT
	p.probe_id AS probe_id, c.pid AS pid, c.delete_on,
	COALESCE(p.parameter_value_list, c.objects) AS objects,
	COALESCE(p.lifetime, c.lifetime) AS lifetime
FROM
	pem.probe_target_without_discard_history p
	FULL OUTER JOIN pem.probe_objects_combo c ON (
		p.probe_id = c.pid AND p.parameter_value_list = c.objects
	)
WHERE
	c.pid IS NULL OR p.lifetime != c.lifetime OR c.delete_on IS NOT NULL OR (
		p.probe_id IS NULL AND (
			c.delete_on IS NULL OR c.delete_on > now()::date
		)
	)
$SQL$;

	LOOP
		FETCH info_curs INTO info;
		EXIT WHEN NOT FOUND;

		IF info.probe_id IS NULL THEN
			-- The probe-object is not available
			IF info.delete_on IS NULL THEN
				-- We have noticed it for the first time.
				-- Set the date on which it should be removed from the
				-- 'pem.probe_objects_combo' table.
				EXECUTE 'UPDATE pem.probe_objects_combo SET delete_on = $3::date WHERE pid = $1::integer AND objects = $2::text[]'
				USING info.pid, info.objects, (now() + ((info.lifetime + 5) * INTERVAL '1 days'))::date;
			ELSE
				-- Remove the combination from the 'pem.probe_objects_combo'
				-- table.
				DELETE FROM pem.probe_objects_combo
				WHERE pid = info.pid AND objects = info.objects;
			END IF;
		ELSE
			IF info.pid IS NULL THEN
				-- Insert the combination from the 'pem.probe_objects_combo'
				-- table.
				INSERT INTO pem.probe_objects_combo (pid, objects, lifetime)
				VALUES (info.probe_id, info.objects, info.lifetime);
			ELSE
				-- Update the lifetime, delete_on in the
				-- 'pem.probe_objects_combo' table.
				UPDATE pem.probe_objects_combo
				SET lifetime = info.lifetime, delete_on = NULL
				WHERE pid = info.probe_id AND objects = info.objects;
			END IF;
		END IF;
	END LOOP;
	CLOSE info_curs;
END;
$function$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION pem.purge_data()
  RETURNS void AS
$BODY$
DECLARE
    curs_probe CURSOR FOR
	SELECT probe_internal_name, parameter_name_list,
	   parameter_value_list, lifetime, discard_history
	FROM pem.probe_target_view;

    table_name varchar;
    parameter_name_list text[];
    parameter_value_list text[];
    lifetime integer;

    i integer; -- Counter
    where_clause varchar;
    subquery varchar;

BEGIN

    FOR probe IN curs_probe LOOP
	IF (NOT probe.discard_history) THEN
		table_name := 'pemhistory.' || pg_catalog.quote_ident(probe.probe_internal_name);
		parameter_name_list := probe.parameter_name_list;
		parameter_value_list := probe.parameter_value_list;
		lifetime := probe.lifetime;

		where_clause := 'WHERE ';

		FOR i IN array_lower(parameter_name_list, 1)..array_upper(parameter_name_list, 1)
		LOOP
			where_clause := where_clause || parameter_name_list[i] || ' = ' || pg_catalog.quote_literal(parameter_value_list[i]::text) || ' AND ';
		END LOOP;

		where_clause := where_clause || 'recorded_time < (now() - interval ''' || lifetime || ' days'' ) ';

		subquery := 'SELECT recorded_time FROM ' || table_name || ' ' || where_clause || 'ORDER BY recorded_time DESC LIMIT 1';

		where_clause := where_clause || ' AND recorded_time < (' || subquery || ')';

		EXECUTE 'DELETE FROM ' || table_name || ' ' || where_clause;
	END IF;
    END LOOP;

END;
$BODY$ LANGUAGE plpgsql;


-- Purge function to remove the data from pemhisotry for database objects
-- for which database has been deleted by user making the data in pemhistory obsolete
CREATE OR REPLACE FUNCTION pem.purge_obsolete_data()
  RETURNS void AS
$BODY$
DECLARE

    curs_probe CURSOR FOR
	SELECT probe_internal_name, parameter_name_list,
	   parameter_value_list, lifetime, discard_history
	FROM pem.probe_obsolete_target_view
	UNION ALL
	SELECT probe_internal_name, parameter_name_list,
	   parameter_value_list, lifetime, discard_history
	FROM pem.probe_deleted_target_view;

    table_name_pemhistory varchar;
	table_name_pemdata varchar;
    parameter_name_list text[];
    parameter_value_list text[];

    i integer; -- Counter
    where_clause varchar;

BEGIN

    FOR probe IN curs_probe LOOP
	IF (NOT probe.discard_history) THEN
		table_name_pemhistory := 'pemhistory.' || pg_catalog.quote_ident(probe.probe_internal_name);
		table_name_pemdata := 'pemdata.' || pg_catalog.quote_ident(probe.probe_internal_name);
		parameter_name_list := probe.parameter_name_list;
		parameter_value_list := probe.parameter_value_list;

		where_clause := 'WHERE ';

		FOR i IN array_lower(parameter_name_list, 1)..array_upper(parameter_name_list, 1)
		LOOP
		    IF (i != 1) THEN
		        where_clause := where_clause || ' AND ';
		    END IF;
			where_clause := where_clause || parameter_name_list[i] || ' = ' || pg_catalog.quote_literal(parameter_value_list[i]::text);
		END LOOP;

        -- Purge the data by deleting it
		EXECUTE 'DELETE FROM ' || table_name_pemdata || ' ' || where_clause;
		EXECUTE 'DELETE FROM ' || table_name_pemhistory || ' ' || where_clause;
		
	END IF;
    END LOOP;

END;
$BODY$ LANGUAGE plpgsql;

-- Fixed PEM-4710 Deleting probe history data for deleted agents, servers and tools
CREATE OR REPLACE FUNCTION pem.purge_deleted_objects_data(
    serverid int DEFAULT NULL, agentid int DEFAULT NULL, toolid int DEFAULT NULL
)
RETURNS void AS
$BODY$
DECLARE
	curs_probe_agent CURSOR FOR
	SELECT internal_name FROM pem.probe WHERE target_type_id = 100;

	curs_probe_server CURSOR FOR
	SELECT internal_name FROM pem.probe WHERE target_type_id >= 200;

	curs_probe_tool CURSOR FOR
	SELECT internal_name FROM pem.probe WHERE target_type_id = 150;

	table_name_pemhistory varchar;
	table_name_pemdata varchar;
	where_clause varchar;

BEGIN
	IF agentid IS NOT NULL THEN
		where_clause := ' WHERE agent_id IN (SELECT id FROM pem.agent WHERE active = false AND id = ' || agentid || ')';
	ELSIF (agentid IS NULL AND serverid IS NULL AND toolid IS NULL) THEN
		where_clause := ' WHERE agent_id IN (SELECT id FROM pem.agent WHERE active = false)';
	END IF;

	IF (agentid IS NULL AND serverid IS NULL AND toolid IS NULL) OR agentid IS NOT NULL THEN
		-- Remove obsolete Agent entries
		FOR probe IN curs_probe_agent LOOP
			BEGIN
				-- Attempt to delete data from pemhistory table
				table_name_pemhistory := 'pemhistory.' || pg_catalog.quote_ident(probe.internal_name);
				EXECUTE 'DELETE FROM ' || table_name_pemhistory || where_clause;
			EXCEPTION
				WHEN others THEN
				RAISE NOTICE 'Delete from % skipped due to an exception: %', table_name_pemhistory, SQLERRM;
			END;

			BEGIN
				-- Attempt to delete data from pemdata table
				table_name_pemdata := 'pemdata.' || pg_catalog.quote_ident(probe.internal_name);
				EXECUTE 'DELETE FROM ' || table_name_pemdata || where_clause;
			EXCEPTION
				WHEN others THEN
				RAISE NOTICE 'Delete from % skipped due to an exception: %', table_name_pemdata, SQLERRM;
			END;
		END LOOP;
	END IF;

	IF serverid IS NOT NULL THEN
		where_clause := ' WHERE server_id IN (SELECT id FROM pem.server WHERE active = false AND id = ' || serverid || ')';
	ELSIF (agentid IS NULL AND serverid IS NULL AND toolid IS NULL) THEN
		where_clause := ' WHERE server_id IN (SELECT id FROM pem.server WHERE active = false)';
	END IF;

	IF (agentid IS NULL AND serverid IS NULL AND toolid IS NULL) OR serverid IS NOT NULL THEN
		-- Remove obsolete Server entries for provided id
		FOR probe IN curs_probe_server LOOP
			BEGIN
				-- Attempt to delete data from pemhistory table
				table_name_pemhistory := 'pemhistory.' || pg_catalog.quote_ident(probe.internal_name);
				EXECUTE 'DELETE FROM ' || table_name_pemhistory || where_clause;
			EXCEPTION
				WHEN others THEN
				RAISE NOTICE 'Delete from % skipped due to an exception: %', table_name_pemhistory, SQLERRM;
			END;

			BEGIN
				-- Attempt to delete data from pemdata table
				table_name_pemdata := 'pemdata.' || pg_catalog.quote_ident(probe.internal_name);
				EXECUTE 'DELETE FROM ' || table_name_pemdata || where_clause;
			EXCEPTION
				WHEN others THEN
				RAISE NOTICE 'Delete from % skipped due to an exception: %', table_name_pemdata, SQLERRM;
			END;
		END LOOP;
	END IF;

	IF toolid IS NOT NULL THEN
		where_clause := ' WHERE tool_id IN (SELECT id FROM pem.tool WHERE active = false AND id = ' || toolid || ')';
	ELSIF (agentid IS NULL AND serverid IS NULL AND toolid IS NULL) THEN
		where_clause := ' WHERE tool_id IN (SELECT id FROM pem.tool WHERE active = false)';
	END IF;

	IF (agentid IS NULL AND serverid IS NULL AND toolid IS NULL) OR toolid IS NOT NULL THEN
		-- Remove obsolete tool entries
		FOR probe IN curs_probe_tool LOOP
			BEGIN
				-- Attempt to delete data from pemhistory table
				table_name_pemhistory := 'pemhistory.' || pg_catalog.quote_ident(probe.internal_name);
				EXECUTE 'DELETE FROM ' || table_name_pemhistory || where_clause;
			EXCEPTION
				WHEN others THEN
				RAISE NOTICE 'Delete from % skipped due to an exception: %', table_name_pemhistory, SQLERRM;
			END;

			BEGIN
				-- Attempt to delete data from pemdata table
				table_name_pemdata := 'pemdata.' || pg_catalog.quote_ident(probe.internal_name);
				EXECUTE 'DELETE FROM ' || table_name_pemdata || where_clause;
			EXCEPTION
				WHEN others THEN
				RAISE NOTICE 'Delete from % skipped due to an exception: %', table_name_pemdata, SQLERRM;
			END;
		END LOOP;
	END IF;

END;
$BODY$ LANGUAGE plpgsql;

