	(SELECT max(id) FROM pem.probe), v.version, 'SELECT datname AS database_name, datallowconn AS connections_allowed, pg_encoding_to_char(encoding) AS encoding, CASE WHEN oid > datlastsysoid THEN false ELSE true END AS system_database FROM pg_catalog.pg_database WHERE NOT datistemplate AND datallowconn'
	FROM (
    VALUES
    (10901), (10902), (10903), (10904), (10905), (10906), (11000), (11100),
    (11200), (11300), (11400),
    (20901), (20902), (20903), (20904), (20905), (20906), (21000), (21100),
    (21200),(21300), (21400)
) v(version);

