	v.sql_data_type, v.unit_of_value, v.calculate_pit, v.discard_history, v.pit_by_default, v.is_graphable
FROM
	(VALUES
		('table_name', 'Table Name', 1, 'k', 'text', '', false, false, false, false),
		('has_primary_key', 'Table has Primary Key', 2, 'm', 'boolean', '', false, false, false, false),
		('parent_table_name', 'Parent Table', 3, 'm', 'text', '', false, false, false, false)
