--
-- Probe: database_statistics
--
-- pg_stat_database was added to PostgreSQL on June 22, 2001.  The initial
-- version had the datname, numbackends, xact_commit, xact_rollback, blks_read,
-- and blks_hit columns.  See commit 8d80b0d980c327edf162e20fdc829559e8aff224,
-- which first appeared in PostgreSQL 7.2.
--
-- The tup_returned, tup_fetched, tup_inserted, tup_updated, and tup_deleted
-- columns were added to pg_stat_database on March 16, 2007.  See commit
-- 51d7741db13332523708cd7ac75a8ca60c9d16a9, which first appeared in PostgreSQL
-- 8.3.
--
INSERT INTO pem.probe
	(display_name, internal_name, collection_method, target_type_id,
	 enabled_by_default, force_enabled, default_execution_frequency,
	 default_lifetime, any_server_version, probe_code)
VALUES
	('Database Statistics', 'database_statistics', 's', 200, true, false, 1800, 90,
	 false,
     'SELECT d1.datname AS database_name,
        	               d1.numbackends,
             	           (SELECT COALESCE(count(current_query)::bigint, 0::bigint) FROM pg_catalog.pg_stat_activity WHERE datname = d1.datname AND current_query = ''<IDLE>'') AS idle_backends,
                  		   d1.xact_commit, d1.xact_rollback, d1.blks_hit, NULL::bigint AS blks_icache_hit, d1.blks_read,
                      	   d1.tup_returned, d1.tup_fetched, d1.tup_inserted, d1.tup_updated, d1.tup_deleted
      FROM pg_catalog.pg_stat_database d1');

