INSERT INTO pem.probe_server_version
    (probe_id, server_version_id, probe_code)
SELECT
    (SELECT id FROM pem.probe WHERE internal_name = 'database_statistics'),
    v.version,
     'SELECT d1.datname AS database_name, d1.numbackends,
            (SELECT COALESCE(count(query)::bigint, 0::bigint) FROM pg_catalog.pg_stat_activity WHERE datname = d1.datname AND state = ''idle'') AS idle_backends,
            d1.xact_commit, d1.xact_rollback, d1.blks_hit, NULL::bigint AS blks_icache_hit, d1.blks_read,
            d1.tup_returned, d1.tup_fetched, d1.tup_inserted, d1.tup_updated, d1.tup_deleted
      FROM pg_catalog.pg_stat_database d1'
FROM
    (VALUES (21100)) v(version);

-- PG/Advanced Server 12+ will return a row with database_name as 'null' for
-- the shared objects, showing database-wide statistics.
INSERT INTO pem.probe_server_version
    (probe_id, server_version_id, probe_code)
SELECT
    (SELECT id FROM pem.probe WHERE internal_name = 'database_statistics'),
    v.version, $SQL$
SELECT COALESCE(d1.datname, '') AS database_name, d1.numbackends, (
        SELECT COALESCE(count(query)::bigint, 0::bigint)
        FROM pg_catalog.pg_stat_activity
        WHERE datname = d1.datname AND state = 'idle'
    ) AS idle_backends,
    d1.xact_commit, d1.xact_rollback, d1.blks_hit,
    NULL::bigint AS blks_icache_hit, d1.blks_read, d1.tup_returned,
    d1.tup_fetched, d1.tup_inserted, d1.tup_updated, d1.tup_deleted
FROM pg_catalog.pg_stat_database d1$SQL$
FROM (VALUES (11200),(11300),(11400),(11500),(11600),(11700), (11800),(21200),(21300),(21400),(21500),(21600),(21700), (21800)) v(version);

