INSERT INTO pem.probe_server_version
    (probe_id, server_version_id, probe_code)
SELECT
	(SELECT max(id) FROM pem.probe), v.version,
		'SELECT checkpoints_timed, checkpoints_req, buffers_clean, buffers_checkpoint, maxwritten_clean, buffers_backend, buffers_alloc FROM pg_catalog.pg_stat_bgwriter'
FROM (
    VALUES (10803), (10804), (10900), (10901), (10902), (10903), (10904),
    (10905), (10906), (11000), (11100), (11200), (11300), (11400), (11500), (11600),
