--
-- Probe: session_info
--
/* For autovacuum, client_port is always NULL. current_query in PG 8.2 starts
 * with VACUUM and for later versions, it starts with autovacuum:
 *
 * The check for is_vacuum is not very robust since user can have a leading SQL
 * comment, but this is the best we can do right now.
 *
 * No need for ILIKE comparison in case of is_autovacuum, since this string
 * format is not user-generated and hence fixed.
 */
INSERT INTO pem.probe
	(display_name, internal_name, collection_method, target_type_id,
	 agent_capability, enabled_by_default, force_enabled,
     default_execution_frequency, default_lifetime, any_server_version, probe_code)
VALUES
	('Session Information', 'session_info', 'i',
     200, NULL, true, false, 300, 180, false,
	'SELECT datname AS database_name, procpid, usename, client_addr, client_port, backend_start, xact_start, query_start,'
		' waiting AS is_waiting, current_query = $$<IDLE>$$ AS is_idle,'
		' current_query = $$<IDLE> in transaction$$ AS is_idle_in_transaction,'
		' current_query ilike $$VACUUM%$$ as is_vacuum,'
		' client_port IS NULL AND (current_query like $$autovacuum:%$$ OR current_query like $$VACUUM%$$) as is_autovacuum,'
		' now() AS capture_time'
	' FROM pg_catalog.pg_stat_activity');

INSERT INTO pem.probe_server_version
    (probe_id, server_version_id, probe_code)
SELECT
	(SELECT max(id) FROM pem.probe), v.version, NULL
FROM
	(VALUES (10803), (10804), (10900), (10901), (20804), (20900), (20901))
		v(version);

INSERT INTO pem.probe_server_version
    (probe_id, server_version_id, probe_code)
SELECT
	(SELECT id FROM pem.probe WHERE internal_name = 'session_info'),
	v.version,
    'SELECT datname AS database_name, procpid, usename, client_addr, client_port, backend_start, NULL::timestamptz AS xact_start, query_start,'
		' waiting AS is_waiting, current_query = $$<IDLE>$$ AS is_idle,'
		' current_query = $$<IDLE> in transaction$$ AS is_idle_in_transaction,'
		' current_query ilike $$VACUUM%$$ as is_vacuum,'
		' client_port IS NULL AND (current_query like $$autovacuum:%$$ OR current_query like $$VACUUM%$$) as is_autovacuum,'
		' now() AS capture_time'
	' FROM pg_catalog.pg_stat_activity'
FROM
	(VALUES (10802)) v(version);

INSERT INTO pem.probe_server_version
    (probe_id, server_version_id, probe_code)
SELECT
	(SELECT id FROM pem.probe WHERE internal_name = 'session_info'),
	v.version,
    'SELECT datname AS database_name, procpid, usename, client_addr, client_port, backend_start, NULL::timestamptz AS xact_start, query_start,'
		' waiting AS is_waiting, current_query = $$<IDLE>$$ AS is_idle,'
		' current_query = $$<IDLE> in transaction$$ AS is_idle_in_transaction,'
		' current_query ilike $$VACUUM%$$ as is_vacuum,'
		' client_port IS NULL AND (current_query like $$autovacuum:%$$ OR current_query like $$VACUUM%$$) as is_autovacuum,'
		' now() AS capture_time'
	' FROM pg_catalog.pg_stat_activity'
FROM
	(VALUES (20803)) v(version);

INSERT INTO pem.probe_server_version
    (probe_id, server_version_id, probe_code)
SELECT
	(SELECT id FROM pem.probe WHERE internal_name = 'session_info'),
	v.version,
	E'SELECT datname AS database_name, pid AS procpid, usename, client_addr, client_port, backend_start,
		xact_start, query_start, waiting AS is_waiting, state = ''idle'' AS is_idle,
		state like ''%idle in transaction%'' AS is_idle_in_transaction, query ilike $$VACUUM%$$ as is_vacuum,
		client_port IS NULL AND (query like $$autovacuum:%$$ OR query like $$VACUUM%$$) as is_autovacuum,
		now() AS capture_time, query, state, state_change, application_name FROM pg_catalog.pg_stat_activity'
FROM
	(VALUES (10902), (10903), (10904), (10905),  (20902), (20903), (20904), (20905)) v(version);

INSERT INTO pem.probe_server_version
    (probe_id, server_version_id, probe_code)
SELECT
	(SELECT id FROM pem.probe WHERE internal_name = 'session_info'),
	v.version,
	E'SELECT datname AS database_name, pid AS procpid, usename, client_addr, client_port, backend_start,
		xact_start, query_start, CASE WHEN wait_event IS NULL THEN false ELSE true END AS is_waiting,
		state = ''idle'' AS is_idle, state like ''%idle in transaction%'' AS is_idle_in_transaction, query ilike $$VACUUM%$$ as is_vacuum,
		client_port IS NULL AND (query like $$autovacuum:%$$ OR query like $$VACUUM%$$) as is_autovacuum,
		now() AS capture_time, wait_event, wait_event_type, query, state, state_change, application_name FROM pg_catalog.pg_stat_activity'
FROM (
    VALUES (10906), (11000), (11100), (11200), (11300), (11400), (11500), (11600), (11700), (11800), (20906), (21000), (21100),
    (21200), (21300), (21400), (21500), (21600), (21700), (21800)
) v(version);

