INSERT INTO pem.probe
        (display_name, internal_name, collection_method, target_type_id,
         enabled_by_default, force_enabled, default_execution_frequency,
         default_lifetime, any_server_version, probe_code, discard_history, extension_name)
VALUES
        ('PGD Conflict History Summary', 'bdr_conflict_history_summary', 's', 1000, false, false, 60, 7, true,
        $sql$
		select EXTRACT(EPOCH FROM date_trunc('hour', local_time))::bigint as conflict_recorded,
        conflict_type, count(*) as conflict_count
        from bdr.conflict_history_summary
        group by date_trunc('hour', local_time), conflict_type
        order by conflict_recorded, conflict_type;
		$sql$, true, 'bdr');


