	'The value of the email body.';
COMMENT ON COLUMN pem.custom_email_template.pem_user IS
	'The name of the current user.';

CREATE OR REPLACE FUNCTION pem.get_email_template (template text)
	RETURNS TABLE (
		mail_subject text,
		mail_message text
)
AS $$
BEGIN
	RETURN QUERY SELECT
		COALESCE(cet.mail_subject, et.mail_subject) AS mail_subject,
		COALESCE(cet.mail_message, et.mail_message) AS mail_message
	FROM pem.email_template AS et
			LEFT JOIN pem.custom_email_template AS cet
					ON (et.display_name = cet.display_name)
	WHERE et.display_name = template;
END; $$
LANGUAGE 'plpgsql';

GRANT SELECT ON TABLE pem.custom_email_template TO pem_agent;

/*******************
 * Alerting Schema *
 *******************/

-- Types of parameters in an alert
CREATE TYPE pem.alert_param_type AS ENUM(
	'STRING',	-- String literals
	'INTEGER',	-- INT type parameters
	'FLOAT',		-- Floating point nuumbers; integers also accepted.
	'BOOL'		-- True or False.
);

COMMENT ON TYPE pem.alert_param_type IS 'Types of parameters in an alert';

CREATE TYPE pem.server_type AS ENUM(
       'ALL',
       'ADVANCED_SERVER',
       'POSTGRES_SERVER'
);

CREATE OR REPLACE FUNCTION pem.check_array_size_equal(arr1 anyarray,
														arr2 anyarray)
RETURNS bool AS $$
	/*
	 * For our purposes, a NULL array is the same as a an empty (zero element)
	 * array.
	 *
	 * Make sure we don't return NULL because a CHECK constraint will not fail
	 * if the CHECK expression returns NULL.
	 */
	SELECT COALESCE(array_upper($1, 1), 0) = COALESCE(array_upper($2, 1), 0)
$$ LANGUAGE sql;

/* Alert templates */
CREATE TABLE pem.alert_template(
	-- Unique ID
	id serial PRIMARY KEY,

	-- Display Name to show in UI
	display_name text NOT NULL,

	-- Cross system reference id
	-- System level alert_template can has reference-id as
	-- object_type '|' display_name'.
	reference_id text NOT NULL,

	-- Description of the alert
	description text NOT NULL,

	/*
	 * SQL query, possibly parameterized, to get a numeric indicating threshold
	 * reached.
	 */
	sql text NOT NULL,

	-- Type of the object that can be monitored using this alert template.
	object_type integer NOT NULL REFERENCES pem.probe_target_type(id)
						ON UPDATE RESTRICT ON DELETE CASCADE,

	-- Friendly parameter names, to show in UI when creating a new alert
	param_names text[],

	-- One element each for corresponding parameter names
	param_types pem.alert_param_type[],

	/*
	 * One element for each param_name element, to show in UI when creating
	 * alert. An element may be NULL to represent no units.
	 */
	param_units text[],

	/* Unit in which threshold is calculated; purely for GUI. Show something
	 * sensible to the user, like MB/kB/seconds/days/...
	 */
	threshold_unit text,

	/*
	 * Default value of check_frequency of an alert created from this template;
	 * in minutes.
	 */
	default_check_frequency integer NOT NULL DEFAULT 1
		CONSTRAINT default_check_frequency_gt_zero
			CHECK(default_check_frequency > 0),

	-- How many days to keep the history of an alert
	default_history_retention integer NOT NULL DEFAULT 30
		CONSTRAINT default_history_retention_gt_zero
			CHECK(default_history_retention > 0),

	probe_dependency_list text[] NOT NULL,

	snmp_oid integer NOT NULL DEFAULT 0,

	applicable_on_server pem.server_type NOT NULL DEFAULT 'ALL',

	-- Defines whether the given template is system or custom
	is_system_template	boolean NOT NULL DEFAULT true,

	/*
	 * Operator to use to compare query result with threshold values. Currently
	 * we support < and >. We may support <= and >= in future.
	 */
	operator "char" DEFAULT '>' NOT NULL
		CONSTRAINT valid_operators CHECK(operator in ('<' ,'>')),

	-- A 3-element array representing low, medium and high thresholds
	thresholds numeric[]
		CONSTRAINT validate_thresholds_ordering
				CHECK(
				CASE WHEN is_auto_create THEN
				  array_upper(thresholds, 1) = 3
					AND thresholds[1] IS NOT NULL
					AND thresholds[2] IS NOT NULL
					AND thresholds[3] IS NOT NULL
					AND CASE
					WHEN operator = '<' THEN
						thresholds[1] > thresholds [2]
						AND thresholds[2] > thresholds[3]
					WHEN operator = '>' THEN
						thresholds[1] < thresholds [2]
						AND thresholds[2] < thresholds[3]
					ELSE false
					END
				ELSE thresholds IS NULL END),

	-- Defines whether using given template alert will be created automatically
	is_auto_create	boolean NOT NULL DEFAULT false,

	-- SQL query, will be used to get the detailed information about the alert.
	info_sql text DEFAULT NULL,

	/*
	 * We don't allow same name for two templates on same object type.
	 */
	CONSTRAINT alert_template_name_object_type_uniq
		UNIQUE(display_name, object_type),

	/*
	 * Check that the number of elements in param_names and param_types is same.
	 * Also check that the number of elements in param_units is not greater than
	 * those in param_names.
	 *
	 * We need to cast param_types to text since param_names is text and the
	 * function expects its parameters' data types to be same.
	 */
	CONSTRAINT check_param_types_array_size
		CHECK (pem.check_array_size_equal(param_names, param_types::text[])),

	/*
	 * We cannot join this CHECK with the above CHECK since SQL does not
	 * guarantee any specific order of evaluation of different branches of
	 * ANDed conditions, and this CHECK can yield NULL value, which can cause
	 * the check_param_types_array_size CHECK constraint to silently allow
	 * incorrect values in the row.
	 */
	CONSTRAINT check_param_units_array_size
		CHECK (array_upper(param_units, 1) <= array_upper(param_names, 1))
);

COMMENT ON TABLE pem.alert_template IS
	'Alert Templates.';
COMMENT ON COLUMN pem.alert_template.id IS
	'Unique ID';
COMMENT ON COLUMN pem.alert_template.display_name IS
	'The name of the alert to show in UI.';
COMMENT ON COLUMN pem.alert_template.description IS
	'Description of the alert.';
COMMENT ON COLUMN pem.alert_template.sql IS
	'SQL query, possibly parameterized, to get a numeric indicating threshold'
		' reached.';
COMMENT ON COLUMN pem.alert_template.object_type IS
	'Type of the object that can be monitored using this alert template.';
COMMENT ON COLUMN pem.alert_template.param_names IS
	'Friendly parameter names, to show in UI when creating a new alert.';
COMMENT ON COLUMN pem.alert_template.param_types IS
	'One element each for corresponding parameter names.';
COMMENT ON COLUMN pem.alert_template.param_units IS
	'One element for each param_name element, to show in UI when creating alert.'
		' An element may be NULL to represent no units.';
COMMENT ON COLUMN pem.alert_template.threshold_unit IS
	'Unit in which threshold is calculated; purely for GUI. Show something'
		' sensible to the user, like MB/kB/seconds/days/...';
COMMENT ON COLUMN pem.alert_template.default_check_frequency IS
	'Default value of check_frequency of an alert created from this template;'
		' in minutes.';
COMMENT ON COLUMN pem.alert_template.default_history_retention IS
	'How many days to keep the history of an alert.';
COMMENT ON COLUMN pem.alert_template.snmp_oid IS
	'Unique OID to for SNMP traps';
COMMENT ON COLUMN pem.alert_template.applicable_on_server IS
        'Template is applicable on which server';
COMMENT ON COLUMN pem.alert_template.is_system_template IS
        'Defines whether the given template is system or custom';
COMMENT ON COLUMN pem.alert_template.operator IS
	'Operator to use to compare query result with threshold values. Currently'
	' we support < and >. We may support <= and >= in future.';
COMMENT ON COLUMN pem.alert_template.thresholds IS
	'A 3-element array representing low, medium and high thresholds.';
COMMENT ON COLUMN pem.alert_template.is_auto_create IS
        'Defines whether using given template alerts will be created automatically';
COMMENT ON COLUMN pem.alert_template.info_sql IS
	'SQL query, will be used to get the detailed information about the alert.';

-- Ensure profile_alert_configs.template_id references alert_template.
-- This ALTER is done here (after creating pem.alert_template) to avoid
-- forward-reference errors when the SQL file is executed top-to-bottom.
ALTER TABLE IF EXISTS pem.profile_alert_configs
ADD CONSTRAINT profile_alert_configs_template_id_fkey
FOREIGN KEY (template_id) REFERENCES pem.alert_template(id) ON DELETE CASCADE;

-- Function to change snmp oid if object_type of alert template is changed
CREATE OR REPLACE FUNCTION pem.update_snmp_oid() RETURNS trigger AS $$
BEGIN
	EXECUTE 'SELECT CASE WHEN MAX(snmp_oid) > 0 THEN MAX(snmp_oid) + 1 ELSE 1 END FROM pem.alert_template WHERE object_type = $1' USING NEW.object_type INTO NEW.snmp_oid;
	RETURN NEW;
END
$$ LANGUAGE plpgsql;

-- Function to create new the reference-id
CREATE OR REPLACE FUNCTION pem.update_alert_template_reference_id()
RETURNS trigger AS $$
DECLARE
    uuid text;
BEGIN
	IF NEW.is_system_template THEN
		NEW.reference_id := NEW.object_type || '|' || NEW.display_name;
	ELSE
        -- If old reference id exist then it may be a case where this template was imported
        -- so we will update it only when it's new and empty
        IF NEW.reference_id IS NULL OR TRIM(NEW.reference_id) = '' THEN
            EXECUTE 'SELECT pem.system_uid();' INTO uuid;
            NEW.reference_id := 'template_' || TRIM(uuid) || '_' || NEW.id::text;
        END IF;
	END IF;
	RETURN NEW;
END
$$ LANGUAGE plpgsql;

-- Trigger on pem.alert_template when the object_type of alert template is changed
CREATE TRIGGER alert_template_snmp_oid
    BEFORE UPDATE ON pem.alert_template
    FOR EACH ROW
    WHEN (OLD.object_type != NEW.object_type)
    EXECUTE PROCEDURE pem.update_snmp_oid();

CREATE TRIGGER alert_template_reference_id
    BEFORE INSERT ON pem.alert_template
    FOR EACH ROW
    EXECUTE PROCEDURE pem.update_alert_template_reference_id();

CREATE TYPE pem.alert_state AS ENUM(
	'LOW',
	'MEDIUM',
	'HIGH'
);

CREATE OR REPLACE FUNCTION pem.check_alert_params_array_size(
	template_id pem.alert_template.id%type,
	params text[]
) RETURNS bool AS $FUNC$
DECLARE
	res bool := TRUE;
BEGIN
	/*
	 * During restoring the pem database, it does not maintain the order while
	 * inserting data in the table, and uses the sort table based on the
	 * names.
	 *
	 * Hence - we need to check the foreign key constraint is present before
	 * validating these values.
	 *
	 */
	IF EXISTS(
		SELECT 1 FROM information_schema.table_constraints
		WHERE constraint_name='alert_template_id_fkey' AND
			table_name='alert' AND table_schema='pem'
	) THEN
		/*
		 * Need to use the IS TRUE construct outside the main query, because
		 * otherwise if there's no template by that ID then the query would return
		 * 0 rows and the result of the function would be undefined and CHECK
		 * constraint would succeed.
		 *
		 * Probably this is being over-cautious, because pem.alert.template_id
		 * references pem.alert_template.id. But the SQL standard (probably) does
		 * not define the order in which the CHECK or the FOREIGN KEY constraints
		 * should be validated; in case CHECK is validated first, we want it to
		 * fail.
		 */
		EXECUTE $SQL$
		SELECT (
			SELECT pem.check_array_size_equal(t.param_names, $2)
			FROM pem.alert_template AS t
			WHERE id = $1
		) IS TRUE
		$SQL$ INTO res USING template_id, params;
	END IF;
	RETURN res;
END
$FUNC$ LANGUAGE 'plpgsql';

/* Each row represents an instance of one of the rows from alert_template */
CREATE TABLE pem.alert(
	-- Unique ID
	id serial PRIMARY KEY,

	-- Alert name assigned by the user.
	name text,

	-- Is this alert enabled?
	enabled bool NOT NULL DEFAULT TRUE,

	-- ID of the alert_template of which this row is an instance.
	template_id integer REFERENCES pem.alert_template(id)
						ON UPDATE RESTRICT ON DELETE CASCADE,

	-- Agent's id which is monitoring the object covered by this alert
	agent_id integer NOT NULL,

	-- Database server id where this object is hosted
	server_id integer,

	-- Name of the object's containing database
	database_name text,

	-- Name of the object's containing schema
	schema_name text,

	-- Name of the object's containing package (most likely for a function/procedure object)
	package_name text,

	-- The table/view/index/... name
	object_name text,

	/*
	 * Parameters to substitute in the sql query of the alert_template; see
	 * alert_template.param_* columns.
	 */
	params text[],

	/*
	 * Operator to use to compare query result with threshold values. Currently
	 * we support < and >. We may support <= and >= in future.
	 */
	operator "char" NOT NULL
		CONSTRAINT valid_operators CHECK(operator in ('<' ,'>')),

	-- A 3-element array representing low, medium and high thresholds
	thresholds numeric[] NOT NULL
		CONSTRAINT validate_thresholds_ordering
									CHECK(array_upper(thresholds, 1) = 3
										AND thresholds[1] IS NOT NULL
										AND thresholds[2] IS NOT NULL
										AND thresholds[3] IS NOT NULL
										AND CASE
											WHEN operator = '<' THEN
												thresholds[1] > thresholds [2]
												AND thresholds[2] > thresholds[3]
											WHEN operator = '>' THEN
												thresholds[1] < thresholds [2]
												AND thresholds[2] < thresholds[3]
											ELSE false
											END),

	/*
	 * How often to check for this alert; in minutes. The default value for an
	 * alert is picked from alert_template.default_check_frequency
	 */
	check_frequency integer NOT NULL DEFAULT 1
		CONSTRAINT check_frequency_gt_zero CHECK(check_frequency > 0),

	-- How many days to keep the history of an alert
	history_retention integer NOT NULL DEFAULT 30
		CONSTRAINT history_gt_zero CHECK(history_retention > 0),

	/*
	 * The columns above are all static, populated during alert creation, and
	 * modified only by user request.
	 *
	 * The columns below here are the ones that show the current state of the
	 * alert and are managed by different components of alerting infrastrcuture.
	 */

	/*
	 * If there was an error while processing this alert, the error message will
	 * be stored here, and the alert will not be processed again until this
	 * error message is cleared.
	 *
	 * A NULL value or an empty string '' in this column is treated as a
	 * non-error condition.
	 */
	error_message text,

	-- An ACK'd alert is neither shown in GUI, nor delivered to a contact
	acknowledged bool NOT NULL DEFAULT FALSE,

	-- ID of the email_group to whom SMTP email to be send
	email_group_id integer DEFAULT NULL REFERENCES pem.email_group(id)
	ON UPDATE RESTRICT ON DELETE SET DEFAULT,

	-- send_email flag on per alert basis to send an email.
	send_email bool NOT NULL DEFAULT FALSE,

	-- When was SMTP email send for this alert last time.
	last_mail_send timestamptz DEFAULT NULL,

	-- flapping detection flag
	flapping_detected bool NOT NULL DEFAULT FALSE,

	-- When was flapping detection runs for this alert last time
	last_flapping_detection_processed timestamptz NOT NULL DEFAULT current_timestamp,

	-- send_trap flag on per alert basis to send an snmp trap.
	send_trap bool NOT NULL DEFAULT FALSE,

	-- snmp_trap_version.
	snmp_trap_version integer NOT NULL DEFAULT 2,

	-- add new column error timestamp to display time in alert dashboard
	error_timestamp timestamp with time zone,

	-- low_send_trap flag on per alert level basis.
	low_send_trap bool NOT NULL DEFAULT FALSE,

	-- ID of the email_group to whom SMTP email to be send when low alert will be raised
	low_email_group_id integer DEFAULT NULL REFERENCES pem.email_group(id)
	ON UPDATE RESTRICT ON DELETE SET DEFAULT,

	-- med_send_trap flag on per alert level basis.
	med_send_trap bool NOT NULL DEFAULT FALSE,

	-- ID of the email_group to whom SMTP email to be send when med alert will be raised
	med_email_group_id integer DEFAULT NULL REFERENCES pem.email_group(id)
	ON UPDATE RESTRICT ON DELETE SET DEFAULT,

	-- high_send_trap flag on per alert level basis.
	high_send_trap bool NOT NULL DEFAULT FALSE,

	-- ID of the email_group to whom SMTP email to be send when low alert will be raised
	high_email_group_id integer DEFAULT NULL REFERENCES pem.email_group(id)
	ON UPDATE RESTRICT ON DELETE SET DEFAULT,

	-- execute_script flag, execute script when alert raises.
	execute_script bool NOT NULL DEFAULT FALSE,

	-- execute_script_on_clear flag, execute the script when alert is cleared.
	execute_script_on_clear bool NOT NULL DEFAULT FALSE,

	-- execute_script_on_pem_server flag, if true then run the script on pem server else on monitored server.
	execute_script_on_pem_server bool NOT NULL DEFAULT FALSE,

	script_code text,

	-- submit to nagios flag, send passive service check result to nagios
	submit_to_nagios boolean NOT NULL DEFAULT FALSE,

	-- Is this alert automatically created
	auto_created bool NOT NULL DEFAULT FALSE,

	-- flag to mute the clear alert notification
	cleared_alert_enable bool NOT NULL DEFAULT TRUE,

	CONSTRAINT check_alert_params_array_size
		CHECK (pem.check_alert_params_array_size(template_id, params))
);


CREATE TABLE pem.webhook_alert_config(
	id bigserial PRIMARY KEY,
	alert_id integer UNIQUE,
    send_notification bool NOT NULL DEFAULT TRUE,
    override_default_config bool NOT NULL DEFAULT FALSE,
	low_webhook_ids integer[],
	med_webhook_ids integer[],
	high_webhook_ids integer[],
	cleared_webhook_ids integer[],
	CONSTRAINT fk_alert_webhook_config_id
      FOREIGN KEY(alert_id)
	  REFERENCES pem.alert(id) MATCH SIMPLE
            ON UPDATE NO ACTION
            ON DELETE CASCADE
);

COMMENT ON TABLE pem.webhook_alert_config IS 'This contains the information about webhook alert configuration';
COMMENT ON COLUMN pem.webhook_alert_config.alert_id IS 'This column stores the reference to unique alert id';
COMMENT ON COLUMN pem.webhook_alert_config.send_notification IS 'This column stores whether to send webhook notification or not';
COMMENT ON COLUMN pem.webhook_alert_config.override_default_config IS 'This column stores whether default configuration is overridden';
COMMENT ON COLUMN pem.webhook_alert_config.low_webhook_ids IS 'This column stores all the webhook ids to send low alert';
COMMENT ON COLUMN pem.webhook_alert_config.med_webhook_ids IS 'This column stores all the webhook ids to send medium alert';
COMMENT ON COLUMN pem.webhook_alert_config.high_webhook_ids IS 'This column stores all the webhook ids to send high alert';
COMMENT ON COLUMN pem.webhook_alert_config.cleared_webhook_ids IS 'This column stores all the webhook ids to send cleared alert';

-- Function to log error timestamp value to pem.alert table if error_message changed
CREATE OR REPLACE FUNCTION pem.log_alert_error_timestamp() RETURNS trigger AS $$
BEGIN
        IF (NEW.error_message IS NOT NULL) THEN
                NEW.error_timestamp = now();
                RETURN NEW;
        ELSE
                NEW.error_timestamp = NULL;
                RETURN NEW;
        END IF;
END

$$ LANGUAGE plpgsql;

-- Trigger on pem.alert when the old error message changed to new error message
CREATE TRIGGER alert_error_timestamp
    BEFORE UPDATE ON pem.alert
    FOR EACH ROW
    WHEN (OLD.error_message IS DISTINCT FROM NEW.error_message)
    EXECUTE PROCEDURE pem.log_alert_error_timestamp();

COMMENT ON TRIGGER alert_error_timestamp ON pem.alert IS 'Add the current timestamp with timezone in alert table.';

