SELECT pem.create_alert_template(
	'Most used disk percentage',
	'Percentage used of the most utilized disk on the system.',
	$sql$
SELECT MAX(space_used_mb::float * 100 / (size_mb - COALESCE(space_reserved_mb, 0)))
FROM pemdata.disk_space
WHERE size_mb > 0
AND agent_id = ${agent_id}$sql$,
	100, NULL, NULL, NULL, '%','{disk_space}', (SELECT CASE WHEN MAX(snmp_oid) > 0 THEN MAX(snmp_oid) + 1 ELSE 1 END FROM pem.alert_template WHERE object_type = 100),
	'ALL', 1, 30, true, $sql$SELECT a.description AS "Agent name", d.mount_point AS "Mount point",
        d.file_system AS "File system", d.size_mb AS "Total size (MB)", d.space_used_mb AS "Space used (MB)",
        d.space_available_mb AS "Space available (MB)", d.space_reserved_mb AS "Space reserved (MB)"
    FROM
        pemdata.disk_space AS d
    JOIN pem.agent AS a
        ON d.agent_id = a.id
    WHERE
        d.size_mb > 0 AND
        d.agent_id = '${agent_id}'::integer AND
        (d.space_used_mb::float * 100 / (d.size_mb - COALESCE(d.space_reserved_mb, 0))) ${comparison_operator} '${threshold_value}'::numeric ORDER BY (d.space_used_mb::float * 100 / (d.size_mb - COALESCE(d.space_reserved_mb, 0))) DESC;$sql$,
        true, '>', '{80, 85, 90}');

SELECT pem.create_alert_template(
	'Table bloat',
	'Space wasted by the table, in MB.',
	$sql$
SELECT b.estimated_pages_wasted*s.setting::integer/1048576
FROM pemdata.table_bloat AS b
JOIN pemdata.settings AS s
ON		b.server_id = s.server_id
AND		s.name = 'block_size'
WHERE b.server_id = ${server_id}
AND		b.database_name = '${database_name}'
AND		b.schema_name = '${schema_name}'
AND		b.table_name = '${object_name}'$sql$,
	500, NULL, NULL, NULL, 'MB','{table_bloat, settings}', (SELECT CASE WHEN MAX(snmp_oid) > 0 THEN MAX(snmp_oid) + 1 ELSE 1 END FROM pem.alert_template WHERE object_type = 500),
	info_sql :=$SQL$
        SELECT b.database_name AS "Database name",b.schema_name AS "Schema name",b.table_name AS "Table name", b.estimated_pages AS "Estimated page",b.target_pages AS "Target pages",
               b.estimated_bloat_multiple AS "Estimated bloat multiple",b.estimated_bytes_per_tuple AS "Estimated bytes per tuple",
               b.estimated_pages_wasted::numeric*s.setting::integer/1048576 AS "Table bloat in MB"
        FROM pemdata.table_bloat b JOIN pemdata.settings as s ON b.server_id = s.server_id AND s.name = 'block_size'
        WHERE b.server_id = '${server_id}' AND b.database_name = '${database_name}' AND b.schema_name = '${schema_name}' AND b.table_name = '${object_name}'
        ORDER BY estimated_pages_wasted DESC;$SQL$);

