    pemdata.blocked_session_info
WHERE
    server_id = '${server_id}'::integer;$sql$);

SELECT pem.create_alert_template(
	'Percentage of buffers written by backends',
	'The percentage of buffers written by backends vs. the total buffers written.',
	$sql$
SELECT buffers_backend*100/GREATEST(buffers_checkpoint+buffers_clean+buffers_backend, 1)
FROM pemdata.background_writer_statistics
WHERE	server_id = ${server_id}$sql$,
	200, NULL, NULL, NULL, '%','{background_writer_statistics}', (SELECT CASE WHEN MAX(snmp_oid) > 0 THEN MAX(snmp_oid) + 1 ELSE 1 END FROM pem.alert_template WHERE object_type = 200));

SELECT pem.create_alert_template(
	'Percentage of buffers written by checkpoint',
	'The percentage of buffers written by the checkpoints vs. the total buffers written.',
	$sql$
SELECT buffers_checkpoint*100/GREATEST(buffers_checkpoint+buffers_clean+buffers_backend, 1)
FROM pemdata.background_writer_statistics
WHERE	server_id = ${server_id}$sql$,
	200, NULL, NULL, NULL, '%','{background_writer_statistics}', (SELECT CASE WHEN MAX(snmp_oid) > 0 THEN MAX(snmp_oid) + 1 ELSE 1 END FROM pem.alert_template WHERE object_type = 200));

SELECT pem.create_alert_template(
	'Buffers written per second',
	'Number of buffers written per second, over the last two probe cycles.',
	$sql$
SELECT (d.buffers_checkpoint + d.buffers_clean + d.buffers_backend)
		- (h.buffers_checkpoint + h.buffers_clean + h.buffers_backend)
FROM pemdata.background_writer_statistics AS d
JOIN pemhistory.background_writer_statistics AS h
ON		d.server_id = h.server_id
WHERE	d.server_id = ${server_id}
AND		h.recorded_time = (SELECT max(recorded_time)
							FROM pemhistory.background_writer_statistics AS h2
							WHERE	h2.server_id = d.server_id
							AND		h2.recorded_time < d.recorded_time)$sql$,
	200, NULL, NULL, NULL, '#','{background_writer_statistics}', (SELECT CASE WHEN MAX(snmp_oid) > 0 THEN MAX(snmp_oid) + 1 ELSE 1 END FROM pem.alert_template WHERE object_type = 200));

SELECT pem.create_alert_template(
	'Buffers allocated per second',
	'Number of buffers allocated per second, over the last two probe cycles.',
	$sql$
SELECT d.buffers_alloc - h.buffers_alloc
FROM pemdata.background_writer_statistics AS d
JOIN pemhistory.background_writer_statistics AS h
ON		d.server_id = h.server_id
WHERE	d.server_id = ${server_id}
AND		h.recorded_time = (SELECT max(recorded_time)
							FROM pemhistory.background_writer_statistics AS h2
							WHERE	h2.server_id = d.server_id
							AND		h2.recorded_time < d.recorded_time)$sql$,
	200, NULL, NULL, NULL, '#','{background_writer_statistics}', (SELECT CASE WHEN MAX(snmp_oid) > 0 THEN MAX(snmp_oid) + 1 ELSE 1 END FROM pem.alert_template WHERE object_type = 200));

SELECT pem.create_alert_template(
