SELECT pem.create_alert_template(
	'Connections in idle-in-transaction state, as a percentage of max_connections',
	'Number of connections in database that are in idle-in-transaction state, as a percentage of maximum connections allowed on server, settings',
	$sql$
SELECT COALESCE((SELECT COUNT(*)::float * 100 / mc.setting::integer
FROM pemdata.session_info AS si
JOIN pemdata.settings AS mc
ON		si.server_id = mc.server_id
