SELECT pem.create_alert_template(
	'Long-running queries',
	'Number of queries in database that have been running for more than N seconds specified in "Parameter Options" section.',
	$sql$
SELECT COUNT(*)
FROM    pemdata.session_info
WHERE	server_id = ${server_id}
AND		database_name = '${database_name}'
/* query_start is updated, and not set to null when connection goes into idle state */
AND		is_idle = false
AND		is_vacuum = false
AND		is_autovacuum = false
