SELECT pem.create_alert_template(
	'Committed transactions percentage',
	'Percentage of transactions in the database that committed vs. that rolled-back over last N minutes specified in "Parameter Options" section.',
	$sql$
SELECT
    CASE
    WHEN (commits + rollbacks) = 0 THEN 100
    ELSE (commits * 100) / (commits + rollbacks)
    END percentage
FROM (SELECT
        SUM(h.xact_commit_pit)::float AS commits,
        SUM(h.xact_rollback_pit)::float AS rollbacks
    FROM pemhistory.database_statistics h
    WHERE
        h.server_id = ${server_id}::int4 AND h.database_name = '${database_name}'
        AND (h.xact_commit_pit >= 0 OR h.xact_commit_pit IS NOT NULL)
        AND h.recorded_time >= (
	    SELECT min(recorded_time) - '${param_1} minutes'::interval FROM pemdata.database_statistics d
	    WHERE d.server_id = ${server_id}::int4 AND d.database_name = '${database_name}'
	    )
    HAVING count(*) != 0
    ) t
$sql$,
	300, '{Time interval to monitor}', '{INTEGER}', '{Minutes}', '%','{database_statistics}', (SELECT CASE WHEN MAX(snmp_oid) > 0 THEN MAX(snmp_oid) + 1 ELSE 1 END FROM pem.alert_template WHERE object_type = 300));

