SELECT pem.create_alert_template(
	'Percentage of buffers written by backends over last N minutes',
	'The percentage of buffers written by backends vs. the total buffers written over last N minutes specified in "Parameter Options" section.

Probe dependency list: background_writer_statistics',
	$sql$
SELECT bg.buffers_backend::float * 100
		/GREATEST(bg.buffers_checkpoint+bg.buffers_clean+bg.buffers_backend, 1)
FROM pemdata.background_writer_statistics AS bg
JOIN	pemhistory.background_writer_statistics AS h
ON		bg.server_id = h.server_id
WHERE	bg.server_id = ${server_id}
AND		h.recorded_time = (SELECT min(recorded_time)
							FROM pemhistory.background_writer_statistics AS h2
							WHERE	h2.server_id = bg.server_id
							AND		h2.recorded_time > bg.recorded_time
														- '${param_1} minutes'::interval)$sql$,
	200, '{Time interval to monitor}', '{INTEGER}', '{Minutes}', '%','{background_writer_statistics}', (SELECT CASE WHEN MAX(snmp_oid) > 0 THEN MAX(snmp_oid) + 1 ELSE 1 END FROM pem.alert_template WHERE object_type = 200));

