SELECT pem.create_alert_template(
	'Number of users expiring in N days',
	'Number of users whose accounts are expiring in N days.(Will return top 10 users only)',
	$sql$
SELECT value AS display_value FROM (SELECT count(*)
             AS value
            FROM
                pemdata.user_info
            WHERE  server_id = ${server_id}
            AND		valuntil IS NOT NULL
            AND		valuntil NOT IN ('infinity','-infinity')
            AND		valuntil < now()+('${param_1}'||'days')::interval
            AND ('${param_2}' OR valuntil > NOW()))s
$sql$,
	200, '{Number of days,Include expired users?}', '{INTEGER,BOOL}', '{Days, True or False}', '#','{user_info}', (SELECT CASE WHEN MAX(snmp_oid) > 0 THEN MAX(snmp_oid) + 1 ELSE 1 END FROM pem.alert_template WHERE object_type = 200),
    info_sql := $SQL$
SELECT usename AS "Username",
        CASE
            WHEN valuntil > now() THEN
                CASE
                    WHEN ROUND(EXTRACT(EPOCH FROM (valuntil - capture_time)) / 86400)::integer = 1 THEN
                    '1 day'
                ELSE
                    ROUND(EXTRACT(EPOCH FROM (valuntil - capture_time)) / 86400)::integer || ' days'
                END
            ELSE
        'Expired'
        END AS "Account expires (in Days)",
        CASE
            WHEN usesuper = true THEN 'True'
            ELSE 'False'
        END AS "Is superuser?",
        valuntil AS "Account expires on"
        FROM
            pemdata.user_info
        WHERE  server_id = '${server_id}'
        AND    valuntil IS NOT NULL
        AND    valuntil NOT IN ('infinity','-infinity')
        AND    valuntil < now()+('${param_1}'||'days')::interval
        AND ('${param_2}' OR valuntil > NOW())
        GROUP BY usename, usesuper, valuntil, capture_time
        ORDER BY 2 ASC LIMIT 10;
$SQL$
);

