		/ CASE sum(tsz.table_size_mb) WHEN 0 THEN 1 ELSE sum(tsz.table_size_mb) END
FROM	pemdata.table_size AS tsz
WHERE	tsz.server_id = ${server_id}
AND		tsz.database_name = '${database_name}'$sql$,
	300, NULL, NULL, NULL, '%','{table_size}', (SELECT CASE WHEN MAX(snmp_oid) > 0 THEN MAX(snmp_oid) + 1 ELSE 1 END FROM pem.alert_template WHERE object_type = 300),
	'ALL', 1, 30, true, NULL);

