SELECT pem.create_alert_template(
       'Audit config mismatch',
       'Check for audit config parameter mismatch',
       $sql$
SELECT
  CASE
    WHEN COUNT(r.result) <> 0 THEN MAX(r.result)
    ELSE -1
  END
FROM
  (SELECT
     CASE
       WHEN(p.edb_audit = pd.edb_audit
         AND p.edb_audit_directory = pd.edb_audit_directory
         AND p.edb_audit_filename = pd.edb_audit_filename
         AND p.edb_audit_rotation_day = pd.edb_audit_rotation_day
         AND p.edb_audit_rotation_sec = pd.edb_audit_rotation_sec
         AND p.edb_audit_rotation_size = pd.edb_audit_rotation_size
         AND p.edb_audit_connect = pd.edb_audit_connect
         AND p.edb_audit_disconnect = pd.edb_audit_disconnect
         AND p.edb_audit_statements = pd.edb_audit_statements
         AND p.edb_audit_tag = pd.edb_audit_tag
         AND p.edb_audit_destination = pd.edb_audit_destination) OR (p.server_id IS NULL)
         THEN -1
       ELSE 1
     END AS result
   FROM
     pem.audit_configuration p RIGHT JOIN
     pemdata.audit_configuration pd ON (p.server_id = pd.server_id)
   WHERE p.server_id = ${server_id}) AS r $sql$,
       200, NULL, NULL, NULL, '#','{audit_configuration}',
	   (SELECT CASE WHEN MAX(snmp_oid) > 0 THEN MAX(snmp_oid) + 1 ELSE 1 END FROM pem.alert_template WHERE object_type = 200), 'ADVANCED_SERVER',
	   1, 30, true,
$sql$SELECT a[1] as "Parameter", a[2] AS "User specified value", a[3] as "Current value"
FROM (
  SELECT pem.reduce_dim(
      ARRAY[
       CASE
         WHEN(p.edb_audit != pd.edb_audit) THEN ARRAY['Audit parameter'::text, p.edb_audit::text, pd.edb_audit::text]::text[]
	     ELSE ARRAY[null, null, null]::text[]
       END,
       CASE
         WHEN(p.edb_audit_directory != pd.edb_audit_directory) THEN ARRAY['Audit Directory'::text, p.edb_audit_directory::text, pd.edb_audit_directory::text]::text[]
	     ELSE ARRAY[null, null, null]::text[]
       END,
       CASE
         WHEN(p.edb_audit_filename != pd.edb_audit_filename) THEN ARRAY['Audit filename'::text, p.edb_audit_filename::text, pd.edb_audit_filename::text]::text[]
	     ELSE ARRAY[null, null, null]::text[]
       END,
       CASE
         WHEN(p.edb_audit_rotation_day != pd.edb_audit_rotation_day) THEN ARRAY['Audit rotation day'::text, p.edb_audit_rotation_day::text, pd.edb_audit_rotation_day::text]::text[]
	     ELSE ARRAY[null, null, null]::text[]
       END,
       CASE
         WHEN(p.edb_audit_rotation_sec != pd.edb_audit_rotation_sec) THEN ARRAY['Audit rotation sec'::text, p.edb_audit_rotation_sec::text, pd.edb_audit_rotation_sec::text]::text[]
	     ELSE ARRAY[null, null, null]::text[]
       END,
       CASE
         WHEN(p.edb_audit_rotation_size != pd.edb_audit_rotation_size) THEN ARRAY['Audit rotation size'::text, p.edb_audit_rotation_size::text, pd.edb_audit_rotation_size::text]::text[]
	     ELSE ARRAY[null, null, null]::text[]
       END,
       CASE
         WHEN(p.edb_audit_connect != pd.edb_audit_connect) THEN ARRAY['Audit connect'::text, p.edb_audit_connect::text, pd.edb_audit_connect::text]::text[]
	     ELSE ARRAY[null, null, null]::text[]
       END,
       CASE
         WHEN(p.edb_audit_disconnect != pd.edb_audit_disconnect) THEN ARRAY['Audit disconnect'::text, p.edb_audit_disconnect::text, pd.edb_audit_disconnect::text]::text[]
	     ELSE ARRAY[null, null, null]::text[]
       END,
       CASE
         WHEN(p.edb_audit_statements != pd.edb_audit_statements) THEN ARRAY['Audit statements'::text, p.edb_audit_statements::text, pd.edb_audit_statements::text]::text[]
	     ELSE ARRAY[null, null, null]::text[]
       END,
       CASE
         WHEN(p.edb_audit_tag != pd.edb_audit_tag) THEN ARRAY['Audit tag'::text, p.edb_audit_tag::text, pd.edb_audit_tag::text]::text[]
	     ELSE ARRAY[null, null, null]::text[]
       END,
       CASE
         WHEN(p.edb_audit_destination != pd.edb_audit_destination) THEN ARRAY['Audit destination'::text, p.edb_audit_destination::text, pd.edb_audit_destination::text]::text[]
	     ELSE ARRAY[null, null, null]::text[]
       END ]::text[]) as a
   FROM
     pem.audit_configuration p RIGHT JOIN
     pemdata.audit_configuration pd ON (p.server_id = pd.server_id)
   WHERE p.server_id = '${server_id}'::integer) t
WHERE t.a[1] is not NULL ORDER BY t.a[1];$sql$, true, '>', '{0.1, 0.2, 0.3}'
);

SELECT pem.create_alert_template(
	'Agent Down',
	'Specified agent is currently down',
	$sql$
SELECT
    count(pa.id) AS current_value,
    CASE WHEN count(pa.id) = 0 THEN 'UP' ELSE 'DOWN' END display_value
FROM
    pem.agent pa LEFT OUTER JOIN pem.agent_heartbeat pah ON (pa.id = pah.agent_id)
WHERE
    pa.id = ${agent_id} AND
    pa.active = TRUE AND
    NOT pa.alert_blackout AND
    CASE WHEN pah.agent_id IS NULL THEN FALSE ELSE pah.last_heartbeat < now() - (pa.heartbeat_tolerance+15)*'1 second'::interval END$sql$,
    100, NULL, NULL, NULL, 'STATE', '{}', (SELECT CASE WHEN MAX(snmp_oid) > 0 THEN MAX(snmp_oid) + 1 ELSE 1 END FROM pem.alert_template WHERE object_type = 100),
    'ALL', 1, 30, true,$SQL$
    SELECT pa.description AS "Agent description",pa.platform AS "Agent platform", pah.last_heartbeat AS "Down since", pa.heartbeat_tolerance AS "Hearbeat tolerance"
    FROM
           pem.agent pa LEFT OUTER JOIN pem.agent_heartbeat pah ON (pa.id = pah.agent_id)
    WHERE
        pa.id = '${agent_id}' AND
        pa.active = TRUE AND
    NOT pa.alert_blackout AND
    CASE WHEN pah.agent_id IS NULL THEN FALSE ELSE pah.last_heartbeat < now() - (pa.heartbeat_tolerance+15)*'1 second'::interval END;$SQL$,
true, '>', '{0.1, 0.2, 0.3}');

SELECT pem.create_alert_template(
	'Server Down',
	'Specified server is currently inaccessible.',
