INSERT INTO pem.config (param, value, unit, datatype) VALUES ('auto_create_agent_alerts', 't', 't/f', 'bool');
INSERT INTO pem.config (param, value, unit, datatype) VALUES ('auto_create_server_alerts', 't', 't/f', 'bool');

CREATE OR REPLACE FUNCTION pem.check_alert_exist(alert_name text, alert_agent_id integer, alert_server_id integer,
					alert_database_name text, alert_schema_name text,
					alert_package_name text, alert_object_name text, alert_object_type integer)
RETURNS boolean AS $$
DECLARE
	is_already_exist boolean:= false;
BEGIN
	-- select alert already exist
	PERFORM id FROM pem.alert WHERE name = alert_name AND template_id = (SELECT id FROM pem.alert_template WHERE display_name = alert_name AND object_type = alert_object_type LIMIT 1)
	AND agent_id = alert_agent_id
	AND CASE WHEN alert_server_id IS NULL THEN (server_id IS NULL OR server_id = 0) ELSE server_id = alert_server_id END
	AND CASE WHEN alert_database_name IS NULL THEN (database_name IS NULL OR database_name = '') ELSE database_name = alert_database_name END
	AND CASE WHEN alert_schema_name IS NULL THEN (schema_name IS NULL OR schema_name = '') ELSE schema_name = alert_schema_name END
	AND CASE WHEN alert_package_name IS NULL THEN (package_name IS NULL OR package_name = '') ELSE package_name = alert_package_name END
	AND CASE WHEN alert_object_name IS NULL THEN (object_name IS NULL OR object_name = '') ELSE object_name = alert_object_name END;

	IF FOUND THEN
		is_already_exist := true;
	END IF;

	RETURN is_already_exist;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION pem.auto_create_agent_alerts()
RETURNS trigger AS $$
DECLARE
	is_auto_create boolean:= false;
BEGIN
	-- select value of auto_create_agent_alerts
	SELECT value INTO is_auto_create FROM pem.config WHERE param = 'auto_create_agent_alerts';

	IF is_auto_create THEN
		PERFORM pem.create_default_agent_alerts(NEW.id);
	END IF;
	RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION pem.create_default_agent_alerts(agent_id integer)
RETURNS VOID AS $$
DECLARE
	temp_rec record;
BEGIN

	FOR temp_rec IN EXECUTE 'SELECT id, display_name, default_check_frequency, default_history_retention, operator, thresholds FROM pem.alert_template WHERE object_type = 100 and is_auto_create ORDER BY id'
	LOOP
		IF NOT pem.check_alert_exist(temp_rec.display_name, $1, NULL, NULL, NULL, NULL, NULL, 100) THEN
			PERFORM pem.create_alert(temp_rec.display_name, temp_rec.id,
			$1, NULL, NULL, NULL, NULL, NULL, '{}', temp_rec.operator, temp_rec.thresholds,
			temp_rec.default_check_frequency, temp_rec.default_history_retention, true, true);
		END IF;
	END LOOP;

END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION pem.auto_create_alerts_on_exisiting_agents()
RETURNS VOID AS $$
DECLARE
	rec record;
BEGIN
	FOR rec in (SELECT id FROM pem.agent WHERE active = true)
	LOOP
		PERFORM pem.create_default_agent_alerts(rec.id);
	END LOOP;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION pem.auto_create_server_alerts()
RETURNS trigger AS $$
DECLARE
	is_auto_create boolean:= false;
BEGIN
	-- select value of auto_create_server_alerts
	SELECT value INTO is_auto_create FROM pem.config WHERE param = 'auto_create_server_alerts';

	IF is_auto_create THEN
		PERFORM pem.create_default_server_alerts(NEW.server_id);
	END IF;
	RETURN NEW;
END;
$$ LANGUAGE plpgsql;

