CREATE OR REPLACE FUNCTION pem.create_default_server_alerts(server_id integer, server_version_id integer DEFAULT 0)
RETURNS VOID AS $$
DECLARE
	temp_rec record;
	sql text;
	enabled boolean;
BEGIN
	IF server_version_id = 0 THEN
		sql = 'SELECT id, display_name, default_check_frequency, default_history_retention, operator, thresholds FROM pem.alert_template WHERE object_type = 200 and is_auto_create and applicable_on_server = ''ALL'' ORDER BY id';
	ELSIF (server_version_id > 10900 AND server_version_id < 20000) THEN
		sql = 'SELECT id, display_name, default_check_frequency, default_history_retention, operator, thresholds FROM pem.alert_template WHERE object_type = 200 and is_auto_create and applicable_on_server IN (''ALL'', ''POSTGRES_SERVER'') ORDER BY id';
	ELSIF (server_version_id > 20000) THEN
		sql = 'SELECT id, display_name, default_check_frequency, default_history_retention, operator, thresholds FROM pem.alert_template WHERE object_type = 200 and is_auto_create and applicable_on_server IN (''ALL'', ''ADVANCED_SERVER'') ORDER BY id';
	END IF;
	FOR temp_rec IN EXECUTE sql
	LOOP

		IF temp_rec.display_name in ('Database size in server',' Total table size in server','Number of WAL archives pending') THEN
		    enabled = false;
		  else
		    enabled = true;
		END IF;

		IF NOT pem.check_alert_exist(temp_rec.display_name, 0, $1, NULL, NULL, NULL, NULL, 200) THEN
			PERFORM pem.create_alert(temp_rec.display_name, temp_rec.id,
			0, $1, NULL, NULL, NULL, NULL, '{}', temp_rec.operator, temp_rec.thresholds,temp_rec.default_check_frequency, temp_rec.default_history_retention, enabled, true);
		END IF;
	END LOOP;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION pem.auto_create_alerts_on_exisiting_servers()
RETURNS VOID AS $$
DECLARE
	rec record;
	server_version integer;
BEGIN
	FOR rec in (SELECT id FROM pem.server WHERE active = true)
	LOOP
		SELECT server_version_id INTO server_version FROM pemdata.server_info WHERE server_id = rec.id;
		IF NOT FOUND THEN
		  PERFORM pem.create_default_server_alerts(rec.id, 0);
		ELSE
		  PERFORM pem.create_default_server_alerts(rec.id, server_version);
		END IF;
	END LOOP;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER auto_create_agent_alerts_trigger AFTER INSERT
	ON pem.agent FOR EACH ROW
	EXECUTE PROCEDURE pem.auto_create_agent_alerts();
COMMENT ON TRIGGER auto_create_agent_alerts_trigger ON pem.agent IS 'Create some auto configured agent level alerts.';

CREATE TRIGGER auto_create_server_alerts_trigger AFTER INSERT
	ON pem.agent_server_binding FOR EACH ROW
	EXECUTE PROCEDURE pem.auto_create_server_alerts();
COMMENT ON TRIGGER auto_create_server_alerts_trigger ON pem.agent_server_binding IS 'Create some auto configured server level alerts.';

CREATE OR REPLACE FUNCTION pem.alert_template_postupdate() RETURNS trigger AS $$
BEGIN
	UPDATE pem.alert SET error_message = '' WHERE template_id = NEW.id;
	IF NEW.is_auto_create AND OLD.is_auto_create <> NEW.is_auto_create THEN
		-- Newly marked as auto-create: ensure template is present in all published profiles
		-- (Published and draft profiles inherit auto-create templates.)
		IF NEW.object_type IN (100,200) THEN
		INSERT INTO pem.profile_alert_configs (
			profile_id, template_id, name, params, operator, thresholds, check_frequency,
			history_retention, enabled, email_group_id, send_email, send_trap, snmp_trap_version,
			low_send_trap, low_email_group_id, med_send_trap, med_email_group_id, high_send_trap,
			high_email_group_id, execute_script, execute_script_on_clear, execute_script_on_pem_server,
			script_code, submit_to_nagios, cleared_alert_enable
		)
		SELECT p.id, NEW.id, NEW.display_name, '{}'::text[], NEW.operator, NEW.thresholds,
		       NEW.default_check_frequency, NEW.default_history_retention, TRUE,
		       NULL, FALSE, FALSE, 1,
		       FALSE, NULL, FALSE, NULL, FALSE, NULL,
		       FALSE, FALSE, FALSE, NULL, FALSE, FALSE
		FROM pem.profile p
		WHERE p.status IN ('published','draft')
		  AND ((NEW.object_type = 100 AND p.target_kind = 'a') OR (NEW.object_type = 200 AND p.target_kind = 's'))
		ON CONFLICT (profile_id, name) DO NOTHING;
		END IF;
	    IF NEW.object_type = 100 THEN
		    PERFORM pem.auto_create_alerts_on_exisiting_agents();
	    ELSIF NEW.object_type = 200 THEN
		    PERFORM pem.auto_create_alerts_on_exisiting_servers();
	    END IF;
	END IF;
	RETURN NULL;
END
$$ LANGUAGE plpgsql;

CREATE TRIGGER custom_alert_template_postupdate
	AFTER UPDATE ON pem.alert_template
	FOR EACH ROW EXECUTE PROCEDURE pem.alert_template_postupdate();

CREATE OR REPLACE FUNCTION pem.alert_template_postinsert() RETURNS trigger AS $$
BEGIN
	IF NEW.is_auto_create THEN
		-- Insert auto-create template into all published and draft profiles at creation time.
		IF NEW.object_type IN (100,200) THEN
		INSERT INTO pem.profile_alert_configs (
			profile_id, template_id, name, params, operator, thresholds, check_frequency,
			history_retention, enabled, email_group_id, send_email, send_trap, snmp_trap_version,
			low_send_trap, low_email_group_id, med_send_trap, med_email_group_id, high_send_trap,
			high_email_group_id, execute_script, execute_script_on_clear, execute_script_on_pem_server,
			script_code, submit_to_nagios, cleared_alert_enable
		)
		SELECT p.id, NEW.id, NEW.display_name, '{}'::text[], NEW.operator, NEW.thresholds,
		       NEW.default_check_frequency, NEW.default_history_retention, TRUE,
		       NULL, FALSE, FALSE, 1,
		       FALSE, NULL, FALSE, NULL, FALSE, NULL,
		       FALSE, FALSE, FALSE, NULL, FALSE, FALSE
		FROM pem.profile p
		WHERE p.status IN ('published','draft')
		  AND ((NEW.object_type = 100 AND p.target_kind = 'a') OR (NEW.object_type = 200 AND p.target_kind = 's'))
		ON CONFLICT (profile_id, name) DO NOTHING;
		END IF;
	    IF NEW.object_type = 100 THEN
		    PERFORM pem.auto_create_alerts_on_exisiting_agents();
	    ELSIF NEW.object_type = 200 THEN
		    PERFORM pem.auto_create_alerts_on_exisiting_servers();
	    END IF;
	END IF;
	RETURN NULL;
END
$$ LANGUAGE plpgsql;

CREATE TRIGGER custom_alert_template_postinsert
	AFTER INSERT ON pem.alert_template
	FOR EACH ROW EXECUTE PROCEDURE pem.alert_template_postinsert();

/********************************
* SMTP Spooler			*
********************************/
INSERT INTO pem.config (param, value, unit, datatype) VALUES ('smtp_server', '127.0.0.1', '', 'string'); -- The SMTP mail server/smarthost to use
INSERT INTO pem.config (param, value, unit, datatype) VALUES ('smtp_port', '25', '', 'integer'); -- The SMTP port on the mail server
INSERT INTO pem.config (param, value, unit, datatype) VALUES ('smtp_encryption', 'f', 't/f', 'bool'); -- Should a secure connection be used (t/f)?
INSERT INTO pem.config (param, value, unit, datatype) VALUES ('smtp_username', NULL, '', 'string'); -- The username for the SMTP server
INSERT INTO pem.config (param, value, unit, datatype) VALUES ('smtp_password', NULL, '', 'password'); -- The password for the SMTP server
INSERT INTO pem.config (param, value, unit, datatype) VALUES ('smtp_enabled', 't', 't/f', 'bool'); -- Enable/disable SMTP delivery (t/f)
INSERT INTO pem.config (param, value, unit, datatype) VALUES ('smtp_authentication', 'f', 't/f', 'bool'); -- Required authentication (t/f)
INSERT INTO pem.config (param, value, unit, datatype) VALUES ('reminder_notification_interval', '1440', 'minutes', 'integer'); -- Reminder notification interval
INSERT INTO pem.config (param, value, unit, datatype) VALUES ('flapping_detection_state_change', '3', '', 'integer'); -- Default no of state change for flapping detection
INSERT INTO pem.config (param, value, unit, datatype) VALUES ('smtp_spool_retention_time', '7', 'days', 'integer'); -- Default values to be used by purging function.
INSERT INTO pem.config (param, value, unit, datatype, options) VALUES ('smtp_message_linebreak', '1', '', 'enum', '[{"label": "LF", "value": "1"}, {"label": "CR", "value": "2"}, { "label": "CR+LF", "value": "3"}, {"label": "LF+CR", "value": "4"}]'); -- This Line break character will be used in SMTP message body

CREATE TABLE pem.smtp_spool (
	id 		serial NOT NULL,
	mail_to 	text NOT NULL,
	mail_cc		text,
	mail_bcc	text,
	mail_from	text NOT NULL,
	mail_reply_to	text,
	subject		text NOT NULL,
	message		text NOT NULL,
	error_count	integer,
	sent_status 	char NOT NULL,
	recorded_time	timestamp with time zone NOT NULL DEFAULT now(),

	CONSTRAINT smtp_spool_pkey PRIMARY KEY (id),

	CONSTRAINT smtp_spool_sent_status
	CHECK (sent_status IN ('s', 'u', 'i'))
);

CREATE OR REPLACE FUNCTION pem.send_email(mail_group_id integer[], subject text, message text)
RETURNS boolean AS $$
DECLARE
	mail_to text[] := '{}';
	mail_cc text[] := '{}';
	mail_bcc text[] := '{}';
	mail_reply_to text[] := '{}';
	mail_to_str text := '';
	mail_cc_str text := '';
	mail_bcc_str text := '';
	mail_reply_to_str text := '';
	mail_from_str text := '';
	mail_subject_prefix text := '';
	is_smtp_enabled boolean:= false;
	smtp_message_linebreak text;
	i integer;
	is_notify boolean:= false;
	tmp_row RECORD;
	now_time numeric;
BEGIN
	-- Check if smtp_enabled == true, if not return.
	SELECT value INTO is_smtp_enabled FROM pem.config WHERE param = 'smtp_enabled';

	-- Check the linebreak for message body
	SELECT res_option ->> 'label' AS label INTO smtp_message_linebreak
		FROM   pem.config pc, json_array_elements(pc.options) res_option
	WHERE  param = 'smtp_message_linebreak' AND res_option->>'value' = pc.value;

	IF smtp_message_linebreak = 'LF' THEN
		smtp_message_linebreak := '\n';
	ELSIF (smtp_message_linebreak = 'CR') THEN
		smtp_message_linebreak := '\r';
	ELSIF (smtp_message_linebreak = 'CR+LF') THEN
		smtp_message_linebreak := '\r\n';
	ELSIF (smtp_message_linebreak = 'LF+CR') THEN
		smtp_message_linebreak := '\n\r';
	END IF;

	-- If user has specified any other linebreak value then replace it against default `\n`.
	IF smtp_message_linebreak IS NOT NULL AND LENGTH(TRIM(smtp_message_linebreak)) > 0 AND TRIM(smtp_message_linebreak) != '\n' THEN
		message := REPLACE(message, '\n', smtp_message_linebreak);
	END IF;

	SELECT (EXTRACT(EPOCH FROM now()::timetz) + EXTRACT(TIMEZONE FROM now()::timetz)) INTO now_time;

	-- There are not email groups for the email to send.
	IF COALESCE(array_length(mail_group_id, 1), 0) = 0 THEN
		RETURN false;
	END IF;

	IF is_smtp_enabled THEN
		-- iterate through all the group id's and insert into the spool table
		FOR i in 1..COALESCE(array_upper(mail_group_id, 1), 0) LOOP

			-- Clear the email address array before any operations.
			mail_to := '{}';
			mail_cc := '{}';
			mail_bcc := '{}';
			mail_reply_to := '{}';

			-- Get email details
			-- iterate through all time intervals for a particular group and
			-- check time against server's current time and send mail to only
			-- those addresses for which current time lies within their interval
			FOR tmp_row IN SELECT grp_to, grp_cc, grp_bcc, grp_from, grp_reply_to, grp_subject_prefix, (EXTRACT(EPOCH FROM time_from) + EXTRACT(TIMEZONE FROM time_from)) as time_from, (EXTRACT(EPOCH FROM time_to) + EXTRACT(TIMEZONE FROM time_to)) as time_to FROM pem.email_group_option WHERE gid = mail_group_id[i]
			LOOP

				-- If 'FROM' is not available, we won't be to send the email.
				CONTINUE WHEN tmp_row.grp_from = '';

				IF tmp_row.time_from < tmp_row.time_to THEN
					IF tmp_row.time_from <= now_time AND now_time <= tmp_row.time_to THEN
						mail_to := array_append(mail_to, tmp_row.grp_to);
						mail_cc := array_append(mail_cc, tmp_row.grp_cc);
						mail_bcc := array_append(mail_bcc, tmp_row.grp_bcc);
						mail_reply_to := array_append(mail_reply_to, tmp_row.grp_reply_to);
						mail_from_str := tmp_row.grp_from;
						mail_subject_prefix := COALESCE(tmp_row.grp_subject_prefix, '')::text;
					END IF;
				ELSIF tmp_row.time_from > tmp_row.time_to THEN
					IF (tmp_row.time_from <= now_time AND now_time <= (EXTRACT(EPOCH FROM '23:59:59'::timetz) + EXTRACT(TIMEZONE FROM '23:59:59'::timetz))) OR
						((EXTRACT(EPOCH FROM '00:00:00'::timetz) + EXTRACT(TIMEZONE FROM '00:00:00'::timetz)) <= now_time AND now_time <=tmp_row.time_to) THEN
						mail_to := array_append(mail_to, tmp_row.grp_to);
						mail_cc := array_append(mail_cc, tmp_row.grp_cc);
						mail_bcc := array_append(mail_bcc, tmp_row.grp_bcc);
						mail_reply_to := array_append(mail_reply_to, tmp_row.grp_reply_to);
						mail_from_str := tmp_row.grp_from;
						mail_subject_prefix := COALESCE(tmp_row.grp_subject_prefix, '')::text;
					END IF;
				END IF;
			END LOOP;

			mail_to_str := array_to_string(array_remove(array_remove(mail_to, ''), NULL), ',');
			mail_cc_str := array_to_string(array_remove(array_remove(mail_cc, ''), NULL), ',');
			mail_bcc_str := array_to_string(array_remove(array_remove(mail_bcc, ''), NULL), ',');
			mail_reply_to_str := array_to_string(array_remove(array_remove(mail_reply_to, ''), NULL), ',');

			-- We won't be able to send an email if all TO, CC and BCC are not available.
			CONTINUE WHEN mail_to_str = '' AND mail_cc_str = '' AND mail_bcc_str = '';

			IF COALESCE(mail_subject_prefix, '') <> '' THEN
				subject := mail_subject_prefix || ': ' || subject;
			END IF;

			-- Insert the spool record
			INSERT INTO pem.smtp_spool(
				mail_to, mail_cc, mail_bcc, mail_reply_to, mail_from,
				subject, message, sent_status
			) VALUES(
				mail_to_str, mail_cc_str, mail_bcc_str, mail_reply_to_str, mail_from_str,
				subject, message, 'u'
			);

			is_notify = true;

		END LOOP;

		IF is_notify THEN
			-- Notify listeners that a message is ready for delivery
			NOTIFY SMTP_SPOOL;
			RETURN true;
		END IF;
	END IF;

	RETURN false;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Function used to get the active webhook endpoints
CREATE or REPLACE FUNCTION pem.get_webhook_endpoints(_alert_id integer) RETURNS TABLE (
	_alertid integer,
	_send_notification bool,
	_low_webhook_ids integer[],
	_med_webhook_ids integer[],
	_high_webhook_ids integer[],
	_cleared_webhook_ids integer[]
  ) AS $$
DECLARE
	_lwids integer[];
	_mwids integer[];
	_hwids integer[];
	_cwids integer[];
BEGIN
	-- Check if user has overidden default webhook end points.
	IF EXISTS (SELECT 1 FROM pem.webhook_alert_config where alert_id = _alert_id) THEN
		RETURN QUERY SELECT alert_id, send_notification,
                        (SELECT array_agg(id) FROM pem.webhook_endpoints we JOIN
					        unnest(low_webhook_ids) low_ids ON low_ids = we.id WHERE we.enabled = true) AS low_webhook_ids,
						(SELECT array_agg(id) FROM pem.webhook_endpoints we JOIN
						    unnest(med_webhook_ids) med_ids ON med_ids = we.id WHERE we.enabled = true) AS med_webhook_ids,
						(SELECT array_agg(id) FROM pem.webhook_endpoints we JOIN
						    unnest(high_webhook_ids) high_ids ON high_ids = we.id WHERE we.enabled = true) AS high_webhook_ids,
						(SELECT array_agg(id) FROM pem.webhook_endpoints we JOIN
						    unnest(cleared_webhook_ids) clear_ids ON clear_ids = we.id WHERE we.enabled = true) AS cleared_webhook_ids
			     FROM pem.webhook_alert_config WHERE alert_id = _alert_id AND  send_notification = true LIMIT 1;
	ELSE
		-- Get default webhook end points if not overridden by user
		SELECT array_agg(id) INTO  _lwids FROM pem.webhook_endpoints WHERE enabled = true AND low_alert = true;
		SELECT array_agg(id) INTO  _mwids FROM pem.webhook_endpoints WHERE enabled = true AND med_alert = true;
		SELECT array_agg(id) INTO  _hwids FROM pem.webhook_endpoints WHERE enabled = true AND high_alert = true;
		SELECT array_agg(id) INTO  _cwids FROM pem.webhook_endpoints WHERE enabled = true AND cleared_alert = true;

	RETURN QUERY SELECT
		(SELECT CASE WHEN pa.a = 1 THEN _alert_id ELSE NULL END
			FROM (SELECT 1 as a FROM pem.alert WHERE id = _alert_id) as pa),
				true, _lwids, _mwids, _hwids, _cwids;
	END IF;
END;
$$ LANGUAGE plpgsql;

-- JIRA: PEM-3834: Replace json params if not applicable with null

CREATE OR REPLACE FUNCTION pem.replace_json_params(original_string text, to_replace text, replace_with text, additional_flag text)
RETURNS text AS $$
DECLARE
	result text;
BEGIN
    IF replace_with IS NULL OR replace_with = '' THEN
        SELECT concat('"',to_replace,'"') INTO to_replace;
        result = regexp_replace(original_string, to_replace, 'null'::text, additional_flag);
    ELSE
        SELECT replace(replace_with::text,'"','\"') INTO replace_with;
        result = regexp_replace(original_string, to_replace, replace_with::text, additional_flag);
    END IF;
    RETURN result;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- JIRA: PEM-3834: Replace text params if not applicable with blank text

CREATE OR REPLACE FUNCTION pem.replace_text_params(original_string text, to_replace text, replace_with text, additional_flag text)
RETURNS text AS $$
DECLARE
	result text;
BEGIN
    IF replace_with IS NULL OR replace_with = '' THEN
        result = regexp_replace(original_string, to_replace, '', additional_flag);
    ELSE
        result = regexp_replace(original_string, to_replace, replace_with::text, additional_flag);
    END IF;
    RETURN result;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION pem.send_notifications() RETURNS trigger AS $$
DECLARE
	subject text;
	message text;
	mail_group_id integer[];
	is_send_email boolean:= false;
	is_acknowledged boolean:= false;
	send_mail_val boolean:= false;
	is_flapping_detected boolean:= false;
	is_send_trap boolean:= false;
	trap_oid text;
	enterprise_oid text;
	trap_version integer:= 2;
	varbinding_oid text;
	varbinding_value text;
	send_trap_val boolean:= false;
	templateid integer;
	template_name text;
	down_objects_list text;
	agentid integer;
	low_trap boolean:= false;
	med_trap boolean:= false;
	high_trap boolean:= false;
	is_send_webhook boolean:= false;
	webhook_ids integer[];
	low_webhook_ids integer[];
	med_webhook_ids integer[];
	high_webhook_ids integer[];
	cleared_webhook_ids integer[];
	payload text;
	send_webhook_val boolean:= false;
	is_execute_script boolean:= false;
	is_execute_on_clear boolean:= false;
	is_execute_on_pem_server boolean:= false;
	code text;
	is_submit_to_nagios boolean:= false;
	passive_check_result_text text;
	submit_to_nagios_val boolean:= false;
	alert_curr_value text;
	-- PEM-3612: Adding support for more placeholders
	alert_name text;
	alert_server_id int;
	alert_object_name text;
	alert_thresholdvalue text;
	server_name text;
	server_ip text;
	server_port integer;
	agent_name text;
	job_id integer;
	job_name text;
	alert_database_name text;
	alert_schema_name text;
	alert_package_name text;
	alert_db_object_name text;
	alert_object_type text;
	alert_params_details text;
	alert_parameters_names text[];
	alert_parameters_values text[];
	alert_info_details text;
	alert_info_names text[];
	alert_info_values text[];
	alert_param_units text[];
	email_group_name text;
	low_email_group_id integer;
	med_email_group_id integer;
	high_email_group_id integer;
	all_email_group_id integer;
	email_group_id integer;
	cleared_alert_enable boolean:= true;

BEGIN
	-- Get alert details
	SELECT
		a.agent_id, a.template_id, a.send_email, a.acknowledged, a.flapping_detected, a.send_trap, a.snmp_trap_version, a.low_send_trap, a.med_send_trap,
		a.high_send_trap, wa._send_notification, wa._low_webhook_ids, wa._med_webhook_ids, wa._high_webhook_ids, wa._cleared_webhook_ids,
		a.execute_script, a.execute_script_on_clear, a.execute_script_on_pem_server, a.script_code, a.submit_to_nagios,a.cleared_alert_enable,
		-- Get additional alert, agent, server details
		a.name, a.server_id, a.thresholds, a.database_name, a.schema_name, a.package_name, a.object_name,
		-- Get email group ids
		a.email_group_id, a.low_email_group_id, a.med_email_group_id, a.high_email_group_id,
		a.params, s.description, s.server, s.port, ag.description, at.param_names, at.param_units, ptt.display_name,
		pas.info_cols, pas.info_vals
		INTO
		agentid, templateid, is_send_email, is_acknowledged, is_flapping_detected, is_send_trap, trap_version, low_trap, med_trap,
		high_trap, is_send_webhook, low_webhook_ids, med_webhook_ids, high_webhook_ids, cleared_webhook_ids,
		is_execute_script, is_execute_on_clear, is_execute_on_pem_server, code, is_submit_to_nagios,cleared_alert_enable,
		alert_name, alert_server_id, alert_thresholdvalue, alert_database_name, alert_schema_name, alert_package_name, alert_db_object_name,
		all_email_group_id, low_email_group_id, med_email_group_id, high_email_group_id,
		alert_parameters_values, server_name, server_ip, server_port, agent_name, alert_parameters_names, alert_param_units, alert_object_type,
		alert_info_names, alert_info_values
	FROM
		pem.alert a
		LEFT JOIN pem.get_webhook_endpoints(NEW.alert_id) wa ON a.id = wa._alertid
		LEFT JOIN pem.server s ON a.server_id = s.id
		LEFT JOIN pem.agent ag ON a.agent_id = ag.id
		LEFT JOIN pem.alert_template at ON a.template_id = at.id
		LEFT JOIN pem.alert_status pas ON (a.id = pas.alert_id)
		LEFT OUTER JOIN pem.probe_target_type ptt ON at.object_type = ptt.id
	WHERE
		a.id = NEW.alert_id;

	CASE WHEN server_name IS NOT NULL THEN
		alert_object_name = server_name || ' ('|| server_ip ||': ' || server_port || ')';
	WHEN agent_name IS NOT NULL THEN
		alert_object_name = agent_name;
	ELSE
		alert_object_name = 'Postgres Enterprise Manager Server';
	END CASE;

	-- Replace single "\" with "\\" because regexp_replace escapes backslash
	alert_name = replace(alert_name, E'\\', E'\\\\');
	alert_object_name = replace(alert_object_name, E'\\', E'\\\\');

	alert_params_details = '';

	IF alert_parameters_names IS NOT NULL THEN
		FOR idx IN 1 .. array_length(alert_parameters_names, 1)
		LOOP
		BEGIN
		alert_params_details = concat(
			alert_params_details,
			alert_parameters_names[idx], ': ', alert_parameters_values[idx], E'\n'
		);
		EXCEPTION WHEN OTHERS THEN
			-- Do nothing just keep looping
		END;
		END LOOP;
	END IF;

	alert_info_details = '';
	IF alert_info_values IS NOT NULL THEN
		alert_info_details = concat(alert_info_details, '[');
		FOR idx in 1 .. array_length(alert_info_values, 1)
		LOOP
			alert_info_details = concat(alert_info_details, '{');

			FOR ifn in 1 .. array_length(alert_info_names, 1)
			LOOP
				BEGIN
					-- Fixed (PEM-4766/91551):
					-- Don't use newline character as it will not recognise it
					-- as JSON object.
					alert_info_details = concat(
						alert_info_details,
						alert_info_names[ifn], ': ',
						COALESCE(alert_info_values[idx][ifn], '')::text,
						E', '
					);
				EXCEPTION WHEN OTHERS THEN
				-- Do nothing just keep looping
				END;
			END LOOP;

			alert_info_details = concat(trim(trailing ', ' from alert_info_details), '}, ');
		END LOOP;
		alert_info_details = trim(trailing ', ' from alert_info_details);
		alert_info_details = concat(alert_info_details, ']');
	END IF;

	-- Get the template name
	SELECT display_name INTO template_name FROM pem.alert_template WHERE id = templateid;

	-- Get the list of Agents/Servers Down
	down_objects_list = pem.get_down_objects_list(template_name);

	-- Get the current value of alert
	CASE WHEN COALESCE(NEW.display_value, '')::text != '' THEN
		alert_curr_value = COALESCE(NEW.display_value, '')::text;
	ELSE
		alert_curr_value = COALESCE(NEW.current_value, 0)::text;
	END CASE;

	IF ((TG_OP = 'INSERT') AND (NEW.current_state IS NOT NULL) AND (NOT is_flapping_detected)) THEN
		-- Update state change count
		UPDATE pem.alert_status SET state_change_count = state_change_count + 1 WHERE alert_id = NEW.alert_id;

		-- Get group id's to send email
		SELECT ARRAY(SELECT DISTINCT UNNEST(pem.get_email_group_ids(NEW.alert_id, NEW.current_state::text, ''))) INTO mail_group_id;

		-- Check whether to send trap according to alert level low, med and high.
		IF (NEW.current_state IS NOT NULL) AND (NEW.current_state::text = 'LOW') AND low_trap THEN
			is_send_trap = true;
		ELSIF (NEW.current_state IS NOT NULL) AND (NEW.current_state::text = 'MEDIUM') AND med_trap THEN
			is_send_trap = true;
		ELSIF (NEW.current_state IS NOT NULL) AND (NEW.current_state::text = 'HIGH') AND high_trap THEN
			is_send_trap = true;
		ELSE
			is_send_trap = false;
		END IF;

		-- Get webhook_ids and group id according to alert level low, med, high and cleared.
		IF (NEW.current_state IS NOT NULL) AND (NEW.current_state::text = 'LOW') AND COALESCE(array_length(low_webhook_ids, 1), 0) > 0 THEN
				webhook_ids = low_webhook_ids;
				email_group_id = low_email_group_id;
		ELSIF (NEW.current_state IS NOT NULL) AND (NEW.current_state::text = 'MEDIUM') AND COALESCE(array_length(med_webhook_ids, 1), 0) > 0 THEN
				webhook_ids = med_webhook_ids;
				email_group_id = med_email_group_id;
		ELSIF (NEW.current_state IS NOT NULL) AND (NEW.current_state::text = 'HIGH') AND COALESCE(array_length(high_webhook_ids, 1), 0) > 0 THEN
				webhook_ids = high_webhook_ids;
				email_group_id = high_email_group_id;
		END IF;
		
		email_group_id := COALESCE(email_group_id, all_email_group_id);
		SELECT name FROM pem.email_group WHERE id = email_group_id INTO email_group_name;

		-- SMTP Notifications
		IF is_send_email AND (NOT is_acknowledged) AND (NOT is_flapping_detected) THEN
			-- Create subject and message
			SELECT subject_mail, message_mail INTO subject, message FROM pem.create_email(NEW.alert_id, 'Alert Detected');
			subject = pem.replace_text_params(subject, '%AlertType%', NEW.current_state::text, 'g');
			message = pem.replace_text_params(message, '%CurrentValue%', alert_curr_value, 'g');
			message = pem.replace_text_params(message, '%AlertDetected%', now()::text, 'g');
			message = pem.replace_text_params(message, '%DetailInfo%', COALESCE(NEW.info, 'None')::text, 'g');

			-- send emails.
			send_mail_val = pem.send_email(mail_group_id, subject, message);
			IF send_mail_val THEN
				-- update the time of mail send.
				UPDATE pem.alert SET last_mail_send = now() WHERE id = NEW.alert_id;
			END IF;
		END IF;

		-- SNMP Notifications
		IF is_send_trap AND (NOT is_acknowledged) AND (NOT is_flapping_detected) THEN
			-- Create SNMP trap objects
			SELECT
				snmp_trap_oid, snmp_enterprise_oid, snmp_varbinding_oid, snmp_varbinding_value
			INTO
				trap_oid, enterprise_oid, varbinding_oid, varbinding_value
			FROM
				pem.create_trap(NEW.alert_id);

			-- Append varbinding values
			varbinding_value = varbinding_value || '|NULL|' || alert_curr_value || '|NULL|';
			IF NEW.current_state IS NULL THEN
				varbinding_value = varbinding_value || '|CLEAR';
			ELSE
				varbinding_value = varbinding_value || NEW.current_state::text;
			END IF;
			-- Append current timestamp
			varbinding_value = varbinding_value || '|' || now()::text;

			-- Special handling for "Agents Down" and "Servers Down" alert
			IF (template_name = 'Agents Down') OR  (template_name = 'Servers Down') THEN
				varbinding_oid = varbinding_oid || '|' || enterprise_oid || '.10.15';
				varbinding_value = varbinding_value || '|' || down_objects_list::text;
			END IF;

			-- Send SNMP traps
			send_trap_val = pem.send_snmptrap(trap_oid, enterprise_oid, trap_version, varbinding_oid, varbinding_value);
		END IF;

		-- Webhook Notifications
		IF is_send_webhook AND (NOT is_acknowledged) AND (NOT is_flapping_detected) THEN
			-- Loop through all the webhook ids
			IF webhook_ids IS NOT NULL THEN
				FOR idx in 1 .. array_length(webhook_ids,1)
				LOOP
					BEGIN
						SELECT payload_template INTO payload FROM pem.webhook_endpoints where id = webhook_ids[idx];
						-- Create Payload
						payload = pem.replace_json_params(payload, '%AlertID%', NEW.alert_id::text, 'g');
						payload = pem.replace_json_params(payload, '%ObjectType%', alert_object_type, 'g');
						payload = pem.replace_json_params(payload, '%ThresholdValue%', alert_thresholdvalue::text, 'g');
						payload = pem.replace_json_params(payload, '%CurrentValue%', alert_curr_value, 'g');
						payload = pem.replace_json_params(payload, '%CurrentState%', NEW.current_state::text, 'g');
						payload = pem.replace_json_params(payload, '%OldState%', '', 'g');
						payload = pem.replace_json_params(payload, '%AlertRaisedTime%', now()::text, 'g');
						payload = pem.replace_json_params(payload, '%ObjectName%', alert_object_name, 'g');
						payload = pem.replace_json_params(payload, '%AlertName%', alert_name, 'g');
						payload = pem.replace_json_params(payload, '%AlertDetected%', now()::text, 'g');
						payload = pem.replace_json_params(payload, '%EmailGroupId%', email_group_id::text, 'g');
						payload = pem.replace_json_params(payload, '%EmailGroup%', email_group_name::text, 'g');

						-- Additional support for more placeholders
						IF agentid >= 1 THEN
							payload = pem.replace_json_params(payload, '%AgentID%', agentid::text, 'g');
							payload = pem.replace_json_params(payload, '%AgentName%', agent_name, 'g');
						ELSE
							payload = pem.replace_json_params(payload, '%AgentID%', '', 'g');
							payload = pem.replace_json_params(payload, '%AgentName%', '', 'g');
						END IF;

						IF alert_server_id >= 1 THEN
							payload = pem.replace_json_params(payload, '%ServerID%', alert_server_id::text, 'g');
							server_name = replace(server_name, E'\\', E'\\\\');
							payload = pem.replace_json_params(payload, '%ServerName%', server_name, 'g');
							payload = pem.replace_json_params(payload, '%ServerIP%', server_ip, 'g');
							payload = pem.replace_json_params(payload, '%ServerPort%', server_port::text, 'g');
						ELSE
							payload = pem.replace_json_params(payload, '%ServerID%', '', 'g');
							payload = pem.replace_json_params(payload, '%ServerName%', '', 'g');
							payload = pem.replace_json_params(payload, '%ServerIP%', '', 'g');
							payload = pem.replace_json_params(payload, '%ServerPort%', '', 'g');
						END IF;

						IF alert_database_name IS NOT NULL AND alert_database_name <> '' THEN
							alert_database_name = replace(alert_database_name, E'\\', E'\\\\');
						END IF;
						payload = pem.replace_json_params(payload, '%DatabaseName%', alert_database_name, 'g');

						IF alert_schema_name IS NOT NULL AND alert_schema_name <> '' THEN
							alert_schema_name = replace(alert_schema_name, E'\\', E'\\\\');
						END IF;
						payload = pem.replace_json_params(payload, '%SchemaName%', alert_schema_name, 'g');

						IF alert_package_name IS NOT NULL AND alert_package_name <> '' THEN
							alert_package_name = replace(alert_package_name, E'\\', E'\\\\');
						END IF;
						payload = pem.replace_json_params(payload, '%PackageName%', alert_package_name, 'g');

						IF alert_db_object_name IS NOT NULL AND alert_db_object_name <> '' THEN
							alert_db_object_name = replace(alert_db_object_name, E'\\', E'\\\\');
						END IF;
						payload = pem.replace_json_params(payload, '%DatabaseObjectName%', alert_db_object_name, 'g');

						payload = pem.replace_json_params(payload, '%Parameters%', alert_params_details, 'g');
						payload = pem.replace_json_params(payload, '%AlertInfo%', alert_info_details, 'g');

						-- send webhook requests
						PERFORM pem.send_webhook(webhook_ids[idx], NEW.alert_id, agentid, payload);
					EXCEPTION WHEN OTHERS THEN
					-- Do nothing just keep looping
					END;
				END LOOP;
			END IF;
		END IF;

		-- Script Execution
		IF is_execute_script AND (NOT is_acknowledged) AND (NOT is_flapping_detected) THEN
			PERFORM pem.create_script_job(NEW.alert_id, alert_curr_value, NEW.current_state::text, ''::text, is_execute_on_pem_server, code);
		END IF;

		-- submit to Nagios
		IF is_submit_to_nagios AND (NOT is_acknowledged) AND (NOT is_flapping_detected) THEN

			SELECT passive_check_result INTO passive_check_result_text FROM pem.create_passive_service_check_result(NEW.alert_id, 'Alert Detected',
															alert_curr_value,
															NEW.current_state::text);
			submit_to_nagios_val = pem.submit_to_nagios(passive_check_result_text);
		END IF;
	END IF;

	IF ((TG_OP = 'UPDATE') AND (NEW.current_state IS DISTINCT FROM OLD.current_state) AND (NOT is_flapping_detected)) THEN
		-- Update state change count
		UPDATE pem.alert_status SET state_change_count = state_change_count + 1 WHERE alert_id = NEW.alert_id;

		-- Get group id's to send email
		SELECT ARRAY(SELECT DISTINCT UNNEST(pem.get_email_group_ids(NEW.alert_id, NEW.current_state::text, OLD.current_state::text))) INTO mail_group_id;

		-- Check whether to send trap according to alert level low, med and high.
		IF (NEW.current_state IS NOT NULL) AND (NEW.current_state::text = 'LOW' OR OLD.current_state::text = 'LOW') AND low_trap THEN
			is_send_trap = true;
		ELSIF (NEW.current_state IS NOT NULL) AND (NEW.current_state::text = 'MEDIUM' OR OLD.current_state::text = 'MEDIUM') AND med_trap THEN
			is_send_trap = true;
		ELSIF (NEW.current_state IS NOT NULL) AND (NEW.current_state::text = 'HIGH' OR OLD.current_state::text = 'HIGH') AND high_trap THEN
			is_send_trap = true;
		ELSIF (NEW.current_state IS NULL) AND (OLD.current_state::text = 'LOW') AND low_trap THEN
			is_send_trap = true;
		ELSIF (NEW.current_state IS NULL) AND (OLD.current_state::text = 'MEDIUM') AND med_trap THEN
			is_send_trap = true;
		ELSIF (NEW.current_state IS NULL) AND (OLD.current_state::text = 'HIGH') AND high_trap THEN
			is_send_trap = true;
		ELSE
			is_send_trap = false;
		END IF;

		-- Get webhook_ids and group id according to alert level low, med, high and cleared.
		IF (NEW.current_state IS NOT NULL) AND (NEW.current_state::text = 'LOW') AND COALESCE(array_length(low_webhook_ids, 1), 0) > 0 THEN
				webhook_ids = low_webhook_ids;
				email_group_id = low_email_group_id;
		ELSIF (NEW.current_state IS NOT NULL) AND (NEW.current_state::text = 'MEDIUM') AND COALESCE(array_length(med_webhook_ids, 1), 0) > 0 THEN
				webhook_ids = med_webhook_ids;
				email_group_id = med_email_group_id;
		ELSIF (NEW.current_state IS NOT NULL) AND (NEW.current_state::text = 'HIGH') AND COALESCE(array_length(high_webhook_ids, 1), 0) > 0 THEN
				webhook_ids = high_webhook_ids;
				email_group_id = high_email_group_id;
		ELSIF (NEW.current_state IS NULL) AND (OLD.current_state IS NOT NULL) AND COALESCE(array_length(cleared_webhook_ids, 1), 0) > 0 THEN
				webhook_ids = cleared_webhook_ids;
		END IF;

		email_group_id := COALESCE(email_group_id, all_email_group_id);
		SELECT name FROM pem.email_group WHERE id = email_group_id INTO email_group_name;

		-- SMTP Notifications
        IF is_send_email AND (NOT is_acknowledged) AND (NOT is_flapping_detected) AND ((NEW.current_state IS NOT NULL) OR cleared_alert_enable) THEN
			-- If current state is NULL means alert is cleared.
			IF (NEW.current_state IS NOT NULL) THEN
				-- if OLD current_state is not null means alert level changed.
				IF (OLD.current_state IS NOT NULL AND (OLD.current_state > NEW.current_state)) THEN
					-- Create subject and message
					SELECT subject_mail, message_mail INTO subject, message FROM pem.create_email(NEW.alert_id, 'Alert Level Decreased');
					message = pem.replace_text_params(message, '%CurrentState%', NEW.current_state::text, 'g');
					message = pem.replace_text_params(message, '%OldState%', OLD.current_state::text, 'g');
					message = pem.replace_text_params(message, '%StateChanged%', now()::text, 'g');
				ELSIF (OLD.current_state IS NOT NULL AND (OLD.current_state < NEW.current_state)) THEN
					-- Create subject and message
					SELECT subject_mail, message_mail INTO subject, message FROM pem.create_email(NEW.alert_id, 'Alert Level Increased');
					message = pem.replace_text_params(message, '%CurrentState%', NEW.current_state::text, 'g');
					message = pem.replace_text_params(message, '%OldState%', OLD.current_state::text, 'g');
					message = pem.replace_text_params(message, '%StateChanged%', now()::text, 'g');
				ELSE
					-- Create subject and message
					SELECT subject_mail, message_mail INTO subject, message FROM pem.create_email(NEW.alert_id, 'Alert Detected');
					subject = pem.replace_text_params(subject, '%AlertType%', NEW.current_state::text, 'g');
					message = pem.replace_text_params(message, '%AlertDetected%', now()::text, 'g');
				END IF;
			ELSE
				-- Create subject and message
				SELECT subject_mail, message_mail INTO subject, message FROM pem.create_email(NEW.alert_id, 'Alert Cleared');
				message = pem.replace_text_params(message, '%AlertCleared%', now()::text, 'g');
			END IF;

			message = pem.replace_text_params(message, '%CurrentValue%', alert_curr_value, 'g');
			message = pem.replace_text_params(message, '%DetailInfo%', COALESCE(NEW.info, 'None')::text, 'g');

			-- send emails.
			send_mail_val = pem.send_email(mail_group_id, subject, message);
			IF send_mail_val THEN
				-- update the time of mail send.
				UPDATE pem.alert SET last_mail_send = now() WHERE id = NEW.alert_id;
			END IF;
		END IF;

		-- SNMP Notifications
		IF is_send_trap AND (NOT is_acknowledged) AND (NOT is_flapping_detected) THEN
			-- Create SNMP trap objects
			SELECT
				snmp_trap_oid, snmp_enterprise_oid, snmp_varbinding_oid, snmp_varbinding_value
			INTO
				trap_oid, enterprise_oid, varbinding_oid, varbinding_value
			FROM
				pem.create_trap(NEW.alert_id);

			-- Append varbinding values
			varbinding_value = varbinding_value || '|' || COALESCE(OLD.current_value, 0)::text || '|' || alert_curr_value;

			IF OLD.current_state IS NULL THEN
				varbinding_value = varbinding_value || '|CLEAR';
			ELSE
				varbinding_value = varbinding_value || '|' || OLD.current_state::text;
			END IF;

			IF NEW.current_state IS NULL THEN
				varbinding_value = varbinding_value || '|CLEAR';
			ELSE
				varbinding_value = varbinding_value || '|' || NEW.current_state::text;
			END IF;
			-- Append current timestamp
			varbinding_value = varbinding_value || '|' || now()::text;

			-- Special handling for "Agents Down" and "Servers Down" alert
			IF (template_name = 'Agents Down') OR  (template_name = 'Servers Down') THEN
				varbinding_oid = varbinding_oid || '|' || enterprise_oid || '.10.15';
				varbinding_value = varbinding_value || '|' || down_objects_list::text;
			END IF;

			-- Send SNMP traps
			send_trap_val = pem.send_snmptrap(trap_oid, enterprise_oid, trap_version, varbinding_oid, varbinding_value);
		END IF;

		-- Webhook Notifications
		IF is_send_webhook AND (NOT is_acknowledged) AND (NOT is_flapping_detected) THEN
			-- Loop through all the webhook ids
			IF COALESCE(array_length(webhook_ids, 1), 0) > 0 THEN
				FOR idx in 1 .. array_length(webhook_ids,1)
				LOOP
					BEGIN
						SELECT payload_template INTO payload FROM pem.webhook_endpoints where id = webhook_ids[idx];
						-- Create Payload
						payload = pem.replace_json_params(payload, '%AlertID%', NEW.alert_id::text, 'g');
						payload = pem.replace_json_params(payload, '%ObjectType%', alert_object_type, 'g');
						payload = pem.replace_json_params(payload, '%ThresholdValue%', alert_thresholdvalue::text, 'g');
						payload = pem.replace_json_params(payload, '%CurrentValue%', alert_curr_value, 'g');
						payload = pem.replace_json_params(payload, '%EmailGroupId%', email_group_id::text, 'g');
						payload = pem.replace_json_params(payload, '%EmailGroup%', email_group_name::text, 'g');

						IF (NEW.current_state IS NULL) THEN
							payload = pem.replace_json_params(payload, '%CurrentState%', 'CLEARED', 'g');
						ELSE
							payload = pem.replace_json_params(payload, '%CurrentState%', NEW.current_state::text, 'g');
						END IF;
						payload = pem.replace_json_params(payload, '%OldState%', OLD.current_state::text, 'g');
						payload = pem.replace_json_params(payload, '%AlertRaisedTime%', now()::text, 'g');
						payload = pem.replace_json_params(payload, '%ObjectName%', alert_object_name, 'g');
						payload = pem.replace_json_params(payload, '%AlertName%', alert_name, 'g');
						payload = pem.replace_json_params(payload, '%AlertDetected%', now()::text, 'g');
						-- Additional support for more placeholders
						IF agentid >= 1 THEN
							payload = pem.replace_json_params(payload, '%AgentID%', agentid::text, 'g');
							payload = pem.replace_json_params(payload, '%AgentName%', agent_name, 'g');
						ELSE
							payload = pem.replace_json_params(payload, '%AgentID%', '', 'g');
							payload = pem.replace_json_params(payload, '%AgentName%', '', 'g');
						END IF;

						IF alert_server_id >= 1 THEN
							payload = pem.replace_json_params(payload, '%ServerID%', alert_server_id::text, 'g');
							server_name = replace(server_name, E'\\', E'\\\\');
							payload = pem.replace_json_params(payload, '%ServerName%', server_name, 'g');
							payload = pem.replace_json_params(payload, '%ServerIP%', server_ip, 'g');
							payload = pem.replace_json_params(payload, '%ServerPort%', server_port::text, 'g');
						ELSE
							payload = pem.replace_json_params(payload, '%ServerID%', '', 'g');
							payload = pem.replace_json_params(payload, '%ServerName%', '', 'g');
							payload = pem.replace_json_params(payload, '%ServerIP%', '', 'g');
							payload = pem.replace_json_params(payload, '%ServerPort%', '', 'g');
						END IF;

						IF alert_database_name IS NOT NULL AND alert_database_name <> '' THEN
							alert_database_name = replace(alert_database_name, E'\\', E'\\\\');
						END IF;
						payload = pem.replace_json_params(payload, '%DatabaseName%', alert_database_name, 'g');

						IF alert_schema_name IS NOT NULL AND alert_schema_name <> '' THEN
							alert_schema_name = replace(alert_schema_name, E'\\', E'\\\\');
						END IF;
						payload = pem.replace_json_params(payload, '%SchemaName%', alert_schema_name, 'g');

						IF alert_package_name IS NOT NULL AND alert_package_name <> '' THEN
							alert_package_name = replace(alert_package_name, E'\\', E'\\\\');
						END IF;
						payload = pem.replace_json_params(payload, '%PackageName%', alert_package_name, 'g');

						IF alert_db_object_name IS NOT NULL AND alert_db_object_name <> '' THEN
							alert_db_object_name = replace(alert_db_object_name, E'\\', E'\\\\');
						END IF;
						payload = pem.replace_json_params(payload, '%DatabaseObjectName%', alert_db_object_name, 'g');

						payload = pem.replace_json_params(payload, '%Parameters%', alert_params_details, 'g');
						payload = pem.replace_json_params(payload, '%AlertInfo%', alert_info_details, 'g');

						-- send webhook requests
						PERFORM pem.send_webhook(webhook_ids[idx], NEW.alert_id, agentid, payload);
					EXCEPTION WHEN OTHERS THEN
					-- Do nothing just keep looping
					END;
				END LOOP;
			END IF;
		END IF;

		-- Script Execution
		IF is_execute_script AND (NOT is_acknowledged) AND (NOT is_flapping_detected) THEN
			-- If current state is NULL means alert is cleared then need to check the value of is_execute_on_clear flag.
			IF (NEW.current_state IS NULL) THEN
				IF is_execute_on_clear THEN
					PERFORM pem.create_script_job(NEW.alert_id, alert_curr_value, 'CLEAR'::text, OLD.current_state::text, is_execute_on_pem_server, code);
				END IF;
			ELSE
				PERFORM pem.create_script_job(NEW.alert_id, alert_curr_value, NEW.current_state::text, OLD.current_state::text, is_execute_on_pem_server, code);
			END IF;
		END IF;

		-- submit to Nagios
		IF is_submit_to_nagios AND (NOT is_acknowledged) AND (NOT is_flapping_detected) THEN

			-- If current state is NULL means alert is cleared.
			IF (NEW.current_state IS NOT NULL) THEN
				-- if OLD current_state is not null means alert level changed.
				IF (OLD.current_state IS NOT NULL AND (OLD.current_state > NEW.current_state)) THEN
					SELECT passive_check_result INTO passive_check_result_text FROM pem.create_passive_service_check_result(NEW.alert_id,
																	'Alert Level Decreased',
																	alert_curr_value,
																	NEW.current_state::text);
					passive_check_result_text = regexp_replace(passive_check_result_text, '%OldState%', OLD.current_state::text, 'g');
					passive_check_result_text = regexp_replace(passive_check_result_text, '%NewState%', NEW.current_state::text, 'g');

				ELSIF (OLD.current_state IS NOT NULL AND (OLD.current_state < NEW.current_state)) THEN
					SELECT passive_check_result INTO passive_check_result_text FROM pem.create_passive_service_check_result(NEW.alert_id,
																	'Alert Level Increased',
																	alert_curr_value,
																	NEW.current_state::text);
					passive_check_result_text = regexp_replace(passive_check_result_text, '%OldState%', OLD.current_state::text, 'g');
					passive_check_result_text = regexp_replace(passive_check_result_text, '%NewState%', NEW.current_state::text, 'g');

				ELSE
					SELECT passive_check_result INTO passive_check_result_text FROM pem.create_passive_service_check_result(NEW.alert_id,
																	'Alert Detected',
																	alert_curr_value,
																	NEW.current_state::text);
				END IF;

			ELSE
				SELECT passive_check_result INTO passive_check_result_text FROM pem.create_passive_service_check_result(NEW.alert_id,
																'Alert Cleared',
																alert_curr_value,
																NEW.current_state::text);
			END IF;

			submit_to_nagios_val = pem.submit_to_nagios(passive_check_result_text);
		END IF;
	END IF;

	RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION pem.create_script_job(_alert_id integer, _current_value text, _current_state text, _previous_state text, _run_on_pem_server boolean, _script_code text) RETURNS VOID AS $$
DECLARE
	alert_name text;
	alert_agent_id int;
	alert_server_id int;
	alert_object_name text;
	alert_thresholdvalue text;
	server_name text;
	server_ip text;
	server_port integer;
	agent_name text;
	job_id integer;
	job_name text;
	alert_database_name text;
	alert_schema_name text;
	alert_package_name text;
	alert_db_object_name text;
	alert_object_type text;
	alert_params_details text;
	alert_parameters_names text[];
	alert_parameters_values text[];
	alert_info_details text;
	alert_info_names text[];
	alert_info_values text[];
	alert_param_units text[];
BEGIN
	-- Get alert, agent, server details
	SELECT
		a.name, a.agent_id, a.server_id, a.thresholds, s.description, s.server, s.port,
		ag.description, a.database_name, a.schema_name, a.package_name, a.object_name,
		a.params, at.param_names, at.param_units, ptt.display_name,
		pas.info_cols, pas.info_vals
	INTO
		alert_name, alert_agent_id, alert_server_id, alert_thresholdvalue, server_name, server_ip, server_port,
		agent_name, alert_database_name, alert_schema_name, alert_package_name, alert_db_object_name,
		alert_parameters_values, alert_parameters_names, alert_param_units, alert_object_type,
		alert_info_names, alert_info_values
	FROM
		pem.alert a
		LEFT JOIN pem.server s ON a.server_id = s.id
		LEFT JOIN pem.agent ag ON a.agent_id = ag.id
		LEFT JOIN pem.alert_template at ON a.template_id = at.id
		LEFT JOIN pem.alert_status pas ON (a.id = pas.alert_id)
		LEFT OUTER JOIN pem.probe_target_type ptt ON at.object_type = ptt.id
	WHERE
		a.id = _alert_id;

	CASE WHEN server_name IS NOT NULL THEN
		alert_object_name = server_name || ' ('|| server_ip ||': ' || server_port || ')';
	WHEN agent_name IS NOT NULL THEN
		alert_object_name = agent_name;
	ELSE
		alert_object_name = 'Postgres Enterprise Manager Server';
	END CASE;

	-- Replace single "\" with "\\" because regexp_replace escapes backslash
	alert_name = replace(alert_name, E'\\', E'\\\\');
	alert_object_name = replace(alert_object_name, E'\\', E'\\\\');

	_script_code = pem.replace_text_params(_script_code, '%ThresholdValue%', alert_thresholdvalue::text, 'g');
	_script_code = pem.replace_text_params(_script_code, '%CurrentValue%', _current_value, 'g');
	_script_code = pem.replace_text_params(_script_code, '%CurrentState%', COALESCE(_current_state, '')::text, 'g');
	_script_code = pem.replace_text_params(_script_code, '%OldState%', COALESCE(_previous_state, '')::text, 'g');
	_script_code = pem.replace_text_params(_script_code, '%AlertRaisedTime%', now()::text, 'g');
	_script_code = pem.replace_text_params(_script_code, '%ObjectName%', alert_object_name, 'g');
	_script_code = pem.replace_text_params(_script_code, '%AlertName%', alert_name, 'g');

    -- PEM-3612: Adding support for more placeholders
    -- We will form a alert params details string from arrays
    _script_code = pem.replace_text_params(_script_code, '%AlertID%', _alert_id::text, 'g');
    _script_code = pem.replace_text_params(_script_code, '%ObjectType%', alert_object_type, 'g');

    alert_params_details = '';
    IF alert_parameters_names IS NOT NULL THEN
        FOR idx in 1 .. array_length(alert_parameters_names, 1)
        LOOP
            BEGIN
                alert_params_details = concat(
                    alert_params_details,
                    alert_parameters_names[idx], ': ', alert_parameters_values[idx], E'\n'
                );
            EXCEPTION WHEN OTHERS THEN
               -- Do nothing just keep looping
            END;
        END LOOP;
    END IF;

    alert_info_details = '';
    IF alert_info_values IS NOT NULL THEN
        FOR idx in 1 .. array_length(alert_info_values, 1)
        LOOP
            FOR ifn in 1 .. array_length(alert_info_names, 1)
            LOOP
                BEGIN
                    alert_info_details = concat(
                        alert_info_details,
                        alert_info_names[ifn], ': ',  COALESCE(alert_info_values[idx][ifn], '')::text, E'\n'
                    );
                EXCEPTION WHEN OTHERS THEN
                   -- Do nothing just keep looping
                END;
            END LOOP;
        END LOOP;
    END IF;

    IF alert_agent_id >= 1 THEN
        _script_code = pem.replace_text_params(_script_code, '%AgentID%', alert_agent_id::text, 'g');
        _script_code = pem.replace_text_params(_script_code, '%AgentName%', agent_name, 'g');
    ELSE
        _script_code = pem.replace_text_params(_script_code, '%AgentID%', '', 'g');
        _script_code = pem.replace_text_params(_script_code, '%AgentName%', '', 'g');
    END IF;

	IF alert_server_id >= 1 THEN
	    _script_code = pem.replace_text_params(_script_code, '%ServerID%', alert_server_id::text, 'g');
        server_name = replace(server_name, E'\\', E'\\\\');
	    _script_code = pem.replace_text_params(_script_code, '%ServerName%', server_name, 'g');
	    _script_code = pem.replace_text_params(_script_code, '%ServerIP%', server_ip, 'g');
	    _script_code = pem.replace_text_params(_script_code, '%ServerPort%', server_port::text, 'g');
	ELSE
	    _script_code = pem.replace_text_params(_script_code, '%ServerID%', '', 'g');
	    _script_code = pem.replace_text_params(_script_code, '%ServerName%', '', 'g');
	    _script_code = pem.replace_text_params(_script_code, '%ServerIP%', '', 'g');
	    _script_code = pem.replace_text_params(_script_code, '%ServerPort%', '', 'g');
	END IF;

    IF alert_database_name IS NOT NULL AND alert_database_name <> '' THEN
        alert_database_name = replace(alert_database_name, E'\\', E'\\\\');
    END IF;
    _script_code = pem.replace_text_params(_script_code, '%DatabaseName%', alert_database_name, 'g');

    IF alert_schema_name IS NOT NULL AND alert_schema_name <> '' THEN
        alert_schema_name = replace(alert_schema_name, E'\\', E'\\\\');
    END IF;
    _script_code = pem.replace_text_params(_script_code, '%SchemaName%', alert_schema_name, 'g');

    IF alert_package_name IS NOT NULL AND alert_package_name <> '' THEN
        alert_package_name = replace(alert_package_name, E'\\', E'\\\\');
    END IF;
    _script_code = pem.replace_text_params(_script_code, '%PackageName%', alert_package_name, 'g');

    IF alert_db_object_name IS NOT NULL AND alert_db_object_name <> '' THEN
        alert_db_object_name = replace(alert_db_object_name, E'\\', E'\\\\');
    END IF;
    _script_code = pem.replace_text_params(_script_code, '%DatabaseObjectName%', alert_db_object_name, 'g');

    _script_code = pem.replace_text_params(_script_code, '%Parameters%', alert_params_details, 'g');
    _script_code = pem.replace_text_params(_script_code, '%AlertInfo%', alert_info_details, 'g');

	IF _run_on_pem_server THEN
		SELECT agent_id FROM pem.pem_host_and_server WHERE is_leader LIMIT 1 INTO alert_agent_id;
	ELSE
		IF alert_agent_id < 1 THEN
			SELECT agent_id FROM pem.agent_server_binding WHERE server_id = alert_server_id INTO alert_agent_id;
		END IF;
	END IF;

	-- Create jobs only when agent_id is correct
	IF alert_agent_id >= 1 THEN
		job_name = 'Execute script for alert "' || alert_name || '"';
		-- Create script execution job.
		INSERT INTO pem.job(jobname, jobdesc, agent_id, jobnextrun, is_alert_job) VALUES(job_name, 'This job executes the given script when alert raises', alert_agent_id, now(), true) RETURNING jobid INTO job_id;
		-- Create script execution step.
		IF alert_server_id >= 1 THEN
			INSERT INTO pem.jobstep(jstjobid, jstname, jstdesc, jstkind, jstcode, server_id, jstonerror, jstsetenvironment) VALUES (job_id, job_name,'This job step executes the given script when alert raises', 'b', _script_code, alert_server_id, 'f', 't');
		ELSE
			INSERT INTO pem.jobstep(jstjobid, jstname, jstdesc, jstkind, jstcode, jstonerror, jstsetenvironment) VALUES (job_id, job_name,'This job step executes the given script when alert raises', 'b', _script_code, 'f', 'f');
		END IF;
	END IF;
END
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION pem.get_email_group_ids(alert_id integer, current_state text, previous_state text) RETURNS integer[] AS
$$
DECLARE
	res integer[] = ARRAY[]::integer[];
	all_group_id integer;
	low_group_id integer;
	med_group_id integer;
	high_group_id integer;
	arrindex integer:= 1;
BEGIN
	-- Get alert details
	SELECT
		email_group_id, low_email_group_id, med_email_group_id, high_email_group_id
	INTO
		all_group_id, low_group_id, med_group_id, high_group_id
	FROM
		pem.alert
	WHERE
		id = alert_id;

	IF (all_group_id IS NOT NULL) AND (all_group_id > 0) THEN
		res[arrindex] = all_group_id;
		arrindex = arrindex + 1;
	END IF;

	IF (low_group_id IS NOT NULL) AND (low_group_id > 0) AND (current_state = 'LOW' OR previous_state = 'LOW') THEN
		res[arrindex] = low_group_id;
		arrindex = arrindex + 1;
	END IF;

	IF (med_group_id IS NOT NULL) AND (med_group_id > 0) AND (current_state = 'MEDIUM' OR previous_state = 'MEDIUM') THEN
		res[arrindex] = med_group_id;
		arrindex = arrindex + 1;
	END IF;

	IF (high_group_id IS NOT NULL) AND (high_group_id > 0) AND (current_state = 'HIGH' OR previous_state = 'HIGH') THEN
		res[arrindex] = high_group_id;
		arrindex = arrindex + 1;
	END IF;

	return res;
END
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION pem.create_email(alert_id integer, template text, OUT subject_mail text, OUT message_mail text) AS $$
DECLARE
	alert_name text;
	alert_agent_id int;
	alert_server_id int;
	alert_database_name text;
	alert_object_name text;
	alert_schema_name text;
	alert_thresholdvalue text;
	server_name text;
	server_ip text;
	server_port integer;
	agent_name text;
	msg_object_name text;
BEGIN
	-- Get alert, agent, server details
	SELECT
		a.name, a.agent_id, a.server_id, a.database_name, a.schema_name, a.thresholds,
		s.description, s.server, s.port,
		ag.description
	INTO
		alert_name, alert_agent_id, alert_server_id, alert_database_name, alert_schema_name,
		alert_thresholdvalue, server_name, server_ip, server_port,
		agent_name
	FROM
		pem.alert a
		LEFT JOIN pem.server s ON a.server_id = s.id
		LEFT JOIN pem.agent ag ON a.agent_id = ag.id
	WHERE
		a.id = alert_id;

	SELECT
		mail_subject, mail_message
		INTO subject_mail, message_mail
	FROM pem.get_email_template(template);

	CASE WHEN server_name IS NOT NULL THEN
		alert_object_name = server_name || ' ('|| server_ip ||': ' || server_port || ')';
		msg_object_name = alert_object_name;
	WHEN agent_name IS NOT NULL THEN
		alert_object_name = agent_name;
		msg_object_name = alert_object_name;
	ELSE
		alert_object_name = 'Postgres Enterprise Manager Server';
		msg_object_name = 'N/A';
	END CASE;

	-- Replace single "\" with "\\" because regexp_replace escapes backslash
	alert_name = replace(alert_name, E'\\', E'\\\\');
	alert_object_name = replace(alert_object_name, E'\\', E'\\\\');

	subject_mail = regexp_replace(subject_mail, '%AlertName%', alert_name, 'g');
	subject_mail = regexp_replace(subject_mail, '%ObjectName%', alert_object_name, 'g');
	message_mail = regexp_replace(message_mail, '%AlertName%', alert_name, 'g');
	message_mail = regexp_replace(message_mail, '%ObjectName%', msg_object_name, 'g');
	message_mail = regexp_replace(message_mail, '%ThresholdValue%', alert_thresholdvalue::text, 'g');
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION pem.get_down_objects_list(template_name text) RETURNS text AS $$
DECLARE
	rec record;
	down_objetcs_list text:= '';
	index integer:= 1;
BEGIN
	-- Get the list of down agents
	IF (template_name = 'Agents Down') THEN
		down_objetcs_list = E'Agents Down:\n';
		FOR rec in (SELECT id, description FROM pem.get_agents_with_status('DOWN') AS (id integer, description text))
		LOOP
			down_objetcs_list = down_objetcs_list || index || ') ' || rec.description || E'\n';
			index = index + 1;
		END LOOP;
	END IF;

	-- Get the list of down servers
	IF (template_name = 'Servers Down') THEN
		down_objetcs_list = E'Servers Down:\n';
		index = 1;
		FOR rec in (SELECT id, description, server , port FROM pem.get_servers_with_status('DOWN') AS
					(id integer, description text, server text, port integer))
		LOOP
			down_objetcs_list = down_objetcs_list || index || ') ' || rec.description || ' (' || rec.server ||
							':' || rec.port || E')\n';
			index = index + 1;
		END LOOP;
	END IF;

	RETURN down_objetcs_list;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER send_notifications_trigger AFTER INSERT OR UPDATE ON pem.alert_status FOR EACH ROW EXECUTE PROCEDURE pem.send_notifications();
COMMENT ON TRIGGER send_notifications_trigger ON pem.alert_status IS 'Send notifications';

/******************************
 * Capacity Manager Templates *
 ******************************/

-- Types of time period options for capacity manager
CREATE TYPE pem.cm_time_period AS ENUM(
	'START_DATE_TO_END_DATE',		-- Start date and end date
	'START_DATE_TO_THREHOLD',		-- Start date and threshold
	'HISTORIC_DATE_TO_EXTRAPOLATED_DATE',	-- Historical date and extrapolated date
	'HISTORIC_DATE_TO_THRESHOLD'		-- Historical date and threshold
);

COMMENT ON TYPE pem.cm_time_period IS 'Types of time period options for capacity manager';

-- Threshold operators for capacity manager
CREATE TYPE pem.cm_threshold_operator AS ENUM(
	'FALLS_BELOW',		-- Falls below
	'EXCEEDS'		-- Exceeds
);

COMMENT ON TYPE pem.cm_threshold_operator IS 'Threshold operators for capacity manager';

-- Types of report for capacity manager
CREATE TYPE pem.cm_report_type AS ENUM(
	'GRAPH',		-- Graph
	'TABLE',		-- Table
	'GRAPH_AND_TABLE'	-- Graph and table
);

COMMENT ON TYPE pem.cm_report_type IS 'Types of report for capacity manager';

-- Output location for capacity manager reports
CREATE TYPE pem.cm_output_loc AS ENUM(
	'NEW_TAB',	-- New tab
	'PREV_TAB',	-- Previous tab
	'FILE'		-- Html file
);

COMMENT ON TYPE pem.cm_output_loc IS 'Output location for capacity manager reports';

-- Aggregation associated with metric for capacity manager reports
CREATE TYPE pem.cm_metric_aggregation AS ENUM(
	'AVERAGE',	-- Average
	'MAXIMUM',	-- Maximum
	'MINIMUM',	-- Minimum
	'FIRST'		-- First
);

COMMENT ON TYPE pem.cm_metric_aggregation IS 'Aggregation associated with metric for capacity manager reports';

CREATE TABLE pem.cm_template_path (
	-- Unique ID
	id serial,

	-- Parent ID
	parent_id integer,

	-- Folder/template title
	title text NOT NULL,

	CONSTRAINT template_path_pkey PRIMARY KEY (id),
	CONSTRAINT template_path_parent_fkey FOREIGN KEY (parent_id)
		REFERENCES pem.cm_template_path (id) MATCH SIMPLE
		ON UPDATE NO ACTION ON DELETE CASCADE
);

CREATE TABLE pem.cm_template (
	-- Unique ID
	id serial,

	-- Folder ID
	folder_id integer NOT NULL,

	-- Template name
	name text NOT NULL,

	-- Individual report
	individual_report boolean,

	-- Time period options
	time_period pem.cm_time_period,

	-- Start date
	start_date timestamptz,

	-- End date
	end_date timestamptz,

	-- Historical days
	historical_days integer,

	-- Extrapolated days
	extrapolated_days integer,

	-- Index of selected threshold metric
	threshold_index integer,

	-- selected operator for threshold
	threshold_opr pem.cm_threshold_operator,

	-- threshold value
	threshold_value numeric,

	-- Report type
	report_type pem.cm_report_type,

	-- Report output type
	output_loc pem.cm_output_loc,

	-- Report output value (only for file and email options)
	output_value text,

	CONSTRAINT cm_template_pkey PRIMARY KEY (id),
	CONSTRAINT cm_template_folder_fkey FOREIGN KEY (folder_id)
		REFERENCES pem.cm_template_path (id) MATCH SIMPLE
		ON UPDATE NO ACTION ON DELETE CASCADE
);

CREATE TABLE pem.cm_template_metrics (
	-- Unique ID
	id serial,

	-- ID of associated option in pem.cm_template
	template_id integer NOT NULL,

	-- Metric ID
	metric_id integer,

	-- Metric name
	metric_name text,

	-- Metric display name
	metric_disp_name text,

	-- Metric agent id
	metric_agent_id integer,

	-- Metric target attribute
	metric_target_attributes text,

	-- Metric target values
	metric_target_values text,

	-- Metric type pit
	metric_calculate_pit text,

	-- Metric unit
	metric_unit text,

	-- Server type for the given metric
	metric_server_type text,

	-- Query type for given metric
	metric_query_type integer,

	-- Path of the object related to metric
	metric_object text,

	-- Aggregation of each metric
	metric_aggregation pem.cm_metric_aggregation,

	CONSTRAINT cm_template_metrics_pkey PRIMARY KEY (id),
	CONSTRAINT cm_template_metrics_fkey FOREIGN KEY (template_id)
		REFERENCES pem.cm_template (id) MATCH SIMPLE
		ON UPDATE NO ACTION ON DELETE CASCADE
);

