CREATE TABLE pem.snmp_spool (
	id 			serial NOT NULL,
	trap_oid 		text NOT NULL,
	enterprise_oid		text NOT NULL,
	trap_version		integer NOT NULL DEFAULT 1,
	varbinding_oid		text,
	varbinding_value	text,
	sent_status 		char NOT NULL,
	recorded_time		timestamp with time zone NOT NULL DEFAULT now(),

	CONSTRAINT snmp_spool_pkey PRIMARY KEY (id),

	CONSTRAINT snmp_spool_sent_status
	CHECK (sent_status IN ('s', 'u', 'i'))
);

CREATE INDEX snmp_spool_recorded_time_idx ON pem.snmp_spool (recorded_time);

CREATE OR REPLACE FUNCTION pem.send_snmptrap(trap_oid text, enterprise_oid text, trap_version integer, varbinding_oid text, varbinding_value text)
RETURNS boolean AS $$
DECLARE
	is_snmp_enabled boolean:= false;
BEGIN
	-- Check if snmp_enabled == true, if not return.
	SELECT value INTO is_snmp_enabled FROM pem.config WHERE param = 'snmp_enabled';

	IF is_snmp_enabled THEN
		/* Insert the spool record */
		INSERT INTO pem.snmp_spool(trap_oid, enterprise_oid, trap_version, varbinding_oid, varbinding_value, sent_status) VALUES(trap_oid, enterprise_oid, trap_version, varbinding_oid, varbinding_value, 'u');

		/* Notify listeners that a message is ready for delivery */
		NOTIFY SNMP_SPOOL;

		RETURN true;
	END IF;

	RETURN false;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION pem.create_trap(alert_id integer, OUT snmp_trap_oid text, OUT snmp_enterprise_oid text, OUT snmp_varbinding_oid text, OUT snmp_varbinding_value text) AS $$
DECLARE
	alert_name text;
	alert_agent_id int;
	alert_server_id int;
	alert_database_name text;
	alert_object_name text;
	alert_schema_name text;
	alert_thresholdvalue text;
	server_name text;
	server_ip text;
	server_port integer;
	agent_name text;
	alert_template_id integer;
	alert_object_type integer;
	alert_snmp_oid integer;
BEGIN
	snmp_enterprise_oid = '.1.3.6.1.4.1.27645.5444';

	-- Get alert, agent, server details
	SELECT
		a.name, a.agent_id, a.server_id, a.database_name, a.schema_name, a.object_name, a.thresholds, a.template_id,
		s.description, s.server, s.port,
		ag.description
	INTO
		alert_name, alert_agent_id, alert_server_id, alert_database_name, alert_schema_name, alert_object_name,
		alert_thresholdvalue, alert_template_id, server_name, server_ip, server_port,
		agent_name
	FROM
		pem.alert a
		LEFT JOIN pem.server s ON a.server_id = s.id
		LEFT JOIN pem.agent ag ON a.agent_id = ag.id
	WHERE
		a.id = alert_id;

	-- We used "|" as one of the delimiter for snmp_varbinding_oid and snmp_varbinding_value, so replacing it with " " to avoid errors.
	alert_name = replace(alert_name, '|', ' ');
	agent_name = replace(agent_name, '|', ' ');
	server_name = replace(server_name, '|', ' ');
	alert_database_name = replace(alert_database_name, '|', ' ');
	alert_object_name = replace(alert_object_name, '|', ' ');
	alert_schema_name = replace(alert_schema_name, '|', ' ');

	-- Get SNMP OID
	SELECT snmp_oid, object_type INTO alert_snmp_oid, alert_object_type FROM pem.alert_template WHERE id = alert_template_id;

	CASE
	WHEN alert_object_type = 50 THEN
		snmp_trap_oid = snmp_enterprise_oid || '.9.' || alert_snmp_oid;
		snmp_varbinding_oid = snmp_enterprise_oid || '.10.1|' || snmp_enterprise_oid || '.10.9|' || snmp_enterprise_oid || '.10.10|' || snmp_enterprise_oid || '.10.11|'
							|| snmp_enterprise_oid || '.10.12|' || snmp_enterprise_oid || '.10.13|' || snmp_enterprise_oid || '.10.14';
		snmp_varbinding_value = alert_name || '|' || alert_thresholdvalue;
	WHEN alert_object_type = 100 THEN
		snmp_trap_oid = snmp_enterprise_oid || '.1.' || alert_snmp_oid;
		snmp_varbinding_oid = snmp_enterprise_oid || '.10.1|' || snmp_enterprise_oid || '.10.2|' || snmp_enterprise_oid || '.10.4|' || snmp_enterprise_oid ||
							'.10.9|' || snmp_enterprise_oid || '.10.10|' || snmp_enterprise_oid || '.10.11|' || snmp_enterprise_oid ||
							'.10.12|' || snmp_enterprise_oid || '.10.13|' || snmp_enterprise_oid || '.10.14';
		snmp_varbinding_value = alert_name || '|' || alert_agent_id || '|' || agent_name || '|' || alert_thresholdvalue;
	WHEN alert_object_type = 200 THEN
		snmp_trap_oid = snmp_enterprise_oid || '.2.' || alert_snmp_oid;
		snmp_varbinding_oid = snmp_enterprise_oid || '.10.1|' || snmp_enterprise_oid || '.10.3|' || snmp_enterprise_oid || '.10.5|' || snmp_enterprise_oid ||
							'.10.9|' || snmp_enterprise_oid || '.10.10|' || snmp_enterprise_oid || '.10.11|' || snmp_enterprise_oid ||
							'.10.12|' || snmp_enterprise_oid || '.10.13|' || snmp_enterprise_oid || '.10.14';
		snmp_varbinding_value = alert_name || '|' || alert_server_id || '|' || server_name || ' ('|| server_ip ||': ' || server_port || ')|'
							|| alert_thresholdvalue;
	WHEN alert_object_type = 300 THEN
		snmp_trap_oid = snmp_enterprise_oid || '.3.' || alert_snmp_oid;
		snmp_varbinding_oid = snmp_enterprise_oid || '.10.1|' || snmp_enterprise_oid || '.10.3|' || snmp_enterprise_oid || '.10.5|' || snmp_enterprise_oid ||
							'.10.6|' || snmp_enterprise_oid || '.10.9|' || snmp_enterprise_oid || '.10.10|' || snmp_enterprise_oid ||
							'.10.11|'|| snmp_enterprise_oid || '.10.12|' || snmp_enterprise_oid || '.10.13|' || snmp_enterprise_oid || '.10.14';
		snmp_varbinding_value = alert_name || '|' || alert_server_id || '|' || server_name || ' ('|| server_ip ||': ' || server_port || ')|' ||
							alert_database_name || '|' || alert_thresholdvalue;
	WHEN alert_object_type = 400 THEN
		snmp_trap_oid = snmp_enterprise_oid || '.4.' || alert_snmp_oid;
		snmp_varbinding_oid = snmp_enterprise_oid || '.10.1|' || snmp_enterprise_oid || '.10.3|' || snmp_enterprise_oid || '.10.5|' || snmp_enterprise_oid ||
							'.10.6|' || snmp_enterprise_oid || '.10.7|' || snmp_enterprise_oid || '.10.9|' || snmp_enterprise_oid ||
							'.10.10|' || snmp_enterprise_oid || '.10.11|'|| snmp_enterprise_oid || '.10.12|' || snmp_enterprise_oid ||
							'.10.13|'  ||snmp_enterprise_oid || '.10.14';
		snmp_varbinding_value = alert_name || '|' || alert_server_id || '|' || server_name || ' ('|| server_ip ||': ' || server_port || ')|' ||
							 alert_database_name || '|' || alert_schema_name || '|' || alert_thresholdvalue;
	WHEN alert_object_type = 500 THEN
		snmp_trap_oid = snmp_enterprise_oid || '.5.' || alert_snmp_oid;
		snmp_varbinding_oid = snmp_enterprise_oid || '.10.1|' || snmp_enterprise_oid || '.10.3|' || snmp_enterprise_oid || '.10.5|' || snmp_enterprise_oid ||
							'.10.6|' || snmp_enterprise_oid || '.10.7|' || snmp_enterprise_oid || '.10.8|' || snmp_enterprise_oid ||
							'.10.9|' || snmp_enterprise_oid || '.10.10|'|| snmp_enterprise_oid || '.10.11|' || snmp_enterprise_oid ||
							'.10.12|'|| snmp_enterprise_oid || '.10.13|' || snmp_enterprise_oid || '.10.14';
		snmp_varbinding_value = alert_name || '|' || alert_server_id || '|' || server_name || ' ('|| server_ip ||': ' || server_port || ')|' ||
							 alert_database_name || '|' || alert_schema_name || '|' || alert_object_name || '|' ||
							 alert_thresholdvalue;
	WHEN alert_object_type = 600 THEN
		snmp_trap_oid = snmp_enterprise_oid || '.6.' || alert_snmp_oid;
		snmp_varbinding_oid = snmp_enterprise_oid || '.10.1|' || snmp_enterprise_oid || '.10.3|' || snmp_enterprise_oid || '.10.5|' || snmp_enterprise_oid ||
							'.10.6|' || snmp_enterprise_oid || '.10.7|' || snmp_enterprise_oid || '.10.8|' || snmp_enterprise_oid ||
							'.10.9|' || snmp_enterprise_oid || '.10.10|'|| snmp_enterprise_oid || '.10.11|' || snmp_enterprise_oid ||
							'.10.12|'|| snmp_enterprise_oid || '.10.13|' || snmp_enterprise_oid || '.10.14';
		snmp_varbinding_value = alert_name || '|' || alert_server_id || '|' || server_name || ' ('|| server_ip ||': ' || server_port || ')|' ||
							 alert_database_name || '|' || alert_schema_name || '|' || alert_object_name || '|' ||
							 alert_thresholdvalue;
	WHEN alert_object_type = 700 THEN
		snmp_trap_oid = snmp_enterprise_oid || '.7.' || alert_snmp_oid;
		snmp_varbinding_oid = snmp_enterprise_oid || '.10.1|' || snmp_enterprise_oid || '.10.3|' || snmp_enterprise_oid || '.10.5|' || snmp_enterprise_oid ||
							'.10.6|' || snmp_enterprise_oid || '.10.7|' || snmp_enterprise_oid || '.10.8|' || snmp_enterprise_oid ||
							'.10.9|' || snmp_enterprise_oid || '.10.10|'|| snmp_enterprise_oid || '.10.11|' || snmp_enterprise_oid ||
							'.10.12|'|| snmp_enterprise_oid || '.10.13|' || snmp_enterprise_oid || '.10.14';
		snmp_varbinding_value = alert_name || '|' || alert_server_id || '|' || server_name || ' ('|| server_ip ||': ' || server_port || ')|' ||
							 alert_database_name || '|' || alert_schema_name || '|' || alert_object_name || '|' ||
							 alert_thresholdvalue;
	WHEN alert_object_type = 800 THEN
		snmp_trap_oid = snmp_enterprise_oid || '.8.' || alert_snmp_oid;
		snmp_varbinding_oid = snmp_enterprise_oid || '.10.1|' || snmp_enterprise_oid || '.10.3|' || snmp_enterprise_oid || '.10.5|' || snmp_enterprise_oid ||
							'.10.6|' || snmp_enterprise_oid || '.10.7|' || snmp_enterprise_oid || '.10.8|' || snmp_enterprise_oid ||
							'.10.9|' || snmp_enterprise_oid || '.10.10|'|| snmp_enterprise_oid || '.10.11|' || snmp_enterprise_oid ||
							'.10.12|'|| snmp_enterprise_oid || '.10.13|' || snmp_enterprise_oid || '.10.14';
		snmp_varbinding_value = alert_name || '|' || alert_server_id || '|' || server_name || ' ('|| server_ip ||': ' || server_port || ')|' ||
							 alert_database_name || '|' || alert_schema_name || '|' || alert_object_name || '|' ||
							 alert_thresholdvalue;
	END CASE;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION pem.purge_smtp_spool()
RETURNS void AS $$
DECLARE
	cutoff_ts timestamp with time zone;
BEGIN
	cutoff_ts := (SELECT now() - CAST(value || ' ' || unit AS interval)
		FROM pem.config WHERE param = 'smtp_spool_retention_time');

	DELETE FROM pem.smtp_spool AS s
	WHERE s.sent_status = 's' AND s.recorded_time < cutoff_ts;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION pem.purge_snmp_spool()
RETURNS void AS $$
DECLARE
	cutoff_ts timestamp with time zone;
BEGIN
	cutoff_ts := (SELECT now() - CAST(value || ' ' || unit AS interval)
		FROM pem.config WHERE param = 'smnp_spool_retention_time');

	DELETE FROM pem.snmp_spool AS s
	WHERE s.sent_status = 's' AND s.recorded_time < cutoff_ts;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION pem.purge_audit_log()
RETURNS void AS $$
DECLARE
	cutoff_ts timestamp with time zone;
BEGIN
	cutoff_ts := (SELECT now() - CAST(value || ' ' || unit AS interval)
		FROM pem.config WHERE param = 'audit_log_retention_time');

	-- Purge data from audit log table
	DELETE FROM pemdata.audit_logs AS al
	WHERE al.log_time < cutoff_ts;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION pem.purge_server_log()
RETURNS void AS $$
DECLARE
	cutoff_ts timestamp with time zone;
BEGIN
	cutoff_ts := (SELECT now() - CAST(value || ' ' || unit AS interval)
		FROM pem.config WHERE param = 'server_log_retention_time');

	-- Purge data from server log table
	DELETE FROM pemdata.server_logs AS sl
	WHERE sl.log_time < cutoff_ts;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION pem.purge_probe_log()
RETURNS void AS $$
DECLARE
	cutoff_ts timestamp with time zone;
BEGIN
	cutoff_ts := (SELECT now() - CAST(value || ' ' || unit AS interval)
		FROM pem.config WHERE param = 'probe_log_retention_time');

	-- Purge data from probe log table
	DELETE FROM pem.probe_log AS pl
	WHERE pl.recorded_time < cutoff_ts;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION pem.purge_alert_history()
RETURNS void AS $$
	-- Purge data from alert history table
	DELETE FROM pem.alert_history AS h
	USING pem.alert AS a
	WHERE a.id = h.alert_id AND
		h.generated < now() - a.history_retention * interval '1 day';
$$ LANGUAGE sql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION pem.purge_job_log()
RETURNS void AS $$
DECLARE
	cutoff_ts timestamp with time zone;
BEGIN
	cutoff_ts := (SELECT now() - CAST(value || ' ' || unit AS interval)
		FROM pem.config WHERE param = 'job_retention_time');

	-- Purge old jobs, steps and schedules
	DELETE FROM pem.job AS j
	WHERE j.jobnextrun IS NULL AND j.joblastrun < cutoff_ts AND j.issystemjob = false;

	-- Purge job log and job step log
	DELETE FROM pem.joblog AS jl
	WHERE jl.jlgstart < cutoff_ts;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION pem.purge_deleted_probes()
RETURNS void AS $BODY$
DECLARE
	curs_del_probes CURSOR FOR
		SELECT pr.id, pr.internal_name, pr.discard_history, pr.deleted_time,
			(CASE  WHEN (SELECT 1 FROM pem.probe_column AS pc WHERE pc.probe_id = pr.id AND pc.calculate_pit = true) = 1 THEN true ELSE false END) AS has_pit
		FROM pem.probe AS pr WHERE pr.deleted AND NOT pr.is_system_probe;
	quoted_table_name varchar;
	retention_time interval;
	deleted_time interval;
BEGIN
	SELECT (value ||'days')::interval FROM pem.config WHERE param = 'deleted_probes_retention_time' into retention_time;
	FOR deleted_probes IN curs_del_probes LOOP
		deleted_time = now() - deleted_probes.deleted_time;
		IF deleted_time >= retention_time THEN
			quoted_table_name := quote_ident(deleted_probes.internal_name);

			IF deleted_probes.has_pit = true THEN
				EXECUTE 'DROP TRIGGER ' || quote_ident('calculate_' || deleted_probes.internal_name || '_pit_value') || ' ON pemdata.' || quoted_table_name;
				EXECUTE 'DROP FUNCTION pemdata.' ||  quote_ident('calculate_' || deleted_probes.internal_name || '_pit_value') || E'()';
			END IF;

			IF NOT deleted_probes.discard_history THEN
				EXECUTE 'DROP TRIGGER ' || quote_ident('copy_' || deleted_probes.internal_name || '_to_history') || ' ON pemdata.' || quoted_table_name;
				EXECUTE 'DROP FUNCTION pemdata.' ||  quote_ident('copy_' || deleted_probes.internal_name || '_to_history') || E'()';
				EXECUTE 'DROP TABLE pemhistory.' || quoted_table_name || ' CASCADE';
			END IF;

			EXECUTE 'DROP TABLE pemdata.' || quoted_table_name || ' CASCADE';
			EXECUTE 'DELETE FROM pem.probe WHERE internal_name = ''' || deleted_probes.internal_name || ''' AND deleted AND NOT is_system_probe';
		END IF;
	END LOOP;
END;
$BODY$ LANGUAGE plpgsql SECURITY DEFINER;


CREATE OR REPLACE FUNCTION pem.generate_alert_mib()
RETURNS text AS $$
DECLARE
	mib_text text;
BEGIN

	mib_text = E'\n-- File Name : PEM-ALERTING-MIB\n
-- Date      : ' || now()::text || E'\n
-- Author    : EnterpriseDB \n

PEM-ALERTING-MIB	DEFINITIONS ::= BEGIN

	IMPORTS
		enterprises, MODULE-IDENTITY, OBJECT-TYPE, Integer32, NOTIFICATION-TYPE
			FROM SNMPv2-SMI
		DisplayString
			FROM SNMPv2-TC
		OBJECT-GROUP, NOTIFICATION-GROUP
			FROM SNMPv2-CONF;


	postgresql	MODULE-IDENTITY
		LAST-UPDATED	"201109271419Z"
		ORGANIZATION	"EnterpriseDB"
		CONTACT-INFO	"http://www.enterprisedb.com"
		DESCRIPTION	"This MIB file used for alerting notifications."
		REVISION	"201109271419Z"
		DESCRIPTION	"This MIB file used for alerting notifications."
		::=  {  enterprises  27645  }

	pem	OBJECT IDENTIFIER ::=  {  postgresql  5444  }

	agentAlerts	OBJECT IDENTIFIER ::=  {  pem  1  }

	serverAlerts	OBJECT IDENTIFIER ::=  {  pem  2  }

	databaseAlerts	OBJECT IDENTIFIER ::=  {  pem  3  }

	schemaAlerts	OBJECT IDENTIFIER ::=  {  pem  4  }

    tableObjectAlerts   OBJECT IDENTIFIER ::=  {  pem  5  }

    indexObjectAlerts   OBJECT IDENTIFIER ::=  {  pem  6  }

    sequenceObjectAlerts    OBJECT IDENTIFIER ::=  {  pem  7  }

    functionObjectAlerts    OBJECT IDENTIFIER ::=  {  pem  8  }

	globalAlerts	OBJECT IDENTIFIER ::=  {  pem  9  }

	bindingVariables	OBJECT IDENTIFIER ::=  {  pem  10  }

	pemObjectGroup  OBJECT-GROUP
		OBJECTS { alertName,
			agentID,
			agentName,
			databaseName,
			objectName,
			previousStatus,
			previousValue,
			schemaName,
			serverID,
			serverName,
			status,
			thresholdValue,
			value,
			recordedTime,
			downObjects,
			detailedInformation}
	STATUS 	current
	DESCRIPTION
		"This group contains the notification detail objects"
	::= { postgresql 5445 }

	alertName	OBJECT-TYPE
		SYNTAX			DisplayString
		MAX-ACCESS		read-only
		STATUS			current
		DESCRIPTION		"This parameter gives the alert name"
		::=  {  bindingVariables  1  }

	agentID		OBJECT-TYPE
		SYNTAX			Integer32
		MAX-ACCESS		read-only
		STATUS			current
		DESCRIPTION		"This parameter gives the agent id for which this alert is raised"
		::=  {  bindingVariables  2  }

	serverID	OBJECT-TYPE
		SYNTAX			Integer32
		MAX-ACCESS		read-only
		STATUS			current
		DESCRIPTION		"This parameter gives the server id for which this alert is raised"
		::=  {  bindingVariables  3  }

	agentName	OBJECT-TYPE
		SYNTAX			DisplayString
		MAX-ACCESS		read-only
		STATUS			current
		DESCRIPTION		"This parameter gives the agent name for which this alert is raised"
		::=  {  bindingVariables  4  }

	serverName	OBJECT-TYPE
		SYNTAX			DisplayString
		MAX-ACCESS		read-only
		STATUS			current
		DESCRIPTION		"This parameter gives the server name for which this alert is raised"
		::=  {  bindingVariables  5  }

	databaseName	OBJECT-TYPE
		SYNTAX			DisplayString
		MAX-ACCESS		read-only
		STATUS			current
		DESCRIPTION		"This parameter gives the database name for which this alert is raised"
		::=  {  bindingVariables  6  }

	schemaName	OBJECT-TYPE
		SYNTAX			DisplayString
		MAX-ACCESS		read-only
		STATUS			current
		DESCRIPTION		"This parameter gives the schema name for which this alert is raised"
		::=  {  bindingVariables  7  }

	objectName	OBJECT-TYPE
		SYNTAX			DisplayString
		MAX-ACCESS		read-only
		STATUS			current
		DESCRIPTION		"This parameter gives the object name for which this alert is raised"
		::=  {  bindingVariables  8  }

	thresholdValue	OBJECT-TYPE
		SYNTAX			DisplayString
		MAX-ACCESS		read-only
		STATUS			current
		DESCRIPTION		"This parameter gives the threshold value of the alert"
		::=  {  bindingVariables  9  }

	previousValue	OBJECT-TYPE
		SYNTAX			DisplayString
		MAX-ACCESS		read-only
		STATUS			current
		DESCRIPTION		"This parameter gives the previous value of the alert"
		::=  {  bindingVariables  10  }

	value	OBJECT-TYPE
		SYNTAX			DisplayString
		MAX-ACCESS		read-only
		STATUS			current
		DESCRIPTION		"This parameter gives the current value of the alert"
		::=  {  bindingVariables  11  }

	previousStatus	OBJECT-TYPE
		SYNTAX			DisplayString
		MAX-ACCESS		read-only
		STATUS			current
		DESCRIPTION		"This parameter gives the previous status of the alert"
		::=  {  bindingVariables  12  }

	status	OBJECT-TYPE
		SYNTAX			DisplayString
		MAX-ACCESS		read-only
		STATUS			current
		DESCRIPTION		"This parameter gives the current status of the alert"
		::=  {  bindingVariables  13  }

	recordedTime	OBJECT-TYPE
		SYNTAX			DisplayString
		MAX-ACCESS		read-only
		STATUS			current
		DESCRIPTION		"This parameter gives the time when the event was recorded"
		::=  {  bindingVariables  14  }

	downObjects		OBJECT-TYPE
		SYNTAX			DisplayString
		MAX-ACCESS		read-only
		STATUS			current
		DESCRIPTION		"This parameter lists the servers/agents that are in a down state"
		::=  {  bindingVariables  15  }

	detailedInformation		OBJECT-TYPE
		SYNTAX			DisplayString
		MAX-ACCESS		read-only
		STATUS			current
		DESCRIPTION		"This parameter displays the detailed information of the alert"
		::=  {  bindingVariables  16  }';

	/* Agent Alerts */
	mib_text = mib_text || pem.create_mib_notification_type(100, 5446);
	/* server Alerts */
	mib_text = mib_text || pem.create_mib_notification_type(200, 5447);
	/* database Alerts */
	mib_text = mib_text || pem.create_mib_notification_type(300, 5448);
	/* schema Alerts */
	mib_text = mib_text || pem.create_mib_notification_type(400, 5449);
	/* object Alerts */
	mib_text = mib_text || pem.create_mib_notification_type(500, 5450);
	mib_text = mib_text || pem.create_mib_notification_type(600, 5451);
	mib_text = mib_text || pem.create_mib_notification_type(700, 5452);
	mib_text = mib_text || pem.create_mib_notification_type(800, 5453);
	/* global Alerts */
	mib_text = mib_text || pem.create_mib_notification_type(50, 5454);

	mib_text = mib_text || E'\nEND';

	RETURN mib_text;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION pem.create_mib_notification_type(object_type integer, group_oid_type integer)
RETURNS text AS $$
DECLARE
	return_text text = '';
	tmp_rec	RECORD;
	parent_node text;
	where_clause text;
	object_prefix text;
	object_string text;
	group_text text = '';
	group_description text = '';
	is_alert_found boolean = false;
BEGIN
	CASE
	WHEN object_type = 50 THEN
		where_clause = 'WHERE object_type = 50 AND snmp_oid > 0';
		parent_node = 'globalAlerts';
		object_string = '{ alertName, thresholdValue, previousValue, value, previousStatus, status, recordedTime, downObjects, detailedInformation }';
		object_prefix = 'gl';
		group_text = E'\n\n\tpemGlobalNotificationGroup  NOTIFICATION-GROUP
	\tNOTIFICATIONS {';
		group_description = 'This group contains the global notification types';
	WHEN object_type = 100 THEN
		where_clause = 'WHERE object_type = 100 AND snmp_oid > 0';
		parent_node = 'agentAlerts';
		object_string = '{ alertName, agentID , agentName, thresholdValue, previousValue, value, previousStatus, status, recordedTime, detailedInformation }';
		object_prefix = 'ag';
		group_text = E'\n\n\tpemAgentNotificationGroup  NOTIFICATION-GROUP
	\tNOTIFICATIONS {';
		group_description = 'This group contains the agent level notification types';
	WHEN object_type = 200 THEN
		where_clause = 'WHERE object_type = 200 AND snmp_oid > 0';
		parent_node = 'serverAlerts';
		object_string = '{ alertName, serverID , serverName, thresholdValue, previousValue, value, previousStatus, status, recordedTime, detailedInformation }';
		object_prefix = 'sr';
		group_text = E'\n\n\tpemServerNotificationGroup  NOTIFICATION-GROUP
	\tNOTIFICATIONS {';
		group_description = 'This group contains the server level notification types';
	WHEN object_type = 300 THEN
		where_clause = 'WHERE object_type = 300 AND snmp_oid > 0';
		parent_node = 'databaseAlerts';
		object_string = '{ alertName, serverID , serverName, databaseName, thresholdValue, previousValue, value, previousStatus, status, recordedTime, detailedInformation }';
		object_prefix = 'db';
		group_text = E'\n\n\tpemDatabaseNotificationGroup  NOTIFICATION-GROUP
	\tNOTIFICATIONS {';
		group_description = 'This group contains the database level notification types';
	WHEN object_type = 400 THEN
		where_clause = 'WHERE object_type = 400 AND snmp_oid > 0';
		parent_node = 'schemaAlerts';
		object_string = '{ alertName, serverID , serverName, databaseName, schemaName, thresholdValue, previousValue, value, previousStatus, status, recordedTime, detailedInformation }';
		object_prefix = 'sc';
		group_text = E'\n\n\tpemSchemaNotificationGroup  NOTIFICATION-GROUP
	\tNOTIFICATIONS {';
		group_description = 'This group contains the schema level notification types';
	WHEN object_type = 500 THEN
		where_clause = 'WHERE object_type = 500 AND snmp_oid > 0';
		parent_node = 'tableObjectAlerts';
		object_string = '{ alertName, serverID , serverName, databaseName, schemaName, objectName, thresholdValue, previousValue, value, previousStatus, status, recordedTime, detailedInformation }';
		object_prefix = 'tb';
		group_text = E'\n\n\tpemTableNotificationGroup  NOTIFICATION-GROUP
	\tNOTIFICATIONS {';
		group_description = 'This group contains the table level notification types';
	WHEN object_type = 600 THEN
		where_clause = 'WHERE object_type = 600 AND snmp_oid > 0';
		parent_node = 'indexObjectAlerts';
		object_string = '{ alertName, serverID , serverName, databaseName, schemaName, objectName, thresholdValue, previousValue, value, previousStatus, status, recordedTime, detailedInformation }';
		object_prefix = 'in';
		group_text = E'\n\n\tpemIndexNotificationGroup  NOTIFICATION-GROUP
	\tNOTIFICATIONS {';
		group_description = 'This group contains the index level notification types';
	WHEN object_type = 700 THEN
		where_clause = 'WHERE object_type = 700 AND snmp_oid > 0';
		parent_node = 'sequenceObjectAlerts';
		object_string = '{ alertName, serverID , serverName, databaseName, schemaName, objectName, thresholdValue, previousValue, value, previousStatus, status, recordedTime, detailedInformation }';
		object_prefix = 'se';
		group_text = E'\n\n\tpemSequenceNotificationGroup  NOTIFICATION-GROUP
	\tNOTIFICATIONS {';
		group_description = 'This group contains the sequence level notification types';
	WHEN object_type = 800 THEN
		where_clause = 'WHERE object_type = 800 AND snmp_oid > 0';
		parent_node = 'functionObjectAlerts';
		object_string = '{ alertName, serverID , serverName, databaseName, schemaName, objectName, thresholdValue, previousValue, value, previousStatus, status, recordedTime, detailedInformation }';
		object_prefix = 'fn';
		group_text = E'\n\n\tpemFunctionNotificationGroup  NOTIFICATION-GROUP
	\tNOTIFICATIONS {';
		group_description = 'This group contains the function level notification types';
	END CASE;

	FOR tmp_rec IN EXECUTE 'SELECT display_name, description , snmp_oid FROM pem.alert_template ' || where_clause || ' ORDER BY snmp_oid'
	LOOP
		is_alert_found = true;
		tmp_rec.display_name = lower(tmp_rec.display_name);
		tmp_rec.display_name = replace(tmp_rec.display_name, '(', '');
		tmp_rec.display_name = replace(tmp_rec.display_name, ')', '');
		tmp_rec.display_name = replace(tmp_rec.display_name, ',', '');
		tmp_rec.display_name = replace(tmp_rec.display_name, '-', '');
		tmp_rec.display_name = replace(tmp_rec.display_name, '_', '');
		tmp_rec.display_name = initcap(tmp_rec.display_name);
		tmp_rec.display_name = replace(tmp_rec.display_name, ' ', '');

		tmp_rec.description = replace(tmp_rec.description, '"', '');

		IF char_length(tmp_rec.display_name) > 62 THEN
			tmp_rec.display_name = substr(tmp_rec.display_name, 0, 62);
		END IF;

		return_text =  return_text || E'\n\n\t' || object_prefix || tmp_rec.display_name || E'   NOTIFICATION-TYPE
		OBJECTS			' || object_string || E'
		STATUS			current
		DESCRIPTION \t\t"'	||	tmp_rec.description || E'"
		::=  {  ' || parent_node || '  ' || tmp_rec.snmp_oid::text ||  '  }';

		group_text = group_text || E'\n\t\t\t' ||object_prefix || tmp_rec.display_name || E',';
	END LOOP;

	group_text = trim(trailing ',' from group_text);

	group_text = group_text || '}
	STATUS 	current
	DESCRIPTION
		"'|| group_description ||'"
	::= { postgresql ' || group_oid_type || '}';

	IF is_alert_found THEN
		RETURN group_text || return_text;
	ELSE
		RETURN return_text;
	END IF;
END;
$$ LANGUAGE plpgsql;

CREATE TYPE pem.server_agent_state AS ENUM(
	'UP',
	'DOWN',
	'UNKNOWN',
	'BLACKEDOUT'
);

/********************************
* WEBHOOK endpoints			*
********************************/
CREATE TABLE pem.webhook_endpoints
(
   id           serial,
   name         text NOT NULL,
   url          text NOT NULL,
   enabled      bool,
   method       text NOT NULL,
   payload_template     text NOT NULL,
   low_alert     bool,
   med_alert     bool,
   high_alert    bool,
   cleared_alert bool,
   active        bool default true,
   owner text default current_user,
   payload_type text NOT NULL default 'ALERT',
   CONSTRAINT webhook_endpoints_pk PRIMARY KEY (id),
   CONSTRAINT webhook_endpoints_method CHECK (method IN ('POST', 'PUT'))
);

COMMENT ON TABLE pem.webhook_endpoints IS 'This contains the information about webhook endpoints saved by user';
COMMENT ON COLUMN pem.webhook_endpoints.url IS 'This column stores the webhook URL';
COMMENT ON COLUMN pem.webhook_endpoints.enabled IS 'This column stores whether webhook is enabled or not';
COMMENT ON COLUMN pem.webhook_endpoints.method IS 'This column stores the method type (POST/PUT) to be used during request';
COMMENT ON COLUMN pem.webhook_endpoints.payload_template IS 'This column stores the payload_template for webhook';
COMMENT ON COLUMN pem.webhook_endpoints.low_alert IS 'This column stores whether to send alert for low alert or not';
COMMENT ON COLUMN pem.webhook_endpoints.med_alert IS 'This column stores whether to send alert for medium alert or not';
COMMENT ON COLUMN pem.webhook_endpoints.high_alert IS 'This column stores whether to send alert for high alert or not';
COMMENT ON COLUMN pem.webhook_endpoints.cleared_alert IS 'This column stores whether to send alert for cleared alert or not';
COMMENT ON COLUMN pem.webhook_endpoints.owner IS 'This column stores the owner who created this particular webhook endpoint';

CREATE TABLE pem.webhook_http_headers
(
   id                serial,
   webhook_id        int NOT NULL,
   http_header_key   text NOT NULL,
   http_header_value text NOT NULL,
   CONSTRAINT webhook_http_pk PRIMARY KEY (id),
   UNIQUE(webhook_id, http_header_key),
   CONSTRAINT fk_webhook_id
      FOREIGN KEY(webhook_id)
	  REFERENCES pem.webhook_endpoints(id) MATCH SIMPLE
            ON UPDATE NO ACTION
            ON DELETE CASCADE
);

COMMENT ON TABLE pem.webhook_http_headers IS 'This contains the information about webhook http headers for each wenhook endpoints';
COMMENT ON COLUMN pem.webhook_http_headers.webhook_id IS 'This column stores the webhook id to which the key-value belongs';
COMMENT ON COLUMN pem.webhook_http_headers.http_header_key IS 'This column stores webhook http header key';
COMMENT ON COLUMN pem.webhook_http_headers.http_header_value IS 'This column stores webhook http header value';

/********************************
* WEBHOOK Spooler			*
********************************/
INSERT INTO pem.config (param, value, unit, datatype) VALUES ('webhook_spool_retention_time', '7', 'days', 'integer');  -- Default values to be used by purging function.

CREATE TABLE pem.webhook_spool
(
   recorded_time  timestamp with time zone NOT NULL DEFAULT now(),
   id          bigserial,
   webhook_id  integer NOT NULL,
   alert_id    integer NOT NULL,
   agent_id    integer NOT NULL,
   payload     text NOT NULL,
   sent_status    char NOT NULL,
   error          text default '',
   CONSTRAINT webhook_spool_pk PRIMARY KEY (id),
   CONSTRAINT webhook_spool_sent_status CHECK (sent_status IN ('s', 'u', 'f'))
);

COMMENT ON TABLE pem.webhook_spool IS 'This contains webhook spooler information';
COMMENT ON COLUMN pem.webhook_spool.webhook_id IS 'This column stores the webhook id to refer to other webhook endpoints details';
COMMENT ON COLUMN pem.webhook_spool.alert_id IS 'This column stores alert id to refer to other alert details';
COMMENT ON COLUMN pem.webhook_spool.agent_id IS 'This column stores agent id for auditing purpose';
COMMENT ON COLUMN pem.webhook_spool.payload IS 'This column stores the actual payload to be sent';
COMMENT ON COLUMN pem.webhook_spool.sent_status IS 'This column stores sent status of webhook';
COMMENT ON COLUMN pem.webhook_spool.error IS 'This column stores the error message if any';

-- Purge Webhook spool table function
CREATE INDEX webhook_spool_recorded_time_idx ON pem.webhook_spool(recorded_time);
CREATE OR REPLACE FUNCTION pem.purge_webhook_spool()
RETURNS void AS $$
DECLARE
   cutoff_ts timestamp with time zone;
BEGIN
    cutoff_ts := (SELECT now() - CAST(value || ' ' || unit AS interval)
        FROM pem.config WHERE param = 'webhook_spool_retention_time');

    DELETE FROM pem.webhook_spool AS s
        WHERE s.recorded_time < cutoff_ts;

    -- Clean up the notifications for which webhook endpoint is no longer
    -- in the system.
    DELETE FROM pem.webhook_spool
    WHERE webhook_id not in (SELECT id FROM pem.webhook_endpoints);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Send Webhook function
CREATE OR REPLACE FUNCTION pem.send_webhook(webhook_id int, alert_id int, agent_id int, payload text)
RETURNS TABLE(success boolean, inserted_id int) AS $$
DECLARE
    new_id int;
BEGIN
    -- Insert the spool record and get the new ID
    INSERT INTO pem.webhook_spool(webhook_id, alert_id, agent_id, payload, sent_status)
    VALUES (webhook_id, alert_id, agent_id, payload, 'u')
    RETURNING id INTO new_id;

    -- Notify listener
    NOTIFY WEBHOOK_SPOOL;

    -- Correctly return values
    RETURN QUERY SELECT TRUE, new_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Webhook Spool History table
INSERT INTO pem.config (param, value, unit, datatype) VALUES ('webhook_spool_history_retention_time', '15', 'days', 'integer');  -- Default values to be used by purging function.

CREATE TABLE pemhistory.webhook_spool
(
   recorded_time  timestamp with time zone NOT NULL DEFAULT now(),
   id          bigint,
   webhook_id  integer NOT NULL,
   alert_id    integer NOT NULL,
   agent_id    integer NOT NULL,
   payload     text NOT NULL,
   sent_status    char NOT NULL,
   error          text default '',
   CONSTRAINT webhook_spool_sent_status CHECK (sent_status IN ('s', 'u', 'f'))
);

COMMENT ON TABLE pemhistory.webhook_spool IS 'This contains webhook spooler history information';
COMMENT ON COLUMN pemhistory.webhook_spool.webhook_id IS 'This column stores the webhook id to refer to other webhook endpoints details';
COMMENT ON COLUMN pemhistory.webhook_spool.alert_id IS 'This column stores alert id to refer to other alert details';
COMMENT ON COLUMN pemhistory.webhook_spool.agent_id IS 'This column stores agent id for auditing purpose';
COMMENT ON COLUMN pemhistory.webhook_spool.payload IS 'This column stores the actual payload to be sent';
COMMENT ON COLUMN pemhistory.webhook_spool.sent_status IS 'This column stores sent status of webhook';
COMMENT ON COLUMN pemhistory.webhook_spool.error IS 'This column stores the error message if any';

-- Purge Webhook spool history table function
CREATE INDEX webhook_spool_history_recorded_time_idx ON pemhistory.webhook_spool(recorded_time);
CREATE OR REPLACE FUNCTION pem.purge_webhook_spool_history()
RETURNS void AS $$
DECLARE
   cutoff_ts timestamp with time zone;
BEGIN
    cutoff_ts := (SELECT now() - CAST(value || ' ' || unit AS interval)
        FROM pem.config WHERE param = 'webhook_spool_history_retention_time');
    DELETE FROM pemhistory.webhook_spool AS s
    WHERE s.recorded_time < cutoff_ts;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- To update webhook_spool history table
CREATE OR REPLACE FUNCTION pem.log_webhook_spool_history() RETURNS TRIGGER AS $$
    BEGIN
       IF (TG_OP = 'INSERT')
          OR (TG_OP = 'UPDATE')
       THEN
          INSERT INTO pemhistory.webhook_spool(id, webhook_id, alert_id, agent_id, payload, sent_status)
          VALUES(
             NEW.id, NEW.webhook_id, NEW.alert_id, NEW.agent_id, NEW.payload, NEW.sent_status
          );
       END IF;
       RETURN new;
    END;
    $$ LANGUAGE plpgsql;

CREATE TRIGGER log_webhook_spool_history
   AFTER INSERT OR UPDATE ON pem.webhook_spool
   FOR EACH ROW
   EXECUTE PROCEDURE pem.log_webhook_spool_history();

/********************************
* NAGIOS Spooler			*
********************************/
INSERT INTO pem.config (param, value, unit, datatype) VALUES ('nagios_enabled', 't', 't/f', 'bool'); --Enable/disable submit to nagios functionality
INSERT INTO pem.config (param, value, unit, datatype ) VALUES ('nagios_medium_alert_as_critical', 'f', 't/f', 'bool'); --consider medium pem alerts as critical
INSERT INTO pem.config (param, value, unit, datatype) VALUES ('nagios_cmd_file_name', '/usr/local/nagios/var/rw/nagios.cmd', '', 'string'); --nagios cmd file to which passive service check result are needed to be sent
INSERT INTO pem.config (param, value, unit, datatype) VALUES ('nagios_spool_retention_time', '7', 'days', 'integer');  -- Default values to be used by purging function.

CREATE SEQUENCE pem.nagios_spool_id_seq;
CREATE TABLE pem.nagios_spool
(
   id                          int NOT NULL DEFAULT nextval('pem.nagios_spool_id_seq'::regclass),
   message			text NOT NULL,
   sent_status		char NOT NULL,
   recorded_time	timestamp with time zone NOT NULL DEFAULT now(),

   CONSTRAINT nagios_primary_key PRIMARY KEY (id),
   CONSTRAINT nagios_spool_sent_status CHECK (sent_status IN ('s', 'u', 'i'))
);

CREATE INDEX nagios_spool_recorded_time_idx	ON pem.nagios_spool (recorded_time);

CREATE OR REPLACE FUNCTION pem.purge_nagios_spool()
RETURNS void AS $$
DECLARE
	cutoff_ts timestamp with time zone;
BEGIN
	cutoff_ts := (SELECT now() - CAST(value || ' ' || unit AS interval)
		FROM pem.config WHERE param = 'nagios_spool_retention_time');

	DELETE FROM pem.nagios_spool AS s
	WHERE sent_status = 's' AND s.recorded_time < cutoff_ts;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Function to create unique service name for nagios
CREATE OR REPLACE FUNCTION pem.create_nagios_service_name(
    alert_name text,
    server_name text DEFAULT NULL::text,
    database_name text DEFAULT NULL::text,
    schema_name text DEFAULT NULL::text,
    package_name text DEFAULT NULL::text,
    object_name text DEFAULT NULL::text)
  RETURNS text AS
$BODY$
DECLARE
    service_name_text    text := '';
    new_alert_name       text := '';
BEGIN

        new_alert_name = regexp_replace(regexp_replace(alert_name, E'[`~$%^&*|''"<>?,(=]', '-', 'g'), E'[)]', '-', 'g');
        service_name_text = E'' || new_alert_name || CASE WHEN (server_name IS NOT NULL AND server_name != '') THEN ' - svr: ' || server_name ELSE '' END || CASE WHEN (database_name IS NOT NULL AND database_name != '') THEN ' - db: ' || database_name ELSE '' END || CASE WHEN (schema_name IS NOT NULL AND schema_name != '') THEN ' - schema: ' || schema_name ELSE '' END || CASE WHEN (package_name IS NOT NULL AND package_name != '') THEN ' - pkg: ' || package_name ELSE '' END || CASE WHEN (object_name IS NOT NULL AND object_name != '') THEN ' - obj: ' || object_name ELSE '' END || E'';

RETURN service_name_text;

END
$BODY$
  LANGUAGE plpgsql;

-- Function to create host name for nagios
CREATE OR REPLACE FUNCTION pem.create_nagios_host_name(
    ag_id int,
    srv_id int)
  RETURNS text AS
$BODY$
DECLARE
    host_name    text := '';
BEGIN

	-- ag_id > 0 - Alert is configured as agent level
        -- ag_id = 0 - Alert is configured other then global and agent level
        -- ag_id = -1 - Alert is configured as global level
	IF ag_id > 0 THEN
            SELECT description INTO host_name FROM pem.agent where id = ag_id;
        ELSIF ag_id = 0 THEN
            SELECT description INTO host_name FROM pem.agent where id = (SELECT agent_id FROM pem.agent_server_binding where server_id = srv_id);
        ELSE
            SELECT description INTO host_name FROM pem.agent where id = 1;
        END IF;

RETURN host_name;

END
$BODY$
  LANGUAGE plpgsql;

-- Function to create nagios hosts.cfg file
CREATE OR REPLACE FUNCTION pem.create_nagios_host_config(
    template_name text DEFAULT NULL::text,
    is_max_check_attemp_require boolean DEFAULT FALSE::boolean,
    icon_image text DEFAULT NULL::text,
    icon_image_alt text DEFAULT NULL::text,
    statusmap_image text DEFAULT NULL::text)
  RETURNS text AS
$BODY$

DECLARE
    host_config_text    text := '';
    row                 RECORD;
BEGIN
    FOR row IN SELECT DISTINCT ON (pa.description) pa.description, ps.server FROM pem.agent pa LEFT JOIN pem.agent_server_binding pasb ON (pa.id = pasb.agent_id) LEFT JOIN pem.server ps ON (ps.id = pasb.server_id)  WHERE pa.active = true AND ps.active = true
    LOOP
        host_config_text = host_config_text || E'define host {
        host_name                ' || row.description || E'
        address                  ' || row.server || E'
        active_checks_enabled    1
        passive_checks_enabled	 1
        check_command            check-host-alive';

        IF is_max_check_attemp_require THEN
            host_config_text = host_config_text || E'\n        max_check_attempts       10';
        END IF;

        IF icon_image IS NOT NULL THEN
            host_config_text = host_config_text || E'\n        icon_image               ' || icon_image;
        END IF;

        IF icon_image_alt IS NOT NULL THEN
            host_config_text = host_config_text || E'\n        icon_image_alt           ' || icon_image_alt;
        ELSE
            host_config_text = host_config_text || E'\n        icon_image_alt           ' || row.description;
        END IF;

        IF statusmap_image IS NOT NULL THEN
            host_config_text = host_config_text || E'\n        statusmap_image          ' || statusmap_image;
        END IF;

        IF template_name IS NOT NULL THEN
            host_config_text = host_config_text || E'\n        use                      ' || template_name;
        END IF;
        host_config_text = host_config_text ||    E'\n}\n\n';
    END LOOP;

RETURN host_config_text;

END

$BODY$
  LANGUAGE plpgsql;

-- Function to create nagios services.cfg file
CREATE OR REPLACE FUNCTION pem.create_nagios_service_config(template_name text)
  RETURNS text AS
$BODY$

DECLARE
    service_config_text    text := '';
    row                 RECORD;
    service_desc        text;
    host_agent_name        text;
    agent_description        text := '';
    service_name        text := '';

BEGIN
    -- List all the services except agent and global level
    FOR row IN SELECT a.server_id, a.agent_id, s.description, s.server, a.name, a.database_name, a.schema_name, a.package_name, a.object_name FROM pem.server s, pem.alert a WHERE a.server_id = s.id AND s.active = true AND a.enabled = true AND a.submit_to_nagios = true ORDER BY s.description, a.name
    LOOP
	-- Function to create the nagios host name from agent and server id
	SELECT pem.create_nagios_host_name(row.agent_id , row.server_id) INTO agent_description;
	-- Function to create the nagios service/alert name
	SELECT pem.create_nagios_service_name(row.name, row.description, row.database_name, row.schema_name, row.package_name, row.object_name) INTO service_name;

        service_config_text = service_config_text || E'define service {
        host_name                ' || agent_description || E'
        service_description      ' || service_name || E'
        use                      ' || template_name  || E'
        check_command            check_ping!3000.0,80%!5000.0,100%
        check_freshness          0
        active_checks_enabled    0
        passive_checks_enabled   1\n}\n\n';
    END LOOP;

    -- List only agent and global services
    FOR row IN SELECT a.server_id, a.agent_id, ag.description, a.name FROM pem.agent ag, pem.alert a WHERE (a.agent_id = ag.id) AND ag.active = true AND a.enabled = true AND a.submit_to_nagios = true ORDER BY ag.description, a.name
    LOOP
        -- Function to create the nagios service/alert name
	SELECT pem.create_nagios_service_name(row.name) INTO service_name;

        service_config_text = service_config_text || E'define service {
        host_name                ' || row.description || E'
        service_description      ' || service_name || E'
        use                      ' || template_name  || E'
        check_command            check_ping!3000.0,80%!5000.0,100%
        check_freshness          0
        active_checks_enabled    0
        passive_checks_enabled   1\n}\n\n';
    END LOOP;

RETURN service_config_text;

END
$BODY$
  LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION pem.create_passive_service_check_result(
    IN alert_id integer,
    IN template text,
    IN current_value text,
    IN current_state text,
    OUT passive_check_result text)
  RETURNS text AS
$BODY$
DECLARE
    alert_name                            text;
    alert_object_name                    text;
    msg_object_name                        text;
    alert_thresholdvalue                text;
    server_name                            text;
    server_ip                            text;
    server_port                            integer;
    agent_name                            text;
    status_text                            text;
    is_nagios_medium_alert_as_critical    boolean:=false;
    agent_id                             integer;
    server_id                            integer;
    database_name                        text;
    schema_name                          text;
    package_name                         text;
    object_name                          text;
    agent_description                    text;
    service_name                         text;
BEGIN

    -- Get alert, agent, server details
    SELECT
        a.name, a.thresholds,
        s.description, s.server, s.port,
        ag.description, a.agent_id, a.server_id,
        a.database_name, a.schema_name, a.package_name, a.object_name
    INTO
        alert_name, alert_thresholdvalue,
        server_name, server_ip, server_port,
        agent_name, agent_id, server_id, database_name,
        schema_name, package_name, object_name
    FROM
        pem.alert a
        LEFT JOIN pem.server s ON a.server_id = s.id
        LEFT JOIN pem.agent ag ON a.agent_id = ag.id
    WHERE
        a.id = alert_id;

    SELECT value INTO is_nagios_medium_alert_as_critical FROM pem.config WHERE param = 'nagios_medium_alert_as_critical';

	SELECT mail_subject INTO status_text
	FROM pem.get_email_template(template);

    -- Function to create the nagios host name from agent and server id
    SELECT pem.create_nagios_host_name(agent_id , server_id) INTO agent_description;

    CASE WHEN server_name IS NOT NULL THEN
        alert_object_name = server_name || ' ('|| server_ip ||': ' || server_port || ')';
        msg_object_name = alert_object_name;
    WHEN agent_name IS NOT NULL THEN
        alert_object_name = agent_name;
        msg_object_name = alert_object_name;
    -- in case of global alert agent name and server_name are NULL so description from main pem agent has been fetched
    ELSE
        SELECT description INTO alert_object_name FROM pem.agent where id = 1;
        msg_object_name = alert_object_name;
    END CASE;

    -- Replace single "\" with "\\" because regexp_replace escapes backslash
    alert_name = replace(alert_name, E'\\', E'\\\\');
    alert_object_name = replace(alert_object_name, E'\\', E'\\\\');

    status_text = regexp_replace(status_text, '%AlertName%', alert_name, 'g');
    status_text = regexp_replace(status_text, '%ObjectName%', msg_object_name, 'g');
    IF current_state IS NOT NULL THEN
        status_text = regexp_replace(status_text, '%AlertType%', current_state, 'g');
    END IF;
    status_text = status_text || E' (threshold values: ' || alert_thresholdvalue;
        IF current_value IS NOT NULL THEN
        status_text = status_text || E', current value: ' || current_value || ')';
        ELSE
        status_text = status_text || E', current value: UNKNOWN)';
        END IF;

    IF template NOT IN ('Alert Detected','Alert Cleared') THEN
        status_text = status_text || E' (new State: %NewState% ';
        status_text = status_text || E', old State: %OldState%)';
    END IF;

    passive_check_result = E'[';
    passive_check_result = passive_check_result || round(extract('epoch' from now())) || E'] ';
    passive_check_result = passive_check_result || E'PROCESS_SERVICE_CHECK_RESULT;';

    passive_check_result = passive_check_result || agent_description || E';';

    -- Function to create the nagios service/alert name
    SELECT pem.create_nagios_service_name(alert_name, server_name, database_name, schema_name, package_name, object_name) INTO service_name;

    passive_check_result = passive_check_result || service_name || E';';
    IF (current_state = 'HIGH') THEN
        passive_check_result = passive_check_result || E'2;';

    ELSIF (current_state = 'LOW') THEN
        passive_check_result = passive_check_result || E'1;';

    ELSIF (current_state = 'MEDIUM') THEN

        IF(is_nagios_medium_alert_as_critical) THEN
            passive_check_result = passive_check_result || E'2;';
        ELSE
            passive_check_result = passive_check_result || E'1;';
        END IF;

    ELSIF (current_state IS NULL) THEN
        passive_check_result = passive_check_result || E'0;';
    END IF;

    passive_check_result = passive_check_result || status_text;
END $BODY$
  LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION pem.submit_to_nagios(passive_check_result text)
  RETURNS boolean AS $$
DECLARE
	is_nagios_enabled 	boolean:= false;
	is_notify 			boolean:= false;

BEGIN
	SELECT value INTO is_nagios_enabled FROM pem.config WHERE param = 'nagios_enabled';

	IF is_nagios_enabled THEN
		INSERT INTO pem.nagios_spool(message,sent_status) VALUES (passive_check_result,'u');
		NOTIFY NAGIOS_SPOOL;
		return true;
	END IF;

	return false;
END $$ LANGUAGE plpgsql;

-- This is an additional SQL function that will send the current state of all the alerts to Nagios. This enables the user to "prime" Nagios,
-- otherwise alerts will stay in an "Unknown" state until PEM sends a state change (which of course, ideally will never happen).
-- NOTE: This should only be executable by Admins.
CREATE OR REPLACE FUNCTION pem.prime_nagios_passive_alerts(
	)
    RETURNS SETOF boolean
    LANGUAGE 'sql'
    COST 100.0

AS $function$

SELECT
    pem.submit_to_nagios(
        pem.create_passive_service_check_result(
            alert_id::integer,
            template::text,
            current_value::text,
            current_state::text
        )
    )
FROM
(
    SELECT
        a.name,
        a.agent_id,
        a.server_id,
        alert_id,
        CASE WHEN current_state IS NULL THEN
                'Alert Cleared'
        ELSE
                'Alert Detected'
        END AS template,
        current_value,
        current_state
    FROM
        pem.alert a,
        pem.alert_status s
    WHERE
        submit_to_nagios = true AND
        enabled = true AND
        a.id = s.alert_id AND
        CASE WHEN agent_id IS NOT NULL THEN
            (agent_id IN (SELECT id FROM pem.agent WHERE active) = true OR agent_id = 0)
        ELSE
            true
        END AND
        CASE WHEN server_id IS NOT NULL THEN
             (server_id IN (SELECT id FROM pem.server WHERE active) = true)
        ELSE
            true
        END
) AS alerts

$function$;

CREATE OR REPLACE FUNCTION pem.get_servers_with_status(server_state pem.server_agent_state) RETURNS SETOF RECORD
AS $$
DECLARE
	row  RECORD;
	sql  text;
BEGIN

	IF (server_state = 'UP') THEN
		sql =  'SELECT ps.id, ps.description, ps.server, ps.port
				FROM
					pem.avail_servers ps LEFT OUTER JOIN pem.server_heartbeat psh ON (ps.id = psh.server_id),
					pem.agent pa,
					pem.agent_server_binding pasb
				WHERE
					pa.id = pasb.agent_id AND
					ps.id = pasb.server_id AND
					NOT ps.alert_blackout AND
					CASE WHEN psh.agent_id IS NULL THEN FALSE ELSE psh.agent_id = pa.id END AND
					CASE WHEN psh.server_id IS NULL THEN FALSE ELSE psh.last_heartbeat < now() AND psh.last_heartbeat > now() - (pa.heartbeat_tolerance+15)*''1 second''::interval END';
	ELSIF (server_state = 'DOWN') THEN
		sql =  'SELECT ps.id, ps.description, ps.server, ps.port
				FROM
					pem.avail_servers ps LEFT OUTER JOIN pem.server_heartbeat psh ON (ps.id = psh.server_id),
					pem.agent pa LEFT OUTER JOIN pem.agent_heartbeat pah ON (pa.id = pah.agent_id),
					pem.agent_server_binding pasb
				WHERE
					pa.id = pasb.agent_id AND
					ps.id = pasb.server_id AND
					pa.active = TRUE AND
					NOT ps.alert_blackout AND
					CASE WHEN psh.agent_id IS NULL THEN FALSE ELSE psh.agent_id = pa.id END AND
					CASE WHEN pah.agent_id is NULL THEN FALSE ELSE pah.last_heartbeat < now() AND pah.last_heartbeat > now() - (pa.heartbeat_tolerance+15)*''1 second''::interval END AND
					CASE WHEN psh.server_id IS NULL THEN FALSE ELSE psh.last_heartbeat < now() - (pa.heartbeat_tolerance+15)*''1 second''::interval END';
	ELSIF (server_state = 'UNKNOWN') THEN
		sql =  'SELECT ps.id, ps.description, ps.server, ps.port
				FROM
					pem.avail_servers ps LEFT OUTER JOIN pem.server_heartbeat psh ON (ps.id = psh.server_id),
					pem.agent pa LEFT OUTER JOIN pem.agent_heartbeat pah ON (pa.id = pah.agent_id),
					pem.agent_server_binding pasb
				WHERE
					pa.id = pasb.agent_id AND
					ps.id = pasb.server_id AND
					pa.active = TRUE AND
					NOT ps.alert_blackout AND
					((pah.agent_id IS NULL) OR
					(pah.last_heartbeat < now() - (pa.heartbeat_tolerance+15)*''1 second''::interval) OR
					(psh.server_id IS NULL))';
	ELSIF (server_state = 'BLACKEDOUT') THEN
		sql =  'SELECT ps.id, ps.description, ps.server, ps.port
				FROM
					pem.avail_servers ps LEFT OUTER JOIN pem.server_heartbeat psh ON (ps.id = psh.server_id),
					pem.agent pa,
					pem.agent_server_binding pasb
				WHERE
					pa.id = pasb.agent_id AND
					ps.id = pasb.server_id AND
					ps.alert_blackout AND
					CASE WHEN psh.agent_id IS NULL THEN FALSE ELSE psh.agent_id = pa.id END AND
					CASE WHEN psh.server_id IS NULL THEN FALSE ELSE psh.last_heartbeat < now() AND psh.last_heartbeat > now() - (pa.heartbeat_tolerance+15)*''1 second''::interval END';
	END IF;

	FOR row IN EXECUTE sql
	LOOP
		RETURN NEXT row;
	END LOOP;

	RETURN;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION pem.get_agents_with_status(agent_state pem.server_agent_state) RETURNS SETOF RECORD
AS $$
DECLARE
	row  RECORD;
	sql  text;
BEGIN

	IF (agent_state = 'UP') THEN
		sql =  'SELECT pa.id, pa.description
				FROM
					pem.agent pa LEFT OUTER JOIN pem.agent_heartbeat pah ON (pa.id = pah.agent_id)
				WHERE
					pa.active = TRUE AND
					NOT pa.alert_blackout AND
					CASE WHEN pah.agent_id IS NULL THEN FALSE ELSE pah.last_heartbeat < now() AND pah.last_heartbeat > now() - (pa.heartbeat_tolerance+15)*''1 second''::interval END';
	ELSIF (agent_state = 'DOWN') THEN
		sql =  'SELECT pa.id, pa.description
				FROM
					pem.agent pa LEFT OUTER JOIN pem.agent_heartbeat pah ON (pa.id = pah.agent_id)
				WHERE
					pa.active = TRUE AND
					NOT pa.alert_blackout AND
					CASE WHEN pah.agent_id IS NULL THEN FALSE ELSE pah.last_heartbeat < now() - (pa.heartbeat_tolerance+15)*''1 second''::interval END';
	ELSIF (agent_state = 'UNKNOWN') THEN
		sql =  'SELECT pa.id, pa.description
				FROM
					pem.agent pa LEFT OUTER JOIN pem.agent_heartbeat pah ON (pa.id = pah.agent_id)
				WHERE
					pa.active = TRUE AND
					NOT pa.alert_blackout AND
					pah.agent_id IS NULL';
	ELSIF (agent_state = 'BLACKEDOUT') THEN
		sql =  'SELECT pa.id, pa.description
				FROM
					pem.agent pa LEFT OUTER JOIN pem.agent_heartbeat pah ON (pa.id = pah.agent_id)
				WHERE
					pa.active = TRUE AND
					pa.alert_blackout AND
					CASE WHEN pah.agent_id IS NULL THEN FALSE ELSE pah.last_heartbeat < now() AND pah.last_heartbeat > now() - (pa.heartbeat_tolerance+15)*''1 second''::interval END';
	END IF;

	FOR row IN EXECUTE sql
	LOOP
		RETURN NEXT row;
	END LOOP;

	RETURN;
END;
$$ LANGUAGE plpgsql;


-- First argument takes the agent id as integer value
-- Second argument takes the last number of hours users wants to get the data
-- Third argument takes type of error severity e.g. 1 - ERROR , 2- WARNING, 3 - ERROR OR WARNING
CREATE OR REPLACE FUNCTION pem.agent_level_number_errors_warning_logfile (integer, integer, integer)
RETURNS integer AS $$

DECLARE
	total_servers RECORD;
	total_errors integer;
	error_count integer;

BEGIN
	total_errors := 0;
	error_count := 0;

	-- Find one agent is bindning to how many servers and depending on that total count will be calculated
	FOR total_servers IN SELECT DISTINCT server_id FROM pem.agent_server_binding WHERE agent_id = $1 ORDER BY server_id ASC LOOP

		error_count := 0;

		-- If user requested for ERROR count only then below condition will be executed
		IF $3 = 1 THEN
			SELECT COUNT(log_time) INTO error_count FROM pemdata.server_logs WHERE error_severity = 'ERROR' AND server_id = total_servers.server_id  AND log_time > now() - ($2)*'1 hours'::interval;
		END IF;

		-- If user requested for WARNING count only then below condition will be executed
		IF $3 = 2 THEN
			SELECT COUNT(log_time) INTO error_count FROM pemdata.server_logs WHERE error_severity = 'WARNING' AND server_id = total_servers.server_id  AND log_time > now() - ($2)*'1 hours'::interval;
		END IF;

		-- If user requested for WARNING OR ERROR count only then below condition will be executed
		IF $3 = 3 THEN
			SELECT COUNT(log_time) INTO error_count FROM pemdata.server_logs WHERE (error_severity = 'ERROR' OR error_severity = 'WARNING') AND server_id = total_servers.server_id  AND log_time > now() - ($2)*'1 hours'::interval;
		END IF;

		total_errors := total_errors + error_count;
	END LOOP;

	RETURN total_errors;

END;

$$ LANGUAGE plpgsql;

