-- SQL/Protect

-- First argument takes last number of minutes user wants to get the data
-- Second argument takes the server id as integer

CREATE OR REPLACE FUNCTION pem.number_sqlinjection_attacks_detected (integer,integer)
RETURNS integer AS $$

DECLARE
    total_count integer;
    user_requested_count integer;
    total_attacks_detected integer;
    tmp_count integer;
    tmp_days integer;
    attack_count_per_user integer;
    tmp_loop_count integer;
    total_users RECORD;
    last_row_fetched RECORD;
    first_row_fetched RECORD;
    tmp_flag boolean;

BEGIN
    total_count := 0;
    user_requested_count := 0;
    total_attacks_detected := 0;
    tmp_count := 0;
    tmp_days := 1;
    tmp_loop_count := 1;

    FOR total_users IN SELECT DISTINCT username FROM pemhistory.sql_protect WHERE server_id = $2 LOOP

        -- Find the total number of rows for specific user in the table
        SELECT count(*) INTO total_count FROM pemhistory.sql_protect WHERE server_id = $2 AND username = total_users.username;
        -- Find the rows for specific user for user requested last N minutes in the table
        SELECT count(*) INTO user_requested_count FROM pemhistory.sql_protect WHERE server_id = $2 AND username = total_users.username AND recorded_time > now() - ($1)*'1 minutes'::interval;

        attack_count_per_user := 0;
        tmp_flag := false;

        -- If the difference is 1 then there are total two entry in the table and for first row we have directly get the value and count the number of attacks
       IF (total_count - user_requested_count) = 1 THEN

                -- Select the last value from the below query and search for previous until we get the difference
                SELECT superusers, relations, commands, tautology, dml INTO last_row_fetched FROM pemhistory.sql_protect WHERE server_id = $2 AND username = total_users.username AND recorded_time > now() - ($1)*'1 minutes'::interval ORDER BY recorded_time DESC LIMIT 1;


                SELECT superusers, relations, commands, tautology, dml INTO first_row_fetched FROM pemhistory.sql_protect WHERE server_id = $2 AND username = total_users.username ORDER BY recorded_time ASC LIMIT 1;

                attack_count_per_user := (last_row_fetched.superusers - first_row_fetched.superusers) + (last_row_fetched.relations - first_row_fetched.relations) + (last_row_fetched.commands - first_row_fetched.commands) + (last_row_fetched.tautology - first_row_fetched.tautology) + (last_row_fetched.dml - first_row_fetched.dml);

                tmp_flag := true;
	END IF;

	-- If total user count and user requested count for specific time is zero that means all the entry contains in the user requested time slot and no entry in the time slot before that so we have to take the decision based on the user requested count is one then dirctly add the attacks and for more then one take the difference between the rows.
	IF (total_count - user_requested_count) = 0 THEN
		IF user_requested_count = 1 THEN
			SELECT SUM(superusers + relations + commands + tautology + dml) INTO attack_count_per_user FROM pemhistory.sql_protect WHERE server_id = $2 AND pemhistory.sql_protect.username = total_users.username AND recorded_time > now() - ($1)*'1 minutes'::interval;
			tmp_flag := true;

		ELSE
			WHILE (tmp_loop_count < user_requested_count) LOOP

				SELECT superusers, relations, commands, tautology, dml INTO last_row_fetched FROM pemhistory.sql_protect WHERE server_id = $2 AND pemhistory.sql_protect.username = total_users.username AND recorded_time > now() - ($1)*'1 minutes'::interval ORDER BY recorded_time DESC LIMIT 1 OFFSET (tmp_loop_count - 1);

				tmp_loop_count := tmp_loop_count + 1;

				SELECT superusers, relations, commands, tautology, dml INTO first_row_fetched FROM pemhistory.sql_protect WHERE server_id = $2 AND pemhistory.sql_protect.username = total_users.username AND recorded_time > now() - ($1)*'1 minutes'::interval ORDER BY recorded_time DESC LIMIT 1 OFFSET (tmp_loop_count - 1);

				attack_count_per_user := attack_count_per_user + (last_row_fetched.superusers - first_row_fetched.superusers) + (last_row_fetched.relations - first_row_fetched.relations) + (last_row_fetched.commands - first_row_fetched.commands) + (last_row_fetched.tautology - first_row_fetched.tautology) + (last_row_fetched.dml - first_row_fetched.dml);

			END LOOP;

			attack_count_per_user := attack_count_per_user + first_row_fetched.superusers + first_row_fetched.relations + first_row_fetched.commands + first_row_fetched.tautology + first_row_fetched.dml;

			tmp_flag := true;

		END IF;
	END IF;

	-- There are no entry in the table for that user so don't do anything
	IF (total_count - user_requested_count) = total_count THEN
		NULL;

        ELSE
                IF tmp_flag = false THEN

                -- Select the last row value from the below query
                SELECT superusers, relations, commands, tautology, dml INTO last_row_fetched FROM pemhistory.sql_protect WHERE server_id = $2 AND pemhistory.sql_protect.username = total_users.username AND recorded_time > now() - ($1)*'1 minutes'::interval ORDER BY recorded_time DESC LIMIT 1;

                -- Loop until we get the previous entry for specific user to take the difference to calculate the number of SQL injection attacks
                LOOP
                    tmp_days := tmp_days + 1;
                    SELECT count(*) INTO tmp_count FROM pemhistory.sql_protect WHERE server_id = $2 AND pemhistory.sql_protect.username = total_users.username AND recorded_time > now() - (tmp_days)*'1 days'::interval;

                    IF tmp_count > user_requested_count THEN
                        SELECT superusers, relations, commands, tautology, dml INTO first_row_fetched FROM pemhistory.sql_protect WHERE server_id = $2 AND pemhistory.sql_protect.username = total_users.username AND recorded_time > now() - (tmp_days)*'1 days'::interval ORDER BY recorded_time DESC LIMIT 1 OFFSET user_requested_count;
                        EXIT;
                   ELSE
                        tmp_days := tmp_days + 1;
                    END IF;

                END LOOP;

                attack_count_per_user := (last_row_fetched.superusers - first_row_fetched.superusers) + (last_row_fetched.relations - first_row_fetched.relations) + (last_row_fetched.commands - first_row_fetched.commands) + (last_row_fetched.tautology - first_row_fetched.tautology) + (last_row_fetched.dml - first_row_fetched.dml);

                END IF;

        END IF;

        -- Calculate the total number of SQL injection attacks for each user
        total_attacks_detected := total_attacks_detected + attack_count_per_user;

    END LOOP;

    RETURN total_attacks_detected;

END;
$$ LANGUAGE plpgsql;


CREATE OR REPLACE FUNCTION pem.number_sqlinjection_attacks_detected_by_username (integer,TEXT,integer)
RETURNS integer AS $$

DECLARE
    total_count integer;
    user_requested_count integer;
    tmp_count integer;
    tmp_days integer;
    attack_count_per_user integer;
    tmp_loop_count integer;
    last_row_fetched RECORD;
    first_row_fetched RECORD;
    tmp_flag boolean;

BEGIN
    total_count := 0;
    user_requested_count := 0;
    tmp_count := 0;
    tmp_days := 1;
    tmp_loop_count := 1;

    -- Find the total number of rows for specific user in the table
    SELECT count(*) INTO total_count FROM pemhistory.sql_protect WHERE server_id = $3 AND username = $2;
    -- Find the rows for specific user for user requested last N minutes in the table
    SELECT count(*) INTO user_requested_count FROM pemhistory.sql_protect WHERE server_id = $3 AND username = $2 AND recorded_time > now() - ($1)*'1 minutes'::interval;

    attack_count_per_user := 0;
    tmp_flag := false;

    -- If the difference is 1 then there are total two entry in the table and for first row we have directly get the value and count the number of attacks
    IF (total_count - user_requested_count) = 1 THEN

            -- Select the last value from the below query and search for previous until we get the difference
            SELECT superusers, relations, commands, tautology, dml INTO last_row_fetched FROM pemhistory.sql_protect WHERE server_id = $3 AND username = $2 AND recorded_time > now() - ($1)*'1 minutes'::interval ORDER BY recorded_time DESC LIMIT 1;


            SELECT superusers, relations, commands, tautology, dml INTO first_row_fetched FROM pemhistory.sql_protect WHERE server_id = $3 AND username = $2 ORDER BY recorded_time ASC LIMIT 1;

            attack_count_per_user := (last_row_fetched.superusers - first_row_fetched.superusers) + (last_row_fetched.relations - first_row_fetched.relations) + (last_row_fetched.commands - first_row_fetched.commands) + (last_row_fetched.tautology - first_row_fetched.tautology) + (last_row_fetched.dml - first_row_fetched.dml);

            tmp_flag := true;
    END IF;

    -- If total user count and user requested count for specific time is zero that means all the entry contains in the user requested time slot and no entry in the time slot before that so we have to take the decision based on the user requested count is one then dirctly add the attacks and for more then one take the difference between the rows.
    IF (total_count - user_requested_count) = 0 THEN
	IF user_requested_count = 1 THEN
		SELECT SUM(superusers + relations + commands + tautology + dml) INTO attack_count_per_user FROM pemhistory.sql_protect WHERE server_id = $3 AND pemhistory.sql_protect.username = $2 AND recorded_time > now() - ($1)*'1 minutes'::interval;
		tmp_flag := true;

	ELSE
		WHILE (tmp_loop_count < user_requested_count) LOOP

			SELECT superusers, relations, commands, tautology, dml INTO last_row_fetched FROM pemhistory.sql_protect WHERE server_id = $3 AND pemhistory.sql_protect.username = $2 AND recorded_time > now() - ($1)*'1 minutes'::interval ORDER BY recorded_time DESC LIMIT 1 OFFSET (tmp_loop_count - 1);

			tmp_loop_count := tmp_loop_count + 1;

			SELECT superusers, relations, commands, tautology, dml INTO first_row_fetched FROM pemhistory.sql_protect WHERE server_id = $3 AND pemhistory.sql_protect.username = $2 AND recorded_time > now() - ($1)*'1 minutes'::interval ORDER BY recorded_time DESC LIMIT 1 OFFSET (tmp_loop_count - 1);

			attack_count_per_user := attack_count_per_user + (last_row_fetched.superusers - first_row_fetched.superusers) + (last_row_fetched.relations - first_row_fetched.relations) + (last_row_fetched.commands - first_row_fetched.commands) + (last_row_fetched.tautology - first_row_fetched.tautology) + (last_row_fetched.dml - first_row_fetched.dml);

		END LOOP;

		attack_count_per_user := attack_count_per_user + first_row_fetched.superusers + first_row_fetched.relations + first_row_fetched.commands + first_row_fetched.tautology + first_row_fetched.dml;

		tmp_flag := true;

	END IF;
    END IF;

    -- There are no entry in the table for that user so don't do anything
    IF (total_count - user_requested_count) = total_count THEN
	NULL;

    ELSE
		IF tmp_flag = false THEN

		-- Select the last row value from the below query
		SELECT superusers, relations, commands, tautology, dml INTO last_row_fetched FROM pemhistory.sql_protect WHERE server_id = $3 AND pemhistory.sql_protect.username = $2 AND recorded_time > now() - ($1)*'1 minutes'::interval ORDER BY recorded_time DESC LIMIT 1;

		-- Loop until we get the previous entry for specific user to take the difference to calculate the number of SQL injection attacks
		LOOP
			tmp_days := tmp_days + 1;
			SELECT count(*) INTO tmp_count FROM pemhistory.sql_protect WHERE server_id = $3 AND pemhistory.sql_protect.username = $2 AND recorded_time > now() - (tmp_days)*'1 days'::interval;

			IF tmp_count > user_requested_count THEN
				SELECT superusers, relations, commands, tautology, dml INTO first_row_fetched FROM pemhistory.sql_protect WHERE server_id = $3 AND pemhistory.sql_protect.username = $2 AND recorded_time > now() - (tmp_days)*'1 days'::interval ORDER BY recorded_time DESC LIMIT 1 OFFSET user_requested_count;
				EXIT;
			ELSE
				tmp_days := tmp_days + 1;
			END IF;

		END LOOP;

		attack_count_per_user := (last_row_fetched.superusers - first_row_fetched.superusers) + (last_row_fetched.relations - first_row_fetched.relations) + (last_row_fetched.commands - first_row_fetched.commands) + (last_row_fetched.tautology - first_row_fetched.tautology) + (last_row_fetched.dml - first_row_fetched.dml);

		END IF;

    END IF;

    RETURN attack_count_per_user;

END;
$$ LANGUAGE plpgsql;

-- First argument takes last number of minutes user wants to get the data
-- Second argument takes the server id as integer
-- Third argument takes the database name

CREATE OR REPLACE FUNCTION pem.sqlinjection_attacks_detected_on_database(integer,integer,TEXT)
RETURNS integer AS $$

DECLARE
    total_count integer;
    user_requested_count integer;
    total_attacks_detected integer;
    tmp_count integer;
    tmp_days integer;
    attack_count_per_user integer;
    tmp_loop_count integer;
    total_users RECORD;
    last_row_fetched RECORD;
    first_row_fetched RECORD;
    tmp_flag boolean;

BEGIN
    total_count := 0;
    user_requested_count := 0;
    total_attacks_detected := 0;
    tmp_count := 0;
    tmp_days := 1;
    tmp_loop_count := 1;

    FOR total_users IN SELECT DISTINCT username FROM pemhistory.sql_protect WHERE server_id = $2 AND database_name = $3 LOOP

        -- Find the total number of rows for specific user in the table
        SELECT count(*) INTO total_count FROM pemhistory.sql_protect WHERE server_id = $2 AND database_name = $3 AND username = total_users.username;
        -- Find the rows for specific user for user requested last N minutes in the table
        SELECT count(*) INTO user_requested_count FROM pemhistory.sql_protect WHERE server_id = $2 AND database_name = $3 AND username = total_users.username AND recorded_time > now() - ($1)*'1 minutes'::interval;

        attack_count_per_user := 0;
        tmp_flag := false;

        -- If the difference is 1 then there are total two entry in the table and for first row we have directly get the value and count the number of attacks
       IF (total_count - user_requested_count) = 1 THEN

                -- Select the last value from the below query and search for previous until we get the difference
                SELECT superusers, relations, commands, tautology, dml INTO last_row_fetched FROM pemhistory.sql_protect WHERE server_id = $2 AND database_name = $3 AND username = total_users.username AND recorded_time > now() - ($1)*'1 minutes'::interval ORDER BY recorded_time DESC LIMIT 1;


                SELECT superusers, relations, commands, tautology, dml INTO first_row_fetched FROM pemhistory.sql_protect WHERE server_id = $2 AND database_name = $3 AND username = total_users.username ORDER BY recorded_time ASC LIMIT 1;

                attack_count_per_user := (last_row_fetched.superusers - first_row_fetched.superusers) + (last_row_fetched.relations - first_row_fetched.relations) + (last_row_fetched.commands - first_row_fetched.commands) + (last_row_fetched.tautology - first_row_fetched.tautology) + (last_row_fetched.dml - first_row_fetched.dml);

                tmp_flag := true;
	END IF;

	-- If total user count and user requested count for specific time is zero that means all the entry contains in the user requested time slot and no entry in the time slot before that so we have to take the decision based on the user requested count is one then dirctly add the attacks and for more then one take the difference between the rows.
	IF (total_count - user_requested_count) = 0 THEN
		IF user_requested_count = 1 THEN
			SELECT SUM(superusers + relations + commands + tautology + dml) INTO attack_count_per_user FROM pemhistory.sql_protect WHERE server_id = $2 AND database_name = $3 AND pemhistory.sql_protect.username = total_users.username AND recorded_time > now() - ($1)*'1 minutes'::interval;
			tmp_flag := true;

		ELSE
			WHILE (tmp_loop_count < user_requested_count) LOOP

				SELECT superusers, relations, commands, tautology, dml INTO last_row_fetched FROM pemhistory.sql_protect WHERE server_id = $2 AND database_name = $3 AND pemhistory.sql_protect.username = total_users.username AND recorded_time > now() - ($1)*'1 minutes'::interval ORDER BY recorded_time DESC LIMIT 1 OFFSET (tmp_loop_count - 1);

				tmp_loop_count := tmp_loop_count + 1;

				SELECT superusers, relations, commands, tautology, dml INTO first_row_fetched FROM pemhistory.sql_protect WHERE server_id = $2 AND database_name = $3 AND pemhistory.sql_protect.username = total_users.username AND recorded_time > now() - ($1)*'1 minutes'::interval ORDER BY recorded_time DESC LIMIT 1 OFFSET (tmp_loop_count - 1);

				attack_count_per_user := attack_count_per_user + (last_row_fetched.superusers - first_row_fetched.superusers) + (last_row_fetched.relations - first_row_fetched.relations) + (last_row_fetched.commands - first_row_fetched.commands) + (last_row_fetched.tautology - first_row_fetched.tautology) + (last_row_fetched.dml - first_row_fetched.dml);

			END LOOP;

			attack_count_per_user := attack_count_per_user + first_row_fetched.superusers + first_row_fetched.relations + first_row_fetched.commands + first_row_fetched.tautology + first_row_fetched.dml;

			tmp_flag := true;

		END IF;
	END IF;

	-- There are no entry in the table for that user so don't do anything
	IF (total_count - user_requested_count) = total_count THEN
		NULL;

        ELSE
                IF tmp_flag = false THEN

                -- Select the last row value from the below query
                SELECT superusers, relations, commands, tautology, dml INTO last_row_fetched FROM pemhistory.sql_protect WHERE server_id = $2 AND database_name = $3 AND pemhistory.sql_protect.username = total_users.username AND recorded_time > now() - ($1)*'1 minutes'::interval ORDER BY recorded_time DESC LIMIT 1;

                -- Loop until we get the previous entry for specific user to take the difference to calculate the number of SQL injection attacks
                LOOP
                    tmp_days := tmp_days + 1;
                    SELECT count(*) INTO tmp_count FROM pemhistory.sql_protect WHERE server_id = $2 AND database_name = $3 AND pemhistory.sql_protect.username = total_users.username AND recorded_time > now() - (tmp_days)*'1 days'::interval;

                    IF tmp_count > user_requested_count THEN
                        SELECT superusers, relations, commands, tautology, dml INTO first_row_fetched FROM pemhistory.sql_protect WHERE server_id = $2 AND database_name = $3 AND pemhistory.sql_protect.username = total_users.username AND recorded_time > now() - (tmp_days)*'1 days'::interval ORDER BY recorded_time DESC LIMIT 1 OFFSET user_requested_count;
                        EXIT;
                   ELSE
                        tmp_days := tmp_days + 1;
                    END IF;

                END LOOP;

                attack_count_per_user := (last_row_fetched.superusers - first_row_fetched.superusers) + (last_row_fetched.relations - first_row_fetched.relations) + (last_row_fetched.commands - first_row_fetched.commands) + (last_row_fetched.tautology - first_row_fetched.tautology) + (last_row_fetched.dml - first_row_fetched.dml);

                END IF;

        END IF;

        -- Calculate the total number of SQL injection attacks for each user
        total_attacks_detected := total_attacks_detected + attack_count_per_user;

    END LOOP;

    RETURN total_attacks_detected;

END;
$$ LANGUAGE plpgsql;


CREATE OR REPLACE FUNCTION pem.sqlinjection_attacks_detected_by_username_on_database(integer,TEXT,integer,TEXT)
RETURNS integer AS $$

DECLARE
    total_count integer;
    user_requested_count integer;
    tmp_count integer;
    tmp_days integer;
    attack_count_per_user integer;
    tmp_loop_count integer;
    last_row_fetched RECORD;
    first_row_fetched RECORD;
    tmp_flag boolean;

BEGIN
    total_count := 0;
    user_requested_count := 0;
    tmp_count := 0;
    tmp_days := 1;
    tmp_loop_count := 1;

    -- Find the total number of rows for specific user in the table
    SELECT count(*) INTO total_count FROM pemhistory.sql_protect WHERE server_id = $3 AND username = $2 AND database_name = $4;
    -- Find the rows for specific user for user requested last N minutes in the table
    SELECT count(*) INTO user_requested_count FROM pemhistory.sql_protect WHERE server_id = $3 AND username = $2 AND database_name = $4 AND recorded_time > now() - ($1)*'1 minutes'::interval;

    attack_count_per_user := 0;
    tmp_flag := false;

    -- If the difference is 1 then there are total two entry in the table and for first row we have directly get the value and count the number of attacks
    IF (total_count - user_requested_count) = 1 THEN

            -- Select the last value from the below query and search for previous until we get the difference
            SELECT superusers, relations, commands, tautology, dml INTO last_row_fetched FROM pemhistory.sql_protect WHERE server_id = $3 AND username = $2 AND database_name = $4 AND recorded_time > now() - ($1)*'1 minutes'::interval ORDER BY recorded_time DESC LIMIT 1;


            SELECT superusers, relations, commands, tautology, dml INTO first_row_fetched FROM pemhistory.sql_protect WHERE server_id = $3 AND username = $2 AND database_name = $4 ORDER BY recorded_time ASC LIMIT 1;

            attack_count_per_user := (last_row_fetched.superusers - first_row_fetched.superusers) + (last_row_fetched.relations - first_row_fetched.relations) + (last_row_fetched.commands - first_row_fetched.commands) + (last_row_fetched.tautology - first_row_fetched.tautology) + (last_row_fetched.dml - first_row_fetched.dml);

            tmp_flag := true;
    END IF;

    -- If total user count and user requested count for specific time is zero that means all the entry contains in the user requested time slot and no entry in the time slot before that so we have to take the decision based on the user requested count is one then dirctly add the attacks and for more then one take the difference between the rows.
    IF (total_count - user_requested_count) = 0 THEN
	IF user_requested_count = 1 THEN
		SELECT SUM(superusers + relations + commands + tautology + dml) INTO attack_count_per_user FROM pemhistory.sql_protect WHERE server_id = $3 AND database_name = $4 AND pemhistory.sql_protect.username = $2 AND recorded_time > now() - ($1)*'1 minutes'::interval;
		tmp_flag := true;

	ELSE
		WHILE (tmp_loop_count < user_requested_count) LOOP

			SELECT superusers, relations, commands, tautology, dml INTO last_row_fetched FROM pemhistory.sql_protect WHERE server_id = $3 AND database_name = $4 AND pemhistory.sql_protect.username = $2 AND recorded_time > now() - ($1)*'1 minutes'::interval ORDER BY recorded_time DESC LIMIT 1 OFFSET (tmp_loop_count - 1);

			tmp_loop_count := tmp_loop_count + 1;

			SELECT superusers, relations, commands, tautology, dml INTO first_row_fetched FROM pemhistory.sql_protect WHERE server_id = $3 AND database_name = $4 AND pemhistory.sql_protect.username = $2 AND recorded_time > now() - ($1)*'1 minutes'::interval ORDER BY recorded_time DESC LIMIT 1 OFFSET (tmp_loop_count - 1);

			attack_count_per_user := attack_count_per_user + (last_row_fetched.superusers - first_row_fetched.superusers) + (last_row_fetched.relations - first_row_fetched.relations) + (last_row_fetched.commands - first_row_fetched.commands) + (last_row_fetched.tautology - first_row_fetched.tautology) + (last_row_fetched.dml - first_row_fetched.dml);

		END LOOP;

		attack_count_per_user := attack_count_per_user + first_row_fetched.superusers + first_row_fetched.relations + first_row_fetched.commands + first_row_fetched.tautology + first_row_fetched.dml;

		tmp_flag := true;

	END IF;
    END IF;

    -- There are no entry in the table for that user so don't do anything
    IF (total_count - user_requested_count) = total_count THEN
	NULL;

    ELSE
		IF tmp_flag = false THEN

		-- Select the last row value from the below query
		SELECT superusers, relations, commands, tautology, dml INTO last_row_fetched FROM pemhistory.sql_protect WHERE server_id = $3 AND database_name = $4 AND pemhistory.sql_protect.username = $2 AND recorded_time > now() - ($1)*'1 minutes'::interval ORDER BY recorded_time DESC LIMIT 1;

		-- Loop until we get the previous entry for specific user to take the difference to calculate the number of SQL injection attacks
		LOOP
			tmp_days := tmp_days + 1;
			SELECT count(*) INTO tmp_count FROM pemhistory.sql_protect WHERE server_id = $3 AND database_name = $4 AND pemhistory.sql_protect.username = $2 AND recorded_time > now() - (tmp_days)*'1 days'::interval;

			IF tmp_count > user_requested_count THEN
				SELECT superusers, relations, commands, tautology, dml INTO first_row_fetched FROM pemhistory.sql_protect WHERE server_id = $3 AND database_name = $4 AND pemhistory.sql_protect.username = $2 AND recorded_time > now() - (tmp_days)*'1 days'::interval ORDER BY recorded_time DESC LIMIT 1 OFFSET user_requested_count;
				EXIT;
			ELSE
				tmp_days := tmp_days + 1;
			END IF;

		END LOOP;

		attack_count_per_user := (last_row_fetched.superusers - first_row_fetched.superusers) + (last_row_fetched.relations - first_row_fetched.relations) + (last_row_fetched.commands - first_row_fetched.commands) + (last_row_fetched.tautology - first_row_fetched.tautology) + (last_row_fetched.dml - first_row_fetched.dml);

		END IF;

    END IF;

    RETURN attack_count_per_user;

END;
$$ LANGUAGE plpgsql;

-- Types of utilisation defined for tuning wizard
CREATE TYPE pem.tuning_server_util AS ENUM(
	'UTILISATION_DEDICATED', -- dedicated utilisation
	'UTILISATION_MIXED',     -- mixed level utilisation
	'UTILISATION_DEVELOPER'  -- developer level utilisation
);

COMMENT ON TYPE pem.tuning_server_util IS 'Types of utilisation defined for tuning wizard';

-- Types of workload profile defined for tuning wizard
CREATE TYPE pem.tuning_workload_profile AS ENUM(
	'WORKLOAD_OLTP',  -- OLTP type workload
	'WORKLOAD_MIXED', -- mixed type workload
	'WORKLOAD_DW'     -- datawarehouse type workload
);

COMMENT ON TYPE pem.tuning_workload_profile IS 'Types of workload profile defined for tuning wizard';

-- This function executes the calculates the appropriate value for the parameters to
-- be tuned for servers with workload profile of type OLTP
-- Parameters:
--    tune_server_id - server id of the server to tune
--    utilisation - utilisation enum to specify of server
--    total_ram - total ram on the machine
--    shared_memory - shared memory on the machine
--    is_windows - if machine is windows or not
CREATE OR REPLACE FUNCTION pem.server_tuning_oltp (tune_server_id int, utilisation pem.tuning_server_util, total_ram numeric, shared_memory numeric, is_windows boolean)
RETURNS TABLE (tuned_parameter text, tuned_value text, orig_value text)
AS $$
DECLARE
	server_max_conn int := 0;
	server_max_locks_per_xact int := 0;
	server_max_prepared_xacts int := 0;
	server_version int := 0;
	converted_value int := 0;
	shared_mem numeric(1000,0) := shared_memory;
	work_mem_factor decimal := 0.008;
	maint_work_mem_factor decimal := 0.08;
	server_chkpnt_cmpl_trgt decimal := 0.5;
	work_mem bigint := 0;
	maint_work_mem bigint := 0;
	shared_buffers bigint := 0;
	wal_buffers bigint := 0;
	eff_cache_size bigint := 0;
	is_checkpoint_segment_allowed boolean := TRUE;
	units int := 0;
BEGIN
	SELECT setting FROM pemdata.settings WHERE server_id = tune_server_id AND name='max_connections' INTO server_max_conn;
	SELECT setting FROM pemdata.settings WHERE server_id = tune_server_id AND name='max_locks_per_transaction' INTO server_max_locks_per_xact;
	SELECT setting FROM pemdata.settings WHERE server_id = tune_server_id AND name='max_prepared_transactions' INTO server_max_prepared_xacts;
	SELECT setting FROM pemdata.settings WHERE server_id = tune_server_id AND name='checkpoint_completion_target' INTO server_chkpnt_cmpl_trgt;
	SELECT server_version_id FROM pemdata.server_info WHERE server_id = tune_server_id INTO server_version;

	-- calculate amount of memory utilized for max_connections and subtract it from shared memory
	-- to calculate work_mem and maintainance_work_mem
	shared_mem := shared_mem - (server_max_conn * 620 * server_max_locks_per_xact);
	shared_mem := shared_mem - (server_max_prepared_xacts * 820 * server_max_locks_per_xact);

	-- calculate work_mem
	work_mem := round(shared_mem * work_mem_factor);
	work_mem := round(work_mem / (1024)::decimal);

	-- work_mem needs to be at least 1MB
	IF work_mem < 1024 THEN
		work_mem := 1024;
	END IF;

	work_mem := round(work_mem / (1024)::decimal);

	tuned_parameter := 'work_mem';
	tuned_value := work_mem || 'MB';
	orig_value := pem.server_tuning_original_value(tune_server_id, 'work_mem');
	RETURN NEXT;

	shared_mem := shared_mem - (work_mem * 1024 *1024);

	-- calculate maintainence_work_mem
	maint_work_mem := round(shared_mem * maint_work_mem_factor);
	maint_work_mem := round(maint_work_mem / (1024 * 1024)::decimal);

	-- maintainence_work_mem needs to be at max 256MB
	IF maint_work_mem > 256 THEN
		maint_work_mem := 256;
	END IF;

	-- maintainence_work_mem needs to be at least 16MB
	IF maint_work_mem < 16 THEN
		maint_work_mem := 16;
	END IF;

	tuned_parameter := 'maintenance_work_mem';
	tuned_value := maint_work_mem || 'MB';
	orig_value := pem.server_tuning_original_value(tune_server_id, 'maintenance_work_mem');
	RETURN NEXT;

	-- calculate shared_buffers
	IF utilisation = 'UTILISATION_DEVELOPER' THEN
		-- set it default to 32MB
		shared_buffers := 32 * 1024 * 1024;
	ELSIF utilisation = 'UTILISATION_MIXED' THEN
		IF is_windows THEN
			-- set it default to 128MB
			shared_buffers := 128 * 1024 * 1024;
		ELSE
			-- set 25% of total RAM
			shared_buffers := round(total_ram * (0.25)::decimal);
		END IF;
	ELSE
		IF is_windows THEN
			-- set it default to 256MB
			shared_buffers := 256 * 1024 * 1024;
		ELSE
			-- set 40% of total RAM
			shared_buffers := round(total_ram * (0.40)::decimal);
		END IF;
	END IF;

	shared_buffers := round(shared_buffers / (1024*1024)::decimal);

	-- shared_buffers needs to be at max 8GB
	IF shared_buffers > 8192 THEN
		shared_buffers := 8192;
	END IF;

	-- shared_buffers needs to be at least 2MB
	IF shared_buffers < 2 THEN
		shared_buffers := 2;
	END IF;

	tuned_parameter := 'shared_buffers';
	tuned_value := shared_buffers || 'MB';
	orig_value := pem.server_tuning_original_value(tune_server_id, 'shared_buffers');
	RETURN NEXT;

	-- calculate wal_buffers
	shared_buffers := shared_buffers * 1024 * 1024;
	wal_buffers := round(shared_buffers / (8)::decimal);

	-- wal_buffers needs to be at max 16MB
	IF wal_buffers > 16777216 THEN
		wal_buffers := 16777216;
	END IF;

	-- wal_buffers needs to be at least 64KB
	IF wal_buffers < 65536 THEN
		wal_buffers := 65536;
	END IF;

	tuned_parameter := 'wal_buffers';
	IF (wal_buffers / (1048576)::decimal) > 1.00 THEN
		wal_buffers := round(wal_buffers / (1048576)::decimal);
		tuned_value := wal_buffers || 'MB';
	ELSE
		wal_buffers := round(wal_buffers / (1024)::decimal);
		tuned_value := wal_buffers || 'kB';
	END IF;
	orig_value := pem.server_tuning_original_value(tune_server_id, 'wal_buffers');
	RETURN NEXT;

	-- calculate effective_cache_size
	IF utilisation = 'UTILISATION_DEDICATED' THEN
		eff_cache_size := round(total_ram * (0.75)::decimal);
	ELSIF utilisation = 'UTILISATION_MIXED' THEN
		eff_cache_size := round(total_ram * (0.5)::decimal);
	ELSE
		eff_cache_size := round(total_ram * (0.25)::decimal);
	END IF;

	eff_cache_size := round(eff_cache_size / (1048576)::decimal);

	tuned_parameter := 'effective_cache_size';
	tuned_value := eff_cache_size || 'MB';
	orig_value := pem.server_tuning_original_value(tune_server_id, 'effective_cache_size');
	RETURN NEXT;

	-- calculate random_page_cost
	tuned_parameter := 'random_page_cost';
	IF utilisation = 'UTILISATION_DEDICATED' THEN
		tuned_value := '2';
	ELSIF utilisation = 'UTILISATION_MIXED' THEN
		tuned_value := '2.5';
	ELSE
		tuned_value := '3';
	END IF;
	orig_value := pem.server_tuning_original_value(tune_server_id, 'random_page_cost');
	RETURN NEXT;

	-- check if checkpoint_segement is allowed or not depending upon the server version
	IF server_version >= 20905 THEN
		is_checkpoint_segment_allowed = false;
	ELSIF server_version >=10905 and server_version < 20000 THEN
		is_checkpoint_segment_allowed = false;
	ELSE
		is_checkpoint_segment_allowed = true;
	END IF;

	-- calculate checkpoint_segments for server_version < 9.5 and max_wal_size for server_version >= 9.5
	IF utilisation = 'UTILISATION_DEDICATED' THEN
		tuned_value := '32';
	ELSIF utilisation = 'UTILISATION_MIXED' THEN
		tuned_value := '16';
	ELSE
		tuned_value := '6';
	END IF;

	IF is_checkpoint_segment_allowed = TRUE THEN
		tuned_parameter := 'checkpoint_segments';
		orig_value := pem.server_tuning_original_value(tune_server_id, 'checkpoint_segments');
	ELSE
		tuned_parameter := 'max_wal_size';
		-- Reference: http://www.postgresql.org/message-id/E1YPwGB-0006vL-8V@gemulon.postgresql.org
		-- max_wal_size has been calculated using below formula:
		-- max_wal_size = ((2 + checkpoint_completion_target) * checkpoint_segments + 1)*wal_size
		-- where checkpoint_completion_target = Specifies the target of checkpoint completion, as a fraction of total time between checkpoints
		-- default value is 0.5
		-- checkpoint_segments = no of checkpoint decided depending upon utilization. default value is 6
		-- wal_size = size of wal file = 16 MB
		tuned_value = ((((server_chkpnt_cmpl_trgt)::decimal + (2)::decimal) * (tuned_value)::decimal) + (1)::integer) * (16)::integer;
		IF ((tuned_value)::decimal / (1024)::decimal) >= 1.00 THEN
			tuned_value := round((tuned_value)::decimal / (1024)::decimal) || 'GB';
		ELSE
			tuned_value := round((tuned_value)::decimal) || 'MB';
		END IF;
		SELECT COALESCE(SUBSTRING(setting from '[0-9]+'), '1')::decimal, COALESCE(SUBSTRING(unit from '[0-9]+'), '1')::decimal FROM pemdata.settings WHERE server_id = tune_server_id AND name = 'max_wal_size' INTO orig_value, units;
		converted_value := round((orig_value)::decimal * (units)::decimal);
	        IF (converted_value / (1024)::decimal) >= 1.00 THEN
			orig_value := round((converted_value)::decimal / (1024)::decimal) || 'GB';
		ELSE
			orig_value := round((converted_value)::decimal) || 'MB';
		END IF;
	END IF;
	RETURN NEXT;

	-- add min_wal_size for server_version < 9.5 and max_wal_size for server_version >= 9.5
	-- min_wal_size has the fixed size of 80 MB
	IF is_checkpoint_segment_allowed = FALSE THEN
		tuned_parameter := 'min_wal_size';
		tuned_value = '80MB';
		SELECT COALESCE(SUBSTRING(setting from '[0-9]+'), '1')::decimal, COALESCE(SUBSTRING(unit from '[0-9]+'), '1')::decimal FROM pemdata.settings WHERE server_id = tune_server_id AND name = 'min_wal_size' INTO orig_value, units;
		converted_value := round((orig_value)::decimal * (units)::decimal);
		IF (converted_value / (1024)::decimal) >= 1.00 THEN
			orig_value := round((converted_value)::decimal / (1024)::decimal) || 'GB';
		ELSE
			orig_value := round((converted_value)::decimal) || 'MB';
		END IF;
		RETURN NEXT;
	END IF;
	RETURN;
END;
$$ LANGUAGE plpgsql;

-- This function executes the calculates the appropriate value for the parameters to
-- be tuned for servers with workload profile of type Mixed
-- Parameters:
--    tune_server_id - server id of the server to tune
--    utilisation - utilisation enum to specify of server
--    total_ram - total ram on the machine
--    shared_memory - shared memory on the machine
--    is_windows - if machine is windows or not
CREATE OR REPLACE FUNCTION pem.server_tuning_mixed (tune_server_id int, utilisation pem.tuning_server_util, total_ram numeric, shared_memory numeric, is_windows boolean)
RETURNS TABLE (tuned_parameter text, tuned_value text, orig_value text)
AS $$
DECLARE
	server_max_conn int := 0;
	server_max_locks_per_xact int := 0;
	server_max_prepared_xacts int := 0;
	server_version int := 0;
	converted_value int := 0;
	shared_mem numeric(1000,0) := shared_memory;
	work_mem_factor decimal := 0.012;
	maint_work_mem_factor decimal := 0.1;
	server_chkpnt_cmpl_trgt decimal := 0.5;
	work_mem bigint := 0;
	maint_work_mem bigint := 0;
	shared_buffers bigint := 0;
	wal_buffers bigint := 0;
	eff_cache_size bigint := 0;
	is_checkpoint_segment_allowed boolean := TRUE;
	units int := 0;
BEGIN
	SELECT setting FROM pemdata.settings WHERE server_id = tune_server_id AND name='max_connections' INTO server_max_conn;
	SELECT setting FROM pemdata.settings WHERE server_id = tune_server_id AND name='max_locks_per_transaction' INTO server_max_locks_per_xact;
	SELECT setting FROM pemdata.settings WHERE server_id = tune_server_id AND name='max_prepared_transactions' INTO server_max_prepared_xacts;
	SELECT setting FROM pemdata.settings WHERE server_id = tune_server_id AND name='checkpoint_completion_target' INTO server_chkpnt_cmpl_trgt;
	SELECT server_version_id FROM pemdata.server_info WHERE server_id = tune_server_id INTO server_version;

	-- calculate amount of memory utilized for max_connections and subtract it from shared memory
	-- to calculate work_mem and maintainance_work_mem
	shared_mem := shared_mem - (server_max_conn * 620 * server_max_locks_per_xact);
	shared_mem := shared_mem - (server_max_prepared_xacts * 820 * server_max_locks_per_xact);

	-- calculate work_mem
	work_mem := round(shared_mem * work_mem_factor);
	work_mem := round(work_mem / (1024)::decimal);

	-- work_mem needs to be at least 1MB
	IF work_mem < 1024 THEN
		work_mem := 1024;
	END IF;

	work_mem := round(work_mem / (1024)::decimal);

	tuned_parameter := 'work_mem';
	tuned_value := work_mem || 'MB';
	orig_value := pem.server_tuning_original_value(tune_server_id, 'work_mem');
	RETURN NEXT;

	shared_mem := shared_mem - (work_mem * 1024 *1024);

	-- calculate maintainence_work_mem
	maint_work_mem := round(shared_mem * maint_work_mem_factor);
	maint_work_mem := round(maint_work_mem / (1024 * 1024)::decimal);

	-- maintainence_work_mem needs to be at max 256MB
	IF maint_work_mem > 256 THEN
		maint_work_mem := 256;
	END IF;

	-- maintainence_work_mem needs to be at least 16MB
	IF maint_work_mem < 16 THEN
		maint_work_mem := 16;
	END IF;

	tuned_parameter := 'maintenance_work_mem';
	tuned_value := maint_work_mem || 'MB';
	orig_value := pem.server_tuning_original_value(tune_server_id, 'maintenance_work_mem');
	RETURN NEXT;

	-- calculate shared_buffers
	IF utilisation = 'UTILISATION_DEVELOPER' THEN
		-- set it default to 32MB
		shared_buffers := 32 * 1024 * 1024;
	ELSIF utilisation = 'UTILISATION_MIXED' THEN
		IF is_windows THEN
			-- set it default to 128MB
			shared_buffers := 128 * 1024 * 1024;
		ELSE
			-- set 25% of total RAM
			shared_buffers := round(total_ram * (0.25)::decimal);
		END IF;
	ELSE
		IF is_windows THEN
			-- set it default to 256MB
			shared_buffers := 256 * 1024 * 1024;
		ELSE
			-- set 40% of total RAM
			shared_buffers := round(total_ram * (0.40)::decimal);
		END IF;
	END IF;

	shared_buffers := round(shared_buffers / (1024*1024)::decimal);

	-- shared_buffers needs to be at max 8GB
	IF shared_buffers > 8192 THEN
		shared_buffers := 8192;
	END IF;

	-- shared_buffers needs to be at least 2MB
	IF shared_buffers < 2 THEN
		shared_buffers := 2;
	END IF;

	tuned_parameter := 'shared_buffers';
	tuned_value := shared_buffers || 'MB';
	orig_value := pem.server_tuning_original_value(tune_server_id, 'shared_buffers');
	RETURN NEXT;

	-- calculate wal_buffers
	shared_buffers := shared_buffers * 1024 * 1024;
	wal_buffers := round(shared_buffers / (16)::decimal);

	-- wal_buffers needs to be at max 16MB
	IF wal_buffers > 16777216 THEN
		wal_buffers := 16777216;
	END IF;

	-- wal_buffers needs to be at least 64KB
	IF wal_buffers < 65536 THEN
		wal_buffers := 65536;
	END IF;

	tuned_parameter := 'wal_buffers';
	IF (wal_buffers / (1048576)::decimal) > 1.00 THEN
		wal_buffers := round(wal_buffers / (1048576)::decimal);
		tuned_value := wal_buffers || 'MB';
	ELSE
		wal_buffers := round(wal_buffers / (1024)::decimal);
		tuned_value := wal_buffers || 'kB';
	END IF;
	orig_value := pem.server_tuning_original_value(tune_server_id, 'wal_buffers');
	RETURN NEXT;

	-- calculate effective_cache_size
	IF utilisation = 'UTILISATION_DEDICATED' THEN
		eff_cache_size := round(total_ram * (0.75)::decimal);
	ELSIF utilisation = 'UTILISATION_MIXED' THEN
		eff_cache_size := round(total_ram * (0.5)::decimal);
	ELSE
		eff_cache_size := round(total_ram * (0.25)::decimal);
	END IF;

	eff_cache_size := round(eff_cache_size / (1048576)::decimal);

	tuned_parameter := 'effective_cache_size';
	tuned_value := eff_cache_size || 'MB';
	orig_value := pem.server_tuning_original_value(tune_server_id, 'effective_cache_size');
	RETURN NEXT;

	-- calculate random_page_cost
	tuned_parameter := 'random_page_cost';
	IF utilisation = 'UTILISATION_DEDICATED' THEN
		tuned_value := '2';
	ELSIF utilisation = 'UTILISATION_MIXED' THEN
		tuned_value := '2.5';
	ELSE
		tuned_value := '3';
	END IF;
	orig_value := pem.server_tuning_original_value(tune_server_id, 'random_page_cost');
	RETURN NEXT;

		-- check if checkpoint_segement is allowed or not depending upon the server version
	IF server_version >= 20905 THEN
		is_checkpoint_segment_allowed = false;
	ELSIF server_version >=10905 and server_version < 20000 THEN
		is_checkpoint_segment_allowed = false;
	ELSE
		is_checkpoint_segment_allowed = true;
	END IF;

	-- calculate checkpoint_segments for server_version < 9.5 and max_wal_size for server_version >= 9.5
	IF utilisation = 'UTILISATION_DEDICATED' THEN
		tuned_value := '48';
	ELSIF utilisation = 'UTILISATION_MIXED' THEN
		tuned_value := '24';
	ELSE
		tuned_value := '6';
	END IF;

	IF is_checkpoint_segment_allowed = TRUE THEN
		tuned_parameter := 'checkpoint_segments';
		orig_value := pem.server_tuning_original_value(tune_server_id, 'checkpoint_segments');
	ELSE
		tuned_parameter := 'max_wal_size';
		-- Reference: http://www.postgresql.org/message-id/E1YPwGB-0006vL-8V@gemulon.postgresql.org
		-- max_wal_size has been calculated using below formula:
		-- max_wal_size = ((2 + checkpoint_completion_target) * checkpoint_segments + 1)*wal_size
		-- where checkpoint_completion_target = Specifies the target of checkpoint completion, as a fraction of total time between checkpoints
		-- default value is 0.5
		-- checkpoint_segments = no of checkpoint decided depending upon utilization. default value is 6
		-- wal_size = size of wal file = 16 MB
		tuned_value = ((((server_chkpnt_cmpl_trgt)::decimal + (2)::decimal) * (tuned_value)::decimal) + (1)::integer) * (16)::integer;
		IF ((tuned_value)::decimal / (1024)::decimal) >= 1.00 THEN
			tuned_value := round((tuned_value)::decimal / (1024)::decimal) || 'GB';
		ELSE
			tuned_value := round((tuned_value)::decimal) || 'MB';
		END IF;
		SELECT COALESCE(SUBSTRING(setting from '[0-9]+'), '1')::decimal, COALESCE(SUBSTRING(unit from '[0-9]+'), '1')::decimal FROM pemdata.settings WHERE server_id = tune_server_id AND name = 'max_wal_size' INTO orig_value, units;
		converted_value := round((orig_value)::decimal * (units)::decimal);
		IF (converted_value / (1024)::decimal) >= 1.00 THEN
			orig_value := round((converted_value)::decimal / (1024)::decimal) || 'GB';
		ELSE
			orig_value := round((converted_value)::decimal) || 'MB';
		END IF;
	END IF;
	RETURN NEXT;

	-- add min_wal_size for server_version < 9.5 and max_wal_size for server_version >= 9.5
	-- min_wal_size has the fixed size of 80 MB
	IF is_checkpoint_segment_allowed = FALSE THEN
		tuned_parameter := 'min_wal_size';
		tuned_value = '80MB';
		SELECT COALESCE(SUBSTRING(setting from '[0-9]+'), '1')::decimal, COALESCE(SUBSTRING(unit from '[0-9]+'), '1')::decimal FROM pemdata.settings WHERE server_id = tune_server_id AND name = 'min_wal_size' INTO orig_value, units;
		converted_value := round((orig_value)::decimal * (units)::decimal);
		IF (converted_value / (1024)::decimal) >= 1.00 THEN
			orig_value := round((converted_value)::decimal / (1024)::decimal) || 'GB';
		ELSE
			orig_value := round((converted_value)::decimal) || 'MB';
		END IF;
		RETURN NEXT;
	END IF;
	RETURN;
END
$$ LANGUAGE plpgsql;

-- This function executes the calculates the appropriate value for the parameters to
-- be tuned for servers with workload profile of type Datawarehouse
-- Parameters:
--    tune_server_id - server id of the server to tune
--    utilisation - utilisation enum to specify of server
--    total_ram - total ram on the machine
--    shared_memory - shared memory on the machine
--    is_windows - if machine is windows or not
CREATE OR REPLACE FUNCTION pem.server_tuning_dw (tune_server_id int, utilisation pem.tuning_server_util, total_ram numeric, shared_memory numeric, is_windows boolean)
RETURNS TABLE (tuned_parameter text, tuned_value text, orig_value text)
AS $$
DECLARE
	server_max_conn int := 0;
	server_max_locks_per_xact int := 0;
	server_max_prepared_xacts int := 0;
	server_version int := 0;
	converted_value int := 0;
	shared_mem numeric(1000,0) := shared_memory;
	work_mem_factor decimal := 0.020;
	maint_work_mem_factor decimal := 0.2;
	server_chkpnt_cmpl_trgt decimal := 0.5;
	work_mem bigint := 0;
	maint_work_mem bigint := 0;
	shared_buffers bigint := 0;
	wal_buffers bigint := 0;
	eff_cache_size bigint := 0;
	is_checkpoint_segment_allowed boolean := TRUE;
	units int := 0;
BEGIN
	SELECT setting FROM pemdata.settings WHERE server_id = tune_server_id AND name='max_connections' INTO server_max_conn;
	SELECT setting FROM pemdata.settings WHERE server_id = tune_server_id AND name='max_locks_per_transaction' INTO server_max_locks_per_xact;
	SELECT setting FROM pemdata.settings WHERE server_id = tune_server_id AND name='max_prepared_transactions' INTO server_max_prepared_xacts;
	SELECT setting FROM pemdata.settings WHERE server_id = tune_server_id AND name='checkpoint_completion_target' INTO server_chkpnt_cmpl_trgt;
	SELECT server_version_id FROM pemdata.server_info WHERE server_id = tune_server_id INTO server_version;

	-- calculate amount of memory utilized for max_connections and subtract it from shared memory
	-- to calculate work_mem and maintainance_work_mem
	shared_mem := shared_mem - (server_max_conn * 620 * server_max_locks_per_xact);
	shared_mem := shared_mem - (server_max_prepared_xacts * 820 * server_max_locks_per_xact);

	-- calculate work_mem
	work_mem := round(shared_mem * work_mem_factor);
	work_mem := round(work_mem / (1024)::decimal);

	-- work_mem needs to be at least 1MB
	IF work_mem < 1024 THEN
		work_mem := 1024;
	END IF;

	work_mem := round(work_mem / (1024)::decimal);

	tuned_parameter := 'work_mem';
	tuned_value := work_mem || 'MB';
	orig_value := pem.server_tuning_original_value(tune_server_id, 'work_mem');
	RETURN NEXT;

	shared_mem := shared_mem - (work_mem * 1024 *1024);

	-- calculate maintainence_work_mem
	maint_work_mem := round(shared_mem * maint_work_mem_factor);
	maint_work_mem := round(maint_work_mem / (1024 * 1024)::decimal);

	-- maintainence_work_mem needs to be at max 256MB
	IF maint_work_mem > 256 THEN
		maint_work_mem := 256;
	END IF;

	-- maintainence_work_mem needs to be at least 16MB
	IF maint_work_mem < 16 THEN
		maint_work_mem := 16;
	END IF;

	tuned_parameter := 'maintenance_work_mem';
	tuned_value := maint_work_mem || 'MB';
	orig_value := pem.server_tuning_original_value(tune_server_id, 'maintenance_work_mem');
	RETURN NEXT;

	-- calculate shared_buffers
	IF utilisation = 'UTILISATION_DEVELOPER' THEN
		-- set it default to 32MB
		shared_buffers := 32 * 1024 * 1024;
	ELSIF utilisation = 'UTILISATION_MIXED' THEN
		IF is_windows THEN
			-- set it default to 128MB
			shared_buffers := 128 * 1024 * 1024;
		ELSE
			-- set 25% of total RAM
			shared_buffers := round(total_ram * (0.25)::decimal);
		END IF;
	ELSE
		IF is_windows THEN
			-- set it default to 256MB
			shared_buffers := 256 * 1024 * 1024;
		ELSE
			-- set 40% of total RAM
			shared_buffers := round(total_ram * (0.40)::decimal);
		END IF;
	END IF;

	shared_buffers := round(shared_buffers / (1024*1024)::decimal);

	-- shared_buffers needs to be at max 8GB
	IF shared_buffers > 8192 THEN
		shared_buffers := 8192;
	END IF;

	-- shared_buffers needs to be at least 2MB
	IF shared_buffers < 2 THEN
		shared_buffers := 2;
	END IF;

	tuned_parameter := 'shared_buffers';
	tuned_value := shared_buffers || 'MB';
	orig_value := pem.server_tuning_original_value(tune_server_id, 'shared_buffers');
	RETURN NEXT;

	-- calculate wal_buffers
	shared_buffers := shared_buffers * 1024 * 1024;
	wal_buffers := round(shared_buffers / (32)::decimal);

	-- wal_buffers needs to be at max 16MB
	IF wal_buffers > 16777216 THEN
		wal_buffers := 16777216;
	END IF;

	-- wal_buffers needs to be at least 64KB
	IF wal_buffers < 65536 THEN
		wal_buffers := 65536;
	END IF;

	tuned_parameter := 'wal_buffers';
	IF (wal_buffers / (1048576)::decimal) > 1.00 THEN
		wal_buffers := round(wal_buffers / (1048576)::decimal);
		tuned_value := wal_buffers || 'MB';
	ELSE
		wal_buffers := round(wal_buffers / (1024)::decimal);
		tuned_value := wal_buffers || 'kB';
	END IF;
	orig_value := pem.server_tuning_original_value(tune_server_id, 'wal_buffers');
	RETURN NEXT;

	-- calculate effective_cache_size
	IF utilisation = 'UTILISATION_DEDICATED' THEN
		eff_cache_size := round(total_ram * (0.75)::decimal);
	ELSIF utilisation = 'UTILISATION_MIXED' THEN
		eff_cache_size := round(total_ram * (0.5)::decimal);
	ELSE
		eff_cache_size := round(total_ram * (0.25)::decimal);
	END IF;

	eff_cache_size := round(eff_cache_size / (1048576)::decimal);

	tuned_parameter := 'effective_cache_size';
	tuned_value := eff_cache_size || 'MB';
	orig_value := pem.server_tuning_original_value(tune_server_id, 'effective_cache_size');
	RETURN NEXT;

	-- calculate random_page_cost
	tuned_parameter := 'random_page_cost';
	IF utilisation = 'UTILISATION_DEDICATED' THEN
		tuned_value := '2';
	ELSIF utilisation = 'UTILISATION_MIXED' THEN
		tuned_value := '2.5';
	ELSE
		tuned_value := '3';
	END IF;
	orig_value := pem.server_tuning_original_value(tune_server_id, 'random_page_cost');
	RETURN NEXT;

		-- check if checkpoint_segement is allowed or not depending upon the server version
	IF server_version >= 20905 THEN
		is_checkpoint_segment_allowed = false;
	ELSIF server_version >=10905 and server_version < 20000 THEN
		is_checkpoint_segment_allowed = false;
	ELSE
		is_checkpoint_segment_allowed = true;
	END IF;

	-- calculate checkpoint_segments for server_version < 9.5 and max_wal_size for server_version >= 9.5
	IF utilisation = 'UTILISATION_DEDICATED' THEN
		tuned_value := '64';
	ELSIF utilisation = 'UTILISATION_MIXED' THEN
		tuned_value := '32';
	ELSE
		tuned_value := '6';
	END IF;

	IF is_checkpoint_segment_allowed = TRUE THEN
		tuned_parameter := 'checkpoint_segments';
		orig_value := pem.server_tuning_original_value(tune_server_id, 'checkpoint_segments');
	ELSE
		tuned_parameter := 'max_wal_size';
		-- Reference: http://www.postgresql.org/message-id/E1YPwGB-0006vL-8V@gemulon.postgresql.org
		-- max_wal_size has been calculated using below formula:
		-- max_wal_size = ((2 + checkpoint_completion_target) * checkpoint_segments + 1)*wal_size
		-- where checkpoint_completion_target = Specifies the target of checkpoint completion, as a fraction of total time between checkpoints
		-- default value is 0.5
		-- checkpoint_segments = no of checkpoint decided depending upon utilization. default value is 6
		-- wal_size = size of wal file = 16 MB
		tuned_value = ((((server_chkpnt_cmpl_trgt)::decimal + (2)::decimal) * (tuned_value)::decimal) + (1)::integer) * (16)::integer;
		IF ((tuned_value)::decimal / (1024)::decimal) >= 1.00 THEN
			tuned_value := round((tuned_value)::decimal / (1024)::decimal) || 'GB';
		ELSE
			tuned_value := round((tuned_value)::decimal) || 'MB';
		END IF;
		SELECT COALESCE(SUBSTRING(setting from '[0-9]+'), '1')::decimal, COALESCE(SUBSTRING(unit from '[0-9]+'), '1')::decimal FROM pemdata.settings WHERE server_id = tune_server_id AND name = 'max_wal_size' INTO orig_value, units;
		converted_value := round((orig_value)::decimal * (units)::decimal);
		IF (converted_value / (1024)::decimal) >= 1.00 THEN
			orig_value := round((converted_value)::decimal / (1024)::decimal) || 'GB';
		ELSE
			orig_value := round((converted_value)::decimal) || 'MB';
		END IF;
	END IF;
	RETURN NEXT;

	-- add min_wal_size for server_version < 9.5 and max_wal_size for server_version >= 9.5
	-- min_wal_size has the fixed size of 80 MB
	IF is_checkpoint_segment_allowed = FALSE THEN
		tuned_parameter := 'min_wal_size';
		tuned_value = '80MB';
		SELECT COALESCE(SUBSTRING(setting from '[0-9]+'), '1')::decimal, COALESCE(SUBSTRING(unit from '[0-9]+'), '1')::decimal FROM pemdata.settings WHERE server_id = tune_server_id AND name = 'min_wal_size' INTO orig_value, units;
		converted_value := round((orig_value)::decimal * (units)::decimal);
		IF (converted_value / (1024)::decimal) >= 1.00 THEN
			orig_value := round((converted_value)::decimal / (1024)::decimal) || 'GB';
		ELSE
			orig_value := round((converted_value)::decimal) || 'MB';
		END IF;
		RETURN NEXT;
	END IF;
	RETURN;
END
$$ LANGUAGE plpgsql;
-- This function provides recommendation for tuning a given server based on the server utilization
-- and workload profile as selected by the user in the Tuning Wizard dialog. This function reads
-- system parameters like total RAM and shared memory and then suggests tuned values for some parameters
-- Parameters:
--    tune_server_id - server id of the server to tune
--    utilisation - utilisation enum to specify of server
--    profile - workload profile of the server instance
CREATE OR REPLACE FUNCTION pem.server_tuning (tune_server_id int, utilisation pem.tuning_server_util, profile pem.tuning_workload_profile)
RETURNS TABLE (tuned_server_id int, tuned_parameter text, tuned_value text, orig_value text)
AS $$
DECLARE
	bound_agent_id int := 0;
	server_count int := 0;
	total_ram_bytea numeric(1000,0) := 0;
	shared_memory_bytea numeric(1000,0) := 0;
	is_windows boolean := false;
	util_percentage int := 0;
BEGIN
	SELECT agent_id FROM pem.agent_server_binding WHERE server_id = tune_server_id INTO bound_agent_id;
	SELECT count(asb.server_id) AS scount FROM pem.agent_server_binding asb, pem.avail_servers acs WHERE asb.server_id = acs.id AND agent_id = bound_agent_id AND acs.is_remote_monitoring = false INTO server_count;
	SELECT total_ram_memory_mb::numeric(1000,0), sys_shared_memory_mb::numeric(1000,0) FROM pemdata.memory_usage WHERE agent_id = bound_agent_id INTO total_ram_bytea, shared_memory_bytea;
	SELECT 'windows' = ANY(agent_capability_list) INTO is_windows FROM pem.agent WHERE id = bound_agent_id;

	IF utilisation = 'UTILISATION_DEDICATED' THEN
		util_percentage := 100;
	ELSIF utilisation = 'UTILISATION_MIXED' THEN
		util_percentage := 66;
	ELSE
		util_percentage := 33;
	END IF;

	total_ram_bytea := total_ram_bytea * 1024 * 1024;
	shared_memory_bytea := shared_memory_bytea * 1024 * 1024;

	-- divide the total ram and system shared buffer size by the no. of postgres
	-- instances installed on the same machine to avoid over allocation of memory
	-- and resources to the postgres instance being tuned currently
	IF server_count > 0 THEN
		total_ram_bytea := total_ram_bytea / server_count;
		shared_memory_bytea := shared_memory_bytea / server_count;
	END IF;

	-- If SHMMAX > physical memory, we'll use physical memory as the max of SHMMAX.
	-- We don't want to end-up over allocating memory.
	IF total_ram_bytea < shared_memory_bytea THEN
		shared_memory_bytea := total_ram_bytea;
	END IF;

	-- The maximum we'll ever use is 2/3 of system-wide shared memory.
	shared_memory_bytea := round(shared_memory_bytea * (0.66)::decimal);

	-- Calculate the amount of memory we'll use based on the user's defined
	-- percentage for tuning.
	shared_memory_bytea := round(shared_memory_bytea * (util_percentage * 0.01)::decimal);

	IF profile = 'WORKLOAD_OLTP' THEN
		RETURN QUERY EXECUTE 'SELECT $1::int AS tuned_server_id, tuned_parameter, tuned_value, orig_value FROM ' ||
			'pem.server_tuning_oltp($1::int, $2::pem.tuning_server_util, $3::bigint, $4::bigint, $5::boolean)'
			USING tune_server_id, utilisation, total_ram_bytea, shared_memory_bytea, is_windows;
	ELSIF profile = 'WORKLOAD_MIXED' THEN
		RETURN QUERY EXECUTE 'SELECT $1::int AS tuned_server_id, tuned_parameter, tuned_value, orig_value FROM ' ||
			'pem.server_tuning_mixed($1::int, $2::pem.tuning_server_util, $3::bigint, $4::bigint, $5::boolean)'
			USING tune_server_id, utilisation, total_ram_bytea, shared_memory_bytea, is_windows;
	ELSE
		RETURN QUERY EXECUTE 'SELECT $1::int AS tuned_server_id, tuned_parameter, tuned_value, orig_value FROM ' ||
			'pem.server_tuning_dw($1::int, $2::pem.tuning_server_util, $3::bigint, $4::bigint, $5::boolean)'
			USING tune_server_id, utilisation, total_ram_bytea, shared_memory_bytea, is_windows;
	END IF;
END
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION pem.server_tuning_original_value(tuned_server_id int, param_name text)
RETURNS TEXT
AS $$
DECLARE
	param_value text := '';
	orig_val decimal := 0;
	param_unit int := 1;
	unit_val text := '';
BEGIN
	SELECT setting::decimal, unit, COALESCE(SUBSTRING(unit from '[0-9]+'), '1')::int FROM pemdata.settings WHERE server_id = tuned_server_id AND name = param_name INTO orig_val, unit_val, param_unit;

	IF (unit_val IS NOT NULL) AND (unit_val != '') THEN
		orig_val = orig_val * param_unit;
		IF orig_val < 1024 THEN
			param_value = orig_val::text || 'kB';
		ELSE
			param_value = round(orig_val/1024)::text || 'MB';
		END IF;
	ELSE
		param_value = orig_val::text;
	END IF;

	RETURN param_value;
END
$$ LANGUAGE plpgsql;

--
-- Streaming Replication Functions
--

-- Function to convert the hexadecimal value to decimal value
-- Parameter 1 - hexadecimal value
CREATE OR REPLACE FUNCTION pem.hex_to_bigint(TEXT) RETURNS bigint AS $$
DECLARE
        result BIGINT;
BEGIN
        result := 0;

        EXECUTE 'SELECT CAST(X'|| quote_nullable($1) ||' AS BIGINT)' INTO result;

        RETURN result;
END;

$$
LANGUAGE plpgsql;


-- Function to give lag bytes if any of the replica lag behind the primary in streaming replication
-- parameter 1 - User given bytes in MB to generate alert
-- parameter 2 - server id
-- parameter 3 - 1- write location, 2- flush location, 3 - replay location
CREATE OR REPLACE FUNCTION pem.number_replication_lag_bytes(integer, integer, integer)
RETURNS bigint AS '
    SELECT
        count(*) as cnt
    FROM
        pemdata.streaming_replication
    WHERE
        server_id = $2 AND
        CASE $3
        WHEN 1 THEN floor(sent_location - write_location)/(1024*1024) > CAST($1 As BIGINT)
        WHEN 2 THEN floor(sent_location - flush_location)/(1024*1024) > CAST($1 As BIGINT)
        WHEN 3 THEN floor(sent_location - replay_location)/(1024*1024) > CAST($1 As BIGINT)
        ELSE false
        END
' LANGUAGE 'sql';

-- Function to check if user given host is lag behind the primary or not
-- Parameter 1 - hostname
-- Parameter 2 - server id
-- Parameter 3 - 1 - write_location, 2 - flush_location, 3 - replay_location
CREATE OR REPLACE FUNCTION pem.replication_lag_bytes_by_hostname(TEXT,integer,integer)
RETURNS bigint AS $$
DECLARE
        xlog_sent_location BIGINT;
        xlog_write_location BIGINT;
        xlog_flush_location BIGINT;
        xlog_replay_location BIGINT;
        user_given_bytes integer;
        xlog_lag_bytes BIGINT;

BEGIN
        xlog_sent_location := 0;
        xlog_write_location := 0;
        xlog_flush_location := 0;
        xlog_replay_location := 0;
        xlog_lag_bytes := 0;

        -- fetch the sent location that is sent by the primary to the replica server
        SELECT sent_location INTO xlog_sent_location FROM pemdata.streaming_replication WHERE client_addr = $1 AND server_id = $2;

      IF $3 = 1 THEN

                -- fetch xlog location for write transaction by replica server
                SELECT write_location INTO xlog_write_location FROM pemdata.streaming_replication WHERE client_addr = $1 AND server_id = $2;

                xlog_lag_bytes := (xlog_sent_location - xlog_write_location);

        END IF;

        IF $3 = 2 THEN

                -- fetch xlog location for flush transaction by replica server
                SELECT flush_location INTO xlog_flush_location FROM pemdata.streaming_replication WHERE client_addr = $1 AND server_id = $2;

                xlog_lag_bytes := (xlog_sent_location - xlog_flush_location);

        END IF;

       IF $3 = 3 THEN

                -- fetch xlog location for replay transaction by replica server
                SELECT replay_location INTO xlog_replay_location FROM pemdata.streaming_replication WHERE client_addr = $1 AND server_id = $2;

                xlog_lag_bytes := (xlog_sent_location - xlog_replay_location);

        END IF;

	RETURN floor(((xlog_lag_bytes/1024)/1024));

END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION pem.streaming_replication_lag_info(integer, integer)
RETURNS text AS
$SQL$
	SELECT array_to_string(array_agg(sr.host_info || ', ' || sr.lag_info), '\n') FROM (
		SELECT
					(ROW_NUMBER() OVER (ORDER BY client_addr, client_port)::text || 'Host: ' || client_addr || ':' || client_port::text) AS host_info,
			CASE $2
			WHEN 1 THEN 'Write Lag (MB): ' || ROUND((sent_location - write_location)/(1024*1024), 2)::text
			WHEN 2 THEN 'Flush Lag (MB): ' || ROUND((sent_location - flush_location)/(1024*1024), 2)::text
			WHEN 3 THEN 'Flush Lag (MB): ' || ROUND((sent_location - replay_location)/(1024*1024), 2)::text
			ELSE '??'
			END AS lag_info
		FROM pemdata.streaming_replication WHERE server_id = $1
		) sr;
$SQL$ LANGUAGE 'sql';

