-- Check all the alert-templates have the Probe dependency list
DO $$
DECLARE
	n int;
BEGIN
	n := (SELECT COUNT(*)
			FROM (SELECT DISTINCT unnest(probe_dependency_list) AS a
					FROM pem.alert_template) AS v
			WHERE v.a NOT IN (SELECT internal_name FROM pem.probe));

	IF(n <> 0) THEN
		RAISE WARNING 'Some probe names in alert descriptions do not exist in pem.probe table.';
	END IF;

	IF((SELECT COUNT(*) FROM pem.alert_template)
		<> (SELECT COUNT(*) FROM pem.alert_template
			WHERE probe_dependency_list != '{}'))
	THEN
		RAISE WARNING 'Not all alert templates have a dependency list defined.';
	END IF;
END;
$$;

CREATE OR REPLACE FUNCTION pem.pretty_size(size bigint)
  RETURNS text AS $$
DECLARE
  pretty_size text;
BEGIN
  RETURN CASE
			WHEN size >= 1024*1024 THEN
				 (size::float/(1024*1024))::numeric(30,2) || 'TB '
			WHEN size >= 1024 THEN
				 (size::float/1024)::numeric(30,2) || 'GB '
			ELSE
				size || 'MB '
		  END;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION pem.json_escape(text)
  RETURNS text AS $$
SELECT replace(replace($1, E'\\', E'\\\\'), E'"', E'\\"')
$$ LANGUAGE sql IMMUTABLE;
COMMENT ON FUNCTION pem.json_escape(text) IS 'Escapes a string for inclusion in a JSON document';

