FROM
    ((SELECT
        -1::integer as lvl,
        (SELECT (value||'' ''||unit)::interval FROM pem.config WHERE param = ''dash_replication_pagelag_span'') as span,
        (SELECT max_points FROM pem.metrices_chart WHERE cid = $1::integer) as points
    )
    UNION ALL
