    d.database_name AS "Database",
    d.numbackends AS "Connections",
    d.xact_commit AS "TX Committed",
    d.xact_rollback AS "TX Rolled Back",
    d.blks_hit AS "Blocks Hit",
    d.blks_read AS "Blocks Read",
    d.tup_fetched AS "Tuples Fetched",
    d.tup_fetched AS "Tuples Returned",
    d.tup_inserted AS "Tuples Inserted",
    d.tup_updated AS "Tuples Updated",
    d.tup_deleted AS "Tuples Deleted"
  FROM
    pemdata.database_statistics d
    JOIN pemdata.oc_database o ON (d.server_id = o.server_id AND d.database_name = o.database_name)
    LEFT JOIN restricted_dbs r ON (d.server_id = r.id)
  WHERE
    o.connections_allowed = TRUE AND
    d.server_id = %(server_id)s::int4 AND (
      %(show_system_objects)s::boolean OR (
        CASE WHEN d.database_name != '''' THEN
          d.database_name NOT IN (''template0'', ''template1'')
        ELSE TRUE END
      )
    )
    AND (r.dbs IS NULL OR (d.database_name = ANY(r.dbs)))
  ORDER BY 3', true, '{database_statistics, oc_database}'),
  (62, 'P', 'table_session_workload', true, '{session_info}'),
  (63, 'Q', E'
  WITH restricted_dbs AS (
    SELECT s.id, pem.db_escaped_string_to_array(COALESCE(o.database_restriction, oa.database_restriction)) AS dbs
  FROM
    pem.server s
    LEFT OUTER JOIN pg_catalog.pg_roles owner ON (owner.oid = s.owner)
    LEFT OUTER JOIN pem.server_options o ON (s.id = o.server_id AND o.pem_user = current_user)
    LEFT OUTER JOIN pem.server_options oa ON (
      o.server_id IS NULL AND s.id = oa.server_id
      AND (owner.rolname = oa.pem_user OR (owner.rolname IS NULL AND oa.pem_user IS NULL))
    )
  )
  SELECT
     pli.procpid AS "Session Id",
     psi.usename AS "User Name",
     (psi.client_addr || $$:$$ || psi.client_port) as "Source",
     pli.database_name AS "Database Name",
     CASE pli.lockgranted WHEN $$f$$ THEN $$Yes$$ ELSE $$No$$ END AS "Blocked",
     CASE WHEN pli.lockgranted = $$f$$ THEN
       (SELECT string_agg(b.procpid::text, '', '')
       FROM pemdata.lock_info b
       WHERE b.objid = pli.objid AND
         b.objsubid IS NOT DISTINCT FROM pli.objsubid AND
         b.objsubsubid IS NOT DISTINCT FROM pli.objsubsubid AND
         b.lockgranted = $$t$$)
       ELSE NULL END AS "Blocked By",
     pli.locktype AS "Lock Type",
     pli.objid AS "Object Id",
     pli.lockmode AS "Mode",
     cast(date_trunc($$second$$,psi.xact_start) AS timestamp) AS "Transaction Start"
  FROM
     pemdata.lock_info pli JOIN
     pemdata.session_info psi ON ( pli.procpid = psi.procpid and pli.server_id = psi.server_id )
     LEFT OUTER JOIN restricted_dbs r ON ( pli.server_id = r.id )
  WHERE
    pli.server_id = %(server_id)s::int4
    AND (
        %(show_system_objects)s::boolean OR (
          CASE WHEN pli.database_name != '''' THEN
            pli.database_name NOT IN (''template0'', ''template1'')
          ELSE TRUE
          END
        )
    ) AND (r.dbs IS NULL OR (pli.database_name = ANY(r.dbs)))
  ORDER BY 3', true, '{lock_info, session_info}'),
  (64, 'Q', E'
  SELECT
    wait_name AS "Wait Name",
    SUM(wait_count) AS "Total Wait Counts"
  FROM
    pemdata.session_waits
  WHERE
    server_id = %(server_id)s::int4 AND
    dbname = %(database)s::text
  GROUP BY wait_name
  ORDER BY "Total Wait Counts" DESC
  LIMIT 5', false, '{session_waits}'),
  (66, 'Q', E'
  SELECT
    wait_name AS "Wait Name",
    SUM(total_wait_time)*1000 AS "Total Wait Time"
  FROM
    pemdata.session_waits
  WHERE
    server_id = %(server_id)s::int4 AND
    dbname = %(database)s:text
  GROUP BY wait_name
  ORDER BY "Total Wait Time" DESC
  LIMIT 5', false, '{session_waits}'),
  (65, 'Q', E'
  SELECT
    usename AS "User",
    wait_name AS "Wait Name",
    wait_count AS "Wait Count",
    (total_wait_time*1000)::numeric(30, 2) AS "Time (ms)", (
      SELECT
        CASE WHEN SUM(total_wait_time) = 0 THEN 0
        ELSE (psw.total_wait_time * 100 / SUM(total_wait_time))
        END
      FROM pemdata.session_waits
      WHERE server_id = %(server_id)s::int4 AND dbname = %(database)s::text
    )::numeric(5,2) AS "Wait Time (%%)"
  FROM
    pemdata.session_waits psw
  WHERE
    server_id = %(server_id)s::int4 AND dbname = %(database)s::text', false, '{session_waits}'),
  (67, 'Q', E'
  WITH restricted_dbs AS (
    SELECT
      s.id, pem.db_escaped_string_to_array(COALESCE(o.database_restriction, oa.database_restriction)) AS dbs
    FROM pem.server s
      LEFT OUTER JOIN pg_catalog.pg_roles owner ON (owner.oid = s.owner)
      LEFT OUTER JOIN pem.server_options o ON (s.id = o.server_id AND o.pem_user = current_user)
      LEFT OUTER JOIN pem.server_options oa ON (
        o.server_id IS NULL AND s.id = oa.server_id AND (
          owner.rolname = oa.pem_user
          OR (owner.rolname IS NULL AND oa.pem_user IS NULL)
        )
      )
  )
  SELECT
    database_name,
    database_size_mb AS "Size (MB)"
  FROM
    pemdata.database_size d
  LEFT OUTER JOIN restricted_dbs r ON ( r.id = d.server_id )
  WHERE
    server_id = %(server_id)s::int4
    AND (
      %(show_system_objects)s::boolean OR (
        CASE WHEN d.database_name != '''' THEN
          d.database_name NOT IN (''template0'', ''template1'')
        ELSE TRUE
        END
      )
    )
    AND (r.dbs IS NULL OR (d.database_name = ANY(r.dbs)))
  ORDER BY database_size_mb DESC LIMIT 20', true, '{database_size}'),
  (68, 'Q', E'
  SELECT
    tablespace_name,
    tablespace_size_mb
  FROM
    pemdata.tablespace_size
  WHERE
    server_id = %(server_id)s::int4
  ORDER BY tablespace_size_mb DESC LIMIT 20', false, '{tablespace_size}'),
  (69, 'Q', E'
  SELECT
    ''Number of WAL files: '' || number_of_wal_files
  FROM
    pemdata.number_of_wal_files
  WHERE
    server_id = %(server_id)s::int4', false, '{number_of_wal_files}'),
  (70, 'Q', E'
  SELECT
    SUM(space_used_mb) AS used,
    SUM(space_available_mb) AS free
  FROM
    pemdata.disk_space
  WHERE
    agent_id = %(agent_id)s::int4', false, '{disk_space}'),
  (71, 'Q', E'
  WITH restricted_dbs AS (
    SELECT s.id, pem.db_escaped_string_to_array(COALESCE(o.database_restriction, oa.database_restriction)) AS dbs
  FROM
    pem.server s
    LEFT OUTER JOIN pg_catalog.pg_roles owner ON (owner.oid = s.owner)
    LEFT OUTER JOIN pem.server_options o ON (s.id = o.server_id AND o.pem_user = current_user)
    LEFT OUTER JOIN pem.server_options oa
    ON (o.server_id IS NULL AND s.id = oa.server_id AND
    (owner.rolname = oa.pem_user OR (owner.rolname IS NULL AND oa.pem_user IS NULL)))
  )
  SELECT
    database_name AS "Database Name",
    database_size_mb AS "Database Size (MB)",
    tablespace_name AS "Tablespace Name"
  FROM
    pemdata.database_size d
    LEFT OUTER JOIN restricted_dbs r ON ( d.server_id = r.id )
  WHERE
    server_id = %(server_id)s::int4
    AND (
      %(show_system_objects)s::boolean OR (
        CASE WHEN d.database_name != '''' THEN
          d.database_name NOT IN (''template0'', ''template1'')
        ELSE TRUE
        END
      )
    )
    AND (r.dbs IS NULL OR (d.database_name = ANY(r.dbs)))
  ORDER BY 2', true, '{database_size}'),
  (72, 'Q', E'
  SELECT
    tablespace_name AS "Tablespace Name",
    tablespace_size_mb "Tablespace Size (MB)"
  FROM
    pemdata.tablespace_size
  WHERE
    server_id = %(server_id)s::int4
  ORDER BY 2', false, '{tablespace_size}'),
  (73, 'Q', E'
    SELECT
        file_system AS "File System",
        ROUND((size_mb::float/1024)::numeric,2) AS "Size (GB)",
        ROUND((space_used_mb::float/1024)::numeric,2) AS "Used (GB)",
        ROUND((space_available_mb::float/1024)::numeric,2) AS "Available (GB)",
        ROUND((space_used_mb::float * 100/(size_mb - COALESCE(space_reserved_mb, 0)))::numeric,2) AS "%% Used",
        CASE WHEN (device_id is NOT NULL and device_id != '''') THEN mount_point || '' ('' || device_id || '')'' ELSE mount_point END AS "Mounted On"
    FROM pemdata.disk_space
    WHERE agent_id = %(agent_id)s::int4
      AND size_mb != 0
    ORDER BY 3::int DESC', false, '{disk_space}'),
  (74, 'Q', E'
  SELECT
    wait_name AS "Wait Name",
    wait_count AS "Wait Counts"
    FROM
    pemdata.system_waits
  WHERE
    server_id = %(server_id)s::int4
  ORDER BY "Wait Counts" DESC
  LIMIT 5', false, '{system_waits}'),
  (75, 'Q', E'
  SELECT
    wait_name AS "Wait Name",
    total_wait*1000 AS "Total Wait Time (Secs)"
  FROM
    pemdata.system_waits
  WHERE
    server_id = %(server_id)s::int4
  ORDER BY "Total Wait Time (Secs)" DESC
  LIMIT 5', false, '{system_waits}'),
  (76, 'Q', E'
  SELECT
    wait_name AS "Event",
    wait_count AS "Wait Count",
    (SELECT CASE WHEN SUM(wait_count) = 0 THEN 0
        ELSE (psw.wait_count*100/SUM(wait_count)) END
     FROM pemdata.system_waits WHERE server_id = %(server_id)s::int4)::numeric(5,2) AS "Percentage of Total",
    (total_wait*1000)::numeric(30,2) AS "Time Waited (ms)",
    (SELECT CASE WHEN SUM(total_wait) = 0 THEN 0
        ELSE (psw.total_wait*100/SUM(total_wait)) END
     FROM pemdata.system_waits WHERE server_id = %(server_id)s::int4)::numeric(5,2) AS "Percentage of Time Waited",
    (avg_wait*1000)::numeric(30,2) AS "Average Wait Time (ms)"
  FROM
    pemdata.system_waits psw
  WHERE
    server_id = %(server_id)s::int4
  ORDER BY 2::int4', false, '{system_waits}'),
  (78, 'Q', E'
  SELECT
   $$Swap Total: $$ || total_swap_memory_mb || $$MB $$ || $$&#183;$$ ||
   $$ Swap Used: $$ || total_swap_memory_mb - free_swap_memory_mb || $$MB$$
  FROM
   pemdata.memory_usage
  WHERE agent_id = %(agent_id)s::int4', false, '{memory_usage}'),
  (79, 'P', 'table_io_object_index_io', false, '{index_statistics, oc_index}'),
  (83, 'Q', E'
  SELECT
    $$Replication Status: $$ ||
      COALESCE((
        SELECT
          CASE
          WHEN psh.last_heartbeat IS NULL OR pa.heartbeat_tolerance IS NULL THEN $$Unknown$$
          WHEN psh.last_heartbeat < (now() - ((pa.heartbeat_tolerance + 15) * ''1 second''::interval)) THEN $$Stopped$$
          WHEN pstrl.replication_paused THEN $$Paused$$ ELSE $$Running$$
          END
        FROM pemdata.streaming_replication_lag_time pstrl
          LEFT OUTER JOIN pem.server_heartbeat psh ON (pstrl.server_id=psh.server_id)
          LEFT OUTER JOIN pem.agent_server_binding pasb ON (pstrl.server_id = pasb.server_id)
          LEFT OUTER JOIN pem.avail_agents pa ON (pasb.agent_id = pa.id AND psh.agent_id = pa.id)
          LEFT OUTER JOIN pem.agent_heartbeat pah ON (pah.agent_id = pasb.agent_id)
          WHERE pstrl.server_id = %(server_id)s::int4
      ), $$Unknown$$)', false, '{streaming_replication_lag_time}'),
  (88, 'Q', E'
  SELECT
    efm_agent_type AS "Agent Type", efm_ip_address AS "Address",
    efm_db_status AS "DB",
    efm_xlog_loc AS "XLog Location", efm_xlog_receive AS "XLog Receive",
    efm_status_info AS "Status Information", efm_xlog_info AS "XLog Information",
    efm_vip AS "Virtual IP Address", efm_vip_status AS "VIP Status"
  FROM
    pemdata.efm_cluster_node_status
  WHERE server_id = %(server_id)s::int4', false, '{efm_cluster_node_status}'),
  (89, 'Q', E'
  SELECT 
  	property, value
  FROM 
	pemdata.efm_cluster_info pe
	LEFT JOIN pem.server ps ON ps.id = pe.server_id
	CROSS JOIN LATERAL (
  VALUES
	(''Cluster Name'', ps.efm_cluster_name),
    (''Failover Manager Agent Running Status'', CASE WHEN pe.efm_running = true THEN ''UP'' ELSE ''DOWN'' END),
    (''Allowed Node List'', array_to_string(pe.efm_allowed_node_list, '', '')),
    (''Replica Priority List'', array_to_string(pe.efm_standby_priority_list, '', '')),
    (''Missing Nodes'', array_to_string(pe.efm_missing_nodes, '', '')),
    (''Minimum Standbys'', pe.efm_minimum_standbys::text),
    (''Membership Coordinator'', pe.efm_membership_coordinator),
    (''Cluster Status Message'', pe.efm_messages)
	) AS info(property, value)
  WHERE pe.server_id = %(server_id)s::int4;', false, '{efm_cluster_info}');

