--
--Fixing #31622
--
--Preventing the user to enable the XDB probe,
--if pem db don't find the required xdb catalog schema.
--
CREATE OR REPLACE FUNCTION pem.on_probe_config_database_insert_or_update() RETURNS TRIGGER AS
$$
BEGIN
	IF NEW.probe_id = (SELECT id FROM pem.probe WHERE internal_name = 'xdb_smr_mmr_replication') AND NEW.enabled IS TRUE THEN
		IF EXISTS (
			SELECT 1
			FROM pemdata.oc_schema
			WHERE database_name = NEW.database_name
			AND server_id = NEW.server_id
			AND schema_name = '_edb_replicator_pub') THEN

				RETURN NEW;
		ELSE
				RAISE EXCEPTION E'\nXDB publication''s catalog is not found.\nXDB probe should be configured on publication side.';
				RETURN NULL;
		END IF;
	ELSE
		RETURN NEW;
	END IF;
END;
$$
LANGUAGE PLPGSQL;

CREATE TRIGGER on_probe_config_database_insert_or_update_trg BEFORE INSERT OR UPDATE ON pem.probe_config_database FOR EACH ROW EXECUTE PROCEDURE pem.on_probe_config_database_insert_or_update();


-- Function unit_converter(text, text) which convert value
-- of one type to another. It is used on Alert details and Alert status
-- dashboard to display units with alert values.
CREATE OR REPLACE FUNCTION pem.unit_converter(val numeric, unit text)
RETURNS text AS $$
DECLARE
  temp_unit text:= '';
	temp_val text;
BEGIN

	IF unit IS NULL OR unit = '#' THEN
		RETURN TRIM(trailing '0' FROM ROUND(val::decimal, 2)::text)::numeric;
	END IF;

	unit := TRIM(unit);
	IF unit = 'STATE' THEN
		RETURN CASE val WHEN 1 THEN 'UP' WHEN 0 THEN 'DOWN' ELSE 'UNKNOWN ' || val::text END;
	END IF;

	IF unit = '%' THEN
		val = ROUND(val::decimal, 2);
		RETURN TRIM(trailing '0' FROM val::text)::numeric || unit;
	END IF;

	temp_val = val::decimal(30, 2);
	IF UPPER(unit) = 'KB' THEN
		-- Convert value to MB OR GB
		IF (val::decimal / 1024::decimal) >= 1.00 THEN
			val = val::decimal / 1024::decimal;
			IF (val::decimal / 1024::decimal) >= 1.00 THEN
				temp_unit = ' GB';
				temp_val = ROUND(val::decimal / 1024::decimal, 3)::text;
			ELSE
				temp_unit = ' MB';
				temp_val = ROUND(val::decimal, 3)::text;
			END IF;

		ELSE
			temp_unit = ' KB';
			temp_val = ROUND(val::decimal, 3)::text;
		END IF;
	END IF;

	IF UPPER(unit) = 'MB' THEN
		-- Convert value to GB
		IF (val::decimal / 1024::decimal) >= 1.00 THEN
			temp_unit = ' GB';
			temp_val = ROUND(val::decimal / 1024::decimal, 3)::text;
		ELSE
			temp_unit = ' MB';
			temp_val = ROUND(val::decimal, 3)::text;
		END IF;
	END IF;

	IF UPPER(unit) = 'GB' THEN
		temp_unit = ' GB';
		temp_val = ROUND(val::decimal, 3)::text;
	END IF;

	IF UPPER(unit) = 'HOURS' THEN
		temp_unit = ' hrs';
		temp_val = ROUND(val::decimal, 3)::text;
	END IF;


	IF UPPER(unit) = 'MINUTES' THEN
		temp_unit = ' mins';
		temp_val = ROUND(val::decimal, 3)::text;
	END IF;

	IF UPPER(unit) = 'DAYS' THEN
		temp_unit = ' days';
		temp_val = ROUND(val::decimal, 3)::text;
	END IF;

	RETURN TRIM(trailing '0' FROM temp_val)::numeric || temp_unit;
END
$$ LANGUAGE plpgsql;

-- Creating event_history table to identify the user who changed the blackout componenet status and datetime
-- also tracks the failover events from efm/patroni
CREATE TABLE IF NOT EXISTS pem.event_history (
    recorded_time TIMESTAMP NOT NULL,
    user_name     TEXT NOT NULL,
    component     TEXT NOT NULL,
    operation     TEXT NOT NULL,
    message       TEXT NOT NULL,
    details       TEXT NOT NULL
);

GRANT UPDATE ON TABLE pem.event_history TO pem_agent;

-- Create a roles table which stores the rolid and the component to
-- which it has access.
CREATE TABLE pem.roles
(
    rolid OID,
    component text,
    description text,
    PRIMARY KEY(rolid)
);

-- This function will create roles based on component given and
-- allow to set permissions(select, update, delete, all etc.)
-- on associated tables.
-- and set parent roles for created role.
CREATE OR REPLACE FUNCTION pem.create_role_for(
    component_name text,
    description text,
    parent_roles text[] DEFAULT '{}'::text[],
    priv_insert_on_tables text[] DEFAULT '{}'::text[],
    priv_update_on_tables text[] DEFAULT '{}'::text[],
    priv_delete_on_tables text[] DEFAULT '{}'::text[],
    priv_all_on_tables text[] DEFAULT '{}'::text[]
)
RETURNS VOID AS
$$
DECLARE
    role_name text;
    temp_val text;
    tbl text[];
    parent_role text;
    role_oid oid := NULL;
BEGIN
    role_name := quote_ident('pem_'|| component_name);

    -- Fetch oid of newly created role.
    SELECT oid INTO role_oid FROM pg_roles WHERE quote_ident(rolname) = role_name;
    IF role_oid IS NULL THEN
        EXECUTE 'CREATE ROLE ' || quote_ident(role_name);
        SELECT oid INTO role_oid FROM pg_roles WHERE quote_ident(rolname) = role_name;
    END IF;

    -- Add new role entry into pem.roles table.
    INSERT INTO pem.roles VALUES (role_oid, component_name, description);

    IF array_length(priv_insert_on_tables, 1) <> 0  THEN
        FOREACH tbl SLICE 1 IN ARRAY priv_insert_on_tables LOOP
            IF array_length(tbl, 1) < 2 THEN
                RAISE INFO 'Granting INSERT permission to table: pem.%', tbl[1];
                EXECUTE 'GRANT INSERT ON TABLE ' ||
                    'pem.' || quote_ident(tbl[1]) || ' TO ' || role_name;
            ELSE
                RAISE INFO 'Granting INSERT permission to table: %.%',
                    tbl[1], tbl[2];

                EXECUTE 'GRANT INSERT ON TABLE ' ||
                    quote_ident(tbl[1]) || '.' || quote_ident(tbl[2]) || ' TO ' ||
                    role_name;
            END IF;
        END LOOP;
    END IF;

    -- Grant "UPDATE" permission to the given role
    IF array_length(priv_update_on_tables, 1) <> 0  THEN
        FOREACH tbl SLICE 1 IN ARRAY priv_update_on_tables LOOP
            IF array_length(tbl, 1) < 2 THEN
                RAISE INFO 'Granting UPDATE permission to table: pem.%', tbl[1];
                EXECUTE 'GRANT UPDATE ON TABLE ' ||
                    'pem.' || quote_ident(tbl[1]) || ' TO ' || role_name;
            ELSE
                RAISE INFO 'Granting UPDATE permission to table: %.%',
                    tbl[1], tbl[2];

                EXECUTE 'GRANT UPDATE ON TABLE ' ||
                    quote_ident(tbl[1]) || '.' || quote_ident(tbl[2]) || ' TO ' ||
                    role_name;
            END IF;
        END LOOP;
    END IF;

    -- Grant "DELETE" permission to the given role
    IF array_length(priv_delete_on_tables, 1) <> 0  THEN
        FOREACH tbl SLICE 1 IN ARRAY priv_delete_on_tables LOOP
            IF array_length(tbl, 1) < 2 THEN
                RAISE INFO 'Granting DELETE permission to table: pem.%', tbl[1];
                EXECUTE 'GRANT DELETE ON TABLE ' ||
                    'pem.' || quote_ident(tbl[1]) || ' TO ' || role_name;
            ELSE
                RAISE INFO 'Granting DELETE permission to table: %.%',
                    tbl[1], tbl[2];

                EXECUTE 'GRANT DELETE ON TABLE ' ||
                    quote_ident(tbl[1]) || '.' || quote_ident(tbl[2]) || ' TO ' ||
                    role_name;
            END IF;
        END LOOP;
    END IF;

    -- Grant "ALL" permission to the given role
    IF array_length(priv_all_on_tables, 1) <> 0  THEN
        FOREACH tbl SLICE 1 IN ARRAY priv_all_on_tables LOOP
            IF array_length(tbl, 1) < 2 THEN
                RAISE INFO 'Granting ALL permission to table: pem.%', tbl[1];
                EXECUTE 'GRANT ALL ON TABLE ' ||
                    'pem.' || quote_ident(tbl[1]) || ' TO ' || role_name;
            ELSE
                RAISE INFO 'Granting ALL permission to table: %.%',
                    tbl[1], tbl[2];

                EXECUTE 'GRANT ALL ON TABLE ' ||
                    quote_ident(tbl[1]) || '.' || quote_ident(tbl[2]) || ' TO ' ||
                    role_name;
            END IF;
        END LOOP;
    END IF;

    -- Iterate over parent roles and Grant them role_name
    FOREACH parent_role IN ARRAY parent_roles LOOP
      EXECUTE 'GRANT ' || role_name || ' TO ' || quote_ident(parent_role);
    END LOOP;
END
$$ LANGUAGE 'plpgsql';

