-- Create table to store ark servers
CREATE TABLE pem.ark_server
(
  id serial NOT NULL,
  description text,
  protocol text NOT NULL,
  host text NOT NULL,
  port integer,
  api_version text NOT NULL,
  owner oid,
  team text,
  CONSTRAINT ark_server_pkey PRIMARY KEY (id)
)
WITH (
  OIDS=FALSE
);
GRANT SELECT, INSERT, UPDATE ON TABLE pem.ark_server TO pem_user;
GRANT ALL ON TABLE pem.ark_server TO pem_admin;
COMMENT ON TABLE pem.ark_server
  IS 'Ark server directory';

-- Function: pem.ark_server_insertion()

CREATE OR REPLACE FUNCTION pem.ark_server_insertion()
  RETURNS trigger AS
$BODY$
DECLARE
	curr_user_oid oid;
BEGIN
	IF NEW.owner IS NULL THEN
		SELECT oid INTO curr_user_oid FROM pg_catalog.pg_roles WHERE rolname = current_user;
		NEW.owner := curr_user_oid;
	END IF;
	RETURN NEW;
END

$BODY$
  LANGUAGE plpgsql VOLATILE
  COST 100;
GRANT EXECUTE ON FUNCTION pem.ark_server_insertion() TO pem_user;
GRANT EXECUTE ON FUNCTION pem.ark_server_insertion() TO pem_admin;

CREATE TRIGGER ark_server_insertion
  BEFORE INSERT
  ON pem.ark_server
  FOR EACH ROW
  EXECUTE PROCEDURE pem.ark_server_insertion();

-- Create table to store ark server user options
CREATE TABLE pem.ark_server_option
(
  id serial NOT NULL,
  ark_server_id integer NOT NULL,
  pem_user text NOT NULL,
  username text NOT NULL,
  tenant_role text,
  domain_name text,
  password text,
  CONSTRAINT ark_server_option_pkey PRIMARY KEY (id),
  CONSTRAINT ark_server_option_ark_server_id_fkey FOREIGN KEY (ark_server_id)
      REFERENCES pem.ark_server (id) MATCH SIMPLE
      ON UPDATE NO ACTION ON DELETE CASCADE
)
WITH (
  OIDS=FALSE
);
GRANT SELECT, INSERT, UPDATE ON TABLE pem.ark_server_option TO pem_user;
GRANT ALL ON TABLE pem.ark_server_option TO pem_admin;

-- As 'pem_user' can hide the group so this permission is required.
GRANT INSERT, UPDATE ON TABLE pem.user_server_group TO pem_user;

CREATE OR REPLACE FUNCTION pem.get_agent_pool_auth(p_usename TEXT)
RETURNS TABLE(username TEXT, password TEXT) AS
$$
BEGIN
    RETURN QUERY
    SELECT u.rolname::TEXT, u.rolpassword::TEXT
    FROM pg_authid g
    JOIN pg_auth_members m ON (m.roleid = g.oid)
    JOIN pg_authid u ON (u.oid = m.member)
    WHERE NOT u.rolsuper
        AND g.rolname = 'pem_agent_pool'
        AND u.rolname = p_usename;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

REVOKE ALL ON FUNCTION pem.get_agent_pool_auth(p_usename TEXT) FROM PUBLIC, pem_admin;

-- Add all BART related schemas
CREATE TABLE pem.bart_version (
        id                      int8 NOT NULL,
        display_name            text NOT NULL,
        CONSTRAINT bart_server_version_pkey PRIMARY KEY (id)
);

COMMENT ON TABLE pem.bart_version IS 'Store BART host version information';
COMMENT ON COLUMN pem.bart_version.id IS 'BART host version';
COMMENT ON COLUMN pem.bart_version.display_name IS 'BART host version string';

-- Version will be ((major version * 1000000) + (minor version * 1000)) and
-- display name will be same as return by "bart --version" command
