-- This table store the user defined BART host configurations.
CREATE TABLE pem.bart_config (
        bart_id                         integer NOT NULL -- BART Server id
            REFERENCES pem.bart (id) ON DELETE CASCADE ON UPDATE RESTRICT,
        name                            text NOT NULL, -- BART configuration name
        value                           text DEFAULT NULL, -- BART configuration value
        CONSTRAINT bart_config_pkey PRIMARY KEY (bart_id, name)
);

COMMENT ON TABLE pem.bart_config IS 'Store user defined BART host configuration parameters';
COMMENT ON COLUMN pem.bart_config.bart_id IS 'BART host id';
COMMENT ON COLUMN pem.bart_config.name IS 'BART host configuration parameter name';
COMMENT ON COLUMN pem.bart_config.value IS 'BART host configuration parameter value';

-- This table store the user defined BART managed database server configurations.
CREATE TABLE pem.bart_server_config (
        server_id                       integer NOT NULL -- BART Server id
            REFERENCES pem.server (id) ON DELETE CASCADE ON UPDATE RESTRICT,
        name                            text NOT NULL, -- BART configuration name
        value                           text DEFAULT NULL, -- BART configuration value
        CONSTRAINT bart_server_config_pkey PRIMARY KEY (server_id, name)
);

COMMENT ON TABLE pem.bart_server_config IS 'Store user defined BART managed database server configurations';
COMMENT ON COLUMN pem.bart_server_config.server_id IS 'BART managed database server id';
COMMENT ON COLUMN pem.bart_server_config.name IS 'BART managed database server configuration parameter name';
COMMENT ON COLUMN pem.bart_server_config.value IS 'BART managed database server configuration parameter value';

-- This table store the user defined BART installation paths
CREATE TABLE pem.bart_default_path (
        id                          serial NOT NULL,
        install_path                text NOT NULL,
        CONSTRAINT bart_default_path_pkey PRIMARY KEY (id, install_path)
);

COMMENT ON TABLE pem.bart_default_path IS 'Store BART Installation paths';
COMMENT ON COLUMN pem.bart_default_path.id IS 'Unique id';
COMMENT ON COLUMN pem.bart_default_path.install_path IS 'Path of BART installation directory';

-- BART backup config to be used while taking backup
CREATE TABLE pem.bart_backup_config
(
    id                      serial NOT NULL,
    bart_id                 integer NOT NULL
        REFERENCES pem.bart (id) ON UPDATE RESTRICT ON DELETE CASCADE,
    server_id               integer NOT NULL
        REFERENCES pem.server (id) ON UPDATE RESTRICT ON DELETE CASCADE,
    backup_name             text,
    backup_type             text NOT NULL,
    parent_backup_id        bigint,
    custom_parent_backup    text,
    output_format           text NOT NULL,
    gzip_compression        boolean,
    compression_level       integer,
    thread_count            integer NOT NULL,
    use_pg_basebackup       boolean,
    verify_checksum         boolean,
    checksum_algorithm      text DEFAULT 'NONE',
    last_backup_id          bigint,
    last_backup_name        text,
    status                  text,
    message                 text,
    job_id                  integer NOT NULL
        REFERENCES pem.job (jobid) ON UPDATE RESTRICT ON DELETE CASCADE
);

COMMENT ON TABLE pem.bart_backup_config IS 'Store BART Backup config';
COMMENT ON COLUMN pem.bart_backup_config.id IS 'Unique id';
COMMENT ON COLUMN pem.bart_backup_config.bart_id IS 'BART Id';
COMMENT ON COLUMN pem.bart_backup_config.server_id IS 'Database server Id';
COMMENT ON COLUMN pem.bart_backup_config.backup_name IS 'Backup name to be used while taking backup';
COMMENT ON COLUMN pem.bart_backup_config.backup_type IS 'Backup type (Full/Incremental)';
COMMENT ON COLUMN pem.bart_backup_config.parent_backup_id IS 'Parent backup id for incremental backup';
COMMENT ON COLUMN pem.bart_backup_config.custom_parent_backup IS 'Custom parent backups latest/latest_full';
COMMENT ON COLUMN pem.bart_backup_config.output_format IS 'Backup output format (Tar/Plain)';
COMMENT ON COLUMN pem.bart_backup_config.gzip_compression IS 'GZip compression while taking Tar backup';
COMMENT ON COLUMN pem.bart_backup_config.thread_count IS 'Thread count for parallel backups';
COMMENT ON COLUMN pem.bart_backup_config.use_pg_basebackup IS 'pg_basebackup while taking Full backup';
COMMENT ON COLUMN pem.bart_backup_config.verify_checksum IS 'Set verify_checksum to verify tar backup';
COMMENT ON COLUMN pem.bart_backup_config.checksum_algorithm IS 'Set checksum algorithm for MBM files';
COMMENT ON COLUMN pem.bart_backup_config.last_backup_id IS 'Used while running verify checksum job step';
COMMENT ON COLUMN pem.bart_backup_config.last_backup_name IS 'Last backup taken';
COMMENT ON COLUMN pem.bart_backup_config.status IS 'Status of backup being taken';
COMMENT ON COLUMN pem.bart_backup_config.message IS 'Store failure message';
COMMENT ON COLUMN pem.bart_backup_config.job_id IS 'Job id of bart backup job';


