-- Function to create BART configuration file
CREATE OR REPLACE FUNCTION pem.generate_bart_config(
    bart_host_id  integer,
    bart_version int8 DEFAULT 2004000::int8,
    all_params boolean DEFAULT true)
  RETURNS text AS
$BODY$

DECLARE
    bart_config_text    text := '';
    query               text := '';
    bart_user_name      text := '';
    row                 RECORD;
    validate_version    bool := TRUE;
BEGIN
    -- If BART installed version is not found in pem.bart_version table, we should use the latest version used in pem.bart_default_config table.
    SELECT bart_version INTO validate_version IN (SELECT DISTINCT(version) FROM pem.bart_default_config ORDER BY 1 DESC);
    IF validate_version IS FALSE THEN
        SELECT DISTINCT(version) INTO bart_version FROM pem.bart_default_config ORDER BY 1 DESC LIMIT 1;
    END IF;

    IF all_params IS FALSE THEN
      query := 'SELECT bc.name, bc.value FROM pem.bart_config bc LEFT OUTER JOIN pem.bart_default_config bdc ON (bdc.name = bc.name ) WHERE version = ' || bart_version || ' AND required_params IS TRUE AND bc.bart_id = '|| bart_host_id ||' ORDER BY bdc.seq_id;';
    ELSE
      query := 'SELECT bc.name, bc.value FROM pem.bart_config bc LEFT OUTER JOIN pem.bart_default_config bdc ON (bdc.name = bc.name ) WHERE version = ' || bart_version || ' AND bc.bart_id = '|| bart_host_id ||' ORDER BY bdc.seq_id;';
    END IF;

    FOR row IN EXECUTE query
    LOOP
        IF COALESCE(TRIM(bart_config_text), '') = '' THEN
          bart_config_text = bart_config_text || E'[BART]';
        END IF;

        IF row.name = 'bart_user' THEN
          bart_user_name = row.value;
        ELSIF row.name = 'bart_host' THEN
          bart_config_text = bart_config_text || E'\n' || row.name || ' = ' || bart_user_name || '@' || COALESCE(TRIM(row.value), '');
        ELSIF COALESCE(TRIM(row.value), '') != '' THEN
          bart_config_text = bart_config_text || E'\n' || row.name || ' = ' || COALESCE(TRIM(row.value), '');
        END IF;

    END LOOP;

    bart_config_text = bart_config_text || E'\n';

RETURN bart_config_text;

END

$BODY$
  LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION pem.generate_bart_server_config(
    bart_server_id  integer,
    bart_version int8 DEFAULT 2004000::int8,
    all_params boolean DEFAULT true,
    tbl_server_id  integer DEFAULT 1,
    tablespace_str text DEFAULT '')
  RETURNS text AS
$BODY$

DECLARE
    bart_server_config_text    text := '';
    query               text := '';
    server_id_query     text := '';
    server_row          RECORD;
    server_header       text := '';
    validate_version    bool := TRUE;
    tblspace_added      bool := FALSE;
BEGIN
    -- If BART installed version is not found in pem.bart_version table, we should use the latest version used in bart_server_default_config table.
    SELECT bart_version INTO validate_version IN (SELECT DISTINCT(version) FROM pem.bart_server_default_config ORDER BY 1 DESC);
    IF validate_version IS FALSE THEN
        SELECT DISTINCT(version) INTO bart_version FROM pem.bart_server_default_config ORDER BY 1 DESC LIMIT 1;
    END IF;

    IF all_params IS FALSE THEN
      query := 'SELECT sbc.server_id, sbb.name AS server_name, sbc.name, sbc.value FROM pem.bart_server_config sbc LEFT OUTER JOIN pem.bart_server_default_config bdc ON (bdc.name = sbc.name ) LEFT OUTER JOIN pem.bart_server_binding sbb ON (sbb.server_id = sbc.server_id) WHERE version = ' || bart_version || ' AND sbc.server_id = ANY(SELECT server_id FROM pem.bart_server_binding WHERE bart_id = '|| bart_server_id ||' ) AND required_params IS TRUE ORDER BY sbc.server_id, bdc.seq_id;';
    ELSE
      query := 'SELECT sbc.server_id, sbb.name AS server_name, sbc.name, sbc.value FROM pem.bart_server_config sbc LEFT OUTER JOIN pem.bart_server_default_config bdc ON (bdc.name = sbc.name ) LEFT OUTER JOIN pem.bart_server_binding sbb ON (sbb.server_id = sbc.server_id) WHERE version = ' || bart_version || ' AND sbc.server_id = ANY(SELECT server_id FROM pem.bart_server_binding WHERE bart_id = '|| bart_server_id ||' ) ORDER BY sbc.server_id, bdc.seq_id;';
    END IF;

    FOR server_row IN EXECUTE query
    LOOP
        IF server_header != server_row.server_name THEN
          bart_server_config_text = bart_server_config_text || E'\n';
          bart_server_config_text = bart_server_config_text || E'\n' || E'[' || server_row.server_name || ']';
          server_header := server_row.server_name;
        END IF;

        IF COALESCE(TRIM(server_row.value), '') != '' THEN
          -- As archive_command required to be quoted in bart.cfg file otherwise BART command will fail
          IF server_row.name = 'archive_command' THEN
            bart_server_config_text = bart_server_config_text || E'\n' || server_row.name || ' = ' || pg_catalog.quote_literal(TRIM(both E'\'' FROM server_row.value));
          ELSE
            bart_server_config_text = bart_server_config_text || E'\n' || server_row.name || ' = ' || COALESCE(TRIM(server_row.value), '');
          END IF;
        END IF;

        -- As tablespace path is proivded, add to 'bart.cfg' as there is no option to override through command line during restore
        IF NOT tblspace_added AND tbl_server_id = server_row.server_id AND COALESCE(TRIM(tablespace_str), '') != '' THEN
          bart_server_config_text = bart_server_config_text || E'\n' || 'tablespace_path' || ' = ' || COALESCE(TRIM(tablespace_str), '');
          tblspace_added := TRUE;
        END IF;

    END LOOP;

    bart_server_config_text = bart_server_config_text || E'\n';

RETURN bart_server_config_text;

END

$BODY$
  LANGUAGE plpgsql;

-- BART Restore config to be used while restoring backup
CREATE TABLE pem.bart_restore_config
(
    id                          serial NOT NULL,
    bart_id                     integer NOT NULL
        REFERENCES pem.bart (id) ON UPDATE RESTRICT ON DELETE CASCADE,
    agent_id                integer NOT NULL
        REFERENCES pem.agent (id) ON UPDATE RESTRICT ON DELETE CASCADE,
    backup_id                   bigint NOT NULL,
    job_id                      integer
        REFERENCES pem.job (jobid) ON UPDATE RESTRICT ON DELETE CASCADE,
    remote_user                 text,
    remote_host                 text,
    ssh_port                    integer,
    restore_path                text,
	verify_checksum				boolean DEFAULT true,
    tablespace_oid              bigint[],
    tablespace_path             text[],
    worker                      integer,
    copy_wals                   boolean,
    pitr                        boolean,
    timeline_id                 text,
    transaction_id              text,
    timestamp                   timestamp with time zone,
    message                     text,
    status                      text
);

COMMENT ON TABLE pem.bart_restore_config IS 'Store BART Restore config';
COMMENT ON COLUMN pem.bart_restore_config.id IS 'Unique id';
COMMENT ON COLUMN pem.bart_restore_config.bart_id IS 'BART Id';
COMMENT ON COLUMN pem.bart_restore_config.agent_id IS 'Agent Id';
COMMENT ON COLUMN pem.bart_restore_config.backup_id IS 'Backup id to restore';
COMMENT ON COLUMN pem.bart_restore_config.job_id IS 'Job id of bart restore job';
COMMENT ON COLUMN pem.bart_restore_config.remote_user IS 'Remote user of the remote host';
COMMENT ON COLUMN pem.bart_restore_config.remote_host IS 'Remote host for the restore';
COMMENT ON COLUMN pem.bart_restore_config.ssh_port IS 'Port used for SSH connection';
COMMENT ON COLUMN pem.bart_restore_config.restore_path IS 'Path where backup will restore';
COMMENT ON COLUMN pem.bart_restore_config.verify_checksum IS 'Use this flag for checksum verification';
COMMENT ON COLUMN pem.bart_restore_config.tablespace_oid IS 'Array of tablespace OID of the backup';
COMMENT ON COLUMN pem.bart_restore_config.tablespace_path IS 'Array of tablespace path of the backup';
COMMENT ON COLUMN pem.bart_restore_config.worker IS 'Number of workers for parallel restore';
COMMENT ON COLUMN pem.bart_restore_config.copy_wals IS 'Copy WALs to restore path flag';
COMMENT ON COLUMN pem.bart_restore_config.pitr IS 'Point in time recovery(PITR) flag';
COMMENT ON COLUMN pem.bart_restore_config.timeline_id IS 'Timeline ID for PITR restore';
COMMENT ON COLUMN pem.bart_restore_config.transaction_id IS 'Transaction(XID) for PITR restore';
COMMENT ON COLUMN pem.bart_restore_config.timestamp IS 'Timestamp for PITR restore';
COMMENT ON COLUMN pem.bart_restore_config.message IS 'Message from restore job';
COMMENT ON COLUMN pem.bart_restore_config.status IS 'Status of BART restore';

GRANT ALL ON TABLE pem.bart_restore_config TO pem_agent;

