-- PEM-3619 Add capability to pemagent to run global jobs, Also added enable, disable blackout jobs
-- This table store global ran by which agent.
CREATE TABLE pem.jobloginfo
(
	agent_id              integer NOT NULL
	REFERENCES pem.agent (id) ON UPDATE RESTRICT ON DELETE CASCADE,
	joblogid              integer NOT NULL
	REFERENCES pem.joblog (jlgid) ON UPDATE RESTRICT ON DELETE CASCADE
);

COMMENT ON TABLE pem.jobloginfo IS 'Stores agent_id by whom global job got executed';
COMMENT ON COLUMN pem.jobloginfo.agent_id IS 'Stores agent_id';
COMMENT ON COLUMN pem.jobloginfo.joblogid IS 'Stores joblog id';
GRANT INSERT ON TABLE pem.jobloginfo TO pem_agent;

-- Function which is responsible for adding information about which agent has ran global job
CREATE OR REPLACE FUNCTION insert_jobinfolog()
RETURNS trigger AS
$$
DECLARE
	agentid    integer;
BEGIN
	agentid := -1;
	SELECT agent_id FROM pem.job WHERE jobid=NEW.jlgjobid AND is_global_job=true INTO agentid;
	IF agentid <> -1 THEN
		INSERT INTO pem.jobloginfo(agent_id, joblogid) VALUES(agentid, NEW.jlgid);
	END IF;
	RETURN NEW;
END;
$$
LANGUAGE 'plpgsql';

-- Trigger for identifying global is ran by which agent
CREATE TRIGGER jobloginfo_insertion
AFTER INSERT ON pem.joblog
    FOR EACH ROW
    EXECUTE PROCEDURE insert_jobinfolog();

-- Function which is responsible for deletion of the webhook_ids from the webhook_alert_config table
-- if the payload_type ic changed from ALERT to JOB
CREATE OR REPLACE FUNCTION pem.cleanup_webhook_ids()
RETURNS TRIGGER AS $$
BEGIN
    -- Check if payload_type is being updated from 'ALERT' to 'JOB'
    IF OLD.payload_type = 'ALERT' AND NEW.payload_type = 'JOB' THEN
        -- Remove webhook id from all webhook_id columns in the relevant table
        UPDATE pem.webhook_alert_config
        SET
            low_webhook_ids = array_remove(low_webhook_ids, OLD.id),
            med_webhook_ids = array_remove(med_webhook_ids, OLD.id),
            high_webhook_ids = array_remove(high_webhook_ids, OLD.id),
            cleared_webhook_ids = array_remove(cleared_webhook_ids, OLD.id)
        WHERE OLD.id = ANY(low_webhook_ids)
           OR OLD.id = ANY(med_webhook_ids)
           OR OLD.id = ANY(high_webhook_ids)
           OR OLD.id = ANY(cleared_webhook_ids);
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger to identify which webhook_id's payload_type is updated
CREATE TRIGGER webhook_cleanup_trigger
AFTER UPDATE OF payload_type ON pem.webhook_endpoints
FOR EACH ROW
EXECUTE FUNCTION pem.cleanup_webhook_ids();

-- PEM-5669: Disable the Last Vacuum and Last AutoVacuum alerts on the replica node.
CREATE OR REPLACE FUNCTION pem.handle_replica_node_alerts()
RETURNS TRIGGER AS $$
BEGIN
  IF NEW.node_type = 'replica' THEN
    -- Disable alerts when node becomes a replica
    UPDATE pem.alert
    SET enabled = false
    WHERE server_id = NEW.server_id
      AND name IN ('Last Vacuum', 'Last AutoVacuum');

  ELSIF OLD.node_type = 'replica' AND NEW.node_type IS DISTINCT FROM 'replica' THEN
    -- Enable alerts when node is changed from replica to something else
    UPDATE pem.alert
    SET enabled = true
    WHERE server_id = NEW.server_id
      AND name IN ('Last Vacuum', 'Last AutoVacuum');
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_handle_replica_alerts
AFTER INSERT OR UPDATE OF node_type ON pemdata.server_info
FOR EACH ROW
EXECUTE FUNCTION pem.handle_replica_node_alerts();

