	CONSTRAINT alert_blackout_config_pkey PRIMARY KEY (id),
	CONSTRAINT alert_blackout_config_unique UNIQUE (start_datetime, duration, blackout_object_ids, is_agent_object),
	CONSTRAINT alert_blackout_config_enable_jobid_fkey FOREIGN KEY (enable_jobid)
		REFERENCES pem.job (jobid) ON DELETE CASCADE,
	CONSTRAINT alert_blackout_config_disable_jobid_fkey FOREIGN KEY (disable_jobid)
		REFERENCES pem.job (jobid) ON DELETE CASCADE
);

COMMENT ON TABLE pem.alert_blackout_config IS 'Stores alert blackout config';
COMMENT ON COLUMN pem.alert_blackout_config.id IS 'Stores id of alert blackout config';
COMMENT ON COLUMN pem.alert_blackout_config.start_datetime IS 'Stores blackout start datetime';
COMMENT ON COLUMN pem.alert_blackout_config.duration IS 'Stores blackout duration';
COMMENT ON COLUMN pem.alert_blackout_config.blackout_object_ids IS 'Stores ids of agents/servers to blackout';
COMMENT ON COLUMN pem.alert_blackout_config.is_agent_object IS 'Stores if blackout_object_ids are of agent or server';
COMMENT ON COLUMN pem.alert_blackout_config.enable_jobid IS 'Stores jobid which is will enable blackout';
COMMENT ON COLUMN pem.alert_blackout_config.disable_jobid IS 'Stores jobid which is will disable blackout';

GRANT SELECT ON TABLE pem.alert_blackout_config TO pem_agent;

-- fuction to update the blackout value for agent/server and maintain the history
CREATE OR REPLACE FUNCTION pem.update_alert_blackout(
	p_agent_object boolean,
	p_blackout_flag boolean,
	p_objects_ids integer[])
RETURNS VOID AS $$
DECLARE
	job_id integer;
	payload text;
	operation text DEFAULT '';
	_rows_affected integer;
	_owner VARCHAR(255);
	message VARCHAR(255) DEFAULT '';
BEGIN
	EXECUTE format(
		'UPDATE pem.%I SET alert_blackout = $1::boolean WHERE active = true AND id in (SELECT unnest(%L::integer[]))',
		CASE WHEN p_agent_object THEN 'agent' ELSE 'server' END,
		p_objects_ids
	) USING p_blackout_flag;

	-- Check for errors by examining the number of affected rows
	GET DIAGNOSTICS _rows_affected = ROW_COUNT;

	IF _rows_affected < 0 THEN
		-- Error occurred during dynamic SQL execution
		RAISE EXCEPTION 'Error updating alert_blackout';
	ELSE
		_owner = pg_catalog.quote_ident(current_user);

		IF p_blackout_flag THEN
			SELECT enable_jobid INTO job_id from pem.alert_blackout_config b WHERE blackout_object_ids = p_objects_ids;
			operation = 'enable_alert_blackout';
			message = concat('Enabled the alert blackout for the ',CASE WHEN p_agent_object THEN 'agent' ELSE 'server' END);
		ELSE
			SELECT disable_jobid INTO job_id from pem.alert_blackout_config b WHERE blackout_object_ids = p_objects_ids;
			operation = 'disable_alert_blackout';
			message = concat('Disabled the alert blackout for the ',CASE WHEN p_agent_object THEN 'agent' ELSE 'server' END);
		END IF;            

		payload = '{
		"AlertBlackoutValue": "%AlertBlackoutValue%",
		"IsAgent": "%AgentObject%",
		"Ids": "%ObjectIds%",
		"Scheduled": "%Scheduled%",
		"JobID": "%JobID%"
		}';

		--cretae payload
		payload = pem.replace_json_params(payload, '%AlertBlackoutValue%',p_blackout_flag::text, 'g');
		payload = pem.replace_json_params(payload, '%AgentObject%', p_agent_object::text, 'g');
		payload = pem.replace_json_params(payload, '%ObjectIds%', p_objects_ids::text, 'g');
		payload = pem.replace_json_params(payload, '%Scheduled%', true::text, 'g');
		payload = pem.replace_json_params(payload, '%JobID%', job_id::text, 'g');

		-- used to maintain the history for alert_blackout component
		INSERT INTO pem.event_history ("recorded_time", "user_name", "component", "operation", "message", "details")
					VALUES (current_timestamp, _owner, 'alert_blackout'::text, operation::text, message::text, payload::text);
	END IF;
END;
$$ LANGUAGE plpgsql;

-- Remove the entry of the probe for the specific monitoring target(s) to force rerun a probe
-- They will be picked up in next run automatically (if the probe is not disabled).
CREATE OR REPLACE FUNCTION pem.rerun_probes_on_agent_restart(agent_id integer)
RETURNS VOID AS $$
BEGIN
	DELETE FROM pem.probe_schedule
		WHERE probe_id IN(SELECT id FROM pem.probe WHERE rerun_on_restart = 't' and target_type_id = 100)
			AND $1::text=ANY(parameter_value_list);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION pem.rerun_probes_on_server_restart(server_id integer)
RETURNS VOID AS $$
BEGIN
	DELETE FROM pem.probe_schedule
		WHERE probe_id IN(SELECT id FROM pem.probe WHERE rerun_on_restart = 't' and target_type_id = 200)
			AND $1::text=ANY(parameter_value_list);
END;
$$ LANGUAGE plpgsql;

-- trggered when an agent is restarted
CREATE OR REPLACE FUNCTION pem.agent_restarted(agent_id integer)
RETURNS text AS $$
BEGIN
	RETURN (SELECT pem.rerun_probes_on_agent_restart($1::integer));
END;
$$ LANGUAGE plpgsql;

-- trggered when an monitored is restarted
CREATE OR REPLACE FUNCTION pem.server_restarted(server_id integer)
RETURNS text AS $$
BEGIN
	RETURN (SELECT pem.rerun_probes_on_server_restart($1::integer));
END;
$$ LANGUAGE plpgsql;


-- Create PEM unique system id for each installation
DO $$
DECLARE
	uuid text;
BEGIN
    -- If we already have unique id then skip
    IF NOT EXISTS ( SELECT * FROM pg_proc WHERE proname = 'system_uid' AND prokind = 'f' ) THEN
        RAISE NOTICE 'Generating unique PEM installation id...';
        -- Generate unique id
        SELECT REGEXP_REPLACE(
            EXTRACT(epoch FROM now())::text, '\.', ''
        )::text || floor(random()* (999999-100001 + 1) + 100001)::text AS id INTO uuid;

        -- Create a function using above id
        EXECUTE format(E'CREATE FUNCTION pem.system_uid() RETURNS text AS \'SELECT %s::text\' LANGUAGE SQL IMMUTABLE;', uuid);

        COMMENT ON FUNCTION pem.system_uid()
            IS 'Returns the unique system installation id';
    END IF;
END;
$$ LANGUAGE plpgsql;

-- PEM-5372
CREATE OR REPLACE FUNCTION pem.delete_cluster(_id integer)
RETURNS boolean AS
$$
DECLARE
	v_parent_id integer;
BEGIN
	SELECT parent_id INTO v_parent_id FROM pem.server_group WHERE id = _id;
	IF v_parent_id IS NULL THEN
		RAISE EXCEPTION 'Cluster not found';
	END IF;

	UPDATE pem.server SET group_id = v_parent_id WHERE group_id = _id;
	UPDATE pem.server_options SET server_group_id = v_parent_id WHERE server_group_id = _id;

	UPDATE pem.agent SET group_id = v_parent_id WHERE group_id = _id;
	UPDATE pem.agent_options SET group_id = v_parent_id WHERE group_id = _id;
	DELETE FROM pem.server_group WHERE id = _id;

	RETURN true;
END$$ LANGUAGE 'plpgsql' SECURITY DEFINER;


CREATE OR REPLACE FUNCTION pem.register_pem_server(integer)
RETURNS void AS
$FUNC$
DECLARE
	agent_id integer := NULL;
BEGIN
	SELECT asb.agent_id FROM pem.agent_server_binding asb WHERE asb.server_id = $1 INTO agent_id;

	IF NOT FOUND THEN
		RAISE EXCEPTION 'Server (%) is not bound to any agent, it can not be registered as a PEM server', $1;
	END IF;

	IF EXISTS (
		SELECT 1 FROM pem.pem_host_and_server WHERE server_id = $1
	) THEN
		RAISE INFO 'Server (%) is already registerd as a PEM backend server!', $1;
		RETURN;
	END IF;

	INSERT INTO pem.pem_host_and_server (agent_id, server_id, database)  VALUES (agent_id, $1, current_database());

	-- Flag and refresh the probe target materialized view so that any
	-- newly registered server's applicable probes can be scheduled immediately.
	-- This is safe even if discovery (oc_* tables) hasn't finished yet; a later
	-- trigger will mark it stale again when those rows arrive.
	UPDATE pem.refresh_materialized_view
	SET update_required = now()
	WHERE view_name = 'probe_target_view';
	PERFORM pem.refresh_stale_probe_view();
END
$FUNC$ LANGUAGE 'plpgsql';

-- This creates triggers and functions to log Patroni and EFM switchover events
CREATE OR REPLACE FUNCTION pem.log_patroni_switchover()
RETURNS TRIGGER AS $$
DECLARE
    detail_text TEXT;
BEGIN
    detail_text := format(
        '{"ClusterType":"patroni","ServerId":%s,"ClusterName":"%s","NodeIp":"%s","NodeName":"%s","NewRole":"%s","OldRole":"%s","Timestamp":"%s"}',
        NEW.server_id,
        COALESCE(NEW.cluster_name, 'null'),
        COALESCE(NEW.host, 'null'),
        NEW.member_name,
        NEW.role,
        OLD.role,
        to_char(OLD.recorded_time, 'YYYY-MM-DD HH24:MI:SS')
    );

    -- Ensure it fits within 255 chars
    IF length(detail_text) > 255 THEN
        detail_text := left(detail_text, 255);
    END IF;

    INSERT INTO pem.event_history (
        recorded_time, user_name, component, operation, message, details
    ) VALUES (
        now(),
        current_user,
        'HA Monitoring',
        'Switchover',
        format('Patroni leader changed for server %s', NEW.server_id),
        detail_text
    );
    RETURN NULL;
END;
$$ LANGUAGE plpgsql
security definer;

CREATE TRIGGER trg_patroni_switchover
AFTER UPDATE ON pemdata.patroni_node_status
FOR EACH ROW
WHEN (
    OLD.role IS DISTINCT FROM NEW.role
)
EXECUTE FUNCTION pem.log_patroni_switchover();

CREATE OR REPLACE FUNCTION pem.patroni_failover_info(
	p_server_id INT,
	p_interval_minutes INT
)
RETURNS TABLE (
	"Failover time" timestamptz,
	"Cluster type" TEXT,
	"Cluster name" TEXT,
	"Previous leader ip" TEXT,
	"Previous primary node" TEXT,
	"New leader ip" TEXT,
	"New primary node" TEXT
) AS $$
DECLARE
	v_cluster_name TEXT;
	r_demotion RECORD;
	r_promotion RECORD;
BEGIN
	-- Step 1: Find the cluster name using the provided server ID
	SELECT patroni_cluster_name
	INTO v_cluster_name
	FROM pem.server
	WHERE id = p_server_id;

	-- If no cluster name is found for this server ID, exit gracefully.
	IF v_cluster_name IS NULL THEN
		RETURN;
	END IF;

	-- Step 2: Find the most recent demotion in that cluster (Leader → non-Leader)
	SELECT
		recorded_time,
		(details::json->>'ClusterType') AS cluster_type,
		(details::json->>'ClusterName') AS cluster_name,
		(details::json->>'NodeIp')      AS old_ip,
		(details::json->>'NodeName')    AS old_node
	INTO r_demotion
	FROM pem.event_history
	WHERE component = 'HA Monitoring'
	AND operation = 'Switchover'
	AND (details::json->>'ClusterType') = 'patroni'
	AND (details::json->>'ClusterName') = v_cluster_name
	AND (details::json->>'OldRole') = 'Leader'
	AND (details::json->>'NewRole') IS DISTINCT FROM 'Leader'
	AND recorded_time >= now() - (p_interval_minutes || ' minutes')::interval
	ORDER BY recorded_time DESC
	LIMIT 1;

	-- If no demotion event was found, no failover occurred.
	IF r_demotion.recorded_time IS NULL THEN
		RETURN;
	END IF;

	-- Step 3: Find the corresponding promotion after the demotion (non-Leader → Leader)
	SELECT
		recorded_time,
		(details::json->>'NodeIp')   AS new_ip,
		(details::json->>'NodeName') AS new_node
	INTO r_promotion
	FROM pem.event_history
	WHERE component = 'HA Monitoring'
	AND operation = 'Switchover'
	AND (details::json->>'ClusterType') = 'patroni'
	AND (details::json->>'ClusterName') = v_cluster_name
	AND (details::json->>'NewRole') = 'Leader'
	AND (details::json->>'OldRole') IS DISTINCT FROM 'Leader'
	AND recorded_time BETWEEN (r_demotion.recorded_time - '30 seconds'::interval)
							AND (r_demotion.recorded_time + '30 seconds'::interval)
	ORDER BY recorded_time
	LIMIT 1;

	-- Step 4: If a matching promotion was found, return the consolidated failover info
	IF r_promotion.new_ip IS NOT NULL THEN
		"Failover time"         := r_demotion.recorded_time;
		"Cluster type"          := r_demotion.cluster_type;
		"Cluster name"          := r_demotion.cluster_name;
		"Previous leader ip"    := r_demotion.old_ip;
		"Previous primary node" := r_demotion.old_node;
		"New leader ip"         := r_promotion.new_ip;
		"New primary node"      := r_promotion.new_node;
		RETURN NEXT;
	END IF;
END;
$$ LANGUAGE plpgsql STABLE;

CREATE OR REPLACE FUNCTION pem.log_efm_switchover()
RETURNS TRIGGER AS $$
DECLARE
    cluster_name TEXT;
    detail_text TEXT;
BEGIN
    -- Get the EFM cluster name
    SELECT efm_cluster_name INTO cluster_name
    FROM pem.server
    WHERE id = NEW.server_id;

    -- Build the JSON detail text
    detail_text := format(
        '{"ClusterType":"efm","ServerId":%s,"ClusterName":"%s","NodeIp":"%s","NewAgentType":"%s","OldAgentType":"%s","Timestamp":"%s"}',
        NEW.server_id,
        COALESCE(cluster_name, 'null'),
        COALESCE(NEW.efm_ip_address, 'null'),
        COALESCE(NEW.efm_agent_type, 'null'),
        COALESCE(OLD.efm_agent_type, 'null'),
        to_char(NEW.recorded_time, 'YYYY-MM-DD HH24:MI:SS')
    );

    -- Truncate if too long
    IF length(detail_text) > 255 THEN
        detail_text := left(detail_text, 255);
    END IF;

    -- Insert the log entry
    INSERT INTO pem.event_history (
        recorded_time,
        user_name,
        component,
        operation,
        message,
        details
    ) VALUES (
        now(),
        current_user,
        'HA Monitoring',
        'Switchover',
        format('EFM primary changed for server %s', NEW.server_id),
        detail_text
    );

    RETURN NULL;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE TRIGGER trg_efm_switchover
AFTER UPDATE ON pemdata.efm_cluster_node_status
FOR EACH ROW
WHEN (
    OLD.efm_agent_type IS DISTINCT FROM NEW.efm_agent_type
)
EXECUTE FUNCTION pem.log_efm_switchover();

-- Function to log last failover information for a efm server in the last X minutes
-- p_server_id: ID of the server to check
-- p_interval_minutes: Interval in minutes to check for failover in last X minutes
CREATE OR REPLACE FUNCTION pem.efm_failover_info(
	p_server_id INT,
	p_interval_minutes INT
)
RETURNS TABLE (
	"Failover time" timestamptz,
	"Cluster type" TEXT,
	"Cluster name" TEXT,
	"Previous primary ip" TEXT,
	"New primary ip" TEXT
) AS $$
DECLARE
	v_cluster_name TEXT;
	r_demotion RECORD;
	r_promotion RECORD;
BEGIN
	-- Step 1: Find the cluster name from the server ID
	-- (This is the fix for the ServerId problem)
	SELECT efm_cluster_name
	INTO v_cluster_name
	FROM pem.server
	WHERE id = p_server_id;

	-- If no cluster name, exit
	IF v_cluster_name IS NULL THEN
		RETURN;
	END IF;

	-- Step 2: Find the latest demotion in that cluster
	SELECT
		recorded_time,
		(details::json->>'ClusterType') AS cluster_type,
		(details::json->>'ClusterName') AS cluster_name,
		(details::json->>'NodeIp')      AS old_ip
	INTO r_demotion
	FROM pem.event_history
	WHERE component = 'HA Monitoring'
	AND operation = 'Switchover'
	AND (details::json->>'ClusterName') = v_cluster_name
	AND (details::json->>'OldAgentType') = 'Primary'
	AND (details::json->>'NewAgentType') IS DISTINCT FROM 'Primary'
	AND recorded_time >= now() - (p_interval_minutes || ' minutes')::interval
	ORDER BY recorded_time DESC
	LIMIT 1;

	IF r_demotion.recorded_time IS NULL THEN
		RETURN;
	END IF;

	-- Step 3: Find the matching promotion in that cluster
	-- (This is the fix for the time logic problem)
	SELECT
		recorded_time,
		(details::json->>'NodeIp') AS new_ip
	INTO r_promotion
	FROM pem.event_history
	WHERE component = 'HA Monitoring'
	AND operation = 'Switchover'
	AND (details::json->>'ClusterName') = v_cluster_name
	AND (details::json->>'NewAgentType') = 'Primary'
	AND (details::json->>'OldAgentType') IS DISTINCT FROM 'Primary'
	AND recorded_time BETWEEN (r_demotion.recorded_time - '30 seconds'::interval)
							AND (r_demotion.recorded_time + '30 seconds'::interval)
	ORDER BY recorded_time
	LIMIT 1;

	-- Step 4: Return the result
	IF r_promotion.new_ip IS NOT NULL THEN
		"Failover time"         := r_demotion.recorded_time;
		"Cluster type"          := r_demotion.cluster_type;
		"Cluster name"          := r_demotion.cluster_name;
		"Previous primary ip"   := r_demotion.old_ip;
		"New primary ip"        := r_promotion.new_ip;
		RETURN NEXT;
	END IF;
END;
$$ LANGUAGE plpgsql STABLE;

